        'Os dias do período saem do plano, de amanhã em diante (os escolhidos à mão, os sorteados e os livres), e o modo de rodízio monta esses dias de novo. Pode deixar um lado vazio: só o começo apaga dele até o fim do plano; só o fim apaga de amanhã até ele.' => '时段内的日子从明天起从计划中删除（手动选择的、抽签的和空闲的），轮换模式会重新安排这些日子。可以只填一边：只填开始，从开始删除到计划结束；只填结束，从明天删除到结束。',
        'Apagar toda a programação, de hoje em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo, e hoje pode sair outro relógio, que passa a ser o do pulso a partir de agora.' => '清除从今天起的全部安排（手动选择、抽选和空闲日）？轮换模式会重新生成计划，今天可能换成另一块表，并从现在起成为戴在手腕上的那块。',
        'Apagar toda a programação, de amanhã em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo; hoje continua como está.' => '清除从明天起的全部安排（手动选择、抽选和空闲日）？轮换模式会重新生成计划；今天保持不变。',
        'Apagar tudo' => '全部清除',
