        'Como pedir acesso (e por que pelo código)' => '如何申请访问（以及为什么用编号）',
        'Por que o código: para proteger quem usa o sistema, nenhuma página mostra a lista de contas nem de coleções. O login é metade do que alguém precisa para tentar entrar numa conta alheia, e o nome de uma coleção costuma levar o login do dono. Por isso o pedido é feito pelo código que o próprio dono passa: quem não recebeu o código não tem como saber de quem ele é.' => '为什么用编号：为了保护使用系统的人，没有任何页面显示账户或收藏的列表。登录名是别人试图进入他人账户所需的一半信息，而收藏的名称通常带有所有者的登录名。因此申请要凭所有者本人给出的编号：没有拿到编号的人无从知道它属于谁。',
        'Peça o código ao dono (por mensagem, e-mail ou pessoalmente). Ele o encontra em Minha conta: o código dele, em Seus dados, dá acesso a todas as coleções dele, também às que ele criar depois; o código de uma coleção só fica na coluna Código da tabela Coleções.' => '向所有者索取编号（通过消息、电子邮件或当面）。他在“我的账户”中找到它：他的编号在“你的资料”中，可访问他的全部收藏，包括以后创建的；单个收藏的编号在“收藏”表格的“编号”列中。',
        'Aqui, escolha se o código é de uma coleção ou do dono, digite o número e deixe um recado dizendo quem você é: o dono vê só o seu login.' => '在这里选择编号是收藏的还是所有者的，输入数字，并留言说明你是谁：所有者只能看到你的登录名。',
        'O dono recebe um e-mail e aprova ou recusa em Aprovações. Até lá, o seu pedido mostra só o código. Aprovado, você recebe um e-mail e a coleção aparece no seletor do menu.' => '所有者会收到一封电子邮件，并在“审批”中批准或拒绝。在此之前，你的申请只显示编号。批准后，你会收到一封电子邮件，收藏会出现在菜单的选择器中。',
