        'Não consegui ler as aprovações: {1}' => '无法读取审批：{1}',
        'Aprovações' => '审批',
        'todos os relógios' => '所有手表',
        'Avisos' => '提醒',
        'Avisos dos relógios' => '手表提醒',
        'Lembretes' => '定时提醒',
        'Para onde vão' => '发往何处',
        'Tudo o que o sistema lembra: os avisos dos relógios, que ele calcula sozinho pelos dados de cada um (dar corda, carregar, trocar a pilha...); os lembretes, que você marca com hora e repetição; e para onde vão os dois (os destinos das mensagens e as agendas).' => '系统会提醒的一切：手表提醒，由系统根据每块手表的数据自动计算（上弦、充电、换电池……）；定时提醒，由你设定时间和重复方式；以及两者发往何处（消息的目的地和日历）。',
        'não' => '否',
        'no relógio do dia' => '在当天的手表上',
        'sempre' => '总是',
        'só dentro da antecedência da agenda' => '仅在日历的提前期内',
        'qualquer data' => '任何日期',
        'Cada aviso tem uma fórmula da data prevista; entra "em breve" dentro da antecedência e "atrasado" quando a data passa. O "vale quando" (uma fórmula) diz para quais relógios o aviso vale (ex.: corda_manual = 0, só para o automático sem corda); vazio, vale para todos do grupo. O texto é o motivo nas mensagens ({motivo}): "Dar corda: San Martin (a reserva acaba em 3h, 28/09/2026 10:53)"; nele: {relogio}, {data}, {quando} e {limite} (o limite de carga do relógio). O tipo que resolve vira o botão na tela Hoje. Como as fórmulas, pode ter uma versão por ponto da árvore. Na escala inteligente: "no relógio do dia" é conferido no escolhido, do começo ao fim do bloco dele; "sempre", também nos guardados, todo dia. O que vence vira o lembrete do dia, e o lançamento que resolve é simulado com o valor (leitura) ou as horas (sessão) do aviso. Se o aviso vai para cada destino e cada agenda (e com que texto) se escolhe neles, em Para onde vão, embaixo; aqui fica a data que ele usa na agenda. "Na hora": além do alerta da manhã, o Telegram recebe o aviso no minuto em que ele vence (uma vez, até ele ser resolvido), como o "Tirar do carregador" quando a bateria enche.' => '每个提醒都有一个预计日期的公式；进入提前期内时变为“即将到期”，日期过后变为“已逾期”。“适用条件”（一个公式）说明该提醒适用于哪些手表（例如 corda_manual = 0，仅适用于不能手动上弦的自动表）；为空则适用于该组的所有手表。文本是消息中的原因（{motivo}）：“上弦：San Martin（动力储存将在 3小时后耗尽，2026-09-28 10:53）”；其中可用：{relogio}、{data}、{quando} 和 {limite}（手表的电量下限）。解决它的记录类型会成为“今天”页面上的按钮。和公式一样，它可以在树的每个节点各有一个版本。在智能排程中：“在当天的手表上”只在被选中的手表上检查，从它的区块开始到结束；“始终”则每天也在存放的手表上检查。到期的内容会成为当天的提示，解决它的记录会按提醒的数值（读数）或时长（时段）进行模拟。提醒是否发往每个目的地和每个日历（以及用什么文字）在它们各自之中选择，见下方的“发往何处”；这里设定它在日历中使用的日期。“即时”：除了早上的提醒外，Telegram 会在到期的那一分钟收到提醒（一次，直到它被解决），例如电池充满时的“从充电器取下”。',
