        'Evento novo já vai por todos os destinos da coleção. Em cada destino e cada agenda (páginas Destinos e Agendas), escolha se ele vai e com que texto.' => '新活动会自动发往该收藏的所有推送目标。在每个推送目标和每个日历中（推送目标和日历页面），选择是否发送以及使用什么文本。',
