        'Nenhum ainda: as mensagens da manhã, da noite e os avisos não saem para lugar nenhum.' => '还没有：早晨、晚上的消息和提醒都不会发往任何地方。',
        'Nenhuma ainda.' => '还没有。',
        'Um destino é um webhook (Telegram, n8n...), um e-mail ou o Web Push do navegador; uma agenda é o Google, um CalDAV (Nextcloud, iCloud, Fastmail), o Outlook ou um link ICS para assinar em qualquer app. Cada um escolhe o que recebe e tem a sua mensagem.' => '推送目标可以是 webhook（Telegram、n8n……）、电子邮件或浏览器的 Web Push；日历可以是 Google、CalDAV（Nextcloud、iCloud、Fastmail）、Outlook，或可在任何应用中订阅的 ICS 链接。每一个都可选择接收内容并有自己的消息。',
