        'A conta nova é de demonstração por {1} dias: depois disso ela é apagada, a menos que o administrador a torne oficial. Você recebe um aviso por e-mail antes.' => '新账户是为期 {1} 天的演示账户：到期后会被删除，除非管理员将其转为正式账户。到期前你会收到电子邮件提醒。',
        'Criar conta' => '创建账户',
