        'Cadastros' => '定义',
        'Campos do cadastro dos relógios' => '手表档案的字段',
        'Cada campo vale para o ponto da árvore escolhido e tudo abaixo dele (os de cada nível somam) e aparece no cadastro desses relógios. O identificador é o nome do campo nas fórmulas. Marcado "só nos desejados", o campo aparece só nos relógios da lista de desejos.' => '每个字段适用于所选的树节点及其下的所有节点（各层的字段会叠加），并显示在这些手表的档案中。标识符是该字段在公式中的名称。勾选“仅心愿单”后，该字段只出现在心愿单中的手表上。',
        'Campo' => '字段',
        'Identificador' => '标识符',
        'Vale para' => '适用于',
        'Padrão' => '默认值',
        ' · só nos desejados' => ' · 仅心愿单',
        'Excluir o campo {1} e os valores dele?' => '删除字段 {1} 及其所有值？',
        'Alterar o campo {1}' => '修改字段 {1}',
        'Novo campo' => '新字段',
        'Unidade {1}' => '单位 {1}',
        'Valor padrão {1}' => '默认值 {1}',
        'Vale para {1}' => '适用于 {1}',
        'Opções (lista: uma por linha) {1}' => '选项（列表：每行一个）{1}',
        ' só nos desejados (a lista de desejos: o preço-alvo, a prioridade)' => ' 仅心愿单（心愿单：目标价、优先级）',
        'O que se registra num relógio: instantâneo (corda), com valor (leitura de carga) ou sessão com início e fim (pulso, winder, sol). O identificador é o nome nas funções das fórmulas: HORAS("pulso"; 30). Sessão exclusiva: o relógio fica num lugar só. Mede o gasto: cada leitura desse tipo mede quanto caiu por dia de uso ou guardado (a função MEDIDO das fórmulas). Vale quando: uma fórmula que diz para quais relógios o tipo vale (ex.: corda_manual, só para quem aceita corda); vazia, vale para todos do grupo.' => '手表上记录的内容：瞬时（上弦）、带数值（电量读数）或有开始和结束的时段（手腕、摇表器、晒太阳）。标识符是公式函数中使用的名称：HORAS("pulso"; 30)。独占时段：手表同一时间只在一个地方。测量消耗：这种类型的每次读数都会测量每天佩戴或存放时下降了多少（公式函数 MEDIDO）。适用条件：一个说明该类型适用于哪些手表的公式（例如 corda_manual，只适用于可以上弦的手表）；为空则适用于该组的所有手表。',
        'Formato' => '格式',
        'Fecha sozinho às' => '自动结束于',
        'Exclusiva' => '独占',
        'Mede o gasto' => '测量消耗',
        'Lançamentos' => '记录',
        'Excluir o tipo {1}?' => '删除类型 {1}？',
        'Novo tipo de lançamento' => '新记录类型',
        'Formato {1}' => '格式 {1}',
        'Unidade (com valor) {1}' => '单位（带数值）{1}',
        'Fecha sozinho às (sessão; vazio: não fecha) {1}' => '自动结束于（时段；为空：不自动结束）{1}',
        'Vale quando (fórmula: 1 vale, 0 não; vazio: sempre) {1}' => '适用条件（公式：1 适用，0 不适用；为空：始终适用）{1}',
        'ex.: corda_manual' => '例如：corda_manual',
        ' sessão exclusiva (o relógio num lugar só)' => ' 独占时段（手表同一时间只在一处）',
        ' mede o gasto (com valor: cada leitura mede o gasto em uso ou guardado, comparando com a anterior)' => ' 测量消耗（带数值：每次读数与上一次比较，测量佩戴或存放时的消耗）',
        'Uma fórmula pode ter uma versão em cada ponto da árvore: vale para o relógio a do ponto mais perto dele. Números com vírgula ou ponto, argumentos separados por ponto e vírgula, textos entre aspas. Variáveis: os identificadores dos campos e das fórmulas.' => '一个公式可以在树的每个节点各有一个版本：手表使用离它最近的节点的版本。数字可用逗号或点，参数用分号分隔，文本放在引号中。变量：字段和公式的标识符。',
        'Fórmula' => '公式',
        'Cálculo' => '计算',
        'Excluir esta versão de {1}?' => '删除 {1} 的这个版本？',
        'Alterar {1} ({2})' => '修改 {1}（{2}）',
        'Nova fórmula (ou nova versão de uma que existe)' => '新公式（或现有公式的新版本）',
        'Cálculo {1}' => '计算 {1}',
        'Testar uma fórmula (sem gravar)' => '测试公式（不保存）',
        'Testar em todos os relógios' => '在所有手表上测试',
        'Resultado' => '结果',
        'As partes da conta' => '计算的各个部分',
        'vazio' => '空',
        'As funções do motor' => '引擎的函数',
        'Os documentos de cada relógio (a página Documentos, aberta pela ficha) ficam numa categoria. "Aceita" limita os arquivos da categoria; nada marcado, ela aceita qualquer arquivo. O jeito de abrir cada arquivo vem do tipo dele, não da categoria: as fotos na galeria, os vídeos no player, o PDF no visualizador, o XML da nota com o resumo, o resto para baixar. Uma categoria com documentos não se exclui: passe os documentos para outra antes.' => '每块手表的文档（“文档”页面，从手表档案打开）都属于一个类别。“接受”限制该类别的文件；什么都不勾选则接受任何文件。每个文件的打开方式取决于文件类型，而不是类别：照片在图库中、视频在播放器中、PDF 在查看器中、发票 XML 带摘要，其余的供下载。有文档的类别不能删除：请先把文档移到其他类别。',
        'Categoria' => '类别',
        'Aceita' => '接受',
        'Ordem' => '顺序',
        'Documentos' => '文档',
        'qualquer arquivo' => '任何文件',
        'Excluir a categoria {1}?' => '删除类别 {1}？',
        'Alterar a categoria {1}' => '修改类别 {1}',
        'Nova categoria' => '新类别',
        'Ordem {1}' => '顺序 {1}',
        'vazio: no fim' => '为空：排在最后',
        'Aceita (nada marcado: qualquer arquivo)' => '接受（不勾选：任何文件）',
        'Total' => '合计',
        'Cada total é uma expressão do motor que olha para todos os relógios mostrados de uma vez (os que o filtro da tabela da página Hoje deixa). Ele aparece no rodapé da tabela, embaixo da coluna dele, e/ou como um quadro na {1}. Vários totais na mesma coluna ficam um embaixo do outro, na ordem desta lista.' => '每个合计都是引擎的一个表达式，一次看所有显示的手表（今天页面表格筛选后留下的）。它显示在表格底部、对应列的下方，和/或作为{1}上的一个方框。同一列的多个合计按此列表的顺序上下排列。',
        'página de totais' => '合计页面',
        'Coluna' => '列',
        'Expressão' => '表达式',
        'Rodapé' => '底部',
        'Página' => '页面',
