        'Coluna {1}' => '列 {1}',
        'Nenhuma (só na página de totais)' => '无（仅在合计页面）',
        'Expressão {1}' => '表达式 {1}',
        'Exibir no rodapé do totalizador (embaixo da coluna)' => '显示在合计底部（列的下方）',
        'Exibir na página de totais' => '显示在合计页面',
        'Largura na página {1}' => '页面上的宽度 {1}',
        'Estreito (três por linha no computador)' => '窄（电脑上每行三个）',
        'Largo (a linha inteira)' => '宽（整行）',
        'Formato dos números {1}' => '数字格式 {1}',
        'Só os totais de uma coluna vão para o rodapé; os outros, quantos você quiser, ficam só na página de totais.' => '只有属于某列的合计才会进入底部；其他的，想要多少都可以，只显示在合计页面。',
        'As funções de total' => '合计函数',
        'Dentro delas vale tudo o que vale numa fórmula (os campos, as fórmulas, SE, DIAS_DESDE, MES_ANO...), calculado em cada relógio; fora delas, só números, textos e as funções que não precisam de um relógio.' => '在函数内部，公式中能用的都能用（字段、公式、SE、DIAS_DESDE、MES_ANO……），在每块手表上计算；在函数外部，只能用数字、文本和不需要手表的函数。',
        'As variáveis da tabela' => '表格变量',
        'Dá agora, em {1} relógios' => '当前结果，{1} 块手表',
        'Não consegui ler os cadastros: {1}' => '无法读取定义：{1}',
        'Atualização do banco' => '数据库更新',
        'O banco está desatualizado' => '数据库已过期',
        'Esta versão do sistema precisa de migrações que ainda não foram aplicadas no banco. Até lá, as páginas, a API e o cron ficam parados, para não gravar nada pela metade.' => '这个版本的系统需要尚未应用到数据库的迁移。在此之前，页面、API 和 cron 都会暂停，以免只写入一半的数据。',
        'Aplicar agora' => '立即应用',
        'Aplica na ordem e para na primeira que falhar. Se o usuário do banco do sistema não tiver permissão de alterar tabelas, rode na mão, na ordem: {1}' => '按顺序应用，遇到第一个失败就停止。如果系统的数据库用户没有修改表的权限，请按顺序手动执行：{1}',
        'Continuar para a Configuração' => '继续前往设置',
        'O cron está com erro' => 'cron 出错了',
        'Some sozinho na primeira execução sem erro.' => '在第一次无错误运行后会自动消失。',
        '{1}, com filtro de datas e busca.' => '{1}，可按日期筛选和搜索。',
        'Ver todas as execuções do cron' => '查看所有 cron 运行记录',
        'Registro da última rodada' => '上一次运行的日志',
        'Rotina do dia' => '每日例程',
        'Manhã: relógio do dia e avisos' => '早上：当天的手表和提醒',
        'Noite: preparar o de amanhã' => '晚上：准备明天的手表',
        'No pulso a partir de' => '开始佩戴于',
        'Pôr no pulso sozinho' => '自动戴上',
        'No pulso até' => '佩戴至',
        'Tirar do pulso sozinho' => '自动取下',
        'Sessão no sol esquecida fecha às' => '忘记结束的晒太阳时段在此时间结束',
        'A semana começa' => '每周开始于',
        'Na segunda-feira' => '星期一',
        'No domingo' => '星期日',
        'Sem <strong>pôr sozinho</strong>, o relógio do dia só entra no pulso pelo <strong>Pôs no pulso</strong>; sem <strong>tirar sozinho</strong>, só sai pelo ' => '不勾选<strong>自动戴上</strong>时，当天的手表只能通过<strong>已戴上</strong>戴到手腕上；不勾选<strong>自动取下</strong>时，只能通过 ',
        '<strong>Tirou do pulso</strong> (esquecido, continua contando como no pulso). O horário de uso vale sempre para o plano e as previsões. Fora do pulso, o relógio conta como guardado.' => '<strong>已取下</strong>取下（如果忘了，会一直按戴在手腕上计算）。佩戴时间始终用于计划和预测。不在手腕上时，手表按存放计算。',
        'A semana do rodízio começa no dia escolhido: o plano vem montado até o último dia da semana, e o ciclo, a próxima semana e o relógio para a semana inteira contam dela.' => '轮换的一周从所选的那天开始：计划编排到这一周的最后一天，循环、下一周和整周一块手表都按它来算。',
        'Limites e contas' => '限值与计算',
        'Carregar quando a carga chegar a (%)' => '电量降到此值时充电（%）',
        'Solar: pôr no sol quando chegar a (%)' => '太阳能：降到此值时晒太阳（%）',
        'Gasto da bateria: como calcular (válido para todos os relógios)' => '电池消耗：如何计算（对所有手表有效）',
        'Individual (no relógio ou no grupo)' => '单独（在手表或分组上）',
        '1. Pelas horas registradas (o motor original)' => '1. 按记录的小时数（原始引擎）',
        '2. Pelas horas registradas, com leituras e cadastro (robusto)' => '2. 按记录的小时数，结合读数和档案（稳健）',
        '3. Pela marcação: duas taxas separadas' => '3. 按标记：两个独立的速率',
        '4. Só o cadastro' => '4. 仅档案',
        '5. Pelas fórmulas do cadastro' => '5. 按档案的公式',
        'Gasto medido: contar por' => '测得消耗：按什么计',
        'Dias (os últimos dias)' => '天数（最近的天数）',
        'Leituras (as últimas de cada tipo)' => '读数（每类最近的几次）',
        'Gasto medido: média dos últimos (dias)' => '实测消耗：最近多少天的平均值',
        'Gasto medido: últimas leituras (de cada tipo)' => '测得消耗：最近读数（每类）',
        'Avisar quando um relógio fica encostado' => '手表闲置时提醒',
        'Aviso Encostado: dias sem ir ao pulso' => '“闲置”提醒：多少天没戴',
        'Cópia dos documentos no banco (válido para todos os relógios)' => '文档在数据库中的副本（对所有手表有效）',
        'Individual (no relógio ou no arquivo)' => '单独（在手表或文件上）',
        'Todos os arquivos' => '所有文件',
        'Nenhum arquivo' => '不复制任何文件',
        'O limite de carga de um relógio (no cadastro dele) vale no lugar do geral. O gasto da bateria tem cinco motores (veja a Ajuda); a escolha aqui vale para todos os relógios da coleção, e vazia valem a do relógio e a do grupo (o campo "Como calcular o gasto da bateria" do cadastro). O gasto medido conta as medições dos últimos dias ou as últimas leituras de cada tipo (em uso e em repouso), conforme o "contar por"; as de fora saem da conta. A cópia dos documentos no banco escolhida aqui vale sobre o relógio e o arquivo. ' => '手表自身的电量下限（在其档案中）优先于总体设置。电池消耗有五种引擎（见帮助）；此处的选择对收藏中的所有手表生效，留空时以手表和分组的选择为准（档案字段“如何计算电池消耗”）。测得消耗按“按什么计”统计最近几天的测量或每类最近的几次读数（使用中和静置中）；范围之外的不计入。此处选择的文档数据库副本优先于手表和文件的设置。 ',
        'O config.php ainda define DOCUMENTOS_COPIA_BANCO, que não vale mais: a cópia dos documentos é escolhida aqui, por coleção. ' => 'config.php 仍定义了 DOCUMENTOS_COPIA_BANCO，它已不再生效：文档副本在此按收藏选择。 ',
        'Um relógio da coleção que passa do limite de dias sem ir ao pulso ganha o aviso <strong>Encostado</strong>; a caixa desliga tudo (o aviso, a coluna da Hoje e o filtro: é o mesmo aviso Encostado da página Avisos).' => '收藏中超过多少天没戴上限的手表会收到<strong>闲置</strong>提醒；此复选框会全部关闭（提醒、今日页的列和筛选：与提醒页中的闲置提醒是同一个）。',
        'Telas' => '界面',
        'Idioma padrão (quem não escolheu outro no menu)' => '默认语言（适用于未在菜单中选择其他语言的人）',
        'Fuso horário (quem não escolheu outro em Minha conta)' => '时区（在“我的账户”中未另选的人）',
        'O do sistema ({1})' => '系统的（{1}）',
        'Relógio da Hora certa' => '准确时间的时钟',
        'Analógico e digital (um ao lado do outro)' => '模拟和数字（并排）',
        'Analógico' => '模拟',
        'Digital' => '数字',
        'Anadigi (o visor digital dentro do analógico)' => '指针数字两用（数字显示嵌在模拟表盘内）',
        'Abrir o relógio na página Hoje' => '在“今天”页面打开手表的方式',
        'Ao lado da lista' => '在列表旁边',
        'Numa janela flutuante, grande' => '在大的浮动窗口中',
        'Destaque no alto da página Hoje' => '“今天”页面顶部的焦点',
        'O relógio do dia' => '当天的手表',
        'O relógio no pulso agora' => '现在戴在手腕上的手表',
        'Reloginho da barra (um dos {1} modelos por hora)' => '菜单栏的小手表（每小时 {1} 种款式之一）',
        'Normal: cada hora tem o seu' => '正常：每个小时有自己的',
        'Aleatório: sorteia um a cada hora (pode repetir)' => '随机：每小时抽一个（可能重复）',
        'Aleatório sem repetição: os 24 embaralhados, cada um uma vez por dia' => '不重复随机：24 种打乱，每天每种一次',
        'Próximos dias (página Hoje): mostrar até (dias por página)' => '未来几天（“今天”页面）：每页最多显示（天）',
        'Plano: mostrar até (dias por página)' => '计划：每页最多显示（天）',
        'Intervalo de atualização das páginas (segundos; 0 desliga)' => '页面刷新间隔（秒；0 关闭）',
        'Endereço do sistema (a âncora {link})' => '系统地址（占位符 {link}）',
        'http://servidor/relogios' => 'http://server/watches',
        '(o do pedido; só o master muda)' => '（来自请求地址；只有 master 能修改）',
        '<strong>Ao lado da lista:</strong> o relógio clicado abre num painel à direita, e a lista continua à vista. <strong>Numa janela flutuante:</strong> abre grande, ' => '<strong>在列表旁边：</strong>点击的手表在右侧面板中打开，列表仍然可见。<strong>在浮动窗口中：</strong>大窗口打开，',
        'no meio da tela, com os quadros lado a lado; fecha no ×, no Esc ou num clique fora. No celular, os dois cobrem a tela inteira.' => '位于屏幕中央，各个方框并排；点 ×、按 Esc 或点击窗口外部即可关闭。在手机上，两种方式都会占满整个屏幕。',
        '<strong>Destaque:</strong> o quadro grande no alto da página Hoje mostra o relógio do dia (o do plano) ou o que está no pulso agora, ' => '<strong>焦点：</strong>“今天”页面顶部的大方框显示当天的手表（计划中的）或现在戴在手腕上的手表，',
        'mesmo que seja outro (o do dia aparece embaixo do nome). Sem nenhum relógio no pulso, fica o do dia.' => '即使是另一块（当天的手表显示在名称下方）。手腕上没有手表时，显示当天的手表。',
        '<strong>Intervalo de atualização:</strong> de quantos em quantos segundos a Hoje (com o painel), a Ficha, o Plano, os Totais e o Histórico leem tudo de novo sozinhos, sem recarregar a página (a carga, a autonomia, a última leitura, os avisos, os contadores). ' => '<strong>刷新间隔：</strong>今天页面（含面板）、手表卡片、计划、合计和历史每隔多少秒自动重新读取全部数据，无需刷新页面（电量、续航、最近读数、提醒、计数）。',
        'De 1 a 86400; 0 desliga; padrão 60. Nunca por cima de quem está digitando ou tem algo mudado e não gravado.' => '1 到 86400；0 关闭；默认 60。正在输入或有未保存的修改时从不刷新。',
        '<strong>Mostrar até:</strong> quantos dias os Próximos dias (página Hoje, padrão 7) e o dia a dia da página Plano (padrão 31) mostram de cada vez. ' => '<strong>最多显示：</strong>“未来几天”（“今天”页面，默认 7）和“计划”页面的逐日列表（默认 31）每次显示多少天。',
        'Passando disso, embaixo aparecem as páginas: &lt; (anterior), os números e &gt; (próxima).' => '超出时，底部会出现分页：&lt;（上一页）、页码和 &gt;（下一页）。',
        '<strong>Fuso horário:</strong> o da coleção vale para quem não escolheu o seu em Minha conta, e para o cron, as mensagens e as agendas dela; vazio, o do sistema (o config.php). ' => '<strong>时区：</strong>收藏的时区适用于在“我的账户”中未选择自己时区的人，以及收藏的 cron、消息和日历；留空则为系统的（config.php）。',
        'Cada pessoa vê e digita as horas no fuso dela; no banco fica tudo no fuso do sistema. <strong>Relógio da Hora certa:</strong> o mostrador da página Hora certa: analógico, digital, anadigi (o visor digital dentro do mostrador) ou os dois, um ao lado do outro.' => '每个人按自己的时区查看和输入时间；数据库中一切都保存在系统时区。<strong>准确时间的时钟：</strong>准确时间页面的表盘：模拟、数字、指针数字两用（数字显示嵌在表盘内）或两者并排。',
        'Cron' => 'Cron',
        'Sorteios' => '抽选',
        'Os números vêm de' => '随机数来源',
        '1. RANDOM.ORG (ruído atmosférico) · 2. fora do ar, ANU QRNG (quântico) · 3. sem os dois, o gerador seguro do PHP' => '1. RANDOM.ORG（大气噪声）· 2. 不可用时用 ANU QRNG（量子）· 3. 两者都不可用时用 PHP 的安全生成器',
        'Último lote' => '上一批',
        'nenhum ainda' => '还没有',
        'Serviços fora' => '不可用的服务',
        'os dois sem responder desde {1} {2}; o sistema tenta de novo depois de 10 minutos' => '两者自 {1} {2} 起都没有响应；系统会在 10 分钟后重试',
        'Todo sorteio do sistema (o rodízio totalmente aleatório, o sorteio pela nota e o desempate de notas iguais na escala) usa estes números. Eles chegam num lote, e cada sorteio usa só o que precisa, sem viés.' => '系统中所有的抽选（完全随机轮换、按评分抽选以及排程中同分时的决胜）都使用这些数字。它们成批到达，每次抽选只取所需，没有偏差。',
        'Avisos, lembretes e mensagens' => '提醒、定时提醒和消息',
        '{1} lembretes · {2} destinos · {3} agendas' => '{1} 个定时提醒 · {2} 个目的地 · {3} 个日历',
        'Os avisos dos relógios, os lembretes (os eventos personalizados) e para onde eles vão ficam juntos na página {1}.' => '手表提醒、定时提醒（自定义事件）以及它们发往何处，都集中在 {1} 页面。',
        'As mudanças desta página valem depois de salvar.' => '本页的更改在保存后生效。',
        'Salvar configuração' => '保存设置',
        'Cópia de segurança' => '备份',
        'Uma cópia do banco inteiro por dia, na rodada da noite, guardando as {1} mais novas, {2} o conteúdo dos documentos (os arquivos já ficam na pasta deles). A cópia volta em qualquer um dos três bancos, na mesma versão do sistema. {3}' => '每天在晚间运行时备份整个数据库一次，保留最新的 {1} 份，{2}文档的内容（文件本身已保存在各自的文件夹中）。备份可以在三种数据库中的任意一种恢复，但需要相同的系统版本。{3}',
        'com' => '包含',
        'sem' => '不含',
        'Última: {1} {2}.' => '最近一次：{1} {2}。',
        'Nenhuma feita ainda.' => '还没有备份。',
        'A cópia automática está desligada: {1}. Ponha no config.php a BACKUP_PASTA, uma pasta do servidor fora da pasta publicada.' => '自动备份已关闭：{1}。请在 config.php 中设置 BACKUP_PASTA，即服务器上发布目录之外的一个文件夹。',
        'Cópia' => '备份',
        'Feita em' => '创建于',
        'Tamanho' => '大小',
        'Baixar' => '下载',
        'Voltar o banco para a cópia de {1}? Tudo o que foi feito depois some. Antes, o sistema guarda uma cópia do que está agora.' => '把数据库恢复到 {1} 的备份？之后所做的一切都会丢失。恢复前，系统会先备份当前的状态。',
        'Restaurar' => '恢复',
        'Fazer uma cópia agora' => '立即备份',
        'Não consegui ler a configuração: {1}' => '无法读取设置：{1}',
        'Configuração' => '设置',
        'Abrir' => '打开',
        'aberta' => '已打开',
        'Renomear' => '重命名',
        'Nome da coleção' => '收藏名称',
        'Sair' => '退出',
        'sua' => '你的',
        'membro' => '成员',
        'master' => 'master',
        'Coleções' => '收藏',
        'Você ainda não vê nenhuma coleção: crie uma aqui embaixo, ou peça acesso à de alguém (e espere a aprovação).' => '你还看不到任何收藏：在下面创建一个，或申请访问别人的收藏（并等待批准）。',
        'Dono' => '所有者',
        'Você é' => '你的身份',
        'Para alguém pedir acesso a uma coleção sua, passe o código dela; para todas as suas, o seu código (em Seus dados). O pedido não mostra a ninguém o seu login nem os nomes das coleções: você aprova ou recusa em Aprovações.' => '要让别人申请访问你的某个收藏，把该收藏的编号给他；要访问你的全部收藏，给他你的编号（在“你的资料”中）。申请不会向任何人显示你的登录名或收藏名称：你在“审批”中批准或拒绝。',
        'Nova coleção' => '新收藏',
        'Começa' => '开始',
        'com o conjunto inicial (grupos, campos, fórmulas, avisos e critérios)' => '带初始数据（分组、字段、公式、提醒和评分标准）',
        'vazia (só a raiz da árvore)' => '空的（只有树的根）',
        'com uma árvore minha que já existe (o cadastro fica em comum)' => '使用我已有的一棵树（定义共用）',
        'Árvore' => '树',
        'Criar coleção' => '创建收藏',
        'Árvores de grupos' => '分组树',
        'A árvore guarda os grupos e o cadastro deles (campos, tipos de lançamento, fórmulas, avisos, categorias e critérios). Uma árvore pode servir a várias coleções suas: o que muda nela vale para todas.' => '树保存分组及其定义（字段、记录类型、公式、提醒、类别和评分标准）。一棵树可以供你的多个收藏使用：对它的修改对所有收藏生效。',
        'Grupos' => '分组',
        'Usada por' => '被使用于',
        'nenhuma coleção' => '没有收藏',
        'Renomear ou copiar' => '重命名或复制',
        'Nome da árvore' => '树的名称',
        'Cópia de {1}' => '{1} 的副本',
        'Nome da cópia' => '副本名称',
        'Copiar' => '复制',
        'Pedir acesso' => '申请访问',
        'Esperando resposta' => '等待回复',
        'O quê' => '内容',
        'Pedido em' => '申请于',
        'Há {1} convite(s) para o seu e-mail: aceite pelo link que chegou nele.' => '有 {1} 个发给你邮箱的邀请：请通过邮件中的链接接受。',
        'O dono (ou o administrador) aprova. Pedidos sem resposta saem sozinhos depois de alguns dias.' => '由所有者（或管理员）批准。没有回复的请求几天后会自动删除。',
        'Seus dados' => '你的资料',
        'Login: {1}' => '登录名：{1}',
        'demonstração' => '演示',
        'desde {1}' => '自 {1}',
        'seu código: {1}' => '你的编号：{1}',
        'Alguém quer ver as suas coleções? Passe o seu código ({1}) para todas elas, também as que você criar depois, ou o código de uma coleção só (na coluna Código da tabela Coleções). A pessoa pede acesso com ele, na Criar conta ou em Minha conta; você recebe um e-mail e aprova ou recusa em Aprovações. Ninguém vê o seu login antes de você aprovar.' => '有人想看你的收藏？把你的编号（{1}）给他，可访问你的全部收藏，包括以后创建的；或者给他单个收藏的编号（在“收藏”表格的“编号”列中）。对方在“创建账户”或“我的账户”中凭编号申请访问；你会收到一封电子邮件，并在“审批”中批准或拒绝。在你批准之前，没有人能看到你的登录名。',
        'Conta de demonstração: vence em {1} dias ({2}). Depois disso, ela e as suas coleções são apagadas. Para continuar, peça ao administrador para torná-la oficial.' => '演示账户：将在 {1} 天后到期（{2}）。到期后，它和你的收藏都会被删除。如需继续使用，请让管理员把它转为正式账户。',
        'Fuso horário' => '时区',
        'O da coleção ({1})' => '收藏的（{1}）',
        'O do navegador (neste aparelho: {1})' => '浏览器的（本设备：{1}）',
        'Senha atual (só para trocar a senha)' => '当前密码（仅修改密码时需要）',
        'O e-mail serve para recuperar a senha, receber os convites e os avisos da conta. Trocou a senha: o navegador pede o login de novo.' => '电子邮件用于找回密码以及接收邀请和账户通知。修改密码后，浏览器会再次要求登录。',
        'O fuso horário vale para tudo o que você vê e digita (a Hora certa, os lançamentos, os avisos); quem divide a coleção com você vê cada hora no fuso dele. O dia do rodízio (o plano, o relógio do dia, as rodadas) é sempre o da coleção. Agora: {1}.' => '时区适用于你查看和输入的一切（准确时间、记录、提醒）；与你共享收藏的人按他自己的时区查看每个时间。轮换的日子（计划、当日手表、各轮次）始终以收藏为准。当前：{1}。',
        'Tokens de API' => 'API 令牌',
        'Para scripts e automações (cabeçalho X-Api-Token): o token vale como o seu login, com as suas coleções. Ele só aparece quando é criado.' => '用于脚本和自动化（X-Api-Token 请求头）：令牌等同于你的登录，带有你的收藏。它只在创建时显示。',
        'Token {1}:' => '令牌 {1}：',
        'Criado em' => '创建于',
        'Último uso' => '最后使用',
        'Revogar' => '撤销',
        'onde vai usar (ex.: atalho do celular)' => '用在哪里（例如：手机快捷指令）',
        'Nome do token' => '令牌名称',
        'Criar token' => '创建令牌',
        'Este aparelho está lembrado desde {1}: o aplicativo (e este navegador) entra sem pedir a senha.' => '此设备自 {1} 起已被记住：应用（和此浏览器）无需密码即可进入。',
        'Esquecer este aparelho' => '忘记此设备',
        'O sistema passa a entrar sem pedir a senha neste aparelho (só nele; a chave fica guardada no navegador, e você pode esquecer quando quiser).' => '系统将在此设备上无需密码即可进入（仅此设备；密钥保存在浏览器中，你随时可以忘记它）。',
        'Lembrar este aparelho' => '记住此设备',
        'Você já está no aplicativo.' => '你已经在应用中。',
        'Instalar o aplicativo' => '安装应用',
        'No iPhone e no iPad: abra o sistema no Safari, toque em Compartilhar e em Adicionar à Tela de Início.' => '在 iPhone 和 iPad 上：在 Safari 中打开系统，点按“共享”，再点按“添加到主屏幕”。',
        'No menu do navegador: Instalar aplicativo (ou Adicionar à tela inicial). Se o botão de instalar aparecer aqui, é só tocar nele.' => '在浏览器菜单中：安装应用（或添加到主屏幕）。如果安装按钮出现在这里，点一下即可。',
        'As notificações (o relógio do dia, a véspera e os avisos) chegam ao aparelho pelo quadro de baixo, {1}; no iPhone, só de dentro do aplicativo instalado. O que chega se escolhe na página Avisos, em Destinos.' => '通知（当日手表、前一天和提醒）通过下方的框 {1} 送达设备；在 iPhone 上，只能从已安装的应用内接收。接收的内容在提醒页的“推送目标”中选择。',
        'Notificações neste aparelho' => '此设备上的通知',
        'Aparelho lembrado' => '已记住的设备',
        '(sem nome)' => '（无名称）',
        '(este)' => '（此设备）',
        'Esquecer' => '忘记',
        'Aplicativo no celular' => '手机上的应用',
        'O sistema vira um aplicativo no seu celular ou tablet: um ícone na tela inicial, abrindo em tela cheia, entrando sem pedir a senha e recebendo as notificações. Três passos, feitos no aparelho em que você quer o aplicativo:' => '系统会变成你手机或平板上的应用：主屏幕上的图标、全屏打开、无需密码进入并接收通知。在你想安装应用的设备上完成三步：',
        'Lembrar este aparelho.' => '记住此设备。',
        'Instalar.' => '安装。',
        'Ligar as notificações.' => '开启通知。',
        'Os aparelhos lembrados (trocar a senha esquece todos):' => '已记住的设备（更改密码会忘记全部）：',
        'Aplicativo instalado: abra pelo ícone na tela inicial.' => '应用已安装：从主屏幕的图标打开。',
        'A instalação foi cancelada.' => '安装已取消。',
        'Notificações neste aparelho (Web Push)' => '此设备上的通知（Web Push）',
        'O Web Push não está configurado no servidor (VAPID_PUBLICA e VAPID_PRIVADA no config.php).' => '服务器未配置 Web Push（config.php 中的 VAPID_PUBLICA 和 VAPID_PRIVADA）。',
        'Este navegador não recebe notificações (no iPhone, primeiro instale o aplicativo: o quadro Aplicativo no celular, acima).' => '此浏览器不接收通知（在 iPhone 上，请先安装应用：上方的“手机上的应用”框）。',
        'Ligue para receber neste aparelho as mensagens dos destinos do tipo Web Push que apontam para você.' => '开启后，此设备将接收指向你的 Web Push 推送目标的消息。',
        'Receber notificações neste aparelho' => '在此设备上接收通知',
        'Aparelho' => '设备',
        'Desligar' => '关闭',
        'Mandar uma notificação de teste' => '发送一条测试通知',
        'Chaves do Web Push (master)' => 'Web Push 密钥（master）',
        'Gera um par novo de chaves VAPID para pôr no config.php. Trocar as chaves desliga os aparelhos já inscritos.' => '生成一对新的 VAPID 密钥，放入 config.php。更换密钥会使已订阅的设备失效。',
        'Gerar chaves' => '生成密钥',
        'as notificações foram bloqueadas no navegador' => '通知已在浏览器中被阻止',
        'Não consegui ligar as notificações: {1}' => '无法开启通知：{1}',
        'SSL (desde o começo)' => 'SSL（从一开始）',
        'TLS (STARTTLS)' => 'TLS（STARTTLS）',
        'sem criptografia' => '不加密',
        'usuário {1}' => '用户 {1}',
        'sem usuário' => '没有用户',
        'senha definida' => '已设置密码',
        'sem senha' => '没有密码',
        'Método' => '方法',
        'SMTP (o servidor de e-mail do config.php)' => 'SMTP（config.php 中的邮件服务器）',
        'mail() do PHP (o sendmail do servidor)' => 'PHP 的 mail()（服务器的 sendmail）',
        'desligado' => '已关闭',
        'Remetente' => '发件人',
        'falta' => '缺少',
        'SMTP (envio)' => 'SMTP（发送）',
        'IMAP (cópia em Enviados)' => 'IMAP（在“已发送”中保存副本）',
        'pasta {1}' => '文件夹 {1}',
        'não configurado (opcional)' => '未配置（可选）',
        'POP (só o teste da conta)' => 'POP（仅用于测试账户）',
        'Servidor de e-mail (master)' => '邮件服务器（master）',
        'O sistema manda e-mail pelo que está no config.php (EMAIL_METODO, EMAIL_REMETENTE, SMTP_*, IMAP_*, POP_*): os convites, o Esqueci a senha, os avisos da conta e os destinos do tipo e-mail. Aqui está o que ele leu de lá, e o teste.' => '系统按照 config.php 中的设置（EMAIL_METODO、EMAIL_REMETENTE、SMTP_*、IMAP_*、POP_*）发送电子邮件：邀请、忘记密码、账户通知以及电子邮件类型的目的地。这里是系统从中读到的内容，以及测试。',
        'Parte' => '部分',
        'O que o sistema leu do config.php' => '系统从 config.php 读到的内容',
        'Para corrigir no config.php:' => '需要在 config.php 中修改：',
        'Testar as conexões (sem mandar nada)' => '测试连接（不发送任何内容）',
        'para quem' => '发给谁',
        'Mandar um e-mail de teste' => '发送一封测试邮件',
        'O teste conecta e entra no SMTP (sem mandar nada), no IMAP (e confere a pasta Enviados) e no POP; o e-mail de teste passa por tudo isso e sai de verdade. A conversa com os servidores aparece embaixo, sem as senhas.' => '测试会连接并登录 SMTP（不发送任何内容）、IMAP（并检查“已发送”文件夹）和 POP；测试邮件会经过以上全部步骤并真正发出。与服务器的对话显示在下方，不含密码。',
        'SMTP' => 'SMTP',
        'IMAP' => 'IMAP',
        'POP' => 'POP',
        'E-mail de teste' => '测试邮件',
        'Resultado do teste' => '测试结果',
        'ok' => '正常',
        'falhou' => '失败',
        'Nada para testar: o envio está desligado.' => '没有可测试的内容：发送已关闭。',
        'Conversa com os servidores' => '与服务器的对话',
        'Excluir a conta' => '删除账户',
        'Sai a conta com tudo o que é dela: as suas coleções (com os relógios, o histórico e os arquivos), as suas árvores, os seus acessos e os seus tokens. Antes de apagar, a API mostra tudo o que sai junto.' => '账户会连同其所有内容一起删除：你的收藏（包括手表、历史和文件）、你的树、你的访问权限和令牌。删除前，API 会显示所有一并删除的内容。',
        'Excluir a minha conta' => '删除我的账户',
        'Minha conta' => '我的账户',
        '{1} pedido(s) ou convite(s) esperam a sua resposta em {2}.' => '有 {1} 个请求或邀请在 {2} 中等待你的回复。',
        'Para convidar alguém para as suas coleções, ou ver quem as vê: {1}.' => '要邀请别人查看你的收藏，或查看谁能看到它们：{1}。',
        'Não consegui ler a conta: {1}' => '无法读取账户：{1}',
        'Inteligente' => '智能',
        'vai o relógio com a maior nota nos critérios' => '选规则评分最高的手表',
        'Inteligente com sorteio' => '智能抽选',
        'sorteio em que a nota de cada relógio é a chance dele: variedade sem perder o critério' => '每块手表的评分就是它的中签概率：既有变化又不失规则',
        'Totalmente aleatório' => '完全随机',
        'todos com a mesma chance, sem olhar os critérios (os números do RANDOM.ORG; fora do ar, do ANU QRNG; sem os dois, do gerador seguro do PHP)' => '所有手表机会均等，不看规则（数字来自 RANDOM.ORG；不可用时来自 ANU QRNG；两者都不可用时来自 PHP 的安全生成器）',
        'Fila (FIFO)' => '队列（FIFO）',
        'vai o que está há mais tempo sem uso: todos passam pelo pulso em rodízio' => '选闲置最久的：所有手表轮流戴',
        'Critérios de escolha do relógio' => '手表的选择规则',
        'Não foi salvo:' => '未保存：',
        'Como a nota funciona' => '评分是如何计算的',
        'Cada {1} — todos os relógios, um grupo em qualquer nível da árvore, ou um relógio — pode ter o seu {2}. O relógio usa o conjunto {3}, inteiro: o dele; senão o do grupo dele; senão o do grupo de cima; e assim até o de todos os relógios. Um lugar sem conjunto próprio herda o de cima.' => '每个{1}——所有手表、树中任意层级的分组，或一块手表——都可以有自己的{2}。手表整体使用{3}的那一组：它自己的；没有则用它所在分组的；再没有则用上一级分组的；依此类推，直到所有手表的那一组。没有自己规则组的位置继承上一级的。',
        'lugar' => '位置',
        'conjunto de critérios' => '规则组',
        'mais perto dele' => '离它最近',
        'Num conjunto, cada {1} tem um peso, e a soma fecha 100%. Cada parâmetro tem {2}, com peso dentro dele, que também fecha 100%. Cada subparâmetro mede uma coisa do relógio e usa {3} para transformar o valor medido numa nota de 0 a 100. {4} = peso do subparâmetro × peso do parâmetro; {5} = soma de nota × peso efetivo. Subparâmetro sem medida para o relógio (autonomia num relógio que não é smartwatch, por exemplo) sai da conta, e os pesos dos que ficam são reescalados.' => '在一个规则组中，每个{1}都有一个权重，总和为 100%。每个参数下有若干{2}，各自在参数内有权重，总和也为 100%。每个子参数衡量手表的一个方面，并用{3}把测量值转换成 0 到 100 的评分。{4} = 子参数权重 × 参数权重；{5} = 评分 × 有效权重之和。对手表没有测量值的子参数（例如非智能手表的续航）不参与计算，其余子参数的权重会重新按比例分配。',
        'parâmetro' => '参数',
        'subparâmetros' => '子参数',
        'faixas' => '区间',
        'Peso efetivo' => '有效权重',
        'nota final' => '最终评分',
        'Como a nota vira escolha' => '评分如何变成选择',
        'Cada modo de rodízio tem a sua forma de escolher o relógio, escolhida no quadro {1}, na página Hoje:' => '每种轮换模式都有自己的选表方式，在“今天”页面的 {1} 方框中选择：',
        'Modo de rodízio' => '轮换模式',
        'Forma de escolha' => '选择方式',
        '(o modo atual)' => '（当前模式）',
        'sempre pela maior nota, com as medidas de cada dia simulado' => '始终按最高评分，使用每个模拟日的测量值',
        'Garantia de rodízio: {1} (no mesmo quadro). Fora da nota também valem o grupo de cada bloco de dias, os relógios fixos e não repetir o de ontem.' => '轮换保证：{1}（在同一个方框中）。评分之外，每个区块的分组、固定手表以及不重复昨天的手表也同样适用。',
        'nenhum relógio fica mais de {1} dias sem uso' => '任何手表都不会超过 {1} 天不戴',
        'desligada' => '已关闭',
        'Onde há critérios' => '哪里有规则',
        'Lugar' => '位置',
        'Parâmetros' => '参数',
        'Usado por' => '使用者',
        'relógio' => '块手表',
        'relógios' => '块手表',
        'editar' => '编辑',
        'Nenhum lugar tem critérios: todos os relógios ficam com nota neutra, 50.' => '没有任何位置有规则：所有手表都得中性分 50。',
        'Há relógios sem conjunto nenhum (nota neutra, 50): {1}.' => '有手表没有任何规则组（中性分 50）：{1}。',
        'Editar os critérios de' => '编辑以下位置的规则',
        ' — com critérios próprios' => ' — 有自己的规则',
        '{1} não tem critérios próprios{2}' => '{1} 没有自己的规则{2}',
        ': usa os de {1}.' => '：使用 {1} 的规则。',
        ', e nenhum lugar acima tem: nota neutra, 50.' => '，且上级位置都没有：中性分 50。',
        'Criar critérios próprios, copiando os de {1}' => '创建自己的规则，复制 {1} 的规则',
        'Criar vazio' => '创建空的',
        'Critérios de {1}' => '{1} 的规则',
        'Usado por {1} {2}{3}. Os lugares abaixo deste, sem critérios próprios, também usam estes.' => '使用者：{1} {2}{3}。此处以下没有自己规则的位置也使用这些规则。',
