{3}',
        'O peso dele é dividido na proporção dos que ficam:
{1}' => '它的权重会按比例分给剩下的参数：
{1}',
        'Era o único: o lugar fica sem critérios próprios e volta a herdar os de cima.' => '这是唯一的参数：该位置将没有自己的规则，重新继承上级的规则。',
        'Novo parâmetro {1}' => '新参数 {1}',
        'Peso (%) {1}' => '权重（%）{1}',
        'Incluir' => '添加',
        'Os outros deste conjunto abrem espaço na proporção de cada um.' => '此规则组中的其他参数会按各自比例让出空间。',
        'Excluir todos os critérios próprios de {1}?

{2}' => '删除 {1} 自己的所有规则？

{2}',
        'Passa a usar os de {1}.' => '改为使用 {1} 的规则。',
        'Os relógios sem conjunto mais perto ficam com nota neutra, 50.' => '没有更近规则组的手表将得中性分 50。',
        'Excluir os critérios próprios de {1}{2}' => '删除 {1} 自己的规则{2}',
        ' (volta a usar os de {1})' => '（改回使用 {1} 的规则）',
        '{1} do conjunto de {2}' => '{2} 规则组中的{1}',
        'Subparâmetro' => '子参数',
