        'Cada relógio' => '每块手表',
        'Do mais usado ao menos usado no período. Dias de uso: os dias em que ele foi ao pulso. A parte: das horas no pulso de todos. Custo por uso: o valor pago dividido por todos os dias de uso (desde sempre). Tendência: as horas da segunda metade do período comparadas com as da primeira.' => '按该时段内佩戴从多到少排列。佩戴天数：戴到手腕上的天数。占比：在所有手表佩戴总时长中所占的比例。每次佩戴成本：购买价格除以全部佩戴天数（自始至今）。趋势：时段后半段的时长与前半段相比。',
