        'Estado {1}' => '状态 {1}',
        '{1} {2} com esses filtros{3}. Os trechos são contínuos: em uso (pelo rodízio, ou fora do plano: no pulso sem ser o relógio do dia), em cada tipo de sessão (no winder, no sol...) e em repouso; as marcações (corda, carga, pilha, revisão) não têm fim nem duração.' => '{1} {2}（按这些筛选条件）{3}。各时段是连续的：使用中（经轮换，或在计划之外：戴在手腕上但不是当天的手表）、各种会话类型（在上链盒上、晒太阳……）以及休息中；标记（上链、充电、电池、保养）没有结束时间和时长。',
