        'Vai o relógio com a maior nota nos critérios. Previsível: com os mesmos dados, a mesma escolha.' => '选择标准得分最高的手表。可预测：数据相同，选择也相同。',
        'Sorteio em que a nota de cada relógio é a chance dele: quem tem nota maior sai mais vezes, mas todos têm chance. Variedade sem perder o critério.' => '抽选时每块手表的得分就是它的机会：得分高的被选中更多，但每块都有机会。在保持标准的同时增加变化。',
        'Todos os relógios do tipo têm a mesma chance, sem olhar os critérios. Os números vêm do RANDOM.ORG (ruído atmosférico); fora do ar, do ANU QRNG (quântico); sem os dois, do gerador seguro do PHP.' => '该类型的所有手表机会均等，不考虑标准。随机数来自 RANDOM.ORG（大气噪声）；它不可用时来自 ANU QRNG（量子）；两者都不可用时，使用 PHP 的安全生成器。',
        'Vai o que está há mais tempo sem uso: todos passam pelo pulso, em fila. Não olha os critérios, e já garante o rodízio por natureza.' => '选择最久未用的那块：所有手表依次上腕。不考虑标准，本身就保证了轮换。',
        'Dia' => '日期',
