        'Um relógio para a semana inteira, de {1} a {2}, escolhido pelo critério.' => '整周一块手表，从{1}到{2}，按标准选出。',
        'Dois trechos na semana: segunda a sexta e o fim de semana, cada um com o seu grupo, um relógio para o trecho ou um por dia.' => '一周分两段：周一到周五和周末，各有自己的分组，每段一块手表或每天一块。',
        'Um relógio por dia, e cada dia da semana diz de onde ele sai.' => '每天一块手表，每个星期几决定它来自哪里。',
        'Um relógio por dia, todos com a mesma chance, sem critério nem garantia de rodízio.' => '每天一块手表，机会均等，没有标准也没有轮换保证。',
        'Monta o plano do período inteiro de uma vez, simulando a carga de cada relógio dia a dia, com os lembretes de carregar, dar corda e pôr no sol. É refeita toda manhã a partir do estado real.' => '一次性为整个期间制定计划，逐日模拟每块手表的电量，并提醒充电、上链和晒太阳。每天早上根据实际状态重新制定。',
        'O roteiro escrito à mão decide quem é candidato em cada dia, a nota, o peso, os dias seguidos e a garantia.' => '手写的脚本决定每天谁是候选、分数、权重、连续天数和保证。',
        'Modo de rodízio {1}' => '轮换模式 {1}',
        'Rodízio manual' => '手动轮换',
        'Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe), "Sortear este dia por" (uma forma de escolha) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre ({1}).' => '你为一段时间内的每一天选择手表。设置开始和结束日期并点击“确定”：日期每 7 天一组显示，每天都有手表列表、“替我决定”（由系统选择）、“按以下方式为这一天抽签”（一种选择方式）和“不戴表（空闲日）”。在这段时间之外，仍按平常的轮换模式（{1}）。',
        'nenhum' => '无',
        'período de {1} dias' => '{1} 天的周期',
        'esta semana' => '本周',
        '{1} semanas à frente' => '向前 {1} 周',
        ' · com ciclo' => ' · 带循环',
        'editar o modo' => '编辑模式',
        'Como escolher o relógio {1}' => '如何选择手表 {1}',
        'Como escolher o relógio: {1}' => '如何选择手表：{1}',
        'pela maior nota' => '按最高分',
        'A escala escolhe sempre pela maior nota nos critérios, com as medidas de cada dia simulado.' => '排程总是按标准的最高分选择，并使用每个模拟日的测量值。',
        'O roteiro do modo diz a nota e o peso de cada relógio; mude-o nos Modos de rodízio.' => '模式的脚本给出每块手表的分数和权重；在轮换模式中修改它。',
        'Garantia de rodízio: dias sem uso, no máximo {1}' => '轮换保证：未使用天数，最多 {1}',
        'Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota.' => '超过上限的优先，闲置最久的排在最前。0 表示关闭。同一数值适用于所有使用分数的模式。',
        'A nota vem dos {1}, que você cadastra.' => '分数来自你定义的{1}。',
        'Aplicar modo' => '应用模式',
        'Aplicar só marca o modo (e grava o critério e a garantia): o plano gravado continua como está, e o modo vale para os próximos sorteios. Para refazer o plano com ele, use "Sortear de novo", embaixo. Os modos, as semanas e o roteiro se cadastram em {1}.' => '应用只是标记模式（并保存标准和保证）：已保存的计划保持原样，该模式用于接下来的抽签。要用它重做计划，请使用下方的“重新抽签”。模式、周数和脚本在{1}中设置。',
        'Modos de rodízio' => '轮换模式',
        'o fim da escala' => '排程结束',
        'o fim da próxima semana' => '下一周结束',
        'a partir de amanhã' => '从明天起',
        'Refaz o plano de amanhã até {1} pelo modo atual; hoje continua o {2}.' => '按当前模式重新制定从明天到 {1} 的计划；今天仍是 {2}。',
        'Sortear de novo a partir de amanhã? Hoje continua o {1}.' => '从明天起重新抽选？今天仍是 {1}。',
        'inclusive hoje' => '包括今天',
        'Refaz também hoje: se sair outro relógio, ele passa a ser o do pulso a partir de agora, e o {1} sai.' => '今天也重做：如果抽到另一块手表，它从现在起成为佩戴的手表，{1} 取下。',
        'Sortear de novo inclusive hoje? Se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora, e o {1} sai.' => '重新抽选并包括今天？如果今天抽到另一块手表，它从现在起成为佩戴的手表，{1} 取下。',
        'a partir de hoje' => '从今天起',
        'Refaz o plano de hoje até {1} pelo modo atual (o dia ainda não começou no pulso).' => '按当前模式重新制定从今天到 {1} 的计划（今天还没有开始佩戴）。',
        'Sortear de novo a partir de hoje?' => '从今天起重新抽选？',
        'a próxima semana ({1} a {2})' => '下一周（{1} 至 {2}）',
        '{1} a semana seguinte inteira, de {2} a {3}, pelo modo atual, com os dias que ainda faltam desta semana já contados como uso. Os dias escolhidos à mão ficam.' => '{1}整个下一周，从{2}到{3}，按当前模式，本周剩下的日子已算作佩戴。手动选择的日子保留。',
        'Refaz' => '重新抽选',
        'Monta' => '制定',
        '{1} a semana de {2} a {3}?{4}' => '{1} {2} 至 {3} 这一周？{4}',
        'Sortear de novo' => '重新抽选',
        'Montar' => '制定',
        ' O que já estava montado para ela é refeito.' => ' 已为该周制定的内容将重做。',
        ' Com Sobrescrever tudo marcado, sai tudo o que o plano tem desse dia em diante, inclusive os dias escolhidos à mão e os dias livres, e o modo sorteia de novo.' => '勾选“全部覆盖”后，计划中从那天起的所有内容都会被清除，包括手动选择的日子和空闲日，然后模式重新抽签。',
        'Sortear' => '抽选',
        'Sobrescrever tudo' => '全部覆盖',
        'Marcada, sai tudo o que o plano tem do começo do sorteio em diante: os dias escolhidos à mão, os dias livres e os sorteados; depois o modo monta tudo de novo. Desmarcada, os dias à mão e os livres ficam como estão.' => '勾选时，计划中从抽签开始那天起的所有内容都会被清除：手动选择的日子、空闲日和抽出的日子；然后模式重新编排全部。不勾选时，手动选择的日子和空闲日保持原样。',
