        'Página {1} de {2} · {3}{4}, de {5} a {6}. O que você escolhe fica guardado enquanto você anda pelas páginas; nada muda antes de gravar.' => '第 {1} 页，共 {2} 页 · {3}{4}，{5} 至 {6}。你在翻页时所做的选择会保留；保存之前不会有任何改变。',
        'Gravar o rodízio manual' => '保存手动轮换',
        'Para apagar os dias de um período (o modo de rodízio monta esses dias de novo): "Apagar um período", embaixo deste quadro, ou na página {1}.' => '要删除一个时段的日子（轮换模式会重新安排这些日子）：在这个框下方或{1}页面的“清除一个时段”。',
        'Plano' => '计划',
