        'Gravar o rodízio manual de {1} a {2}? Os dias ficam com os relógios escolhidos; os de "Decida por mim" são decididos agora pelo sistema.' => '保存 {1} 至 {2} 的手动轮换？这些日子使用所选的手表；设为“替我决定”的由系统现在决定。',
