        'Nenhum relógio com esses filtros.' => '没有符合这些筛选条件的手表。',
        'Inteligente: a maior nota' => '智能：评分最高者',
        'Inteligente com sorteio: a nota é a chance' => '智能抽选：评分即概率',
        'Fila: o que está há mais tempo sem uso' => '队列：闲置最久者',
        'Uma semana' => '一周',
