        'Um ano' => '一年',
        'Dois anos' => '两年',
        'Um relógio para a semana inteira, do primeiro ao último dia dela (a semana começa no dia da Configuração). Escolha de onde ele sai e o critério; o Sortear de novo sorteia um para cada semana.' => '整周一块手表，从这一周的第一天到最后一天（每周从设置中的那天开始）。选择它来自哪里以及标准；重新抽签为每周抽出一块。',
        'Dois trechos na semana: de segunda a sexta e no fim de semana, cada um com o seu grupo e com um relógio para o trecho inteiro ou um por dia.' => '一周分两段：周一到周五和周末，各有自己的分组，整段一块手表或每天一块。',
        'Um relógio por dia, e cada dia da semana diz de onde ele sai: um grupo, um relógio fixo ou nenhum (dia livre).' => '每天一块手表，每个星期几决定它来自哪里：一个分组、一块固定手表或没有（空闲日）。',
        'Um relógio por dia, todos com a mesma chance, sem olhar os critérios nem a garantia de rodízio. O de ontem fica de fora, se houver outro.' => '每天一块手表，机会均等，不看标准也不看轮换保证。如果有其他手表，昨天的会被排除。',
        'Planeja o período inteiro de uma vez, simulando dia a dia a carga de cada relógio: a maior nota do dia simulado, o smartwatch pelos dias que a bateria dá (a fórmula dias_seguidos), os lembretes de carregar e dar corda anotados no dia. É refeita toda manhã a partir do estado real.' => '一次规划整个周期，逐日模拟每块手表的电量：模拟日的最高分数，智能手表按电池能撑的天数（dias_seguidos 公式），充电和上链提醒记在当天。每天早上根据真实状态重做。',
        'Você escreve o roteiro: uma linha por nome, e o motor lê candidato, nota, peso, dias e garantia (o que faltar usa o padrão). Vale tudo o que vale numa fórmula do cadastro.' => '你来写脚本：每个名称一行，引擎读取 candidato、nota、peso、dias 和 garantia（缺少的使用默认值）。公式中能用的这里都能用。',
        'Toda a coleção' => '整个收藏',
        'Um grupo' => '一个分组',
        'Um relógio fixo' => '一块固定手表',
        ' (um para o bloco)' => '（整段一块）',
        'Semana {1}: {2} a {3}' => '第 {1} 周：{2} 至 {3}',
        '(esta)' => '（本周）',
        'Escolher de {1}' => '选择来源 {1}',
        'Período {1}' => '期间 {1}',
        '{1} dias' => '{1} 天',
        'Segunda a sexta' => '周一到周五',
        'um relógio para os cinco dias' => '五天一块手表',
        'Sábado e domingo' => '周六和周日',
        'um relógio para os dois dias' => '两天一块手表',
        'um relógio por dia' => '每天一块手表',
        'Escolher de' => '选择来源',
        'hoje, ' => '今天，',
        'O roteiro {1}' => '脚本 {1}',
        'Uma linha por nome ("nome = expressão"); linhas que começam com # são comentários. Os nomes que o motor lê: {1} (1 entra na escolha do dia), {2} (a nota), {3} (a chance no sorteio: todos 0, a maior nota ganha; todos iguais, aleatório), {4} (quantos dias seguidos fica) e {5} (1 passa na frente de todos, o mais parado primeiro). Os outros nomes são seus. O que faltar usa o padrão: {6}.' => '每个名称一行（“名称 = 表达式”）；以 # 开头的行是注释。引擎读取的名称：{1}（1 进入当天的选择）、{2}（分数）、{3}（抽签中的机会：全为 0 则最高分数获胜；全相等则随机）、{4}（连续停留多少天）和 {5}（1 排在所有手表之前，闲置最久的优先）。其他名称由你定义。缺少的使用默认值：{6}。',
        'Além das funções das fórmulas: DIA_SEMANA() (1 segunda a 7 domingo), SEMANA_DO_ANO(), NO_GRUPO("grupo"), RELOGIO("nome"), ESCOLHIDO_HA(n) (1 se foi o do plano há n dias), VEZES_NO_PLANO(n), ESCOLHA(n; a; b; ...) (o n-ésimo valor), SORTEIO() (0 a 1) e a variável nota_criterios. A lista completa está em {1}.' => '除公式函数外：DIA_SEMANA()（1 周一到 7 周日）、SEMANA_DO_ANO()、NO_GRUPO("分组")、RELOGIO("名称")、ESCOLHIDO_HA(n)（n 天前是计划中的那块则为 1）、VEZES_NO_PLANO(n)、ESCOLHA(n; a; b; ...)（第 n 个值）、SORTEIO()（0 到 1）以及变量 nota_criterios。完整列表见{1}。',
        'Cadastros › Fórmulas' => '登记 › 公式',
        'no dia {1}' => '在 {1}',
        'Planejar {1} semanas à frente' => '向前规划 {1} 周',
        'O plano vem montado até o último dia da última semana ({1}); a seguinte entra quando a sua vez chega, ou antes, em "Sortear de novo: a próxima semana" (só com mais de uma semana). A semana começa no dia escolhido em {2}.' => '计划编排到最后一周的最后一天（{1}）；下一周轮到时加入，或者更早，在“重新抽签：下一周”中（仅限多于一周时）。每周从{2}中选择的那天开始。',
        'o sábado' => '星期六',
        'o domingo' => '星期日',
        'Critério de escolha (o sorteio) {1}' => '选择标准（抽签）{1}',
        'A garantia de rodízio ({1} dias sem uso, no máximo) vale antes do critério, menos no aleatório; ela se muda no quadro Modo de rodízio da página Hoje e vale para todos os modos. A nota vem dos {2}.' => '轮换保证（最多 {1} 天未使用）在标准之前生效，随机除外；它在今天页面的轮换模式框中修改，对所有模式有效。分数来自{2}。',
        'Critério de escolha: a maior nota do dia simulado (a garantia de rodízio na frente). A nota vem dos {1}.' => '选择标准：模拟日的最高分数（轮换保证优先）。分数来自{1}。',
        'ciclo: um relógio só volta depois que todos os candidatos passaram na semana' => '循环：一块手表只有在本周所有候选都轮过后才会回来',
        'O roteiro que este modo gera (só leitura)' => '此模式生成的脚本（只读）',
        'Para escrever o seu, crie um modo do tipo Personalizado a partir deste: {1}.' => '要编写自己的脚本，请基于此模式创建一个自定义模式：{1}。',
        'copiar este roteiro' => '复制此脚本',
        'Salvar o modo' => '保存模式',
        'Criar o modo' => '创建模式',
        'A semana' => '整周',
        'Todo dia' => '每天',
        'Por dia da semana: escolha de onde sai o relógio em pelo menos um dia.' => '按星期几：至少为一天选择手表的来源。',
        'Cada modo tem um tipo, e a tela do tipo pede só o que faz sentido nele. Por baixo, todos geram o mesmo roteiro (candidato, nota, peso, dias, garantia), que o motor calcula relógio a relógio no começo de cada dia do plano, com os dias anteriores já contados como uso. O de ontem fica de fora, se houver outro; a garantia de rodízio ({1} dias) vale antes do critério; e o ciclo, se ligado, segura quem já passou na semana. Escolher o modo ou o critério não mexe no plano gravado: só o "Sortear de novo" do quadro Modo de rodízio refaz.' => '每个模式有一个类型，类型的界面只要求对它有意义的内容。底层所有模式生成同样的脚本（candidato、nota、peso、dias、garantia），引擎在计划每一天开始时逐块手表计算，之前的日子已计为使用。如果有其他手表，昨天的会被排除；轮换保证（{1} 天）在标准之前生效；循环若开启，会拦住本周已轮过的手表。选择模式或标准不会改动已保存的计划：只有轮换模式框中的“重新抽签”会重做。',
