        'os campos, os lançamentos e os critérios de um grupo valem para tudo abaixo dele (páginas Grupos e Cadastros)' => '一个分组的字段、记录和标准适用于其下的所有内容（“分组”和“定义”页面）',
        'Situação na coleção {1} {2}' => '收藏状态 {1} {2}',
        'fora da coleção, ele sai do rodízio e dos avisos; a ficha e o histórico ficam' => '移出收藏后，它会退出轮换和提醒；档案和历史保留',
