        'de 0 a 100%' => '0 到 100%',
        'A conta' => '计算',
        'de onde vem cada número: no quadro Previsão' => '每个数字的来源：见“预测”面板',
        'Cada leitura comparada com a anterior. Os dois gastos (em uso e fora do pulso) saem juntos de todas as medições {1}, cada uma dividida pelas marcações de pulso minuto a minuto e pesando as horas que cobre (o motor original). O botão de cada linha tira ou põe a medição na conta.' => '每次读数都与上一次比较。两种消耗（使用中和未佩戴）由{1}的所有测量一起得出，每次测量按逐分钟的佩戴标记划分并以其覆盖的小时数为权重（原始引擎）。每行的按钮可将该测量移出或放回计算。',
        'Cada leitura comparada com a anterior. Os dois gastos (em uso e fora do pulso) saem juntos das leituras {1}, todas com o mesmo peso e partindo do cadastro; o gasto de cada linha é só o dela. A leitura que não bate bem com as outras pesa menos na conta, e o botão de cada linha tira ou põe a medição na conta.' => '每次读数都与上一次比较。两种消耗（使用中和未佩戴）由{1}的读数一起得出，全部权重相同并以档案为起点；每行的消耗只是该行自己的。与其他不吻合的读数在计算中权重较低，每行的按钮可将该测量移出或放回计算。',
        'Cada leitura comparada com a anterior. Neste relógio vale só o cadastro (o motor escolhido): as medições ficam aqui, no histórico, e não entram em conta nenhuma.' => '每次读数都与上一次比较。这块手表只使用档案（所选引擎）：测量留在这里的历史中，不进入任何计算。',
        'Cada leitura comparada com a anterior. O gasto em uso sai só das medições com as duas leituras marcadas em uso, e o gasto em repouso só das marcadas em repouso, {1} (o "contar por" da Configuração), todas com o mesmo peso e partindo do cadastro; o gasto de cada linha é só o dela. A leitura que não bate bem com as outras pesa menos na conta, e o botão de cada linha tira ou põe a medição na conta.' => '每次读数都与上一次比较。使用中消耗只来自两次读数都标记为使用中的测量，静置中消耗只来自标记为静置中的测量，{1}（设置中的“按什么计”），全部权重相同并以档案为起点；每行的消耗只是该行自己的。与其他读数不吻合的读数在计算中权重较低，每行的按钮可将该测量移出或放回计算。',
