        'Puxe a coroa com o ponteiro dos segundos no 12 (ele para nos relógios com parada de segundos, o hack), ponha os ponteiros um ou dois minutos à frente e empurre a coroa quando o segundo chegar ao :00 da hora certa. Num relógio com data, troque a data longe da meia-noite (fora das 21h às 3h), para não forçar o mecanismo.' => '在秒针指向 12 时拔出表冠（有停秒功能的手表秒针会停下），把指针调快一两分钟，等准确时间的秒数到 :00 时按回表冠。带日期的手表请在远离午夜时调日期（避开晚上 9 点到凌晨 3 点），以免损伤机芯。',
