        'Diga o código: colecao_id (o código de uma coleção) ou dono_id (o código de um dono, para todas as coleções dele), um ou outro.' => '请提供编号：colecao_id（某个收藏的编号）或 dono_id（某个所有者的编号，用于其全部收藏），二选一。',
        'Diga o alvo: colecao_id (uma coleção) ou dono_id (todas as coleções de um dono), um ou outro.' => '请指定目标：colecao_id（一个收藏）或 dono_id（某个所有者的所有收藏），二选一。',
