        'Informe uma senha de pelo menos 6 caracteres (ou o senha_hash de outro sistema).' => '请填写至少 6 个字符的密码（或来自其他系统的 senha_hash）。',
        'Informe um e-mail válido (para recuperar a senha e receber os avisos da conta).' => '请填写有效的电子邮件（用于找回密码和接收账户通知）。',
        'opcao: modelo (uma coleção com o conjunto inicial), vazia (uma coleção sem nada) ou pedir (pedir acesso a uma coleção ou a tudo de um dono).' => 'opcao：modelo（带初始数据的收藏）、vazia（空收藏）或 pedir（申请访问某个收藏或某个所有者的全部）。',
        'Sem convite, a conta nova precisa de uma coleção (modelo ou vazia) ou de um pedido de acesso (pedir).' => '没有邀请时，新账户需要一个收藏（modelo 或 vazia）或一个访问请求（pedir）。',
        'Este login já existe: escolha outro.' => '该登录名已存在：请换一个。',
        'Este e-mail já tem conta: entre com ela, ou use o Esqueci a senha.' => '该电子邮件已有账户：请用它登录，或使用“忘记密码”。',
        'Conta {1} criada.' => '账户 {1} 已创建。',
