        'Pedido de acesso enviado ({1}): quando for aprovado, a coleção aparece para você.' => '访问请求已发送（{1}）：批准后，该收藏就会出现在你这里。',
        'É uma conta de demonstração de {1} dias: para continuar depois disso, peça ao administrador para torná-la oficial.' => '这是一个 {1} 天的演示账户：如需在此之后继续使用，请让管理员把它转为正式账户。',
        'Relojoeiro: a sua conta {1} foi criada' => 'Relojoeiro：你的账户 {1} 已创建',
        'Olá, {1}. A sua conta no Relojoeiro foi criada. Entre em {2} com o seu login e a sua senha.' => '你好，{1}。你的 Relojoeiro 账户已创建。请在 {2} 用你的登录名和密码登录。',
        'Informe o e-mail ou o login da conta.' => '请填写账户的电子邮件或登录名。',
        'O servidor não envia e-mail: peça ao administrador para trocar a sua senha.' => '服务器不发送电子邮件：请让管理员修改你的密码。',
        'Relojoeiro: trocar a senha de {1}' => 'Relojoeiro：修改 {1} 的密码',
        'Olá, {1}. Para escolher uma senha nova, abra este link (vale por 2 horas): {2}. Se não foi você quem pediu, ignore este e-mail.' => '你好，{1}。要设置新密码，请打开此链接（2 小时内有效）：{2}。如果不是你本人请求的，请忽略此邮件。',
        'Se a conta existe e tem e-mail, o link para trocar a senha foi enviado (vale por 2 horas).' => '如果该账户存在且有电子邮件，修改密码的链接已发送（2 小时内有效）。',
        'Link de senha desconhecido ou vencido: peça outro.' => '密码链接未知或已过期：请重新申请。',
        'Senha trocada: entre com a senha nova.' => '密码已修改：请用新密码登录。',
        'Relojoeiro: {1} pede acesso' => 'Relojoeiro：{1} 申请访问',
        '{1} pede acesso ({2}). Aprove ou recuse em {3} (o pedido vence em {4} dias).' => '{1} 申请访问（{2}）。请在 {3} 批准或拒绝（请求在 {4} 天后过期）。',
        'Relojoeiro: {1} convida você' => 'Relojoeiro：{1} 邀请你',
        '{1} convida você para ver {2} no Relojoeiro. Para aceitar, abra este link (vale até {3}): {4}' => '{1} 邀请你在 Relojoeiro 中查看 {2}。要接受，请打开此链接（有效期至 {3}）：{4}',
        'E-mail inválido.' => '电子邮件无效。',
        'Este e-mail já é de outra conta.' => '该电子邮件已属于另一个账户。',
