        'A senha atual não confere.' => '当前密码不正确。',
        'Conta atualizada. Os aparelhos lembrados foram esquecidos: entre de novo com a senha nova.' => '账户已更新。已记住的设备已被忘记：请用新密码重新登录。',
        'Conta atualizada.' => '账户已更新。',
        'Nada para mudar: mande email, idioma, fuso ou senha (com senha_atual).' => '没有要改的：请发送 email、idioma、fuso 或 senha（附 senha_atual）。',
        'Precisa sobrar pelo menos um master.' => '至少要保留一个 master。',
