        'configurado' => '已配置',
        'Só o master gera as chaves do Web Push.' => '只有 master 能生成 Web Push 密钥。',
        'Chaves novas geradas: copie as duas linhas para o config.php (trocar as chaves desliga os aparelhos já inscritos).' => '已生成新密钥：请把这两行复制到 config.php（更换密钥会使已订阅的设备失效）。',
        'Dê um nome à coleção (até 120 caracteres).' => '请给收藏起个名字（最多 120 个字符）。',
        'opcao: modelo (com o conjunto inicial), vazia (sem nada) ou arvore (com arvore_id: uma árvore sua que já existe).' => 'opcao：modelo（带初始数据）、vazia（空的）或 arvore（配合 arvore_id：你已有的一棵树）。',
        'Árvore não encontrada entre as do dono da coleção.' => '在收藏所有者的树中未找到该树。',
        'Já existe uma coleção com este nome.' => '已存在同名的收藏。',
        'Coleção {1} criada.' => '收藏 {1} 已创建。',
        'Coleção não encontrada entre as suas.' => '在你的收藏中未找到该收藏。',
        'Coleção renomeada para {1}.' => '收藏已重命名为 {1}。',
        'Coleção {1} excluída, com tudo o que era dela{2}. A árvore de grupos continua (use arvore_excluir para tirá-la).' => '收藏 {1} 已删除，连同其所有内容{2}。分组树仍然保留（使用 arvore_excluir 删除它）。',
        'Árvore não encontrada entre as suas.' => '在你的树中未找到该树。',
        'Dê um nome à árvore (até 80 caracteres).' => '请给树起个名字（最多 80 个字符）。',
        'Árvore copiada: {1}. Crie uma coleção com ela (opcao=arvore).' => '树已复制：{1}。用它创建一个收藏（opcao=arvore）。',
        'Árvore renomeada para {1}.' => '树已重命名为 {1}。',
        'Árvore {1} excluída, com as coleções que a usavam{2}.' => '树 {1} 已删除，连同使用它的收藏{2}。',
        'Só o dono (ou o master) tira o acesso de alguém.' => '只有所有者（或 master）能取消别人的访问权限。',
        'Acesso não encontrado (o dono não sai da própria coleção: ele a exclui ou a transfere).' => '未找到该访问权限（所有者不能退出自己的收藏：只能删除或转移它）。',
        'Você não vê mais {1}.' => '你已不能再查看 {1}。',
        '{1} não vê mais {2}.' => '{1} 已不能再查看 {2}。',
        'Você só convida para o que você vê.' => '你只能邀请别人查看你能看到的内容。',
        'Só o dono (ou o master) convida para tudo dele.' => '只有所有者（或 master）能邀请别人查看其全部内容。',
        'Convite enviado para {1}.' => '邀请已发送给 {1}。',
        'Convite criado. O e-mail não saiu: mande este link para {1} (ele só aparece agora).' => '邀请已创建。邮件没有发出：请把此链接发给 {1}（它只在此时显示）。',
        'Convite criado: espera o dono aprovar.' => '邀请已创建：等待所有者批准。',
        'Convite não encontrado.' => '未找到邀请。',
        'Só quem convidou (ou o dono) cancela o convite.' => '只有邀请人（或所有者）能取消邀请。',
        'Só o dono (ou o master) aprova ou recusa o convite.' => '只有所有者（或 master）能批准或拒绝邀请。',
        'Convite recusado.' => '邀请已拒绝。',
        'Convite cancelado.' => '邀请已取消。',
        'O convite ainda espera o dono aprovar.' => '邀请仍在等待所有者批准。',
        'Convite aceito: você vê {1}.' => '邀请已接受：你可以查看 {1}。',
        'Você já pediu este acesso: espere a resposta.' => '你已经申请过这个访问权限：请等待回复。',
        'Pedido não encontrado.' => '未找到请求。',
        'Só quem pediu cancela o pedido.' => '只有申请人能取消请求。',
        'Só o dono (ou o master) aprova ou recusa o pedido.' => '只有所有者（或 master）能批准或拒绝请求。',
        'Relojoeiro: acesso aprovado' => 'Relojoeiro：访问已批准',
        'Relojoeiro: acesso recusado' => 'Relojoeiro：访问被拒绝',
        'Olá, {1}. O seu pedido de acesso foi aprovado ({2}). Entre em {3}.' => '你好，{1}。你的访问请求已获批准（{2}）。请在 {3} 登录。',
        'Olá, {1}. O seu pedido de acesso foi recusado ({2}).' => '你好，{1}。你的访问请求被拒绝了（{2}）。',
        'Pedido aprovado: {1} vê {2}.' => '请求已批准：{1} 可以查看 {2}。',
        'Pedido recusado.' => '请求已拒绝。',
        'Pedido cancelado.' => '请求已取消。',
        'Mande a senha ou o senha_hash, não os dois.' => '请发送密码或 senha_hash，不要同时发送。',
        'senha_hash: um hash que o password_verify do PHP entenda (bcrypt, que começa com $2y$, $2b$ ou $2a$, ou argon2, com $argon2).' => 'senha_hash：PHP 的 password_verify 能识别的哈希（bcrypt，以 $2y$、$2b$ 或 $2a$ 开头，或 argon2，以 $argon2 开头）。',
        'Só o master cria usuários e troca a senha de outro.' => '只有 master 能创建用户和修改他人的密码。',
        'Senha de {1} trocada{2}' => '{1} 的密码已更改{2}',
        ' (pelo hash informado).' => '（按提供的哈希）。',
        'Usuário {1} criado{2}' => '用户 {1} 已创建{2}',
        ' (pelo hash informado: entra com a senha do outro sistema).' => '（按提供的哈希：用其他系统的密码登录）。',
        'A coleção dele foi criada.' => '已为其创建收藏。',
        'Só o master cuida das contas dos outros (as suas coisas ficam em recurso=conta).' => '只有 master 能管理他人的账户（你自己的内容在 recurso=conta 中）。',
        'Usuário não encontrado.' => '找不到用户。',
        'Você não pode excluir o usuário com que está conectado.' => '你不能删除当前登录的用户。',
        'Usuário {1} excluído.' => '用户 {1} 已删除。',
        'papel: master ou comum.' => 'papel：master 或 comum。',
        'Usuário {1} atualizado.' => '用户 {1} 已更新。',
        'Nada para mudar: mande novo_login, email, idioma, fuso ou papel.' => '没有要改的：请发送 novo_login、email、idioma、fuso 或 papel。',
        'A conta {1} agora é oficial (não vence).' => '账户 {1} 现在是正式账户（不会到期）。',
        'dias: de 1 a 3650.' => 'dias：1 到 3650。',
        'A conta do master não vence.' => 'master 的账户不会到期。',
        'A conta {1} vence em {2}.' => '账户 {1} 将于 {2} 到期。',
        'Você não pode bloquear o usuário com que está conectado.' => '你不能封禁当前登录的用户。',
        'A conta {1} está bloqueada: não entra até ser desbloqueada.' => '账户 {1} 已被封禁：在解除封禁前无法登录。',
        'A conta {1} foi desbloqueada.' => '账户 {1} 已解除封禁。',
        'Coleção não encontrada entre as de {1}.' => '在 {1} 的收藏中未找到该收藏。',
