',
        'Senha para {1}: ' => '{1} 的密码：',
        'aviso do PHP: {1} ({2}:{3})' => 'PHP 警告：{1}（{2}:{3}）',
        'erro fatal: {1} ({2}:{3})' => '致命错误：{1}（{2}:{3}）',
