' => '{1}
通过命令行：php criar_usuario.php <login>
',
        'o config.php não define API_TOKEN' => 'config.php 没有定义 API_TOKEN',
        'API_TOKEN no config.php tem de ser um texto, entre aspas' => 'config.php 中的 API_TOKEN 必须是文本，放在引号中',
        'semente de teste' => '测试种子',
        '{1} em {2}' => '{1}，于 {2}',
        'todos os relógios' => '所有手表',
        'Número inteiro' => '整数',
        'Número decimal' => '小数',
        'Sim ou não (nas contas: 1 ou 0)' => '是或否（计算中：1 或 0）',
        'Data (nas contas: por DIAS_DESDE, DIAS_ATE e SOMA_MESES)' => '日期（计算中：用 DIAS_DESDE、DIAS_ATE 和 SOMA_MESES）',
        'Lista de opções (compara e dá faixa por categoria)' => '选项列表（比较并按类别给出区间）',
        'Texto (compara e dá faixa por categoria)' => '文本（比较并按类别给出区间）',
        'tem de ser um número inteiro' => '必须是整数',
        'tem de ser um número' => '必须是数字',
        'tem de ser sim ou não' => '必须是“是”或“否”',
        'tem de ser uma data AAAA-MM-DD' => '必须是日期 YYYY-MM-DD',
        'tem de ser uma das opções: {1}' => '必须是以下选项之一：{1}',
        'passa de 1000 caracteres' => '超过 1000 个字符',
        'Instantâneo' => '瞬时',
        'Instantâneo com valor' => '带数值的瞬时',
        'Sessão, com início e fim' => '会话，有开始和结束',
        'lançamentos pela API, com sessões exclusivas (o relógio num lugar só), avisos cadastráveis e a autonomia restante' => '通过 API 记录，带独占会话（手表只在一个地方）、可配置的提醒和剩余续航',
        'modos de rodízio cadastráveis, o plano, os critérios por lugar e o cron' => '可配置的轮换模式、计划、按位置的标准和 cron',
        'a escala inteligente, os eventos personalizados, o Google Agenda, a previsão do smartwatch e a linha do tempo' => '智能排程、自定义事件、Google 日历、智能手表预测和时间线',
        'as telas e as mensagens do sistema antigo: canais com mensagem padrão e personalizada, avisos de carga baixa e de leitura, limite do solar, e o registro completo do cron' => '旧系统的界面和消息：带默认和自定义消息的渠道、低电量和读数提醒、太阳能限值，以及完整的 cron 日志',
        'o gasto medido pelas leituras (a média dos últimos dias) e as autonomias em segundos' => '通过读数测得的消耗（最近几天的平均值）以及以秒计的续航',
        'o ciclo no rodízio (opção de cada modo, desligada por padrão): um relógio só volta depois que todos do bloco passaram' => '轮换中的周期（每个模式的选项，默认关闭）：一块手表要等该块中所有手表都轮过之后才会再出现',
        'a condição "vale quando" nos tipos de lançamento e nos avisos; o automático sem corda recebe "Pôr no winder" em vez de "Dar corda"' => '记录类型和提醒中的“适用条件”；不能手动上链的自动表会收到“放上上链盒”，而不是“上链”',
        'o limite de carga, geral e por relógio: carregar, pôr no sol e dar corda só quando a carga chega a ele' => '电量限值，整体和每块手表：只在电量降到限值时才充电、晒太阳和上链',
        'os avisos de carga pelo estado de agora: no winder ou no pulso (o automático carrega no pulso), sem aviso de winder ou de corda; no sol, sem aviso de sol; a data do "Carregar" pelo gasto de agora (no pulso, o de uso; guardado, o de guardado)' => '按当前状态的电量提醒：在上链盒上或佩戴时（自动表佩戴时会充能），没有上链盒或上链提醒；晒太阳时，没有晒太阳提醒；“充电”日期按当前消耗计算（佩戴时用使用消耗；存放时用存放消耗）',
        'o motivo de cada escolha do plano: por que aquele relógio saiu naquele dia (a garantia de rodízio, a nota, o sorteio, a escolha à mão)' => '计划中每次选择的原因：为什么那天选中那块手表（轮换保证、分数、抽选、手动选择）',
        'os dias sem uso de um relógio nunca usado contam desde a compra (antes valiam 9999 para todos: empatavam na garantia de rodízio)' => '从未佩戴过的手表的未使用天数从购买日算起（以前全部记为 9999：在轮换保证中打平）',
        'o manual de cada relógio: um arquivo (PDF ou imagem) guardado no banco, que se envia e se abre pela ficha' => '每块手表的说明书：保存在数据库中的一个文件（PDF 或图片），在档案中上传和打开',
        'os documentos de cada relógio: qualquer arquivo (manual, nota fiscal em PDF e em XML, fotos, vídeos, diversos), numa categoria, com a página Documentos (galeria, vídeos em sequência, visualizador de PDF, resumo da nota); os manuais da v13 passam para lá' => '每块手表的文件：任何文件（说明书、PDF 和 XML 格式的发票、照片、视频、其他），归入一个类别，配有“文件”页面（图库、连续播放视频、PDF 查看器、发票摘要）；v13 的说明书移到那里',
        'a cópia de segurança de cada documento dentro do banco (em pedaços de 4 MB): o arquivo que sumir da pasta volta sozinho do banco; o cron copia os que já existem e limpa a pasta (relógio excluído, arquivo sem documento)' => '每个文件在数据库中的备份（按 4 MB 分块）：从文件夹中消失的文件会自动从数据库恢复；cron 会复制已有的文件并清理文件夹（已删除的手表、没有对应文件记录的文件）',
        'o banco no modelo relacional estrito: toda ligação é chave estrangeira, com cascata (ou, se opcional, desfazendo a ligação); as listas guardadas num campo (dias dos blocos e dos eventos, tipos aceitos, opções de um campo) viram tabelas; as mensagens e os canais saem da configuração para a tabela canal_aviso; o modo ativo vira uma marca no modo; a tabela manual sai (os manuais viram documentos)' => '严格关系模型的数据库：每个关联都是外键，级联删除（可选关联则解除关联）；保存在一个字段中的列表（块和事件的日期、接受的类型、字段的选项）变成表；消息和渠道从设置移到 canal_aviso 表；当前模式变成模式上的一个标记；manual 表被删除（说明书变成文件）',
        'o banco valida o que guarda: regras (CHECK) em cada tabela, a origem dos lançamentos e do plano numa lista fechada, no máximo um modo em uso, um arquivo por documento; e a cópia dos documentos no banco em três níveis: o sistema (config.php), o relógio e o próprio arquivo' => '数据库校验所保存的内容：每张表都有规则（CHECK），记录和计划的来源取自封闭列表，最多一个模式在使用，每个文件记录一个文件；以及文件在数据库中的副本分三个层级：系统（config.php）、手表和文件本身',
        'o carregador: a sessão "No carregador" onde vale a leitura de carga (o smartwatch), o estado do relógio mostra a sessão aberta (no sol, no winder, no carregador) e, no carregador, o aviso "Carregar" não aparece' => '充电器：“在充电器上”会话，在此电量读数有效（智能手表），手表状态显示打开的会话（晒太阳、在上链盒上、在充电器上），并且在充电器上时不出现“充电”提醒',
        'o solar carrega também no pulso: uma parte do que ganharia no sol direto, pelo campo "No pulso: quanto carrega, comparado ao sol direto" (padrão 25%; 0 é o de antes, a carga parada)' => '太阳能表佩戴时也会充电：相当于直射阳光下所得的一部分，通过“佩戴时：与直射阳光相比的充电比例”字段设置（默认 25%；0 即以前的行为，电量不变）',
        'o smartwatch carrega no carregador (o campo "No carregador: horas para encher"), o aviso "Tirar do carregador" que sai na hora pelo Telegram (os avisos "na hora"), as fórmulas "Dias de uso" e "Custo por uso", e no MySQL/MariaDB as tabelas em utf8mb4_unicode_ci' => '智能手表在充电器上充电（“在充电器上：充满所需小时”字段），通过 Telegram 即时发送的“从充电器取下”提醒（“即时”提醒），“使用天数”和“每次使用成本”公式，以及 MySQL/MariaDB 中使用 utf8mb4_unicode_ci 的表',
        'os dias livres do plano: o "Deixar o período livre" da página Plano apaga o que foi gerado e deixa os dias sem relógio, sem sorteio, para você escolher à mão' => '计划中的空闲日：“计划”页面的“让这段时间空闲”会删除已生成的内容，让这些日子没有手表、不抽选，由你手动选择',
        'a situação de cada relógio na coleção (na coleção, desejado, emprestado, vendido ou arquivado: fora da coleção, ele sai do rodízio e dos avisos, e a ficha e o histórico ficam) e a lista de desejos; os campos Marca, Referência e Link, e, só nos desejados, Preço-alvo e Prioridade' => '每块手表在收藏中的状态（在收藏中、心愿、借出、已售或已归档：移出收藏后，它会退出轮换和提醒，档案和历史保留）和心愿单；品牌、型号和链接字段，以及仅心愿表才有的目标价和优先级',
        'o aviso Encostado: um relógio da coleção que passou do limite de dias sem ir ao pulso (a Configuração, "Aviso Encostado: dias sem ir ao pulso", padrão 30)' => '“闲置”提醒：收藏中的手表超过了未佩戴天数的上限（设置中的“闲置提醒：未佩戴天数”，默认 30）',
        'os acessórios: pulseiras, caixas, estojos, ferramentas, carregadores, peças e o que mais for, de um relógio ou soltos (a página Acessórios e o quadro Acessórios do relógio)' => '配件：表带、表盒、表包、工具、充电器、零件等，属于某块手表或未关联（“配件”页面和手表的“配件”面板）',
        'várias pessoas, cada uma com as suas coleções: usuários (master e comum, conta demo e oficial), coleções com membros, convites e pedidos de acesso, árvores de grupos que servem a várias coleções do mesmo dono, destinos de alerta (webhook, e-mail, Web Push) e agendas (Google, CalDAV, Outlook, link ICS); o banco inteiro em cascata, na 3ª forma normal. O banco antigo é copiado para um arquivo antes, e o usuário mais antigo vira o master e o dono da coleção' => '多人使用，每人有自己的收藏：用户（master 和普通，演示和正式账户）、带成员的收藏、邀请和访问请求、可供同一所有者多个收藏使用的分组树、提醒推送目标（webhook、电子邮件、Web Push）和日历（Google、CalDAV、Outlook、ICS 链接）；整个数据库级联删除，符合第三范式。旧数据库会先复制到一个文件，最早的用户成为 master 和收藏的所有者',
        'o gasto da bateria em cinco motores, escolhidos na Configuração da coleção, no relógio ou no grupo (o campo "Como calcular o gasto da bateria"): pelas horas registradas (o original), robusto, pela marcação das leituras (em uso e em repouso, gravada em cada leitura), só o cadastro, ou pelas fórmulas do cadastro; e a cópia dos documentos no banco escolhida na Configuração da coleção, no lugar do config.php' => '电池消耗的五种引擎，在收藏的设置、手表或分组中选择（字段“如何计算电池消耗”）：按记录的小时数（原始）、稳健、按读数的标记（使用中和静置中，保存在每次读数里）、仅档案，或按档案的公式；以及在收藏的设置中选择文档的数据库副本，取代 config.php',
        'o aplicativo no celular (PWA): os aparelhos lembrados de cada usuário (Minha conta: o aplicativo instalado entra sem a senha pela chave gravada no aparelho), o manifesto e o service worker pela API' => '手机上的应用（PWA）：每个用户记住的设备（我的账户：已安装的应用凭设备上保存的密钥无需密码进入）、通过 API 提供的清单和 service worker',
        'o fuso horário de cada usuário (Minha conta) e de cada coleção (a Configuração): o pedido roda no fuso da pessoa, e no banco as datas continuam no fuso do sistema; e o relógio da página Hora certa escolhido na Configuração (analógico, digital, anadigi ou os dois)' => '每个用户（我的账户）和每个收藏（设置）的时区：请求按此人的时区运行，数据库中的日期仍保持系统时区；以及在设置中选择的准确时间页面的时钟（模拟、数字、指针数字两用或两者）',
        'o fuso horário de cada destino e de cada agenda (Destinos e Agendas, "Fuso horário"; vazio: o da coleção): as horas no texto das mensagens e dos eventos saem nele, como já saem no idioma deles' => '每个推送目标和每个日历的时区（推送目标和日历，“时区”；空：收藏的）：消息和事件文本中的时间按它输出，就像已经按它们的语言输出一样',
        'os modos de rodízio com tipo (a tela de cada um: um por semana, semana e fim de semana, por dia da semana, aleatório todo dia, escala inteligente ou personalizado), semanas à frente e o roteiro (as cinco linhas que o motor calcula: candidato, nota, peso, dias, garantia; escrito à mão no personalizado, gerado dos blocos nos outros); um montador do plano só para todos os modos' => '带类型的轮换模式（每种的界面：每周一块、工作日和周末、按星期几、每天随机、智能排班或自定义）、提前周数和脚本（引擎计算的五行：candidato、nota、peso、dias、garantia；自定义模式手写，其他模式由区块生成）；所有模式共用一个计划生成器',
        'os totais: os da tabela dos relógios (o rodapé, embaixo de cada coluna) e os da página de totais deixam de ser fixos e viram expressões do motor de fórmulas sobre os relógios mostrados (CONTA, SOMA, MEDIA, AGRUPADO, FAIXAS...), cadastradas na aba Totais dos Cadastros; os prontos entram em cada árvore' => '合计：手表表格的合计（底部，每列下方）和合计页面的合计不再固定，变成基于显示手表的公式引擎表达式（CONTA、SOMA、MEDIA、AGRUPADO、FAIXAS……），在定义的“合计”标签中设置；预设的合计进入每棵树',
        'O banco já tem tabelas ({1}{2}): a instalação é só num banco vazio. Para atualizar um banco que já existe, aplique as migrações (recurso=migracoes, acao=aplicar).' => '数据库中已经有表（{1}{2}）：只能安装到空数据库中。要更新已有的数据库，请应用迁移（recurso=migracoes, acao=aplicar）。',
        'A instalação terminou, mas faltam as migrações {1}: o schema.sql está incompleto.' => '安装完成，但缺少迁移 {1}：schema.sql 不完整。',
        'Banco instalado ({1}): {2} comandos, {3} tabelas, em {4} s. Agora crie o primeiro usuário (recurso=usuarios, acao=salvar, com o token).' => '数据库已安装（{1}）：{2} 条命令，{3} 张表，用时 {4} 秒。现在创建第一个用户（recurso=usuarios, acao=salvar，使用令牌）。',
        'Firebird' => 'Firebird',
        'instalar: POST recurso=instalacao, acao=instalar' => '安装：POST recurso=instalacao, acao=instalar',
        'aplicar as migrações: POST recurso=migracoes, acao=aplicar' => '应用迁移：POST recurso=migracoes, acao=aplicar',
        'criar o primeiro usuário: POST recurso=usuarios, acao=salvar, login e senha (com o token)' => '创建第一个用户：POST recurso=usuarios, acao=salvar, login 和 senha（使用令牌）',
        'nada: o sistema está pronto' => '无：系统已就绪',
        'o menor dos valores (ignora os vazios)' => '这些值中的最小值（忽略空值）',
        'o maior dos valores (ignora os vazios)' => '这些值中的最大值（忽略空值）',
        'SE(condição; se verdadeira; se falsa)' => 'SE(条件; 为真时; 为假时)',
        '1 se todas as condições são verdadeiras' => '所有条件都为真时为 1',
        '1 se alguma condição é verdadeira' => '任一条件为真时为 1',
        'inverte a condição' => '取反条件',
        'LIMITA(x; mínimo; máximo)' => 'LIMITA(x; 最小值; 最大值)',
        'o valor sem sinal' => '不带符号的值',
        'PADRAO(x; valor se x estiver vazio)' => 'PADRAO(x; x 为空时的值)',
        '1 se o valor está vazio' => '值为空时为 1',
        'o vazio, de propósito (ex.: SE(condição; NADA(); conta))' => '特意的空值（例：SE(条件; NADA(); 计算)）',
        'a data de hoje (em dias)' => '今天的日期（以天计）',
        'o instante de agora (em dias, com a fração do dia)' => '当前时刻（以天计，含一天中的小数部分）',
        'as horas de um dia de uso, pelo horário de uso da Configuração (das 7h às 22h: 15)' => '一个使用日的小时数，按设置中的佩戴时段（7 点到 22 点：15）',
        'MEDIDO("uso") ou MEDIDO("repouso"): o gasto medido pelas leituras, em % por dia (de uso ou fora do pulso): os dois saem juntos das medições dos últimos dias da Configuração (cada intervalo entre duas leituras: a queda = dias de uso × gasto em uso + dias fora × gasto fora), na conta feita nas leituras de cada trecho entre recargas, todas com o mesmo peso, a que não bate com as outras pesando menos (regressão robusta) e partindo do gasto do cadastro; sem nenhuma nesses dias, as de antes; sem nenhuma, vazio' => 'MEDIDO("uso") 或 MEDIDO("repouso")：由读数测得的消耗，单位为每天的 %（使用时或未佩戴时）：两者一起从设置中最近几天的测量得出（两次读数之间的每个区间：下降 = 使用天数 × 使用消耗 + 未佩戴天数 × 未佩戴消耗），计算基于两次充电之间每一段的读数，所有读数权重相同，与其他不一致的读数权重较小（稳健回归），并以档案中的消耗为起点；这些天里没有测量时，用更早的；完全没有时，为空',
        'CONFIG("chave"): um número da Configuração (ex.: CONFIG("sol_limiar"), o limite do solar); vazio se não for número' => 'CONFIG("键")：设置中的一个数字（例：CONFIG("sol_limiar")，太阳能限值）；不是数字时为空',
        'dias desde uma data' => '自某日期以来的天数',
        'dias até uma data (negativo: já passou)' => '距某日期的天数（负数：已过去）',
        'SOMA_MESES(data; meses): a data somada de meses, pelo calendário' => 'SOMA_MESES(日期; 月数)：按日历加上月数后的日期',
        'ULTIMO_VALOR("tipo"): o valor do último lançamento daquele tipo' => 'ULTIMO_VALOR("类型")：该类型最后一条记录的值',
        'ULTIMA_DATA("tipo"): quando foi o último (numa sessão, o fim; aberta: agora)' => 'ULTIMA_DATA("类型")：最后一条是什么时候（会话取结束时间；进行中：现在）',
        'DIAS_DESDE_ULTIMO("tipo"): dias desde o último (sessão aberta: 0)' => 'DIAS_DESDE_ULTIMO("类型")：距最后一条的天数（会话进行中：0）',
        'HORAS("sessão"; dias): horas naquela sessão nos últimos N dias' => 'HORAS("会话"; 天数)：最近 N 天内该会话的小时数',
        'HORAS_APOS("sessão"; "tipo"): horas naquela sessão desde o último lançamento do outro tipo' => 'HORAS_APOS("会话"; "类型")：自另一类型最后一条记录以来该会话的小时数',
        'CONTAR("tipo"; dias): quantos lançamentos (ou dias com sessão) nos últimos N dias' => 'CONTAR("类型"; 天数)：最近 N 天内的记录数（或有会话的天数）',
        'EM_SESSAO("sessão"): 1 se a sessão está aberta agora' => 'EM_SESSAO("会话")：会话现在进行中时为 1',
        'ACUMULA(início; máximo; perda por hora; "tipo"; efeito; ...): um saldo que percorre o histórico: numa sessão da lista, ganha o efeito por hora (negativo: perde); num lançamento instantâneo da lista, passa a valer o efeito; num lançamento com valor (uma leitura), passa a valer a leitura vezes o efeito (1: a própria leitura); no resto, perde a perda por hora; sempre entre 0 e o máximo' => 'ACUMULA(初始; 最大; 每小时损失; "类型"; 效果; ...)：沿历史累计的余额：在列表中的会话里，每小时获得效果（负数：减少）；在列表中的瞬时记录上，变为效果值；在带数值的记录（读数）上，变为读数乘以效果（1：读数本身）；其余时间，每小时减少损失值；始终在 0 和最大值之间',
        'MEDIA_COLECAO("variável"): a média daquela variável nos relógios disponíveis' => 'MEDIA_COLECAO("变量")：该变量在可用手表中的平均值',
        'LEITURAS("uso" ou "repouso"; dias): quantas medições com as duas leituras marcadas assim há nos últimos N dias (sem dias, ou 0: a janela da Configuração)' => 'LEITURAS("uso" 或 "repouso"; 天数)：最近 N 天内两次读数都如此标记的测量有多少次（不给天数或 0：设置中的窗口）',
        'QUEDA("uso" ou "repouso"; dias): a soma das quedas dessas medições, em pontos de carga' => 'QUEDA("uso" 或 "repouso"; 天数)：这些测量的电量下降之和，以电量百分点计',
        'DIAS_MEDIDOS("uso" ou "repouso"; dias): a soma do tempo delas, em dias de uso (em repouso: dias guardado)' => 'DIAS_MEDIDOS("uso" 或 "repouso"; 天数)：这些测量的时间之和，以使用天数计（静置中：存放天数）',
        'MEDIA_TAXA("uso" ou "repouso"; dias): a média simples das taxas de cada uma (% por dia); vazio sem nenhuma' => 'MEDIA_TAXA("uso" 或 "repouso"; 天数)：各测量速率的简单平均（% 每天）；没有测量时为空',
        'MEDIANA_TAXA("uso" ou "repouso"; dias): a mediana das taxas (resiste a uma medição errada); vazio sem nenhuma' => 'MEDIANA_TAXA("uso" 或 "repouso"; 天数)：速率的中位数（不受一次错误测量影响）；没有测量时为空',
        'ULTIMA_TAXA("uso" ou "repouso"): a taxa da medição mais recente assim (% por dia); vazio sem nenhuma' => 'ULTIMA_TAXA("uso" 或 "repouso")：该类最近一次测量的速率（% 每天）；没有测量时为空',
        'o dia da semana do dia que está sendo montado (fora do rodízio: o do instante da conta): 1 segunda ... 7 domingo' => '正在生成的那一天的星期几（轮换之外：计算时刻的星期几）：1 周一 ... 7 周日',
        'o número da semana do ano (ISO) do dia que está sendo montado' => '正在生成的那一天的年度周数（ISO）',
        'NO_GRUPO("grupo"): 1 se o relógio está nesse ponto da árvore ou abaixo (o nome, o caminho "Tradicional › Quartzo" ou #id; "todos": 1 para todos)' => 'NO_GRUPO("分组")：手表在树的该节点或其下时为 1（名称、路径 "Tradicional › Quartzo" 或 #id；"todos"：所有手表都为 1）',
        'RELOGIO("nome" ou id): 1 se é esse relógio' => 'RELOGIO("名称" 或 id)：是该手表时为 1',
        'ESCOLHIDO_HA(n): 1 se o relógio é o do plano há n dias (1: ontem; -1: amanhã, quando já está no plano)' => 'ESCOLHIDO_HA(n)：手表是 n 天前计划中的那块时为 1（1：昨天；-1：明天，当已在计划中时）',
        'VEZES_NO_PLANO(n): quantos dias o relógio teve no plano nos últimos n dias (antes do dia que está sendo montado)' => 'VEZES_NO_PLANO(n)：最近 n 天里该手表在计划中出现的天数（正在生成的那一天之前）',
        'ESCOLHA(n; a; b; c...): o n-ésimo dos valores (só ele é calculado); fora da lista, vazio. Ex.: ESCOLHA(DIA_SEMANA(); ...) dá um valor por dia da semana' => 'ESCOLHA(n; a; b; c...)：第 n 个值（只计算它）；超出列表则为空。例：ESCOLHA(DIA_SEMANA(); ...) 给每个星期几一个值',
        'um número aleatório de 0 a 1 (do lote do RANDOM.ORG, como os sorteios)' => '0 到 1 之间的随机数（来自 RANDOM.ORG 的批次，和抽签一样）',
        'MES(data): o mês da data, de 1 a 12' => 'MES(日期)：日期的月份，1 到 12',
        'ANO(data): o ano da data' => 'ANO(日期)：日期的年份',
        'MES_ANO(data): o mês e o ano da data, como texto AAAA-MM (os totais mostram "ago/2026")' => 'MES_ANO(日期)：日期的年和月，文本 YYYY-MM（合计显示为“2026年8月”）',
        'a nota do relógio pelos critérios (a página Critérios), no instante da conta' => '手表按标准（标准页面）在计算时刻的评分',
        'texto aberto na posição {1}: falta fechar as aspas' => '位置 {1} 处的文本未闭合：缺少结束引号',
        'caractere inesperado "{1}" na posição {2}' => '位置 {2} 处出现意外字符“{1}”',
        'a fórmula está vazia' => '公式为空',
        '"{1}" sobrando na posição {2}' => '位置 {2} 处多出“{1}”',
        'na posição {1}' => '在位置 {1}',
        'no fim' => '在末尾',
        'falta fechar o parêntese {1}' => '括号 {1} 没有闭合',
        'função desconhecida {1} {2}' => '未知函数 {1} {2}',
        'falta fechar os argumentos de {1} {2} (os argumentos se separam com ponto e vírgula)' => '{1} {2} 的参数没有闭合（参数之间用分号分隔）',
        '{1} recebe {2} argumento(s), e recebeu {3} {4}' => '{1} 需要 {2} 个参数，但收到了 {3} 个 {4}',
        'pelo menos {1}' => '至少 {1}',
        'de {1} a {2}' => '{1} 到 {2}',
        'a fórmula acabou antes do esperado' => '公式提前结束',
        '"{1}" fora do lugar {2}' => '“{1}”位置不对 {2}',
        'Pelas horas registradas (o motor original)' => '按记录的小时数（原始引擎）',
        'Pelas horas registradas, com leituras e cadastro (robusto)' => '按记录的小时数，结合读数和档案（稳健）',
        'Pela marcação: duas taxas separadas' => '按标记：两个独立的速率',
        'Só o cadastro' => '仅档案',
        'Pelas fórmulas do cadastro' => '按档案的公式',
        'das últimas {1} leituras de cada tipo' => '每类最近 {1} 次读数的',
        'dos últimos {1} dias' => '最近 {1} 天的',
        'variável desconhecida: {1} (não é campo nem fórmula)' => '未知变量：{1}（既不是字段也不是公式）',
        'tipo de lançamento desconhecido: "{1}"' => '未知记录类型：“{1}”',
        'a fórmula depende dela mesma: {1}' => '公式依赖于自身：{1}',
        'a fórmula {1} usada aqui está com erro de escrita' => '这里使用的公式 {1} 有书写错误',
        'erro de escrita: {1}' => '书写错误：{1}',
        'agora · {1}' => '现在 · {1}',
        'nunca' => '从未',
        'CONTA(): quantos relógios; CONTA(x): quantos têm x preenchido' => 'CONTA()：多少块手表；CONTA(x)：多少块填写了 x',
        'CONTA_SE(condição): quantos passam na condição, como CONTA_SE(carga <= 20)' => 'CONTA_SE(条件)：多少块满足条件，如 CONTA_SE(carga <= 20)',
        'DISTINTOS(x): quantos valores diferentes de x (os vazios não contam)' => 'DISTINTOS(x)：x 有多少个不同的值（空值不计）',
        'SOMA(x): a soma de x nos relógios que têm x' => 'SOMA(x)：有 x 的手表上 x 的总和',
        'MEDIA(x): a média de x nos relógios que têm x (de uma data, a data média)' => 'MEDIA(x)：有 x 的手表上 x 的平均值（日期则为平均日期）',
        'MEDIANA(x): a mediana de x (o do meio, resiste a um valor fora da curva)' => 'MEDIANA(x)：x 的中位数（居中的值，不受异常值影响）',
        'MENOR(x): o menor valor de x' => 'MENOR(x)：x 的最小值',
        'MAIOR(x): o maior valor de x' => 'MAIOR(x)：x 的最大值',
        'QUEM_MENOR(x): o relógio com o menor x, com o valor ao lado (só como a expressão inteira)' => 'QUEM_MENOR(x)：x 最小的手表，旁边附值（只能作为整个表达式）',
        'QUEM_MAIOR(x): o relógio com o maior x, com o valor ao lado (só como a expressão inteira)' => 'QUEM_MAIOR(x)：x 最大的手表，旁边附值（只能作为整个表达式）',
        'AGRUPADO(chave; conta; limite): uma tabelinha, uma linha por valor da chave e a linha de total; conta (sem ela, CONTA()) é a conta de cada linha, feita só com os relógios dela, e a do total, com todos; limite mostra as que mais têm e junta o resto em "outros" (só como a expressão inteira)' => 'AGRUPADO(键; 计算; 限制)：一个小表，键的每个值一行，加上合计行；计算（没有则为 CONTA()）是每行的计算，只用该行的手表，合计行用全部；限制显示最多的几行，其余合并为“其他”（只能作为整个表达式）',
        'FAIXAS(x; limite1; limite2; ...): uma tabelinha por faixas de x (até o limite1, do limite1 ao limite2, ..., mais que o último quando houver), os sem x numa linha "sem valor" e o total (só como a expressão inteira)' => 'FAIXAS(x; 限值1; 限值2; ...)：按 x 的区间分的小表（到限值1、从限值1到限值2……有超过最后一个的则加一行），没有 x 的放在“无值”一行，加上合计（只能作为整个表达式）',
        'o código do relógio (a coluna Código)' => '手表的编号（编号列）',
        'o nome do relógio' => '手表的名称',
        'o tipo (o grupo da árvore onde ele está: a coluna Tipo)' => '类型（它所在的树分组：类型列）',
        'o estado agora, por extenso (Em uso, Em repouso, No winder, Indisponível...)' => '现在的状态，用文字表示（佩戴中、休息中、在上链盒、不可用……）',
        '1 se o relógio está disponível para o rodízio, 0 se não' => '手表可用于轮换为 1，否则为 0',
        '1 se está no pulso agora' => '现在戴在手腕上为 1',
