        'Já estava no pulso pelo rodízio quando o plano de hoje foi montado.' => '生成今天的计划时，它已经因轮换戴在手腕上。',
        'o que o dia tinha ({1}) ficou de fora' => '该日原有的（{1}）被排除',
        'Decida por mim: o sistema escolhe pela nota dos critérios (os que você cadastra em Critérios: dias sem uso, equilíbrio, preferência, carga...), recalculada no começo de cada dia, com os dias anteriores do período (os que você escolheu e os que ele decidiu) já contados como uso; a garantia de rodízio vem na frente (quem passou do limite de dias sem uso, o mais tempo parado primeiro); e o relógio de ontem e o de amanhã ficam de fora, se houver outro. Empate: o cadastrado primeiro. A decisão é feita ao gravar e fica gravada no plano, com o motivo; hoje, com "Decida por mim", continua o relógio que já está no plano. Sortear este dia por: o dia é sorteado ao gravar pela forma escolhida (a maior nota, sorteio pela nota, aleatório ou fila), com a garantia de rodízio na frente (menos no aleatório) e sem o de ontem e o de amanhã.' => '替我决定：系统按标准分数选择（你在“标准”中定义的：未使用天数、平衡、偏好、电量……），每天开始时重新计算，并把该期间之前的日子（你选的和系统定的）算作已使用；轮换保证优先（超过未使用天数上限的，闲置最久的先）；如果有其他手表，昨天和明天的手表会被排除。打平时：先登记的。决定在保存时做出，并连同原因保存在计划中；今天选“替我决定”时，保留计划中已有的手表。按以下方式为这一天抽签：保存时按所选方式（最高分数、按分数抽签、随机或排队）为该日抽签，轮换保证优先（随机除外），并排除昨天和明天的手表。',
