        'Horas simuladas na escala: de 0 a 48 (vazio: nenhuma).' => '排程中的模拟小时数：0 到 48（留空：无）。',
        'Na escala: nao, uso ou sempre.' => '在排程中：nao、uso 或 sempre。',
        'Na agenda: janela (só dentro da antecedência da agenda) ou sempre (qualquer data).' => '在日历中：janela（仅在日历的提前期内）或 sempre（任何日期）。',
