        'O peso vai de 0,01% a 100%.' => '权重为 0.01% 到 100%。',
        'Parâmetro {1} incluído em {2} com {3}.{4} Inclua os subparâmetros dele: sem nenhum, ele não entra na conta.' => '已将参数 {1} 加入 {2}，权重 {3}。{4} 请添加它的子参数：没有子参数时，它不计入计算。',
