        ' O peso dele foi dividido na proporção de cada um: {1}.' => ' 它的权重已按各自比例分配：{1}。',
        ' O lugar ficou sem parâmetros e volta a herdar os critérios de cima.' => ' 该位置已没有参数，重新继承上级的标准。',
