        'Subparâmetro {1} incluído em {2} com {3}.{4} Ele começou com nota 50 em tudo: ajuste as faixas.' => '已将子参数 {1} 加入 {2}，权重 {3}。{4} 它一开始所有分数都是 50：请调整区间。',
