        '{1} agora mede: {2}. As faixas recomeçaram com nota 50 em tudo: ajuste-as.' => '{1} 现在测量：{2}。区间已重置，所有分数都是 50：请调整。',
        'Escolha o subparâmetro e o parâmetro de destino.' => '请选择子参数和目标参数。',
        '{1} já está em {2}: nada mudou.' => '{1} 已在 {2} 中：没有变化。',
