    'ajuda' => [
        'api.php devolve tudo o que está guardado na coleção do pedido, sem filtro: arvore, campos, lancamento_tipos, formulas, avisos, relogios (com os valores dos campos, o resultado de cada fórmula, os avisos, os lançamentos, a previsão e a linha do tempo inteira com o resumo), modos, plano (inteiro), config (inteira, da coleção), eventos (com os disparos), destinos, agendas, agendas_desejadas, criterios (com a nota de cada relógio), cron (todas as execuções guardadas), usuarios (os logins; o master vê todos), migracoes e motor, e as categorias dos documentos (documento_categorias). A senha dos usuários não existe no sistema: sai o hash dela (veja senhas). Os arquivos dos documentos não vêm (só os dados de cada um, em relogios[].documentos): eles saem pelo recurso=documento. Para pegar só uma parte, ou filtrar, ordenar e paginar: veja filtros.' => 'api.php 返回请求所在收藏中保存的全部内容，不加筛选：arvore、campos、lancamento_tipos、formulas、avisos、relogios（含字段值、每个公式的结果、提醒、记录、预测以及带摘要的完整时间线）、modos、plano（完整）、config（完整，属于该收藏）、eventos（含触发记录）、destinos、agendas、agendas_desejadas、criterios（含每只手表的评分）、cron（所有保存的执行）、usuarios（登录名；master 看到全部）、migracoes 和 motor，以及文档分类（documento_categorias）。用户的密码在系统中并不存在：输出的是它的哈希（见 senhas）。文档的文件不会返回（只有每个文档的数据，在 relogios[].documentos 中）：它们通过 recurso=documento 输出。只取一部分，或进行筛选、排序和分页：见 filtros。',
        'em todo pedido: o login do site (HTTP Basic: o usuário e a senha de uma conta), um token pessoal (Minha conta, Tokens de API: vale como o login do dono dele, com as coleções dele) ou o token do servidor (o API_TOKEN do config.php, com pelo menos 10 caracteres: vale como o master mais antigo), no cabeçalho X-Api-Token ou no parâmetro token. Sem nada: 401. A conta bloqueada pelo master, ou a de demonstração que venceu, não entra. Ex.: curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje; curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje' => '每个请求中：网站登录（HTTP Basic：某个账户的用户名和密码）、个人令牌（我的账户，API 令牌：等同于其所有者的登录，带其收藏）或服务器令牌（config.php 中的 API_TOKEN，至少 10 个字符：等同于最早的 master），放在 X-Api-Token 请求头或 token 参数中。什么都没有：401。被 master 封禁的账户，或已到期的演示账户，无法进入。例：curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje; curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje',
        'cada pedido vale numa coleção: a do parâmetro colecao=<id>, senão a do cookie colecao (o seletor do menu das páginas), senão a primeira que o usuário vê (a dele). Uma coleção que ele não vê: 404, como se não existisse. Tudo o que se lê e se grava (os relógios, o plano, a configuração, os destinos, as agendas...) é dessa coleção; a árvore de grupos e o cadastro dela (campos, tipos, fórmulas, avisos, categorias, critérios dos grupos) são da árvore que a coleção usa, e valem em todas as coleções que usam a mesma árvore. Sem coleção nenhuma (a conta que só pediu acesso), só a conta responde (409 com sem_colecao nos outros recursos). O master vê todas as coleções; com como=<login> (ou o cookie como, da faixa Vendo como das páginas), ele vê e grava como aquele usuário' => '每个请求作用于一个收藏：参数 colecao=<id> 指定的那个，否则是 colecao cookie 中的那个（页面菜单中的选择器），否则是该用户看到的第一个（他自己的）。他看不到的收藏：404，如同不存在。读取和保存的一切（手表、计划、设置、推送目标、日历……）都属于该收藏；分组树及其定义（字段、类型、公式、提醒、分类、分组的标准）属于该收藏所用的树，并在使用同一棵树的所有收藏中生效。完全没有收藏时（只申请了访问的账户），只有账户会响应（其他资源返回 409 并带 sem_colecao）。master 看到所有收藏；使用 como=<login>（或页面“以他人身份查看”横条的 como cookie），他以该用户的身份查看和保存',
        'toda exclusão é em dois passos: sem confirmar=1, a API não apaga nada e responde 409 com confirmar: true e impacto (o que sai junto, seguindo o banco em cascata, no banco inteiro: itens, desfeitos, colecoes, relogios, arquivos, bytes e o texto pronto); com confirmar=1, apaga. Os scripts mandam confirmar=1 de uma vez. Os arquivos dos documentos saem do disco na hora (os do relógio, da coleção, da árvore ou da conta que saiu)' => '所有删除都分两步：没有 confirmar=1 时，API 什么都不删，返回 409，带 confirmar: true 和 impacto（随之删除的内容，按数据库的级联、在整个数据库中统计：itens、desfeitos、colecoes、relogios、arquivos、bytes 以及现成的文字）；带 confirmar=1 时才删除。脚本直接发送 confirmar=1。文档的文件会立即从磁盘删除（属于被删除的手表、收藏、树或账户的那些）',
        'JSON (padrão) ou XML: formato=xml, ou o cabeçalho Accept com xml. Ex.: http://servidor/relojoeiro/api.php?recurso=plano&formato=xml' => 'JSON（默认）或 XML：formato=xml，或请求头 Accept 含 xml。例：http://servidor/relojoeiro/api.php?recurso=plano&formato=xml',
        'tudo o que está guardado, sem filtro (os relógios com os campos, as fórmulas, os avisos, os lançamentos, a previsão e a linha do tempo; modos, plano, configuração, eventos, agenda e o motor)' => '全部已保存的内容，无筛选（手表及其字段、公式、提醒、记录、预测和时间线；模式、计划、设置、事件、日历和引擎）',
        'nao: sem as fotos em base64 (a resposta fica bem menor)' => 'nao：不含 base64 照片（响应会小很多）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?foto=nao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?foto=nao"',
        'tudo o que a página Hoje mostra: o dia e o relógio dele, os avisos de hoje (com o lançamento que resolve cada um), os próximos 62 dias do plano, os Próximos dias da página (uma página: proximos), os modos com os blocos, os grupos, a tabela dos relógios (os da coleção: na coleção e emprestados), os que estão fora dela (desejados, vendidos, arquivados: fora_da_colecao) e os totais da coleção (quantos, disponíveis, em uso, o valor pago, quantos desejados e quantos fora)' => '今天页面显示的全部内容：当天及其手表、今天的提醒（含解决每一条的记录）、计划中接下来的 62 天、页面上的接下来的日子（一页：proximos）、带区块的模式、分组、手表表（收藏中的：在收藏中和已借出）、收藏之外的（心愿中、已售出、已归档：fora_da_colecao）以及收藏合计（数量、可用、使用中、已付金额、心愿数量和之外的数量）',
        'a página dos Próximos dias (padrão 1)' => '接下来的日子的页码（默认 1）',
        'quantos dias por página nos Próximos dias (sem ele: o Mostrar até da Configuração, padrão 7)' => '接下来的日子中每页多少天（不传时：设置中的显示至，默认 7）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hoje"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hoje"',
        'tudo o que o painel de um relógio mostra: agora, carga e de onde vem, situação, nota, quando entra no rodízio, compra, próximas manutenções, previsão, o gasto da bateria, quantos documentos o relógio tem em cada categoria, os tipos de lançamento dele (com a sessão aberta), as últimas leituras, as marcações dos últimos 14 dias, o resumo do histórico, a situação na coleção (com o desejo, no desejado) e o cadastro; sem relogio, só o cadastro de um relógio novo; relógio que não existe: 404' => '一块手表的面板所显示的全部内容：现在、电量及其来源、情况、分数、何时进入轮换、购买、各项下次保养、预测、电池消耗、该手表在每个类别中有多少文档、其记录类型（含已打开的时段）、最近的读数、最近 14 天的标记、历史摘要、在收藏中的情况（含心愿，处于心愿中时）以及档案；不传 relogio 时，只有新手表的档案；手表不存在：404',
        'o id do relógio (vazio: o cadastro de um relógio novo)' => '手表的 id（空：新手表的档案）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ficha&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ficha&relogio=10"',
        'tudo o que a página Configuração mostra (da coleção do pedido): os valores, o Mostrar até de cada lista (mostrar_ate), de onde vêm os números dos sorteios (aleatorio: RANDOM.ORG, senão ANU QRNG, senão o gerador seguro do PHP; o último lote), o endereço do sistema (sistema: só o master muda), os eventos personalizados, o resumo dos destinos e das agendas (que têm as páginas deles: recurso=destinos e recurso=agendas) e a situação do cron (nunca rodou, parado ou rodando)' => '设置页面显示的全部内容（属于请求所在的收藏）：各项值、每个列表的“显示至”（mostrar_ate）、抽签数字的来源（aleatorio：RANDOM.ORG，否则 ANU QRNG，否则 PHP 的安全生成器；最近一批）、系统地址（sistema：只有 master 能改）、自定义事件、推送目标和日历的摘要（它们有各自的页面：recurso=destinos 和 recurso=agendas）以及 cron 的状态（从未运行、已停止或运行中）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=config"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=config"',
        'as execuções do cron, com o resumo do período (total, com atividade, com erro, a mais lenta) e páginas; sem atividade elas ficam 7 dias, com atividade ou erro, 1 ano' => 'cron 的各次执行，含该时段摘要（总计、有活动、有错误、最慢的一次）和分页；无活动的保留 7 天，有活动或有错误的保留 1 年',
        'data (AAAA-MM-DD) ou data e hora (AAAA-MM-DD HH:MM[:SS], espaço ou T); cron_de e cron_ate também valem' => 'data（AAAA-MM-DD）或日期和时间（AAAA-MM-DD HH:MM[:SS]，空格或 T）；cron_de 和 cron_ate 同样有效',
        'atividade (padrão), erro, nada ou todas; cron_situacao também vale' => 'atividade（默认）、erro、nada 或 todas；cron_situacao 同样有效',
        'texto no registro; cron_busca também vale' => '记录中的文本；cron_busca 同样有效',
        'por página (padrão 100, máximo 1000)' => '每页数量（默认 100，最大 1000）',
        'a página (padrão 1)' => '页码（默认 1）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cron&situacao=erro&de=2026-09-01&busca=agenda"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cron&situacao=erro&de=2026-09-01&busca=agenda"',
        'os grupos em ordem de árvore (com o caminho, os de cima, quantos subgrupos, os relógios direto neles e quantos parâmetros de critérios próprios) e o grupo de cada relógio' => '按树顺序排列的分组（含路径、上级、子分组数量、直接属于它们的手表，以及自有标准参数的数量）和每块手表的分组',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=arvore"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=arvore"',
        'tudo o que as páginas Cadastros, Avisos e Modos de rodízio mostram: campos, tipos de lançamento (com quantos lançamentos cada um tem), fórmulas e avisos (todas as versões), modos com os blocos, grupos, relógios e as funções do motor' => '“定义”“提醒”和“轮换模式”页面显示的全部内容：字段、记录类型（含各自有多少条记录）、公式和提醒（全部版本）、带区块的模式、分组、手表以及引擎的函数',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cadastros"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cadastros"',
        'calcula uma fórmula sem gravar, em cada relógio (ou nos pedidos), com as partes da conta (o testar da página Cadastros); fórmula com erro de escrita: 400 com os erros' => '在每块手表上（或在所请求的手表上）计算一条公式而不保存，并给出计算的各部分（定义页面的测试）；公式书写错误：400 并附带错误',
        'a fórmula' => '公式',
        'um id ou vários separados por vírgula (vazio: todos)' => '一个 id 或多个以逗号分隔（空：全部）',
        'curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12' => 'curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12',
        'os avisos de todos os relógios da coleção agora (os desejados, vendidos e arquivados não têm aviso), do mais urgente ao mais distante, com a data prevista, quanto falta, o estado (atrasado, em_breve, ok) e o texto' => '收藏中全部手表当前的提醒（心愿中、已售出和已归档的没有提醒），从最紧急到最远，含预计日期、还差多少、状态（atrasado、em_breve、ok）和文本',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"',
        'os conjuntos de critérios por lugar (parâmetros, subparâmetros, faixas), as variáveis que podem medir (com o limite), os lugares (quem tem critérios próprios e de quem herda), os modos e a nota de cada relógio com a conta' => '按位置划分的标准集合（参数、子参数、区间）、可度量的变量（含上限）、各个位置（谁有自有标准、从谁继承）、模式，以及每块手表带计算过程的分数',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"',
        'a linha do tempo: trechos contínuos por estado (rodizio, pulso: em uso fora do plano, cada tipo de sessão, repouso) e as marcações, com o resumo do tempo em cada estado e os lançamentos crus do período' => '时间线：按状态划分的连续片段（rodizio、pulso 即计划之外的使用中、每种时段类型、repouso）和标记，含每个状态的时间摘要以及该时段的原始记录',
        'um id ou vários (relogio_id também vale; vazio: todos)' => '一个 id 或多个（relogio_id 同样有效；空：全部）',
        'data ou data e hora; entra a linha que cruza o período' => '日期或日期和时间；与该时段相交的行会纳入',
        'rodizio, pulso, winder, sol, repouso, marca... (um ou vários; linha_estado também vale)' => 'rodizio、pulso、winder、sol、repouso、marca……（一个或多个；linha_estado 同样有效）',
        'a página' => '页码',
        'desc (padrão, mais recente primeiro) ou asc; dois no mesmo instante saem pela ordem em que foram lançados (o id)' => 'desc（默认，最近的在前）或 asc；同一时刻的两条按被记录的顺序输出（即 id）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"',
        'a previsão da energia dos relógios com leitura (o smartwatch): quanto dura usando, quando chega ao limite parado, com quanto entra no próximo rodízio e quanto precisa, e a confiança da conta' => '带读数的手表（智能手表）的能量预测：使用时能持续多久、静止时何时到达限值、以多少能量进入下一次轮换以及还需要多少，以及计算的置信度',
        'um id ou vários (vazio: todos)' => '一个 id 或多个（空：全部）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"',
        'o plano gravado (a escala de dois anos sai inteira), o dia a dia da página Plano uma página por vez (dia_a_dia, com os dias livres no meio), com o modo ativo, o fim da escala e o último dia gravado; cada dia com o relógio, o bloco, a origem (sorteio ou manual) e o lembrete; os dias livres do período (sem relógio e sem sorteio, para escolher à mão); e o resumo do período (de hoje em diante), como a página Plano mostra: quantos dias cada relógio tem, a porcentagem, o próximo dia, quantos à mão e os relógios sem nenhum dia' => '已保存的计划（两年排班表完整输出）、计划页面的逐日内容每次一页（dia_a_dia，中间含空闲日），含当前模式、排班表结束日和最后保存日；每一天含手表、区块、来源（抽签或手动）和备忘；该时段的空闲日（无手表且无抽签，供手动选择）；以及从今天起的时段摘要，与计划页面所显示的一致：每块手表有多少天、百分比、下一天、多少天为手动，以及没有任何一天的手表',
        'datas AAAA-MM-DD (vazio: o plano inteiro)' => '日期 AAAA-MM-DD（空：整个计划）',
        'a página do dia_a_dia (padrão 1)' => 'dia_a_dia 的页码（默认 1）',
        'quantos dias por página no dia_a_dia (sem ele: o Mostrar até da Configuração, padrão 31)' => 'dia_a_dia 中每页多少天（不传时：设置中的显示至，默认 31）',
        'o id: o dia_a_dia só com os dias desse relógio' => 'id：dia_a_dia 只含该手表的日子',
        'N: os próximos N dias, de hoje em diante (no lugar de de e ate); todos: de hoje até o fim do plano' => 'N：从今天起接下来的 N 天（用来代替 de 和 ate）；todos：从今天直到计划结束',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"',
        'a lista de desejos (a página Desejos): os relógios desejados, a prioridade mais alta primeiro, cada um com a marca, a referência, o preço-alvo, a prioridade e o link; a soma dos preços-alvo; e os que estão fora da coleção (emprestados, vendidos, arquivados). Pôr na coleção (o Comprei): recurso=relogio, acao=salvar, posse=colecao' => '心愿单（心愿单页面）：心愿中的手表，优先级最高的在前，每块含品牌、型号、目标价格、优先级和链接；目标价格合计；以及收藏之外的（已借出、已售出、已归档）。放入收藏（我买了）：recurso=relogio, acao=salvar, posse=colecao',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"',
        'o uso da coleção num período (a página Estatísticas): o resumo (dias com relógio, horas no pulso, relógios usados, o mais e o menos usado, o valor da coleção, o custo por uso médio), cada relógio (dias de uso, horas, a parte de cada um, o custo por uso, dias sem uso, a tendência), o uso por dia da semana e por mês, e a distribuição da coleção (por grupo, marca, ano da compra, situação e cada campo de lista); as porcentagens e as alturas das barras (0 a 100, comparadas com a maior) vêm prontas. Contam as sessões no pulso (partidas na meia-noite) e as marcações antigas no pulso (o dia, sem horas)' => '某一时段内收藏的使用情况（统计页面）：摘要（有手表的天数、在手腕上的小时数、使用过的手表、使用最多和最少的、收藏金额、平均每次使用成本）、每块手表（使用天数、小时数、各自占比、每次使用成本、未使用天数、趋势）、按星期几和按月的使用，以及收藏分布（按分组、品牌、购买年份、情况和每个列表字段）；百分比和柱高（0 到 100，与最大者比较）已算好。计入手腕上的时段（在午夜拆分）以及手腕上的旧标记（只计日，不计小时）',
        'datas AAAA-MM-DD (padrão: os últimos 90 dias, até hoje; ate depois de hoje vira hoje; até 3661 dias); de=tudo: desde o primeiro uso; inválidas: 400 com erro' => '日期 AAAA-MM-DD（默认：最近 90 天，直到今天；ate 晚于今天则变为今天；最多 3661 天）；de=tudo：从第一次使用起；无效：400 并附带错误',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"',
        'os totais calculados nos relógios mostrados: os do rodapé da tabela dos relógios da página Hoje (embaixo de cada coluna) e os da página de totais (os quadros), na ordem do cadastro (a aba Totais dos Cadastros). Cada total é uma expressão do motor de fórmulas sobre o conjunto de relógios (CONTA, SOMA, MEDIA, AGRUPADO, FAIXAS... em funcoes; dentro delas, os campos, as fórmulas e as variáveis da tabela, em variaveis) e vem com o resultado pronto: um número, uma tabelinha com a linha de total ou um relógio com o valor, já no formato dele' => '在显示的手表上计算的合计：今天页面手表表格底部的合计（每列下方）和合计页面的合计（方框），按定义的顺序（定义的“合计”标签）。每个合计都是公式引擎在手表集合上的表达式（CONTA、SOMA、MEDIA、AGRUPADO、FAIXAS……见 funcoes；函数内可用字段、公式和表格变量，见 variaveis），结果已准备好：一个数字、一个带合计行的小表，或一块手表及其值，已按其格式',
        'os ids, separados por vírgula (os que o filtro da tabela deixa à mostra); sem: todos os da tabela (na coleção e emprestados); 0: nenhum' => 'id，用逗号分隔（表格筛选后可见的）；不填：表格中的全部（收藏中和借出的）；0：无',
        'rodape (só os do rodapé), pagina (só os da página de totais) ou teste (nenhum: só o teste); sem: todos (o cadastro, com as colunas, os formatos, as funções e as variáveis)' => 'rodape（只有底部的）、pagina（只有合计页面的）或 teste（无：只有测试）；不填：全部（定义，含列、格式、函数和变量）',
        'testa uma expressão de total sem gravar (o Testar do cadastro), no formato pedido (padrão numero): o resultado vem em teste' => '不保存地测试一个合计表达式（定义中的“测试”），按请求的格式（默认 numero）：结果在 teste 中',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=totais&parte=rodape&relogios=3,7,12"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=totais&parte=rodape&relogios=3,7,12"',
        'a hora do servidor para acertar os relógios (a página Hora certa): a local no fuso do pedido (o do usuário, o da coleção ou o do sistema), a UTC (Zulu), a letra militar do fuso e o grupo data-hora, o calendário (dia do ano, semana ISO, trimestre, dia juliano) e a fase da lua (pelo ciclo médio, aproximada), como acertar e o relógio escolhido na Configuração (analógico, digital, anadigi ou ambos); agora_ms, em milissegundos, para a tela acertar o relógio dela' => '用于对表的服务器时间（准确时间页面）：请求所在时区（用户的、收藏的或系统的）的本地时间、UTC（Zulu）、时区的军用字母和日期时间组、日历（年中第几天、ISO 周、季度、儒略日）和月相（按平均周期，为近似值）、如何对表以及在设置中选择的时钟（模拟、数字、指针数字两用或两者）；agora_ms，以毫秒计，供界面对其手表对时',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"',
        'os acessórios (a página Acessórios): pulseiras, caixas, estojos, ferramentas, carregadores, peças e outros, cada um com o tipo, o relógio de que ele é (ou solto) e a observação, pelo tipo e pelo nome; os tipos, quantos de cada tipo, quantos soltos e os relógios (o menu). Gravar: escrita acessorios' => '配件（配件页面）：表带、表盒、收纳盒、工具、充电器、零件和其他，每项含类型、所属手表（或未绑定）和备注，按类型和名称排列；类型、每种数量、未绑定数量和手表（菜单）。保存：写入 acessorios',
        'o id: só os acessórios desse relógio; 0: só os soltos (sem ele: todos)' => 'id：只返回该手表的配件；0：只返回未绑定的（不传：全部）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"',
        'o passaporte de um relógio (a página Passaporte, para imprimir ou guardar em PDF), tudo já em texto: quem ele é, o cadastro preenchido (cada valor formatado pelo tipo: data, sim/não, número com a unidade, R$), a compra, o uso (a primeira e a última vez no pulso, as horas no pulso, os dias de uso e o custo por uso), as manutenções (cada tipo de marcação, quantas vezes e a última; as revisões e trocas de pilha), os acessórios, os documentos e os próximos avisos; relógio que não existe: 404' => '一块手表的护照（护照页面，用于打印或保存为 PDF），全部已是文本：它是谁、已填写的档案（每个值按类型格式化：日期、是/否、带单位的数字、R$）、购买、使用（第一次和最后一次在手腕上、在手腕上的小时数、使用天数和每次使用成本）、保养（每种标记类型、次数和最近一次；检修和更换电池）、配件、文档和即将到来的提醒；手表不存在：404',
        'o id do relógio (obrigatório)' => '手表的 id（必填）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"',
        'a coleção em fotos, por grupo (a página Galeria, para ver e imprimir): cada relógio com a foto, a marca, a referência, o ano e o valor da compra e os dias de uso, e os totais' => '按分组的收藏照片（图库页面，用于查看和打印）：每块手表含照片、品牌、型号、购买年份和购买金额以及使用天数，还有合计',
        'todos: também os desejados, vendidos e arquivados (sem ele: os da coleção, na coleção e emprestados)' => 'todos：也包括心愿中、已售出和已归档的（不传：收藏中的，即在收藏中和已借出）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"',
        'os textos das telas no idioma do pedido (o dicionário da função t() do api.js: o texto em português => a tradução), o idioma, o locale das datas e dos números, o padrão da instalação e os idiomas do sistema. Responde sem login (é só o texto da interface). O idioma de qualquer pedido: lingua=, senão o cookie lingua (o seletor do menu), senão o padrão da instalação (config.idioma), senão o Accept-Language, senão português; toda resposta da API sai nele' => '按请求语言返回的界面文本（api.js 中函数 t() 的词典：葡萄牙语文本 => 译文）、语言、日期和数字的 locale、安装默认值以及系统的语言。无需登录即可响应（只是界面文本）。任意请求的语言：lingua=，否则 cookie lingua（菜单中的选择器），否则安装默认值（config.idioma），否则 Accept-Language，否则葡萄牙语；API 的全部响应都用该语言输出',
        'js: um script (window.TEXTOS_API = {...}), que as páginas carregam antes dos outros' => 'js：一段脚本（window.TEXTOS_API = {...}），页面会在其他脚本之前加载它',
        'curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"' => 'curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"',
        'os Próximos dias da página Hoje, uma página (de hoje até o fim do plano, com os dias livres no meio): a troca de página da tela lê só eles' => '今天页面的接下来的日子，一页（从今天直到计划结束，中间含空闲日）：界面翻页只读取这些',
        'quantos dias por página (sem ele: o Mostrar até da Configuração, padrão 7)' => '每页多少天（不传时：设置中的显示至，默认 7）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"',
        'testa um roteiro de modo de rodízio num dia, sem gravar (o "Testar em todos os relógios" da página Modos de rodízio): roteiro (o texto, as linhas "nome = expressão") ou modo (o id: o roteiro efetivo dele), dia (AAAA-MM-DD, de hoje até um ano à frente; padrão hoje). Cada relógio disponível com as linhas calculadas e as cinco saídas, e quem sairia nesse dia pela mesma escolha do rodízio (o de ontem fora, sem o ciclo), com os dias anteriores do plano contados como uso. Roteiro com erro: as linhas boas valem e os erros vêm em erros' => '在某一天测试轮换模式脚本，不保存（轮换模式页面的“在所有手表上测试”）：roteiro（文本，“名称 = 表达式”各行）或 modo（id：其生效脚本），dia（YYYY-MM-DD，从今天到一年后；默认今天）。每块可用手表及其计算出的各行和五个输出，以及按轮换同样的选法那天会选谁（昨天的排除，不含循环），计划中之前的日子算作使用。脚本有错误时：正确的行有效，错误在 erros 中返回',
        'curl -u lucas:senha -G --data-urlencode "roteiro=candidato = NO_GRUPO(\\"Tradicional\\")" -d dia=2026-10-20 "http://servidor/relojoeiro/api.php?recurso=roteiro"' => 'curl -u lucas:senha -G --data-urlencode "roteiro=candidato = NO_GRUPO(\\"Tradicional\\")" -d dia=2026-10-20 "http://服务器/relojoeiro/api.php?recurso=roteiro"',
        'o Rodízio manual (o quadro Modo de rodízio da página Hoje): os dias de um período, de 7 em 7, cada um com o que o plano tem agora e a escolha de partida do seletor (o relógio escolhido à mão, livre ou auto: Decida por mim), os relógios disponíveis e o critério do Decida por mim. Gravar: recurso=rodizio, acao=manual' => '手动轮换（今天页面的轮换模式框）：某一时段的日子，每 7 天一组，每一天含计划当前的内容以及选择器的初始选择（手动选择的手表、空闲或自动：帮我决定）、可用的手表以及“帮我决定”的标准。保存：recurso=rodizio, acao=manual',
        'datas AAAA-MM-DD, de hoje em diante, até 2 anos (obrigatórias; inválidas: 400 com erro)' => '日期 AAAA-MM-DD，从今天起，最多 2 年（必填；无效：400 并附带错误）',
        '1, 2...: a página de 7 dias (padrão 1)' => '1、2……：每 7 天一页的页码（默认 1）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"',
        'os eventos personalizados da coleção, com quando disparam, os destinos e as agendas que recebem cada um, as 10 próximas ocorrências e os disparos' => '收藏的自定义事件，含触发时间、接收每个事件的推送目标和日历、接下来 10 次发生以及触发记录',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"',
        'os destinos das mensagens da coleção (a página Destinos): cada um (webhook HTTP, e-mail ou Web Push) com o nome, se está ligado, a mensagem padrão, o idioma, o que recebe (cada tipo de aviso e cada evento, com o modelo próprio), o que é do tipo dele (o webhook: método, endereço, formato, campos, corpo JSON e os cabeçalhos, sem o valor; o e-mail: para quem; o Web Push: o usuário e quantos aparelhos dele) e a prévia de hoje (o que sairia de manhã e à noite); os tipos, os avisos, as âncoras, os idiomas, a mensagem padrão do modelo, se o e-mail e o Web Push estão configurados no servidor e quem vê a coleção (para o Web Push)' => '收藏的消息推送目标（推送目标页面）：每个（HTTP webhook、电子邮件或 Web Push）含名称、是否启用、默认消息、语言、接收的内容（每种提醒和每个事件，带各自的模板）、其类型特有的内容（webhook：方法、地址、格式、字段、JSON 正文和请求头，不含值；电子邮件：收件人；Web Push：用户及其设备数量）以及今天的预览（早上和晚上会发出的内容）；类型、提醒、占位符、语言、模板的默认消息、服务器是否配置了电子邮件和 Web Push，以及谁能看到该收藏（用于 Web Push）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=destinos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=destinos"',
        'as agendas da coleção (a página Agendas): cada uma (Google Agenda, CalDAV, Outlook ou link ICS) com o nome, se está ativa, a janela em dias, o modelo do evento, o idioma, o que recebe, o que é do tipo dela (sem os segredos: só se estão preenchidos; o link ICS sai inteiro), quantos eventos o sistema criou nela e a prévia (os primeiros eventos que têm de estar nela agora); os tipos, os avisos, as âncoras, os idiomas, o padrão do modelo e se o Outlook está configurado no servidor (com o endereço de retorno para registrar o aplicativo na Microsoft)' => '收藏的日历（日历页面）：每个（Google 日历、CalDAV、Outlook 或 ICS 链接）含名称、是否启用、以天为单位的时间窗口、事件模板、语言、接收的内容、其类型特有的内容（不含机密：只说明是否已填写；ICS 链接完整输出）、系统在其中创建的事件数量以及预览（现在应在其中的前几个事件）；类型、提醒、占位符、语言、默认模板以及服务器是否配置了 Outlook（带用于在 Microsoft 注册应用的回调地址）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agendas"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agendas"',
        'o calendário de uma agenda do tipo link ICS (text/calendar, não é JSON), para assinar em qualquer app de agenda: responde sem login, pela chave secreta do link (quem tem o link vê os eventos; Gerar outro link, na página Agendas, desliga o antigo); chave desconhecida: 404' => 'ICS 链接类型日历的日历内容（text/calendar，不是 JSON），可在任何日历应用中订阅：无需登录即可响应，凭链接的密钥（持有链接者可看到事件；在日历页面“生成新链接”会让旧链接失效）；未知密钥：404',
        'a chave do link (vem pronta no link da agenda)' => '链接的密钥（已包含在日历的链接中）',
        'curl "http://servidor/relojoeiro/api.php?recurso=ics&chave=Xy3..."' => 'curl "http://servidor/relojoeiro/api.php?recurso=ics&chave=Xy3..."',
        'a volta da página da Microsoft depois de Conectar ao Outlook (com code e state): guarda a conexão na agenda e leva para a página Agendas com o recado (302). É o endereço de retorno que se registra no aplicativo da Microsoft (OUTLOOK_CLIENTE_ID); não é para chamar à mão' => '连接到 Outlook 之后从 Microsoft 页面返回（带 code 和 state）：把连接保存到日历中，并带着提示跳转到日历页面（302）。这是在 Microsoft 应用（OUTLOOK_CLIENTE_ID）中注册的回调地址；不要手动调用',
        'o código que a Microsoft manda' => 'Microsoft 发来的代码',
        'a agenda e a assinatura dela' => '日历及其签名',
        '(a Microsoft chama: http://servidor/relojoeiro/api.php?recurso=outlook_retorno&code=...&state=...)' => '（由 Microsoft 调用：http://servidor/relojoeiro/api.php?recurso=outlook_retorno&code=...&state=...）',
        'a foto de um relógio (a imagem, não é JSON)' => '一块手表的照片（图像，不是 JSON）',
        'o id do relógio' => '手表的 id',
        'curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"' => 'curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"',
        'os documentos de um relógio (ou de todos): o manual, a nota fiscal em PDF e em XML (com o resumo da NF-e), fotos, vídeos e o que mais for, com as categorias (e quantos documentos cada uma tem), os relógios (com quantos), se a pasta dos documentos está pronta, se a cópia de segurança no banco está ligada, onde está cada arquivo (na pasta, no banco) e o maior arquivo aceito' => '一块手表（或全部手表）的文档：说明书、PDF 和 XML 发票（含 NF-e 摘要）、照片、视频以及其他内容，含类别（以及每一类有多少文档）、手表（含数量）、文档文件夹是否就绪、数据库中的备份是否已开启、每个文件位于何处（在文件夹中、在数据库中）以及接受的最大文件',
        'o id do relógio (sem ele: de todos)' => '手表的 id（不传：全部手表的）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"',
        'o arquivo de um documento (não é JSON): imagens, vídeos, áudios, PDF e texto vêm para mostrar; o resto (inclusive XML, HTML e SVG), para baixar; aceita o pedido de um pedaço (Range), que o vídeo usa para avançar; se o arquivo sumiu da pasta, ou está cortado (o tamanho não confere com o do envio), ele é recriado antes a partir da cópia no banco' => '一份文档的文件（不是 JSON）：图像、视频、音频、PDF 和文本用于显示；其余（包括 XML、HTML 和 SVG）用于下载；接受分段请求（Range），视频用它来快进；如果文件已从文件夹中消失或被截断（大小与上传时不符），会先根据数据库中的副本重建',
        'o id do documento' => '文档的 id',
        '1: sempre para baixar' => '1：始终用于下载',
        '1: a miniatura da foto (sem ela, a foto)' => '1：照片的缩略图（没有缩略图则为照片）',
        'curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"' => 'curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"',
        'para o master, o painel das contas: cada usuário com o login, o e-mail, o papel (master ou comum), o idioma, quando foi criado, o último acesso, quando vence (a conta de demonstração) e quantos dias faltam, se está bloqueado, as coleções dele (com quantos relógios), as de que é membro, de quem vê tudo, quantos pedidos e tokens tem e o hash da senha (o algoritmo e o custo, para migrar com a mesma senha: veja senhas); e as coleções todas e os dias da demonstração. Para os outros, só a própria conta (o login, quando foi criada e o hash). A senha não existe no sistema' => '对 master 而言是账户面板：每个用户含登录名、电子邮件、角色（master 或普通）、语言、创建时间、最后访问、到期时间（演示账户）和剩余天数、是否被封禁、他的收藏（含手表数量）、他作为成员的收藏、他能看到其全部内容的人、他有多少申请和令牌，以及密码哈希（算法和成本，用于以相同密码迁移：见 senhas）；还有所有收藏和演示天数。对其他人，只有自己的账户（登录名、创建时间和哈希）。密码在系统中并不存在',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"',
        'Minha conta: quem eu sou (o login, o e-mail, o papel, o idioma, se é demonstração e quantos dias faltam), a faixa Vendo como (o master vendo como outro usuário), as coleções que eu vejo (com o dono e o meu papel em cada uma) e a do pedido, as minhas árvores de grupos (com as coleções que usam cada uma), os meus pedidos de acesso esperando, os convites para o meu e-mail, quantas aprovações esperam por mim, os meus tokens de API (sem o token, que só aparece ao criar), os meus aparelhos lembrados (o aplicativo no celular), os meus aparelhos do Web Push e a chave pública dele, se o servidor manda e-mail, os dias da demonstração e os idiomas. Com parte=menu, só o que o menu das páginas usa (o seletor da coleção, o aviso da demonstração, as aprovações, a faixa Vendo como e o idioma padrão)' => '我的账户：我是谁（登录名、邮箱、角色、语言、是否演示账户及剩余天数）、“以某人身份查看”横幅（master 以其他用户身份查看）、我能看到的收藏（含所有者和我在每个收藏中的角色）及本次请求的收藏、我的分组树（含使用每棵树的收藏）、我待处理的访问请求、发到我邮箱的邀请、等待我审批的数量、我的 API 令牌（不含令牌本身，它只在创建时出现）、我记住的设备（手机上的应用）、我的 Web Push 设备及其公钥、服务器是否发送邮件、演示天数和语言。带 parte=menu 时，只返回页面菜单用到的内容（收藏选择器、演示提示、审批、“以某人身份查看”横幅和默认语言）',
        'menu: só o pedaço do menu das páginas' => 'menu：只返回页面菜单的部分',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=conta"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=conta"',
        'as coleções que eu vejo (cada uma com o dono, o meu papel e a raiz da árvore dela), a coleção do pedido e as minhas árvores de grupos (com quantos grupos e as coleções que usam cada uma). Gravar: escrita colecoes' => '我看到的收藏（每个含所有者、我的角色及其树的根）、请求所在的收藏以及我的分组树（含分组数量和使用每棵树的收藏）。保存：escrita colecoes',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=colecoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=colecoes"',
        'a página Aprovações: os pedidos de acesso que eu aprovo (os das minhas coleções e os de tudo meu; o master, todos), os convites de membros que esperam por mim, os convites que eu fiz, quem vê as minhas coleções (os membros de cada uma e quem tem tudo meu), as minhas coleções, para onde posso convidar, se o servidor manda e-mail e quantos dias um convite vale' => '审批页面：我审批的访问申请（我的收藏的申请以及我全部内容的申请；master 审批全部）、等待我的成员邀请、我发出的邀请、谁能看到我的收藏（每个收藏的成员以及能看到我全部内容的人）、我的收藏、我可以邀请到哪里、服务器是否发送电子邮件以及邀请的有效天数',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=aprovacoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=aprovacoes"',
        'o cadastro aberto (a página cadastro.php), sem login: se está aberto (CADASTRO_ABERTO), os dias da demonstração, se o servidor manda e-mail, os idiomas e, com ele aberto, as coleções e os donos (para pedir acesso); com convite=<token>, o convite (o e-mail, o que ele dá, até quando e se o e-mail já tem conta; false: o convite não vale mais). Gravar: escrita cadastro' => '公开注册（cadastro.php 页面），无需登录：是否开放（CADASTRO_ABERTO）、演示天数、服务器是否发送电子邮件、语言，以及开放时的收藏和所有者（用于申请访问）；带 convite=<token> 时返回邀请（电子邮件、它授予的内容、有效期以及该电子邮件是否已有账户；false：邀请已失效）。保存：escrita cadastro',
        'o token do link do convite' => '邀请链接的令牌',
        'curl "http://servidor/relojoeiro/api.php?recurso=cadastro"' => 'curl "http://servidor/relojoeiro/api.php?recurso=cadastro"',
        'as migrações que faltam aplicar no banco (lista vazia: está em dia); com o banco desatualizado, só ele (e o manual e o código, que não usam o banco) responde' => '数据库中尚未应用的迁移（空列表：已是最新）；数据库过期时，只有它（以及不使用数据库的手册和代码）会响应',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"',
        'a situação da instalação: o banco, se está vazio, instalado e em dia, as migrações que faltam, quantos usuários há e o próximo passo (instalar, aplicar as migrações, criar o primeiro usuário ou nada); responde também com o banco vazio, pelo token' => '安装情况：数据库、是否为空、是否已安装且为最新、尚未应用的迁移、有多少用户以及下一步（安装、应用迁移、创建第一个用户或无）；数据库为空时也会响应，通过 token',
        'curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"' => 'curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"',
        'o que a importação do sistema anterior usa: o servidor do banco antigo (sem a senha) e de onde ele vem no config.php, se o PHP tem a extensão do MySQL, quantos relógios este banco já tem (com algum, a importação pede substituir=1) e o que ela traz' => '从旧系统导入时使用的信息：旧数据库的服务器（不含密码）及其在 config.php 中的来源、PHP 是否有 MySQL 扩展、此数据库已有多少块手表（若已有，导入要求 substituir=1）以及它会带入什么',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"',
        'a cópia de segurança do banco (uma por dia, na rodada da noite do cron, na BACKUP_PASTA do config.php): se a pasta serve, quantas cópias ficam, se levam o conteúdo dos documentos, a versão do banco, a última e as cópias da pasta (da mais nova para a mais velha); com arquivo=<nome>, baixa aquela cópia (JSON Lines comprimido, o mesmo nos quatro bancos). Fazer e restaurar: na escrita' => '数据库备份（每天一份，在 cron 的夜间轮次，位于 config.php 的 BACKUP_PASTA）：文件夹是否可用、保留多少份、是否包含文档内容、数据库版本、最近一次以及文件夹中的各份副本（从最新到最旧）；带 arquivo=<nome> 时，下载该副本（压缩的 JSON Lines，四种数据库相同）。执行和还原：在写入操作中',
        'o nome de uma cópia (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): baixa o arquivo' => '一份副本的名称（relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz）：下载该文件',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"',
        'o manifesto do aplicativo no celular (PWA; application/manifest+json): o nome, o ícone, as cores, o start_url e o scope. Responde sem login (o navegador pede ao instalar); com o cookie do aparelho lembrado (Minha conta, Lembrar este aparelho), o start_url leva a chave dele (index.php?aparelho=...): o aplicativo instalado abre já entrando, também no iPhone, onde o aplicativo não compartilha os cookies do Safari' => '手机上应用（PWA；application/manifest+json）的清单：名称、图标、颜色、start_url 和 scope。无需登录即可响应（浏览器在安装时请求）；带已记住设备的 cookie（我的账户，记住此设备）时，start_url 携带其密钥（index.php?aparelho=...）：已安装的应用打开即登录，在 iPhone 上也是如此（那里应用不共享 Safari 的 cookie）',
        'curl "http://servidor/relojoeiro/api.php?recurso=manifest"' => 'curl "http://servidor/relojoeiro/api.php?recurso=manifest"',
        'o service worker do aplicativo (JavaScript, não é JSON): o sw.js com, na frente, a versão (muda quando qualquer arquivo das telas muda) e a lista dos arquivos guardados na instalação (o estilo, os scripts, os ícones e a página sem conexão). Responde sem login. Guarda os arquivos das telas e os textos do idioma; as páginas vêm sempre da rede (sem rede, a página offline.html) e a API nunca fica em cache; recebe o Web Push' => '应用的 service worker（JavaScript，不是 JSON）：sw.js，前面带版本号（任何界面文件变动时都会改变）和安装时缓存的文件列表（样式、脚本、图标和无连接页面）。无需登录即可响应。它缓存界面文件和语言文本；页面始终来自网络（无网络时显示 offline.html），API 永不缓存；它接收 Web Push',
        'curl "http://servidor/relojoeiro/api.php?recurso=sw"' => 'curl "http://servidor/relojoeiro/api.php?recurso=sw"',
        'o login das páginas: sem login, 401 (o navegador pede o usuário e a senha); com login, vai para a página de volta (302) ou diz quem entrou (usuario, por, volta). É para onde o api.js manda quem abre uma página sem login' => '页面登录：未登录时为 401（浏览器要求输入用户和密码）；已登录时，转到返回页面（302）或说明谁已进入（usuario、por、volta）。api.js 会把未登录就打开页面的人送到这里',
        'uma página do sistema para onde ir depois de entrar (index.php, plano.php?..., ajuda.php#...); outra coisa não vale' => '登录后要前往的系统页面（index.php、plano.php?...、ajuda.php#...）；其他内容无效',
        'no navegador: http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php' => '在浏览器中：http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php',
        'as autonomias de cada relógio, enxuto e rápido, para sistemas de fora, em segundos inteiros: prevista (cheio, pelo cadastro), atual (cheio, pela conta do sistema com o gasto medido), estimada (quanto ainda dura seguindo o plano), restante_em_uso (no pulso sem tirar), restante_guardado (parado) e quando acaba (acaba_em_unixtimestamp, acaba_em_segundos, acaba_em_datacomtz); null com o motivo em motivos' => '每块手表的续航，精简且快速，供外部系统使用，以整数秒计：prevista（满电，按档案）、atual（满电，按系统根据实测消耗的计算）、estimada（按计划还能持续多久）、restante_em_uso（戴在手腕上不摘下）、restante_guardado（静止）以及何时耗尽（acaba_em_unixtimestamp、acaba_em_segundos、acaba_em_datacomtz）；为 null 时原因在 motivos 中',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"',
        'esta explicação: os recursos, os parâmetros, as ações de escrita com os campos, os exemplos, o dicionário de todos os campos (campos) e as funções do motor; com parte=manual, o manual (veja manual); com parte=reconstrucao, a reconstrução (veja reconstrucao); com parte=codigo, o código (veja codigo)' => '本说明：资源、参数、带字段的写入操作、示例、全部字段的词典（campos）以及引擎函数；parte=manual 时为手册（见 manual）；parte=reconstrucao 时为重建（见 reconstrucao）；parte=codigo 时为代码（见 codigo）',
        'manual: em vez desta explicação, o texto da página Ajuda (o mesmo que recurso=manual); reconstrucao: o roteiro para reescrever a aplicação do zero (o mesmo que recurso=reconstrucao); codigo: o código do sistema (o mesmo que recurso=codigo)' => 'manual：不返回本说明，而是帮助页面的文本（与 recurso=manual 相同）；reconstrucao：从零重写应用的路线（与 recurso=reconstrucao 相同）；codigo：系统代码（与 recurso=codigo 相同）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"',
        'o texto da página Ajuda: os trechos do README para quem usa (a ideia central, como funciona, o cadastro campo por campo, a Configuração, um dia com o sistema, as telas, as perguntas frequentes e como reescrever o sistema do zero), em markdown, inteiro e seção por seção (título, nível, âncora e texto), e já em HTML com o sumário, como a página Ajuda mostra; sem o README.md na pasta: 404; responde mesmo com o banco desatualizado. O mesmo que recurso=ajuda&parte=manual' => '帮助页面的文本：给使用者的 README 片段（核心理念、如何运作、逐字段的档案、设置、使用系统的一天、各界面、常见问题以及如何从零重写系统），为 markdown，有全文也有逐节（标题、级别、锚点和文本），并且已是带目录的 HTML，与帮助页面所显示的一致；文件夹中没有 README.md：404；即使数据库过期也会响应。与 recurso=ajuda&parte=manual 相同',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"',
        'o roteiro para reescrever a aplicação inteira do zero, em qualquer linguagem e banco, chegando ao mesmo sistema: o que ele é, os princípios, a arquitetura, a ordem de construção e as regras de cada parte (árvore e campos, lançamentos, fórmulas, avisos, gasto medido, critérios, rodízio e escala, pulso sozinho, cron, mensagens e agenda, documentos, telas, segurança, testes), a especificação visual de cada tela (telas: o visual com os valores exatos, o menu e cada página com as tabelas, os campos, os botões e as mensagens), a lista do código do sistema (codigo: o mesmo do recurso=codigo, que traz cada arquivo como está agora), o modelo de dados lido do próprio banco (tabelas, colunas, chaves, índices e regras de validação) e as listas do código (funções das fórmulas, tipos de campo, formatos de lançamento, repetições, dias da semana, âncoras, canais, migrações e as constantes do config.php). O mesmo que recurso=ajuda&parte=reconstrucao' => '从零完整重写应用的路线，可用任何语言和数据库，得到同一个系统：它是什么、原则、架构、构建顺序以及每一部分的规则（树和字段、记录、公式、提醒、实测消耗、标准、轮换和排班表、独自上手腕、cron、消息和日历、文档、界面、安全、测试）、每个界面的视觉规格（telas：带确切值的外观、菜单以及每个页面的表格、字段、按钮和消息）、系统代码清单（codigo：与 recurso=codigo 相同，按现状给出每个文件）、从数据库本身读出的数据模型（表、列、键、索引和校验规则）以及代码中的清单（公式函数、字段类型、记录格式、重复方式、星期几、锚点、渠道、迁移和 config.php 的常量）。与 recurso=ajuda&parte=reconstrucao 相同',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"',
        'o código do sistema como está agora, lido do disco na hora do pedido, para a reescrita ler o original: cada arquivo (as páginas, o estilo, o JavaScript, a API, o núcleo, o banco, as migrações, o servidor, os testes, a documentação e as capturas das telas) com a camada, o que ele é, a linguagem, o tamanho, as linhas, o SHA-256 e a data; nas páginas, os arquivos que ela carrega e o HTML que o navegador recebe; e o que fica de fora de propósito (o config.php, a chave do Google, o banco, os documentos, as senhas), com o que ver no lugar. Só saem os arquivos do sistema (os do repositório); responde mesmo com o banco vazio ou desatualizado. O mesmo que recurso=ajuda&parte=codigo' => '系统当前的代码，在请求时从磁盘读取，供重写时阅读原文：每个文件（页面、样式、JavaScript、API、核心、数据库、迁移、服务器、测试、文档和界面截图）含层次、它是什么、语言、大小、行数、SHA-256 和日期；对于页面，含它加载的文件以及浏览器收到的 HTML；以及有意排除的内容（config.php、Google 密钥、数据库、文档、密码），并说明改看什么。只输出系统文件（仓库中的那些）；即使数据库为空或过期也会响应。与 recurso=ajuda&parte=codigo 相同',
        'um arquivo (o nome como está em arquivos, ex.: estilo.css, docs/telas/hoje.png): vem com o conteúdo como está (conteudo; a imagem em conteudo_base64) e, numa página, com o HTML que o navegador recebe (html)' => '一个文件（名称与 arquivos 中的一致，例：estilo.css、docs/telas/hoje.png）：按原样返回内容（conteudo；图像在 conteudo_base64 中），若是页面，还返回浏览器收到的 HTML（html）',
        '1, com arquivo: o arquivo puro, sem JSON (texto como text/plain, para ler no navegador; imagem como imagem)' => '1，且带 arquivo：纯文件，无 JSON（文本为 text/plain，供在浏览器中阅读；图像作为图像）',
        '1, com arquivo de uma página e cru=1: o HTML que o navegador recebe, puro' => '1，且带某个页面的 arquivo 以及 cru=1：浏览器收到的 HTML，纯文本',
        '1, sem arquivo: a lista com o conteúdo de todos (com f[arquivos][camada]=tela, só o das telas)' => '1，不带 arquivo：带全部内容的列表（带 f[arquivos][camada]=tela 时，只含界面的）',
        'no navegador: http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1' => '在浏览器中：http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1',
        'POST, com os campos em formulário ou em JSON no corpo (Content-Type: application/json); recurso e acao nos campos ou na URL. Resposta: {ok, mensagem, erros, id}; 400 quando recusado (os erros dizem por quê). Ex. em JSON: curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php' => 'POST，字段以表单或正文中的 JSON 提交（Content-Type: application/json）；recurso 和 acao 可在字段中或 URL 中。响应：{ok, mensagem, erros, id}；被拒绝时为 400（erros 说明原因）。JSON 示例：curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php',
        'nome, pai_id (0 = na raiz)' => 'nome, pai_id（0 = 在根）',
        'curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php',
        'id, nome' => 'id, nome',
        'curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php',
        'id, pai_id (0 = na raiz; não pode ir para dentro dele mesmo)' => 'id, pai_id（0 = 在根；不能移入自身内部）',
        'curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php',
        'id, direcao (sobe ou desce)' => 'id, direcao（sobe 或 desce）',
        'curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php',
        'id; o que é dele (subgrupos, relógios, campos, tipos de lançamento, fórmulas, avisos) sobe para o de cima, menos as versões de fórmulas e avisos que o de cima já tem (essas saem); os blocos dos modos que sorteavam dele passam a sortear do de cima; os critérios próprios saem (os relógios usam os do lugar mais perto, acima)' => 'id；属于它的内容（子分组、手表、字段、记录类型、公式、提醒）上移到上级，但上级已有的公式和提醒版本除外（那些会被删除）；原本从它抽签的模式区块改为从上级抽签；自有标准被删除（手表改用上方最近位置的标准）',
        'curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php',
        'grupo[<id do relógio>] = o grupo (0 = na raiz), um ou vários' => 'grupo[<手表的 id>] = 分组（0 = 在根），一个或多个',
        'curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php',
        'identificador, nome, tipo (inteiro, decimal, sim_nao, data, lista, texto), unidade, opcoes (lista: uma por linha), padrao, no_id (0 = todos), so_desejado (1: o campo vale só nos relógios desejados, a lista de desejos; padrão 0)' => 'identificador, nome, tipo（inteiro、decimal、sim_nao、data、lista、texto）, unidade, opcoes（lista：每行一个）, padrao, no_id（0 = 全部）, so_desejado（1：该字段仅对心愿中的手表有效，即心愿单；默认 0）',
        'curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos (só o que vier muda)' => 'id 以及同样的字段（只改传来的）',
        'curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php',
        'confirmar=1; id (os valores dele saem junto)' => 'confirmar=1；id（它的值一并删除）',
        'curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'identificador, nome, formato (instantaneo, valor, sessao), unidade (com valor), fecha_as (sessão: HH:MM; vazio: não fecha sozinha), exclusiva (1 ou 0, só sessão), mede_gasto (1 ou 0, só com valor: cada leitura mede o gasto, comparando com a anterior), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual), no_id' => 'identificador, nome, formato（instantaneo、valor、sessao）, unidade（带值时）, fecha_as（时段：HH:MM；空：不会自行结束）, exclusiva（1 或 0，仅时段）, mede_gasto（1 或 0，仅带值时：每次读数与上一次比较来测量消耗）, condicao（何时有效：一条公式，1 有效、0 无效；空则始终有效；例：corda_manual）, no_id',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos' => 'id 以及同样的字段',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php',
        'confirmar=1; id (só sem lançamentos)' => 'confirmar=1；id（仅限没有记录时）',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'identificador, nome, expressao, unidade, no_id: uma fórmula nova, ou mais uma versão de uma que existe, em outro ponto da árvore' => 'identificador, nome, expressao, unidade, no_id：一条新公式，或已有公式在树的另一处的又一个版本',
        'curl -u lucas:senha -d recurso=formulas -d acao=nova -d identificador=idade_dias -d "nome=Idade (dias)" --data-urlencode "expressao=AGORA() - data_compra" -d unidade=dias -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=nova -d identificador=idade_dias -d "nome=Idade (dias)" --data-urlencode "expressao=AGORA() - data_compra" -d unidade=dias -d no_id=0 http://servidor/relojoeiro/api.php',
        'id: nome, expressao, unidade, no_id' => 'id：nome、expressao、unidade、no_id',
        'curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php',
        'confirmar=1; id (a versão)' => 'confirmar=1；id（版本）',
        'curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 cria), coluna (a chave de uma coluna da tabela dos relógios: codigo, nome, tipo, estado, carga, ultimo, manut, em, fazer, encostado, compra ou valor; vazio: nenhuma), nome, expressao (uma expressão de total: as funções de total em recurso=totais, funcoes), rodape (1 ou 0: no rodapé, embaixo da coluna; só com coluna), pagina (1 ou 0: na página de totais; pelo menos um dos dois), largura (estreito ou largo: o quadro na página de totais), formato (numero, inteiro, decimal, moeda, porcentagem, data ou dias); só o que vier muda' => 'id（0 为创建）、coluna（手表表格某列的键：codigo、nome、tipo、estado、carga、ultimo、manut、em、fazer、encostado、compra 或 valor；空：无）、nome、expressao（合计表达式：合计函数见 recurso=totais 的 funcoes）、rodape（1 或 0：在底部，列的下方；只有有列时）、pagina（1 或 0：在合计页面；两者至少一个）、largura（estreito 或 largo：合计页面上的方框）、formato（numero、inteiro、decimal、moeda、porcentagem、data 或 dias）；只改发送的内容',
        'curl -u lucas:senha -d recurso=totais -d acao=salvar -d id=0 -d coluna=valor -d nome="Valor por tipo" --data-urlencode "expressao=AGRUPADO(tipo; SOMA(valor_compra))" -d rodape=1 -d pagina=1 -d formato=moeda http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=totais -d acao=salvar -d id=0 -d coluna=valor -d nome="Valor por tipo" --data-urlencode "expressao=AGRUPADO(tipo; SOMA(valor_compra))" -d rodape=1 -d pagina=1 -d formato=moeda http://servidor/relojoeiro/api.php',
        'confirmar=1; id' => 'confirmar=1；id',
        'curl -u lucas:senha -d recurso=totais -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=totais -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id: troca de lugar com o de cima na ordem (a ordem embaixo de cada coluna e dos quadros da página)' => 'id：与顺序中上面的一个交换位置（每列下方以及页面方框的顺序）',
        'curl -u lucas:senha -d recurso=totais -d acao=subir -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=totais -d acao=subir -d id=4 http://servidor/relojoeiro/api.php',
        'id: troca de lugar com o de baixo' => 'id：与下面的一个交换位置',
        'curl -u lucas:senha -d recurso=totais -d acao=descer -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=totais -d acao=descer -d id=4 http://servidor/relojoeiro/api.php',
        'id (0 ou ausente cria), nome, no_id, disponivel (1 ou 0), copia_banco (1 ou 0: a cópia no banco de todos os documentos dele; o cron copia ou tira aos poucos), posse (a situação na coleção: colecao, o padrão; desejado, a lista de desejos; emprestado; vendido; arquivado. Fora da coleção o relógio fica indisponível (disponivel=1 é ignorado, com uma nota), e, saindo dela, as sessões abertas dele (no pulso, no sol...) fecham agora e os dias dele no plano de amanhã em diante saem e são sorteados de novo (hoje fica, mas ele não vai ao pulso sozinho); voltando para ela sem disponivel, fica disponível), valores[<identificador do campo>]: só muda o que vier; valor vazio apaga (os campos só nos desejados, como o preco_alvo, só gravam no desejado)' => 'id（0 或省略则创建）, nome, no_id, disponivel（1 或 0）, copia_banco（1 或 0：其全部文档在数据库中的副本；cron 会逐步复制或移除）, posse（在收藏中的情况：colecao，默认；desejado，心愿单；emprestado；vendido；arquivado。离开收藏后手表变为不可用（disponivel=1 被忽略，并附一条说明），并且在离开时，其已打开的时段（在手腕上、在晒太阳中……）立即结束，其计划中从明天起的日子被移除并重新抽签（今天保留，但它不会独自上手腕）；回到收藏时若不传 disponivel，则变为可用）, valores[<字段的标识符>]：只改传来的；空值会删除（仅用于心愿中的字段，如 preco_alvo，只在 desejado 时保存）',
        'curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php',
        'id, foto_base64 (JPEG, PNG ou WebP, até 4 MB; data:image/...;base64,... ou só o base64)' => 'id, foto_base64（JPEG、PNG 或 WebP，最大 4 MB；data:image/...;base64,... 或仅 base64）',
        'curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php',
        'confirmar=1; id (com todo o histórico, a foto e os documentos, inclusive os arquivos deles; os acessórios dele ficam soltos)' => 'confirmar=1；id（连同全部历史、照片和文档，包括它们的文件；它的配件保留为未分配）',
        'curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'relogio_id, categoria_id, titulo (vazio: o nome do arquivo), data (AAAA-MM-DD), descricao, copia_banco (1: pede a cópia destes arquivos no banco; o config.php e o relógio, se pedem, valem por cima) e o arquivo: arquivos[] (upload; vários de uma vez) ou arquivo_base64 com arquivo_nome; a miniatura de uma foto, opcional: miniatura (upload, JPEG, PNG ou WebP até 1 MB) ou miniatura_base64. Cada arquivo até o limite (recurso=documentos, limite) e do tipo que a categoria aceita. O arquivo vai para a pasta e, se a cópia é pedida (pelo config.php, pelo relógio ou pelo próprio arquivo), também para o banco, em pedaços de 4 MB (se a cópia falhar, o documento fica e a mensagem avisa; o cron tenta de novo). Responde ids: os documentos guardados' => 'relogio_id, categoria_id, titulo（空：文件名）, data（AAAA-MM-DD）, descricao, copia_banco（1：要求将这些文件复制到数据库；若 config.php 和手表也提出要求，则它们优先）以及文件：arquivos[]（上传；一次多个）或 arquivo_base64 配 arquivo_nome；照片缩略图，可选：miniatura（上传，JPEG、PNG 或 WebP，最大 1 MB）或 miniatura_base64。每个文件不超过上限（recurso=documentos，limite）且须为类别所接受的类型。文件进入文件夹，若要求副本（由 config.php、手表或文件本身提出），也以 4 MB 的分块写入数据库（若复制失败，文档仍保留并由消息告知；cron 会再试）。响应 ids：已保存的文档',
        'curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php',
        'id, categoria_id, titulo, data, descricao, copia_banco (1 ou 0): só muda o que vier; a cópia entra ou sai do banco na hora (só sai se o arquivo da pasta confere com ela)' => 'id, categoria_id, titulo, data, descricao, copia_banco（1 或 0）：只改传来的；副本立即进入或离开数据库（仅当文件夹中的文件与它一致时才离开）',
        'curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php',
        'confirmar=1; id: o documento, o arquivo dele na pasta e a cópia no banco' => 'confirmar=1；id：文档、它在文件夹中的文件以及数据库中的副本',
        'curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 ou ausente cria), nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro; padrão pulseira), relogio_id (o relógio de que ele é; 0: solto, serve a vários), observacao (até 1000): só muda o que vier' => 'id（0 或省略则创建）, nome（最多 120）, tipo（pulseira、caixa、estojo、ferramenta、carregador、peca、outro；默认 pulseira）, relogio_id（它所属的手表；0：未绑定，可供多块使用）, observacao（最多 1000）：只改传来的',
        'curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'identificador, nome, aceita[] (imagem, video, audio, pdf, xml; nenhum: qualquer arquivo), ordem (vazio: no fim)' => 'identificador, nome, aceita[]（imagem、video、audio、pdf、xml；一个都没有：任意文件）, ordem（空：放在末尾）',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php',
        'id, nome, aceita[], ordem (o identificador não muda)' => 'id, nome, aceita[], ordem（标识符不变）',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php',
        'confirmar=1; id (só uma categoria sem documentos)' => 'confirmar=1；id（仅限没有文档的分类）',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (instantâneo ou com valor), valor (com valor), quando (AAAA-MM-DD HH:MM; vazio: agora), medir (1, o padrão, ou 0: num tipo que mede o gasto, com 1 a medição entra na média; com 0 fica só no histórico), estado (uso ou repouso; vazio: não diz): a marcação da leitura, que fica gravada nela e manda (o gasto em uso sai só das leituras marcadas em uso; o em repouso, só das em repouso); se o pulso registrado no instante da leitura não bate com ela, a resposta vem com confirmar: true e a pergunta, e o lançamento só grava de novo com confirmar=1 (vale o que a pessoa marcou)' => 'relogio_id、tipo（瞬时或带值）、valor（带值）、quando（YYYY-MM-DD HH:MM；空：现在）、medir（1 为默认，或 0：在测量消耗的类型中，1 表示该测量计入平均；0 表示只留在历史）、estado（uso 或 repouso；空：不说明）：读数的标记，保存在读数中并起决定作用（使用中消耗只来自标记为使用中的读数；静置中消耗只来自静置中的读数）；如果读数那一刻记录的佩戴状态与之不符，响应会带 confirmar: true 和提问，记录只有再次发送并带 confirmar=1 才会保存（以本人的标记为准）',
        'curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (sessão), quando: abre a sessão; uma exclusiva fecha a outra exclusiva aberta' => 'relogio_id, tipo（时段）, quando：打开时段；独占的会结束另一个已打开的独占时段',
        'curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php',
        'relogio_id, tipo, quando: fecha a sessão aberta' => 'relogio_id, tipo, quando：结束已打开的时段',
        'curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php',
        'relogio_id, tipo, inicio (quando também vale), fim: uma sessão que já passou (espaço ou T entre data e hora); no pulso do relógio do dia, é uso do rodízio, como o iniciar; os trechos do mesmo tipo que ela cobre ou em que encosta (o iniciar aberto depois dela, por exemplo) viram um só, do primeiro início ao último fim (aberto, se um deles está aberto)' => 'relogio_id, tipo, inicio（quando 同样有效）, fim：一段已经过去的时段（日期与时间之间为空格或 T）；当天手表戴在手腕上时，算作轮换中的使用，与 iniciar 相同；它覆盖或相接的同类型片段（例如在它之后仍打开的 iniciar）合并为一段，从最早的开始到最晚的结束（若其中之一仍打开，则保持打开）',
        'curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php',
        'id: quando ou inicio e fim, valor, estado (a marcação da leitura: uso, repouso ou vazio; só o que vier)' => 'id：quando 或 inicio 和 fim、valor、estado（读数的标记：uso、repouso 或空；只改传来的）',
        'curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (a medição do gasto, de medicoes[] na ficha), usada (1: entra na conta; 0: fica só no histórico): pôr ou tirar uma medição da conta do gasto, sem apagar nada' => 'id（消耗测量，来自档案中的 medicoes[]），usada（1：计入计算；0：只留在历史中）：把一次测量放入或移出消耗计算，不删除任何东西',
        'curl -u lucas:senha -d recurso=lancamento -d acao=medicao -d id=13 -d usada=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=medicao -d id=13 -d usada=0 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (sessão), quando: fecha a sessão se ela está aberta, abre se está fechada (um botão só num atalho de celular). Em todas as ações, relogio_id=hoje é o relógio do dia, pelo plano' => 'relogio_id, tipo（时段）, quando：若时段已打开则结束，若已关闭则打开（手机快捷方式上的单一按钮）。在所有操作中，relogio_id=hoje 是当天的手表，按计划确定',
        'curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php' => 'curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php',
        'identificador, nome, expressao (a data prevista), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual = 0), antecedencia_dias, texto (o motivo, com {relogio}, {data}, {quando}, {limite}), resolve (o tipo de lançamento), ativo, no_id, escala (nao, uso, sempre), simula_valor, simula_horas, agenda (janela ou sempre), na_hora (1 ou 0: o Telegram recebe o aviso no minuto em que ele vence, uma vez)' => 'identificador, nome, expressao（预计日期）, condicao（何时有效：一条公式，1 有效、0 无效；空则始终有效；例：corda_manual = 0）, antecedencia_dias, texto（事由，含 {relogio}、{data}、{quando}、{limite}）, resolve（记录类型）, ativo, no_id, escala（nao、uso、sempre）, simula_valor, simula_horas, agenda（janela 或 sempre）, na_hora（1 或 0：Telegram 在提醒到期的那一分钟收到它，仅一次）',
        'curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos (menos o identificador)' => 'id 以及同样的字段（不含标识符）',
        'curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'escopo ("" todos, g:<grupo>, r:<relógio>), origem (herdado: copia o que ele usa hoje; vazio)' => 'escopo（"" 全部，g:<分组>，r:<手表>）, origem（herdado：复制它今天所使用的；空）',
        'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php',
        'escopo (volta a herdar o de cima)' => 'escopo（改回继承上级的）',
        'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php',
        'escopo, nome, peso (os outros abrem espaço na proporção)' => 'escopo, nome, peso（其余的按比例让出空间）',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php',
        'escopo, nome[<id>], peso[<id>]: todos os do conjunto, somando 100' => 'escopo, nome[<id>], peso[<id>]：该集合的全部，合计为 100',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php',
        'id (o peso dele vai para os outros na proporção)' => 'id（它的权重按比例分给其余各项）',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php',
        'parametro_id, nome, variavel (o identificador de um campo ou fórmula; metrica também vale), peso' => 'parametro_id, nome, variavel（一个字段或公式的标识符；metrica 同样有效）, peso',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php',
        'parametro_id, nome[<id>], peso[<id>]: somando 100' => 'parametro_id, nome[<id>], peso[<id>]：合计为 100',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php',
        'id, variavel (metrica também vale; as faixas recomeçam)' => 'id, variavel（metrica 同样有效；区间重新开始）',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php',
        'id, parametro_id (o de destino, de qualquer lugar)' => 'id, parametro_id（目标参数，可以是任意位置的）',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php',
        'tipo (parametro ou sub), id, direcao (sobe ou desce)' => 'tipo（parametro 或 sub）, id, direcao（sobe 或 desce）',
        'curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php',
        'sub_id, de[], ate[], categoria[], nota[], apagar[] (todas as faixas do subparâmetro de uma vez; a última vai até o limite da medida ou sem limite)' => 'sub_id, de[], ate[], categoria[], nota[], apagar[]（一次提交该子参数的全部区间；最后一档直到度量上限，或没有上限）',
        'curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php',
        '(nada): volta aos critérios iniciais' => '（无）：恢复为初始标准',
        'curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php',
        'modo (o id), selecao (o critério de escolha; só nos tipos semana, semana_fds e dia_semana), max_sem_uso (a garantia de rodízio, da coleção): grava os dois e marca o modo para os próximos sorteios; o plano gravado continua (rodizio resortear o refaz). Os blocos, as semanas e o roteiro se editam em recurso=modos' => 'modo（id）、selecao（选择标准；仅在 semana、semana_fds 和 dia_semana 类型中）、max_sem_uso（收藏的轮换保证）：保存两者并把该模式标记为后续抽签使用；已保存的计划继续有效（rodizio resortear 重做它）。区块、周数和脚本在 recurso=modos 中编辑',
        'curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d selecao=ponderado -d max_sem_uso=21 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d selecao=ponderado -d max_sem_uso=21 http://服务器/relojoeiro/api.php',
        '(nada): refaz o plano de amanhã até o fim da semana (o último dia dela, pela Configuração semana_inicio; até o fim da próxima semana, se ela já foi montada; na escala, até o fim da escala); se o dia ainda não começou no pulso, também hoje; os dias escolhidos à mão e os livres ficam (a mensagem diz quantos); sobrescrever=1 (a caixa Sobrescrever tudo): sai tudo o que o plano tem do começo do sorteio em diante, à mão, livre ou sorteado, e o modo monta de novo (a mensagem diz quantos foram sobrescritos)' => '（无）：从明天起重做计划到本周结束（本周最后一天，按设置 semana_inicio；如果下一周已编排，则到下一周结束；排班表模式下到排班结束）；如果当天还没开始佩戴，今天也重做；手动选择的日子和空闲日保留（消息会说明有多少）；sobrescrever=1（“全部覆盖”复选框）：计划中从抽签开始那天起的所有内容都会被清除，无论手动、空闲还是抽出的，然后模式重新编排（消息会说明覆盖了多少）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php',
        '(nada): inclusive hoje; se sair outro relógio, ele passa a ser o do pulso a partir de agora; sobrescrever=1: como no resortear, sai tudo de hoje em diante' => '（无）：包括今天；如果抽到另一块手表，从现在起它成为手腕上的那块；sobrescrever=1：与 resortear 相同，从今天起全部清除',
        'curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php',
        '(nada): hoje sem relógio: o dia fica livre (sem relógio e sem sorteio) e a sessão do rodízio de hoje termina agora (o tempo que já ficou no pulso conta; a que nem começou sai); nenhum relógio vai ao pulso sozinho hoje; os outros dias não mudam. Desfaz: trocar_dia de hoje (ou usando) com um relógio, ou resortear_hoje' => '（无）：今天没有手表：该日变为空闲（无手表且无抽签），并且今天的轮换时段现在结束（已经在手腕上的时间计入；尚未开始的则删除）；今天没有任何手表会独自上手腕；其他日子不变。撤销：对今天执行 trocar_dia（或 usando）并指定一块手表，或 resortear_hoje',
        'curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php',
        'relogio_id: o relógio de hoje, a partir de agora (na escala, fica os dias que faltavam do bloco de hoje); motivo (opcional): a frase que fica no plano no lugar de "Escolhido à mão: você marcou que está usando este hoje."' => 'relogio_id：从现在起今天的手表（在排班表中，保留今天区块尚未用完的日子）；motivo（可选）：留在计划中的句子，用来代替“手动选择：你标记了今天在用这一块。”',
        'curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php',
        'data (AAAA-MM-DD, de hoje em diante), relogio_id: o relógio daquele dia, escolhido à mão (hoje: como o usando; na escala, ela é refeita a partir do dia); relogio_id 0: o dia volta a ser sorteado; relogio_id sortear:<forma> (inteligente, ponderado, aleatorio ou fifo): o dia é sorteado agora por essa forma de escolha, entre os disponíveis do bloco do modo ativo que cobre o dia (sem bloco: todos), sem o que o dia tinha, com a garantia de rodízio na frente (menos no aleatório) e os dias anteriores do plano contados como uso; fica à mão, com o motivo "Sorteado à mão (<forma>): ..."; hoje, como o usando' => 'data（AAAA-MM-DD，从今天起）, relogio_id：那一天的手表，手动选择（今天：与 usando 相同；在排班表中，从该日起重做）；relogio_id 为 0：该日恢复为抽签；relogio_id 为 sortear:<forma>（inteligente、ponderado、aleatorio 或 fifo）：现在按该选择方式为该日抽签，在覆盖该日的当前模式区块的可用手表中（无区块：全部），排除该日原有的手表，轮换保证优先（随机除外），计划中此前的日子计为使用；该日保持手动，事由为“手动抽签（<方式>）：……”；今天则与 usando 相同',
        'curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php',
        'de, ate (AAAA-MM-DD, de hoje até 2 anos), relogio_ids[] (um ou vários, na ordem), dias_cada (padrão 1): os dias do período ficam escolhidos à mão, cada relógio dias_cada dias seguidos, e depois do último volta ao primeiro (hoje: o primeiro passa a ser o do pulso a partir de agora; na escala, ela é refeita a partir do começo do período)' => 'de, ate（AAAA-MM-DD，从今天起最多 2 年）, relogio_ids[]（一个或多个，按顺序）, dias_cada（默认 1）：该时段的日子改为手动选择，每块手表连续 dias_cada 天，最后一块之后回到第一块（今天：第一块从现在起成为手腕上的那块；在排班表中，从该时段开始处重做）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php',
        'de, ate (um dos dois pode faltar: sem o de, de amanhã; sem o ate, até o último dia do plano): os dias do período, de amanhã em diante (à mão, sorteados ou livres), saem do plano e o modo de rodízio monta esses dias de novo (os dias escolhidos à mão e os livres ficam quando se sorteia de novo ou se monta a próxima semana)' => 'de、ate（可以缺少其中一个：没有 de 时从明天开始；没有 ate 时到计划的最后一天）：时段内的日子从明天起（手动的、抽签的或空闲的）从计划中删除，轮换模式会重新安排这些日子（重新抽签或安排下一周时，手动选择的日子和空闲日保留）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php',
        'hoje (1: Excluindo hoje, de hoje em diante; sem ele, de amanhã em diante): toda a programação (os dias escolhidos à mão, os sorteados e os livres) sai e o modo ativo monta o plano de novo; hoje, se mudar, o novo vai para o pulso a partir de agora' => 'hoje（1：排除今天，从今天起；不传则从明天起）：全部安排（手动选择的日子、已抽签的和空闲的）被移除，由当前模式重新编排计划；今天若有变化，新的手表从现在起上手腕',
        'curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php',
        'de, ate; dias[AAAA-MM-DD]: o id do relógio, auto (Decida por mim: o sistema decide ao gravar, pelo critério do recurso=rodizio_manual), sortear:<forma> (o dia sorteado ao gravar por essa forma de escolha: inteligente, ponderado, aleatorio ou fifo; sem o de ontem e o de amanhã, como o Decida por mim) ou livre (hoje não). O dia que não vem fica com a escolha de partida (dias[].escolha do recurso=rodizio_manual). Tudo fica gravado à mão, com o motivo; hoje, com outro relógio, ele passa a ser o do pulso a partir de agora; hoje em auto continua o que está. Fora do período, vale o modo ativo' => 'de, ate；dias[AAAA-MM-DD]：手表的 id、auto（帮我决定：保存时由系统按 recurso=rodizio_manual 的标准决定）、sortear:<forma>（保存时按该选择方式为该日抽签：inteligente、ponderado、aleatorio 或 fifo；排除昨天和明天的，与帮我决定相同）或 livre（今天不可以）。未传来的日子保持初始选择（recurso=rodizio_manual 的 dias[].escolha）。全部按手动保存，并带事由；今天若换成另一块手表，从现在起它成为手腕上的那块；今天为 auto 则保持现状。时段之外，以当前模式为准',
        'curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php',
        'de, ate (como no periodo_sortear: um dos dois pode faltar): tudo o que o período tem, de amanhã em diante, sai e os dias ficam livres: sem relógio e sem sorteio (nem a escala), para escolher à mão (trocar_dia ou periodo num dia livre o tira de lá)' => 'de、ate（与 periodo_sortear 相同：可以缺少其中一个）：时段从明天起的所有内容都被删除，这些日子变为空闲：没有手表也不抽签（排班表也不排），留待手动选择（在空闲日上使用 trocar_dia 或 periodo 会取消空闲）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php',
        '(nada): em qualquer dia, monta ou refaz a semana seguinte inteira (do primeiro ao último dia, de segunda a domingo ou de domingo a sábado, pela Configuração semana_inicio; no último dia da semana, a que começa amanhã), com os dias que ainda faltam desta semana já contados como uso (a simulação no pulso); os dias escolhidos à mão ficam; sobrescrever=1: sai tudo do primeiro dia dela em diante (à mão, livre ou sorteado) antes de montar; recusada na escala' => '（无）：任何一天都可以编排或重做整个下一周（从第一天到最后一天，星期一至星期日或星期日至星期六，按设置 semana_inicio；在一周的最后一天时为明天开始的那一周），本周剩下的日子已算作佩戴（手腕上的模拟）；手动选择的日子保留；sobrescrever=1：编排前从它的第一天起全部清除（手动、空闲或抽出的）；在排班表模式下会被拒绝',
        'curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php',
        'id (0 cria), nome, tipo (semana, semana_fds, dia_semana, aleatorio, escala ou personalizado; sem ele, inferido dos blocos), selecao (inteligente, ponderado, aleatorio, fifo; o aleatório força aleatorio; a escala e o personalizado não a usam), escala_dias (só na escala: 7 a 730), semanas (1 a 8: quantas semanas à frente o plano vem montado; não na escala), blocos[n][nome], blocos[n][dias][], blocos[n][no_id], blocos[n][um_por] (dia ou bloco), blocos[n][relogio_id] (0: sorteia); substitui os blocos (a forma deles pelo tipo: semana e aleatorio, um bloco com os sete dias; semana_fds, segunda a sexta e sábado e domingo; dia_semana, um por dia); roteiro (o personalizado: as linhas "nome = expressão", conferidas como no recurso=roteiro; os outros tipos geram o roteiro dos blocos); ciclo (1 ou 0, o padrão: com o ciclo, um relógio só volta depois que todos os candidatos passaram na semana)' => 'id（0 为新建）、nome、tipo（semana、semana_fds、dia_semana、aleatorio、escala 或 personalizado；没有时由区块推断）、selecao（inteligente、ponderado、aleatorio、fifo；随机类型强制为 aleatorio；排班和自定义不使用它）、escala_dias（仅排班：7 到 730）、semanas（1 到 8：计划提前生成多少周；排班不用）、blocos[n][nome]、blocos[n][dias][]、blocos[n][no_id]、blocos[n][um_por]（dia 或 bloco）、blocos[n][relogio_id]（0：抽签）；替换全部区块（其形状由类型决定：semana 和 aleatorio，一个含七天的区块；semana_fds，周一到周五和周六周日；dia_semana，每天一个）；roteiro（自定义：“名称 = 表达式”各行，按 recurso=roteiro 的方式检查；其他类型由区块生成脚本）；ciclo（1 或 0，默认值：有循环时，一块手表要等所有候选在本周都轮过才会再来）',
        'curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php',
        'id (só marca o modo: o plano gravado continua, e o modo vale para os próximos sorteios; para refazer o plano, rodizio resortear ou periodo_sortear)' => 'id（只标记模式：已保存的计划保持不变，模式用于接下来的抽签；要重做计划，用 rodizio resortear 或 periodo_sortear）',
        'curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php',
        'confirmar=1; id (não o ativo)' => 'confirmar=1；id（不能是当前启用的）',
        'curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'horario_manha, horario_noite, uso_inicio, uso_fim, sol_fim (HH:MM), pulso_auto_inicio e pulso_auto_fim (1 ou 0), carga_limiar (1 a 99), sol_limiar (1 a 99), painel_modo (lado: o relógio abre no painel ao lado da lista; flutuante: numa janela grande por cima da página), destaque_hoje (dia: o destaque no alto da página Hoje é o relógio do dia; pulso: o relógio no pulso agora), idioma (pt-BR, en, zh-CN, hi, es ou fr: o idioma padrão da coleção: o das mensagens e das agendas sem idioma próprio), proximos_por_pagina e plano_por_pagina (1 a 366: o Mostrar até dos Próximos dias da página Hoje e do dia a dia da página Plano; padrão 7 e 31), atualizar_segundos (0 a 86400: de quantos em quantos segundos as páginas se atualizam sozinhas; 0 desliga; vazio: 60), relojinho_modo (hora, aleatorio ou sem_repeticao: o reloginho da barra e da aba, um dos 24 modelos por hora: o da hora, um sorteado a cada hora (pode repetir) ou os 24 embaralhados, cada um uma vez por dia; vazio: hora), max_sem_uso, previsao_limite, gasto_motor (vazio, horas, robusto, marcacao, cadastro ou formulas: como calcular o gasto da bateria, para todos os relógios da coleção; vazio: o do relógio e o do grupo), medicao_base (dias ou leituras: o que o gasto medido conta), medicao_janela_dias (1 a 3650: a janela da conta do gasto medido, com contar por dias), medicao_janela_leituras (2 a 1000: as últimas leituras de cada tipo, com contar por leituras), documentos_copia (vazio, todos ou nenhum: a cópia dos documentos no banco, para a coleção inteira), encostado_ativo (1 ou 0: liga ou desliga o aviso Encostado inteiro, o aviso do cadastro), encostado_dias (1 a 3650: o aviso Encostado, dias sem ir ao pulso), fuso (o fuso horário da coleção, um nome que o PHP conheça, como America/Sao_Paulo ou Europe/Lisbon: o de quem não escolheu o seu em Minha conta, e o do cron, das mensagens e das agendas; vazio: o do sistema), hora_relogio (o relógio da página Hora certa: analogico, digital, anadigi (o visor digital dentro do analógico) ou ambos (um ao lado do outro); vazio: ambos), semana_inicio (segunda ou domingo: o primeiro dia da semana do rodízio: o plano vem montado até o último dia da semana, e o ciclo, a próxima semana e o relógio para a semana inteira contam dela; vazio: segunda), url_sistema (o endereço do sistema, para os links das mensagens, do ICS e do Outlook: do sistema inteiro, só o master); só o que vier muda. As mensagens e as agendas têm os recursos delas: destinos e agendas' => 'horario_manha、horario_noite、uso_inicio、uso_fim、sol_fim（HH:MM）、pulso_auto_inicio 和 pulso_auto_fim（1 或 0）、carga_limiar（1 到 99）、sol_limiar（1 到 99）、painel_modo（lado：手表在列表旁的面板中打开；flutuante：在页面上方的大窗口中）、destaque_hoje（dia：今日页顶部的焦点是当日手表；pulso：当前佩戴的手表）、idioma（pt-BR、en、zh-CN、hi、es 或 fr：收藏的默认语言：无自身语言的消息和日历所用）、proximos_por_pagina 和 plano_por_pagina（1 到 366：今日页“接下来几天”和计划页逐日的“显示至”；默认 7 和 31）、atualizar_segundos（0 到 86400：页面每隔多少秒自动刷新；0 关闭；空：60）、relojinho_modo（hora、aleatorio 或 sem_repeticao：菜单栏和标签页的小手表，每小时 24 种款式之一：该小时自己的、每小时抽一个（可能重复）或 24 种打乱、每天每种一次；空：hora）、max_sem_uso、previsao_limite、gasto_motor（空、horas、robusto、marcacao、cadastro 或 formulas：如何计算电池消耗，对收藏中所有手表；空：按手表和分组的）、medicao_base（dias 或 leituras：测得消耗按什么计）、medicao_janela_dias（1 到 3650：按天数计时测得消耗的窗口）、medicao_janela_leituras（2 到 1000：按读数计时每类最近的读数数）、documentos_copia（空、todos 或 nenhum：文档在数据库中的副本，对整个收藏）、encostado_ativo（1 或 0：开启或关闭整个闲置提醒，即档案中的提醒）、encostado_dias（1 到 3650：闲置提醒，多少天没戴）、fuso（收藏的时区，PHP 认识的名称，如 America/Sao_Paulo 或 Europe/Lisbon：在“我的账户”中未选择自己时区的人所用，以及 cron、消息和日历所用；空：系统的）、hora_relogio（准确时间页面的时钟：analogico、digital、anadigi（数字显示嵌在模拟表盘内）或 ambos（并排）；空：ambos）、semana_inicio（segunda 或 domingo：轮换一周的第一天：计划编排到这一周的最后一天，循环、下一周和整周一块手表都按它来算；空：segunda）、url_sistema（系统地址，用于消息、ICS 和 Outlook 的链接：整个系统的，仅 master）；只改传来的。消息和日历有各自的资源：destinos 和 agendas',
        'curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d carga_limiar=25 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d carga_limiar=25 http://servidor/relojoeiro/api.php',
        'evento_id (ou id; 0 cria), nome, ativo, repeticao (uma, diaria, semanal, mensal, intervalo), hora (HH:MM), data_inicio, dias_semana (1 a 7), dia_mes, intervalo_dias, relogio_id; o evento novo já vai para todos os destinos da coleção' => 'evento_id（或 id；0 表示新建）、nome、ativo、repeticao（uma、diaria、semanal、mensal、intervalo）、hora（HH:MM）、data_inicio、dias_semana（1 到 7）、dia_mes、intervalo_dias、relogio_id；新事件会自动发往收藏的所有推送目标',
        'curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php',
        'evento_id (ou id), confirmar=1' => 'evento_id（或 id），confirmar=1',
        'curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 cria), tipo (webhook, email ou webpush; só ao criar), nome, ativo (1 ou 0), idioma (vazio: o da coleção), fuso (o fuso das horas no texto das mensagens dele, um nome que o PHP conheça; vazio: o da coleção), modelo (a mensagem padrão, com as âncoras), envia[] (os tipos que ele recebe: dia, vespera, os identificadores dos avisos, ev<id> dos eventos), modelo_<tipo> (o texto próprio de um tipo; vazio: a mensagem padrão); webhook: metodo (GET, POST ou PUT), url, formato (query, form ou json), campo_nome[] e campo_valor[] (cada valor com {titulo} e {mensagem}), corpo_json (opcional), cabecalho_nome[] e cabecalho_valor[] (guardados cifrados; vazio mantém o guardado); email: para (um ou mais, separados por vírgula); webpush: usuario_id (alguém que vê a coleção: vai para os aparelhos dele). Fora das coleções do master, o endereço do webhook tem de ser da internet (nada da rede interna do servidor)' => 'id（0 表示新建）、tipo（webhook、email 或 webpush；仅在新建时）、nome、ativo（1 或 0）、idioma（空：收藏的语言）、fuso（其消息文本中时间的时区，PHP 认识的名称；空：收藏的）、modelo（默认消息，带占位符）、envia[]（它接收的类型：dia、vespera、提醒的标识符、事件的 ev<id>）、modelo_<tipo>（某种类型专用的文本；空：默认消息）；webhook：metodo（GET、POST 或 PUT）、url、formato（query、form 或 json）、campo_nome[] 和 campo_valor[]（每个值可含 {titulo} 和 {mensagem}）、corpo_json（可选）、cabecalho_nome[] 和 cabecalho_valor[]（加密保存；空则保留已保存的值）；email：para（一个或多个，以逗号分隔）；webpush：usuario_id（能看到该收藏的某人：发往他的设备）。在 master 的收藏之外，webhook 地址必须位于互联网上（不能是服务器内部网络中的任何地址）',
        'curl -u lucas:senha -d recurso=destinos -d acao=salvar -d id=0 -d tipo=webhook -d "nome=Telegram" -d metodo=GET --data-urlencode "url=https://api.telegram.org/bot<token>/sendMessage" -d formato=query -d "campo_nome[]=chat_id" -d "campo_valor[]=123" -d "campo_nome[]=text" --data-urlencode "campo_valor[]={mensagem}" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=destinos -d acao=salvar -d id=0 -d tipo=webhook -d "nome=Telegram" -d metodo=GET --data-urlencode "url=https://api.telegram.org/bot<token>/sendMessage" -d formato=query -d "campo_nome[]=chat_id" -d "campo_valor[]=123" -d "campo_nome[]=text" --data-urlencode "campo_valor[]={mensagem}" http://servidor/relojoeiro/api.php',
        'id, qual (texto: uma mensagem de teste; manha ou noite: a mensagem de hoje desse horário, como ela sai por ele)' => 'id、qual（texto：一条测试消息；manha 或 noite：今天该时段的消息，按它的方式发出）',
        'curl -u lucas:senha -d recurso=destinos -d acao=testar -d id=1 -d qual=manha http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=destinos -d acao=testar -d id=1 -d qual=manha http://servidor/relojoeiro/api.php',
        'id, confirmar=1' => 'id，confirmar=1',
        'curl -u lucas:senha -d recurso=destinos -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=destinos -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 cria), tipo (google, caldav, outlook ou ics; só ao criar), nome, ativa (1 ou 0), janela_dias (1 a 365: quantos dias à frente ficam na agenda), idioma, fuso (o fuso das horas no texto dos eventos; vazio: o da coleção), modelo (o título na primeira linha, a descrição no resto, com as âncoras), envia[] (os tipos que ela recebe); google: calendario_id, chave_json (o JSON da conta de serviço, guardado cifrado; o caminho de um arquivo no servidor, só o master); caldav: url (o endereço do calendário), usuario, senha (no iCloud, uma senha de app; guardada cifrada; vazio mantém); outlook: calendario_id (vazio: o calendário principal), e depois outlook_conectar; ics: nada (o link sai pronto)' => 'id（0 表示新建）、tipo（google、caldav、outlook 或 ics；仅在新建时）、nome、ativa（1 或 0）、janela_dias（1 到 365：日历中保留未来多少天）、idioma、fuso（事件文本中时间的时区；空：收藏的）、modelo（第一行是标题，其余是描述，带占位符）、envia[]（它接收的类型）；google：calendario_id、chave_json（服务账户的 JSON，加密保存；服务器上某个文件的路径，仅限 master）；caldav：url（日历地址）、usuario、senha（iCloud 上用应用专用密码；加密保存；空则保留）；outlook：calendario_id（空：主日历），然后 outlook_conectar；ics：无（链接自动生成）',
        'curl -u lucas:senha -d recurso=agendas -d acao=salvar -d id=0 -d tipo=caldav -d "nome=iCloud" --data-urlencode "url=https://caldav.icloud.com/123/calendars/relogios/" -d usuario=eu@icloud.com -d senha=abcd-efgh-ijkl-mnop http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=salvar -d id=0 -d tipo=caldav -d "nome=iCloud" --data-urlencode "url=https://caldav.icloud.com/123/calendars/relogios/" -d usuario=eu@icloud.com -d senha=abcd-efgh-ijkl-mnop http://servidor/relojoeiro/api.php',
        'id: deixa a agenda igual ao que tem de estar nela agora (cria, atualiza e apaga os eventos do sistema); o cron faz sozinho de manhã e à noite' => 'id：让日历与现在应有的内容一致（创建、更新和删除系统的事件）；cron 每天早晚会自动执行',
        'curl -u lucas:senha -d recurso=agendas -d acao=sincronizar -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=sincronizar -d id=1 http://servidor/relojoeiro/api.php',
        'id: cria um evento de teste daqui a 10 minutos' => 'id：在 10 分钟后创建一个测试事件',
        'curl -u lucas:senha -d recurso=agendas -d acao=teste_criar -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=teste_criar -d id=1 http://servidor/relojoeiro/api.php',
        'id: remove o evento de teste' => 'id：删除测试事件',
        'curl -u lucas:senha -d recurso=agendas -d acao=teste_remover -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=teste_remover -d id=1 http://servidor/relojoeiro/api.php',
        'id (uma agenda ICS): gera outro link; o antigo para de funcionar' => 'id（一个 ICS 日历）：生成新链接；旧链接停止工作',
        'curl -u lucas:senha -d recurso=agendas -d acao=novo_link -d id=3 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=novo_link -d id=3 http://servidor/relojoeiro/api.php',
        'id (uma agenda do Outlook): devolve url, o endereço da Microsoft para entrar na conta e autorizar; a Microsoft volta para recurso=outlook_retorno' => 'id（一个 Outlook 日历）：返回 url，即用于登录账户并授权的 Microsoft 地址；Microsoft 随后返回到 recurso=outlook_retorno',
        'curl -u lucas:senha -d recurso=agendas -d acao=outlook_conectar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=outlook_conectar -d id=4 http://servidor/relojoeiro/api.php',
        'id, confirmar=1 (os eventos que o sistema criou nela ficam lá)' => 'id，confirmar=1（系统在其中创建的事件会保留在那里）',
        'curl -u lucas:senha -d recurso=agendas -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'login, senha (6 caracteres ou mais; login que existe: troca a senha); ou login e senha_hash (o hash de outro sistema, bcrypt ou argon2: o usuário entra com a senha de lá; veja senhas). A conta nova (só o master cria): email, idioma, colecao_nova (modelo: uma coleção com o conjunto inicial, o padrão; vazia: uma coleção sem nada; nenhuma: sem coleção). A conta criada pelo master é oficial (não vence). O primeiro usuário sai pelo token (sem usuários, o login não entra) e é o master. Quem não é o master só troca a própria senha' => 'login、senha（6 个字符或更多；已存在的登录名：修改密码）；或 login 和 senha_hash（其他系统的哈希，bcrypt 或 argon2：用户用那边的密码登录；见 senhas）。新账户（只有 master 能创建）：email、idioma、colecao_nova（modelo：带初始集合的收藏，默认；vazia：空收藏；nenhuma：不建收藏）。master 创建的账户是正式账户（不会到期）。第一个用户通过令牌创建（没有用户时登录无法进入），并且是 master。不是 master 的人只能修改自己的密码',
        'curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 -d email=visitante@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 -d email=visitante@exemplo.com http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login; novo_login, email, idioma, fuso (o fuso horário dele: um nome, navegador ou vazio: o da coleção), papel (master ou comum; sobra sempre um master; o master não vence)' => '（仅限 master）usuario_id 或 login；novo_login、email、idioma、fuso（他的时区：一个名称、navegador 或空：收藏的）、papel（master 或 comum；始终至少保留一个 master；master 不会到期）',
        'curl -u lucas:senha -d recurso=usuarios -d acao=alterar -d login=visitante -d email=novo@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=alterar -d login=visitante -d email=novo@exemplo.com http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login: a conta de demonstração vira oficial (não vence mais)' => '（仅限 master）usuario_id 或 login：演示账户转为正式账户（不再到期）',
        'curl -u lucas:senha -d recurso=usuarios -d acao=oficializar -d login=visitante http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=oficializar -d login=visitante http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login, dias (1 a 3650): soma os dias ao vencimento (ou a partir de hoje, se já venceu); os avisos de vencimento recomeçam' => '（仅限 master）usuario_id 或 login，dias（1 到 3650）：在到期日上加上这些天（如已到期则从今天起算）；到期提醒重新开始',
        'curl -u lucas:senha -d recurso=usuarios -d acao=prorrogar -d login=visitante -d dias=30 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=prorrogar -d login=visitante -d dias=30 http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login, dias (padrão: DEMO_DIAS): a conta oficial volta a ser de demonstração, vencendo daqui a esses dias' => '（仅限 master）usuario_id 或 login，dias（默认：DEMO_DIAS）：正式账户重新变为演示账户，在这些天后到期',
        'curl -u lucas:senha -d recurso=usuarios -d acao=voltar_demo -d login=visitante -d dias=15 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=voltar_demo -d login=visitante -d dias=15 http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login, bloqueado (1, o padrão: não entra mais, nem pelo token pessoal; 0: desbloqueia); não o próprio' => '（仅限 master）usuario_id 或 login，bloqueado（1，默认：不能再进入，个人令牌也不行；0：解除封禁）；不能是自己',
        'curl -u lucas:senha -d recurso=usuarios -d acao=bloquear -d login=visitante -d bloqueado=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=bloquear -d login=visitante -d bloqueado=1 http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login (o dono de agora), colecao_id, para (o login do novo dono): a coleção passa para o outro, com tudo; a árvore vai junto quando só ela a usa; senão, o novo dono ganha uma cópia da árvore, e a coleção passa para a cópia' => '（仅限 master）usuario_id 或 login（当前所有者）、colecao_id、para（新所有者的登录名）：收藏连同一切转给对方；只有它使用该树时，树一起转移；否则新所有者获得树的副本，收藏改用该副本',
        'curl -u lucas:senha -d recurso=usuarios -d acao=transferir -d login=lucas -d colecao_id=3 -d para=maria http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=transferir -d login=lucas -d colecao_id=3 -d para=maria http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login; colecao_id (membro de uma coleção) ou dono_id (ou dono, o login: todas as coleções desse dono, também as que vierem)' => '（仅限 master）usuario_id 或 login；colecao_id（成为某个收藏的成员）或 dono_id（或 dono，登录名：该所有者的所有收藏，包括以后的）',
        'curl -u lucas:senha -d recurso=usuarios -d acao=dar_acesso -d login=maria -d dono=lucas http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=dar_acesso -d login=maria -d dono=lucas http://servidor/relojoeiro/api.php',
        '(só o master) login (ou usuario_id), confirmar=1: o usuário sai com tudo o que é dele (as coleções, as árvores, os relógios, os arquivos, os acessos, os tokens); não o próprio; sobra sempre um master' => '（仅限 master）login（或 usuario_id），confirmar=1：用户连同其所有内容一起删除（收藏、树、手表、文件、访问权限、令牌）；不能是自己；始终至少保留一个 master',
        'curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante -d confirmar=1 http://servidor/relojoeiro/api.php',
        'email, idioma (vazio: o da coleção), fuso (o seu fuso horário: um nome que o PHP conheça, como America/Sao_Paulo; navegador: o do aparelho, que as páginas mandam no cookie fuso_navegador (um script manda fuso_pedido=); vazio: o da coleção, senão o do sistema), senha_atual e senha (a nova, 6 caracteres ou mais); só o que vier muda' => 'email、idioma（空：收藏的语言）、fuso（你的时区：PHP 认识的名称，如 America/Sao_Paulo；navegador：设备的，页面通过 fuso_navegador cookie 发送（脚本发送 fuso_pedido=）；空：收藏的，否则系统的）、senha_atual 和 senha（新密码，6 个字符或更多）；只修改传入的内容',
        'curl -u lucas:senha -d recurso=conta -d acao=alterar -d email=lucas@exemplo.com -d idioma=pt-BR -d fuso=America/Sao_Paulo http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=alterar -d email=lucas@exemplo.com -d idioma=pt-BR -d fuso=America/Sao_Paulo http://servidor/relojoeiro/api.php',
        'nome (onde ele vai ser usado): devolve token, que só aparece agora; ele vale como o seu login (cabeçalho X-Api-Token)' => 'nome（它将用于何处）：返回 token，它只在此刻出现；它等同于你的登录（请求头 X-Api-Token）',
        'curl -u lucas:senha -d recurso=conta -d acao=token_criar -d "nome=Atalho do celular" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=token_criar -d "nome=Atalho do celular" http://servidor/relojoeiro/api.php',
        'id (um token seu): quem o usava perde o acesso' => 'id（你的一个令牌）：使用它的一方失去访问权限',
        'curl -u lucas:senha -d recurso=conta -d acao=token_revogar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=token_revogar -d id=2 http://servidor/relojoeiro/api.php',
        'nome (o aparelho; vazio: o navegador que pediu): o aplicativo no celular. Cria a chave deste aparelho, grava o hash dela e devolve a chave num cookie (aparelho: só HTTP, um ano, na pasta do sistema); daí em diante o pedido que chega com o cookie, sem o login do site, entra como você. Devolve id' => 'nome（设备；空：发出请求的浏览器）：手机上的应用。创建此设备的密钥，保存其哈希并通过 cookie 返回密钥（aparelho：仅 HTTP，一年，系统目录下）；此后带该 cookie、不带站点登录的请求以你的身份进入。返回 id',
        'curl -u lucas:senha -c cookies.txt -d recurso=conta -d acao=aparelho_lembrar -d "nome=Celular" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -c cookies.txt -d recurso=conta -d acao=aparelho_lembrar -d "nome=Celular" http://servidor/relojoeiro/api.php',
        'id (um aparelho seu; vazio: o aparelho deste pedido, pelo cookie): a chave deixa de valer, e o cookie deste navegador é apagado se era ele. Trocar a senha esquece todos' => 'id（你的一个设备；空：本次请求的设备，按 cookie）：密钥失效，若是此浏览器则其 cookie 被清除。更改密码会忘记全部',
        'curl -u lucas:senha -d recurso=conta -d acao=aparelho_esquecer -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=aparelho_esquecer -d id=1 http://servidor/relojoeiro/api.php',
        'endpoint (https), p256dh e auth (a inscrição do navegador, como o PushManager entrega), aparelho (um nome): o aparelho passa a receber as notificações dos destinos Web Push que apontam para você' => 'endpoint（https）、p256dh 和 auth（浏览器的订阅，按 PushManager 提供的格式）、aparelho（一个名称）：该设备开始接收指向你的 Web Push 推送目标的通知',
        'curl -u lucas:senha -d recurso=conta -d acao=push_inscrever --data-urlencode endpoint=https://fcm.googleapis.com/fcm/send/... -d p256dh=BN... -d auth=k3... http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=push_inscrever --data-urlencode endpoint=https://fcm.googleapis.com/fcm/send/... -d p256dh=BN... -d auth=k3... http://servidor/relojoeiro/api.php',
        'id (ou endpoint): o aparelho deixa de receber' => 'id（或 endpoint）：该设备不再接收',
        'curl -u lucas:senha -d recurso=conta -d acao=push_cancelar -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=push_cancelar -d id=1 http://servidor/relojoeiro/api.php',
        '(nada): manda uma notificação de teste para os seus aparelhos' => '（无）：向你的设备发送一条测试通知',
        'curl -u lucas:senha -d recurso=conta -d acao=push_testar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=push_testar http://servidor/relojoeiro/api.php',
        '(só o master) para (vazio: só as conexões, sem mandar nada): conecta e entra no SMTP, no IMAP (e confere a pasta Enviados) e no POP, os que estiverem configurados, e manda um e-mail de teste para o endereço. A resposta traz teste: metodo, remetente, smtp, imap, pop e envio (cada um null, se não houve, ou {ok, erro}), registro (a conversa com os servidores, linha a linha, sem a senha nem o usuário em base64) e config (o mesmo que o email do recurso=conta). Sem o envio configurado, a resposta é um erro, com teste.config dizendo o que falta' => '（仅 master）para（留空：只测试连接，不发送任何内容）：连接并登录 SMTP、IMAP（并检查“已发送”文件夹）和 POP 中已配置的那些，并向该地址发送一封测试邮件。响应包含 teste：metodo、remetente、smtp、imap、pop 和 envio（各自为 null 表示没有进行，或 {ok, erro}）、registro（与服务器的对话，逐行显示，不含密码，也不含 base64 编码的用户名）以及 config（与 recurso=conta 的 email 相同）。没有配置发送时，响应为错误，teste.config 说明缺少什么',
        'curl -u lucas:senha -d recurso=conta -d acao=email_testar -d para=lucas@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=email_testar -d para=lucas@exemplo.com http://servidor/relojoeiro/api.php',
        '(só o master; nada): gera um par de chaves do Web Push; a resposta traz config (as duas linhas para o config.php) e chaves' => '（仅限 master；无）：生成一对 Web Push 密钥；响应中带 config（写入 config.php 的两行）和 chaves',
        'curl -u lucas:senha -d recurso=conta -d acao=vapid_gerar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=vapid_gerar http://servidor/relojoeiro/api.php',
        'confirmar=1: a sua conta sai com tudo o que é dela (as coleções, as árvores, os relógios, os arquivos, os acessos, os tokens); sobra sempre um master' => 'confirmar=1：你的账户连同其所有内容一起删除（收藏、树、手表、文件、访问权限、令牌）；始终至少保留一个 master',
        'curl -u lucas:senha -d recurso=conta -d acao=excluir -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=excluir -d confirmar=1 http://servidor/relojoeiro/api.php',
        'nome, opcao (modelo: com o conjunto inicial, numa árvore nova, o padrão; vazia: numa árvore nova só com a raiz; arvore: numa árvore sua que já existe, com arvore_id: o cadastro fica em comum com as outras coleções dela); o master cria para outro com dono_id. A resposta traz id e arvore_id' => 'nome、opcao（modelo：带初始集合，在一棵新树中，默认；vazia：在一棵只有根的新树中；arvore：在你已有的一棵树中，带 arvore_id：定义与该树的其他收藏共用）；master 可用 dono_id 为他人创建。响应中带 id 和 arvore_id',
        'curl -u lucas:senha -d recurso=colecoes -d acao=criar -d "nome=Relógios do meu pai" -d opcao=modelo http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=criar -d "nome=Relógios do meu pai" -d opcao=modelo http://servidor/relojoeiro/api.php',
        'id, nome (não repete entre as coleções do dono)' => 'id、nome（在同一所有者的收藏之间不能重复）',
        'curl -u lucas:senha -d recurso=colecoes -d acao=renomear -d id=3 -d "nome=Herança" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=renomear -d id=3 -d "nome=Herança" http://servidor/relojoeiro/api.php',
        'id, confirmar=1: a coleção sai com tudo o que é dela (os relógios, o histórico, o plano, os destinos, as agendas, os arquivos); a árvore fica' => 'id，confirmar=1：收藏连同其所有内容一起删除（手表、历史、计划、推送目标、日历、文件）；树保留',
        'curl -u lucas:senha -d recurso=colecoes -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'arvore_id, nome: uma cópia da árvore inteira (os grupos e o cadastro deles), sem coleção; a resposta traz arvore_id' => 'arvore_id、nome：整棵树的副本（分组及其定义），不带收藏；响应中带 arvore_id',
        'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_copiar -d arvore_id=1 -d "nome=Grupos para testes" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_copiar -d arvore_id=1 -d "nome=Grupos para testes" http://servidor/relojoeiro/api.php',
        'arvore_id, nome' => 'arvore_id、nome',
        'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_renomear -d arvore_id=1 -d "nome=Meus grupos" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_renomear -d arvore_id=1 -d "nome=Meus grupos" http://servidor/relojoeiro/api.php',
        'arvore_id, confirmar=1: a árvore sai com o cadastro dela e com as coleções que a usam (e tudo delas)' => 'arvore_id，confirmar=1：树连同其定义以及使用它的收藏（及其全部内容）一起删除',
        'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_excluir -d arvore_id=9 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_excluir -d arvore_id=9 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'usuario_id; colecao_id (membro de uma coleção sua) ou dono_id (ou dono, o login: o acesso a tudo seu), confirmar=1: a pessoa deixa de ver; nada mais é apagado. Só o dono (ou o master)' => 'usuario_id；colecao_id（你某个收藏的成员）或 dono_id（或 dono，登录名：对你全部内容的访问），confirmar=1：此人不再能看到；不删除其他任何东西。仅限所有者（或 master）',
        'curl -u lucas:senha -d recurso=acessos -d acao=remover -d usuario_id=5 -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessos -d acao=remover -d usuario_id=5 -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'colecao_id ou dono_id (ou dono), confirmar=1: você deixa de ver (o dono não sai da própria coleção: ele a exclui ou o master a transfere)' => 'colecao_id 或 dono_id（或 dono），confirmar=1：你不再能看到（所有者不能退出自己的收藏：他可以删除它，或由 master 转移）',
        'curl -u maria:senha -d recurso=acessos -d acao=sair -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=acessos -d acao=sair -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'email; colecao_id (uma coleção que você vê) ou dono_id (ou dono: tudo de um dono; só o próprio dono ou o master): o convite do dono (ou do master) sai na hora, por e-mail, com o link (vale CONVITE_DIAS dias; sem e-mail no servidor, a resposta traz link, para você mandar); o de um membro espera o dono aprovar' => 'email；colecao_id（你能看到的一个收藏）或 dono_id（或 dono：某个所有者的全部内容；仅限所有者本人或 master）：所有者（或 master）的邀请会立即通过电子邮件发出，带链接（有效 CONVITE_DIAS 天；服务器没有电子邮件时，响应中带 link，由你发送）；成员的邀请需等待所有者批准',
        'curl -u lucas:senha -d recurso=convites -d acao=convidar -d email=amigo@exemplo.com -d colecao_id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=convidar -d email=amigo@exemplo.com -d colecao_id=1 http://servidor/relojoeiro/api.php',
        'id (um convite de membro, para uma coleção sua): aprova e manda o link' => 'id（成员发出的、针对你某个收藏的邀请）：批准并发送链接',
        'curl -u lucas:senha -d recurso=convites -d acao=aprovar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=aprovar -d id=4 http://servidor/relojoeiro/api.php',
        'id: o convite sai' => 'id：删除邀请',
        'curl -u lucas:senha -d recurso=convites -d acao=recusar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=recusar -d id=4 http://servidor/relojoeiro/api.php',
        'id (um convite já aprovado): manda de novo, com um link novo (o anterior para de valer)' => 'id（已批准的邀请）：重新发送，带新链接（之前的链接失效）',
        'curl -u lucas:senha -d recurso=convites -d acao=reenviar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=reenviar -d id=4 http://servidor/relojoeiro/api.php',
        'id (quem convidou, ou o dono): o convite sai' => 'id（邀请人或所有者）：删除邀请',
        'curl -u lucas:senha -d recurso=convites -d acao=cancelar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=cancelar -d id=4 http://servidor/relojoeiro/api.php',
        'token (o do link): quem já tem conta aceita o convite e passa a ver o que ele dá (quem não tem cria a conta pelo link: recurso=cadastro)' => 'token（链接中的令牌）：已有账户的人接受邀请，开始看到邀请授予的内容（没有账户的人通过链接创建账户：recurso=cadastro）',
        'curl -u maria:senha -d recurso=convites -d acao=aceitar -d token=Xy3... http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=convites -d acao=aceitar -d token=Xy3... http://servidor/relojoeiro/api.php',
        'colecao_id (o código de uma coleção) ou dono_id (o código de um dono: tudo dele, também o que vier), o código que o dono passou (nunca o login: nada no pedido diz quem tem conta; um código que não serve dá sempre o mesmo erro), mensagem (um recado para o dono): o dono recebe um e-mail; o pedido espera CONVITE_DIAS dias; a resposta e a lista dos seus pedidos mostram só o código até a aprovação' => 'colecao_id（某个收藏的编号）或 dono_id（某个所有者的编号：其全部内容，包括以后的），即所有者给出的编号（从不使用登录名：申请中没有任何信息表明谁有账户；无效编号总是返回同样的错误），mensagem（给所有者的留言）：所有者会收到一封电子邮件；申请等待 CONVITE_DIAS 天；在批准之前，回复和你的申请列表只显示编号',
        'curl -u maria:senha -d recurso=pedidos -d acao=pedir -d dono_id=1 -d "mensagem=Oi, é a Maria" http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=pedidos -d acao=pedir -d dono_id=1 -d "mensagem=Oi, é a Maria" http://servidor/relojoeiro/api.php',
        'id (o dono do alvo, ou o master): a pessoa passa a ver, e recebe um e-mail' => 'id（目标的所有者，或 master）：此人开始能看到，并收到一封电子邮件',
        'curl -u lucas:senha -d recurso=pedidos -d acao=aprovar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=pedidos -d acao=aprovar -d id=2 http://servidor/relojoeiro/api.php',
        'id: o pedido sai, e a pessoa recebe um e-mail' => 'id：删除申请，此人收到一封电子邮件',
        'curl -u lucas:senha -d recurso=pedidos -d acao=recusar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=pedidos -d acao=recusar -d id=2 http://servidor/relojoeiro/api.php',
        'id (um pedido seu)' => 'id（你的一个申请）',
        'curl -u maria:senha -d recurso=pedidos -d acao=cancelar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=pedidos -d acao=cancelar -d id=2 http://servidor/relojoeiro/api.php',
        '(sem login) login (até 60 caracteres, sem dois-pontos), senha (6 ou mais), email, idioma, opcao (modelo: uma coleção com o conjunto inicial; vazia: uma coleção sem nada; pedir: pedir acesso, com colecao_id ou dono_id, o código que o dono passou, e mensagem), convite (o token do link: a conta já vê o que o convite dá; opcao modelo ou nenhuma). Com o cadastro fechado (CADASTRO_ABERTO = false), só com convite. A conta é de demonstração por DEMO_DIAS dias (0: oficial), com aviso por e-mail 7 dias e 1 dia antes; vencida, o cron a apaga com tudo' => '（无需登录）login（最多 60 个字符，不含冒号）、senha（6 个或更多）、email、idioma、opcao（modelo：带初始集合的收藏；vazia：空收藏；pedir：申请访问，带 colecao_id 或 dono_id（所有者给出的编号）和 mensagem）、convite（链接中的令牌：账户直接看到邀请授予的内容；opcao 为 modelo 或 nenhuma）。注册关闭时（CADASTRO_ABERTO = false），只能凭邀请。账户为演示账户，有效 DEMO_DIAS 天（0：正式），到期前 7 天和 1 天通过电子邮件提醒；到期后由 cron 连同一切删除',
        'curl -d recurso=cadastro -d acao=criar_conta -d login=maria -d senha=segredo123 -d email=maria@exemplo.com -d opcao=modelo http://servidor/relojoeiro/api.php' => 'curl -d recurso=cadastro -d acao=criar_conta -d login=maria -d senha=segredo123 -d email=maria@exemplo.com -d opcao=modelo http://servidor/relojoeiro/api.php',
        '(sem login) email (ou o login): manda o link para escolher uma senha nova (vale 2 horas); a resposta é a mesma exista a conta ou não' => '（无需登录）email（或登录名）：发送设置新密码的链接（有效 2 小时）；无论账户是否存在，响应都相同',
        'curl -d recurso=cadastro -d acao=esqueci_senha -d email=maria@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -d recurso=cadastro -d acao=esqueci_senha -d email=maria@exemplo.com http://servidor/relojoeiro/api.php',
        '(sem login) token (o do link), senha (a nova)' => '（无需登录）token（链接中的令牌）、senha（新密码）',
        'curl -d recurso=cadastro -d acao=nova_senha -d token=Ab9... -d senha=outra12345 http://servidor/relojoeiro/api.php' => 'curl -d recurso=cadastro -d acao=nova_senha -d token=Ab9... -d senha=outra12345 http://servidor/relojoeiro/api.php',
        '(nada): aplica as migrações pendentes, na ordem: o SQL de cada uma e, se ela tiver, o passo em PHP' => '（无）：按顺序应用待处理的迁移：每一条的 SQL，以及它若有的 PHP 步骤',
        'curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php',
        '(nada; lingua= escolhe o idioma, como em qualquer pedido: fora do português, o cadastro inicial sai nele e ele vira o idioma padrão, config.idioma): instala o banco do config.php, só num banco vazio (o schema.sql traduzido para o banco, com os passos em PHP das migrações), pelo token (antes da instalação não há usuários); a resposta traz comandos, tabelas e segundos. Depois: o primeiro usuário, em recurso=usuarios, acao=salvar' => '（无；lingua= 选择语言，与任意请求相同：若不是葡萄牙语，初始档案用该语言输出，并成为默认语言 config.idioma）：安装 config.php 中的数据库，仅限空数据库（翻译到该数据库的 schema.sql，含各迁移的 PHP 步骤），通过 token（安装之前没有用户）；响应包含 comandos、tabelas 和秒数。然后：第一个用户，在 recurso=usuarios, acao=salvar',
        'curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php' => 'curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php',
        'banco (o nome do banco antigo, MySQL/MariaDB), substituir (1: apaga antes os relógios e o histórico deste banco; obrigatório quando ele já tem relógios): traz a árvore, os relógios, as fotos, os usuários, os valores dos campos e o histórico, tudo numa transação (parou no meio: nada fica gravado); a resposta traz contagem (quantos de cada)' => 'banco（旧数据库的名称，MySQL/MariaDB）, substituir（1：先删除此数据库中的手表和历史；当它已有手表时必填）：带入树、手表、照片、用户、字段的值以及历史，全部在一个事务中（中途停止：什么都不会保存）；响应包含 contagem（每一类有多少）',
        'curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php',
        '(nada): faz uma cópia agora na BACKUP_PASTA (as mais velhas que passam do BACKUP_MANTER saem); a resposta traz arquivo' => '（无）：现在在 BACKUP_PASTA 做一份副本（超过 BACKUP_MANTER 的最旧副本会被删除）；响应包含 arquivo',
        'curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php',
        'arquivo (o nome de uma cópia da pasta): antes, guarda uma cópia do que está agora; depois, num passo só, troca todos os registros pelos da cópia (se algo falha, nada muda); só uma cópia da mesma versão do banco; sem o conteúdo dos documentos, eles voltam sem a cópia no banco e o cron refaz a pedida' => 'arquivo（文件夹中一份副本的名称）：先保存当前内容的一份副本；然后一步把全部记录换成该副本中的记录（若有失败，则什么都不改）；只能是同一数据库版本的副本；若不含文档内容，文档会回来但没有数据库中的副本，cron 会重新做被要求的复制',
        'curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php',
        'a senha não fica guardada em lugar nenhum: fica só o hash dela, feito pelo password_hash do PHP com PASSWORD_DEFAULT (bcrypt). O hash tem 60 caracteres: $2y$, o custo com dois dígitos e $ (12 é 2^12 rodadas), o sal (22 caracteres, sorteado a cada senha) e o resultado (31). O sal e o custo vão dentro do próprio hash' => '密码不会保存在任何地方：只保存其 hash，由 PHP 的 password_hash 以 PASSWORD_DEFAULT（bcrypt）生成。hash 有 60 个字符：$2y$、两位数字的代价和 $（12 即 2^12 轮）、盐（22 个字符，每个密码随机抽取）以及结果（31）。盐和代价都在 hash 自身之内',
        'o hash não se desfaz em senha (é de mão única). Para conferir, calcula-se o bcrypt da senha digitada com o sal e o custo que estão no hash e compara-se com o resultado: é o que o password_verify do PHP faz no login. A mesma senha dá hashes diferentes a cada cálculo (o sal muda), e todos conferem' => 'hash 不能还原成密码（它是单向的）。校验时，用 hash 中的盐和代价计算所输入密码的 bcrypt，再与结果比较：这就是 PHP 的 password_verify 在登录时所做的。同一密码每次计算得到的 hash 都不同（盐会变），但都能对上',
        'leve o login e o senha_hash de cada um (recurso=usuarios, ou a resposta sem recurso) e, no outro sistema, confira a senha digitada contra o hash com o bcrypt dele: cada um entra lá com a mesma senha de sempre. $2y$ (PHP) e $2b$ (Python, Node, Java, C#...) são o mesmo cálculo; se a biblioteca recusar o $2y$, troque o começo por $2b$' => '带走每一个的 login 和 senha_hash（recurso=usuarios，或不带 recurso 的响应），在另一个系统里用它的 bcrypt 把输入的密码与 hash 核对：每个人在那边用一直以来的同一密码进入。$2y$（PHP）和 $2b$（Python、Node、Java、C#……）是同一种计算；若库拒绝 $2y$，把开头换成 $2b$',
        'POST recurso=usuarios, acao=salvar, login e senha_hash (um bcrypt $2y$, $2b$ ou $2a$, ou um argon2): o usuário entra aqui com a senha que tinha lá, sem ninguém saber qual é (o $2b$ é guardado como $2y$, o mesmo cálculo)' => 'POST recurso=usuarios, acao=salvar, login 和 senha_hash（bcrypt 的 $2y$、$2b$ 或 $2a$，或 argon2）：用户在这里用那边原有的密码进入，没有人知道密码是什么（$2b$ 会按 $2y$ 保存，计算相同）',
        'conferir: password_verify($senha, $hash); fazer: password_hash($senha, PASSWORD_DEFAULT)' => '校验：password_verify($senha, $hash)；生成：password_hash($senha, PASSWORD_DEFAULT)',
        'pip install bcrypt; conferir: bcrypt.checkpw(senha.encode(), hash.encode()); fazer: bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()' => 'pip install bcrypt；校验：bcrypt.checkpw(senha.encode(), hash.encode())；生成：bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()',
        'npm install bcryptjs; conferir: require("bcryptjs").compareSync(senha, hash); fazer: require("bcryptjs").hashSync(senha, 12)' => 'npm install bcryptjs；校验：require("bcryptjs").compareSync(senha, hash)；生成：require("bcryptjs").hashSync(senha, 12)',
        'Spring Security: new BCryptPasswordEncoder().matches(senha, hash) (com jBCrypt, BCrypt.checkpw(senha, hash) trocando $2y$ por $2a$)' => 'Spring Security：new BCryptPasswordEncoder().matches(senha, hash)（若用 jBCrypt，则 BCrypt.checkpw(senha, hash)，并把 $2y$ 换成 $2a$）',
        'BCrypt.Net-Next: BCrypt.Net.BCrypt.Verify(senha, hash)' => 'BCrypt.Net-Next: BCrypt.Net.BCrypt.Verify(senha, hash)',
        'em qualquer consulta: a resposta sem parâmetros e todos os recursos' => '在任意查询中：不带参数的响应以及全部资源',
        'incluir=relogios,plano: só essas partes da resposta' => 'incluir=relogios,plano：只返回响应中的这些部分',
        'excluir=motor,criterios: a resposta sem essas partes' => 'excluir=motor,criterios：响应中不含这些部分',
        'as regras valem para uma lista da resposta, pelo caminho dela entre os colchetes: relogios, plano, avisos, eventos, usuarios, cron.execucoes, criterios.notas, criterios.conjuntos, agendas_desejadas, relogios.lancamentos, relogios.avisos, relogios.linha_do_tempo, relogio.leituras (na ficha)...; lista dentro de lista vale em cada item' => '规则作用于响应中的某个列表，以方括号中的路径表示：relogios、plano、avisos、eventos、usuarios、cron.execucoes、criterios.notas、criterios.conjuntos、agendas_desejadas、relogios.lancamentos、relogios.avisos、relogios.linha_do_tempo、relogio.leituras（在详情中）……；列表中的列表作用于每一项',
        'qualquer campo do item; com ponto entra num objeto (compra.valor) ou, numa lista de itens com identificador, no item daquele identificador (formulas.energia.valor, campos.loja.valor)' => '条目的任意字段；用点进入一个对象（compra.valor），或者在带标识符的条目列表中，进入该标识符对应的条目（formulas.energia.valor、campos.loja.valor）',
        'igual a v (vários separados por vírgula: igual a um deles; numa lista de valores, se algum for)' => '等于 v（多个以逗号分隔：等于其中之一；在值列表中，若有任何一个等于）',
        'a partir de v (números como números; datas e textos como texto)' => '从 v 起（数字按数字；日期和文本按文本）',
        'até v (uma data sem hora vai até o fim daquele dia)' => '直到 v（不带时间的日期算到那天结束）',
        'o texto contém t' => '文本包含 t',
        'diferente de v (vários separados por vírgula: de todos)' => '不等于 v（多个以逗号分隔：全部都不等于）',
        'vazio (1) ou preenchido (0)' => '空（1）或已填写（0）',
        'o texto t em qualquer campo do item' => '文本 t 出现在条目的任意字段中',
        'ordena pelo campo; -campo: do maior para o menor; vários separados por vírgula' => '按该字段排序；-campo：从大到小；多个以逗号分隔',
        'N itens por página, a página P' => '每页 N 项，第 P 页',
        'só esses campos de cada item (com ponto também)' => '只返回每个条目的这些字段（也可以用点）',
        'textos sem diferença de maiúsculas e acentos; verdadeiro e falso valem 1 e 0; filtros juntos: o item tem de passar em todos' => '文本不区分大小写和重音；真和假相当于 1 和 0；多个筛选一起用：条目必须全部通过',
        'ganha _filtros: {listas: {caminho: {antes, passaram, devolvidos, pagina, limite}}, ignorados: [o caminho sem lista, a parte que não existe]}; com filtros, objetos vazios saem como listas vazias' => '会多出 _filtros：{listas: {caminho: {antes, passaram, devolvidos, pagina, limite}}, ignorados: [没有列表的路径, 不存在的部分]}；有筛选时，空对象输出为空列表',
        'limite, pagina, ordem e busca sem colchetes continuam sendo os do recurso (historico, cron)' => '不带方括号的 limite、pagina、ordem 和 busca 仍然属于该资源本身（historico、cron）',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][disponivel]=1&mostrar[relogios]=id,nome&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][disponivel]=1&mostrar[relogios]=id,nome&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][formulas.energia.valor][ate]=20&ordem[relogios]=formulas.energia.valor&mostrar[relogios]=nome,formulas.energia.valor&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][formulas.energia.valor][ate]=20&ordem[relogios]=formulas.energia.valor&mostrar[relogios]=nome,formulas.energia.valor&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][id]=10,12&f[relogios.lancamentos][tipo]=carga&f[relogios.lancamentos][inicio][de]=2026-09-01&mostrar[relogios]=nome,lancamentos&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][id]=10,12&f[relogios.lancamentos][tipo]=carga&f[relogios.lancamentos][inicio][de]=2026-09-01&mostrar[relogios]=nome,lancamentos&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][campos.loja.valor][contem]=aliexpress&mostrar[relogios]=nome,campos.valor_compra.valor&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][campos.loja.valor][contem]=aliexpress&mostrar[relogios]=nome,campos.valor_compra.valor&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=plano&f[plano][data][de]=2026-10-01&f[plano][data][ate]=2026-10-31&f[plano][relogio][contem]=xiaomi"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=plano&f[plano][data][de]=2026-10-01&f[plano][data][ate]=2026-10-31&f[plano][relogio][contem]=xiaomi"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=cron&f[cron.execucoes][teve_erro]=1&limite[cron.execucoes]=20&pagina[cron.execucoes]=2"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=cron&f[cron.execucoes][teve_erro]=1&limite[cron.execucoes]=20&pagina[cron.execucoes]=2"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=criterios&f[criterios.notas][nota][de]=50&ordem[criterios.notas]=-nota&mostrar[criterios.notas]=relogio,nota"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=criterios&f[criterios.notas][nota][de]=50&ordem[criterios.notas]=-nota&mostrar[criterios.notas]=relogio,nota"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=hoje&f[relogios][com_aviso]=1&mostrar[relogios]=nome,manutencao.nome"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=hoje&f[relogios][com_aviso]=1&mostrar[relogios]=nome,manutencao.nome"',
        '[] no caminho: uma lista (o campo é de cada item); <...>: uma chave que varia (o identificador de um campo, um estado, uma função...). Datas e horas no fuso do sistema (o FUSO do config.php; sem ele, o do PHP, date.timezone); null: sem valor. Números de tempo em segundos são inteiros.' => '路径中的 []：一个列表（该字段属于每一项）；<...>：会变化的键（一个字段的标识符、一个状态、一个函数……）。日期和时间使用系统时区（config.php 的 FUSO；没有则用 PHP 的 date.timezone）；null：无值。以秒计的时间数字是整数。',
        'os grupos, em ordem de árvore' => '各分组，按树的顺序',
        'o caminho por extenso ("Tradicional › Quartzo › Solar")' => '完整路径（“Tradicional › Quartzo › Solar”）',
        'o número do grupo' => '分组的编号',
        'o nome do grupo' => '分组的名称',
        'a posição entre os irmãos' => '在同级中的位置',
        'o grupo de cima; null: na raiz' => '上级分组；null：在根',
        'o nível na árvore (0: na raiz)' => '在树中的层级（0：在根）',
        'os avisos cadastrados (cada identificador pode ter uma versão por grupo)' => '已登记的提醒（每个标识符可以按分组有一个版本）',
        'a data na agenda: janela (só dentro da antecedência da agenda) ou sempre' => '在日历中的日期：janela（仅在日历提前量之内）或 sempre',
        '1: o aviso vai pelo Telegram no minuto em que vence (uma vez, até ser resolvido); 0: só no alerta da manhã' => '1：提醒在到期的那一分钟经 Telegram 发出（一次，直到被解决）；0：只在早晨警报中',
        'com quantos dias antes ele entra "em breve" (número)' => '提前多少天进入“即将”（数字）',
        'o aviso vale' => '该提醒有效',
        'vale quando: uma fórmula que diz para quais relógios do grupo o aviso vale (1 vale, 0 não; ex.: corda_manual = 0, só o automático sem corda); null: vale para todos' => '何时有效：一条公式，说明该提醒对分组中的哪些手表有效（1 有效，0 无效；例：corda_manual = 0，仅没有上链的自动手表）；null：对全部有效',
        'na escala inteligente: nao, uso ou sempre' => '在智能排班表中：nao、uso 或 sempre',
        'a fórmula da data prevista' => '预计日期的公式',
        'o número da versão' => '版本号',
        'o aviso (o tipo dele nos canais)' => '该提醒（它在各渠道中的类型）',
        'esse grupo por extenso' => '该分组的完整名称',
        'o grupo desta versão; null: todos' => '此版本的分组；null：全部',
        'o nome do aviso — a âncora {acao}' => '提醒的名称——锚点 {acao}',
        'o tipo de lançamento que resolve (o botão na tela Hoje); null: nenhum' => '用来解决它的记录类型（今天界面上的按钮）；null：没有',
        'as horas da sessão que a escala simula para resolver (número; null)' => '排班表为解决它而模拟的时段小时数（数字；null）',
        'o valor do lançamento que a escala simula para resolver (número; null)' => '排班表为解决它而模拟的记录值（数字；null）',
        'o motivo, com {relogio}, {data}, {quando} e {limite} — a âncora {motivo}' => '事由，含 {relogio}、{data}、{quando} 和 {limite}——锚点 {motivo}',
        'os campos do cadastro dos relógios (cada um vale para o grupo dele e tudo abaixo)' => '手表档案的字段（每一个对其分组及其下全部有效）',
        'o número do campo' => '字段的编号',
        'o nome do campo nas fórmulas e nos critérios' => '字段在公式和标准中的名称',
        'o grupo em que o campo vale; null: todos os relógios' => '字段生效的分组；null：全部手表',
        'o nome do campo' => '字段的名称',
        'as opções de um campo de lista, uma por linha (texto; vazio nos outros)' => '列表字段的选项，每行一个（文本；其他类型为空）',
        'a posição do campo no cadastro' => '字段在档案中的位置',
        'o valor usado quando o relógio não tem o campo preenchido (texto; null: nenhum)' => '手表未填写该字段时使用的值（文本；null：没有）',
        'inteiro, decimal, sim_nao, data, lista ou texto' => 'inteiro、decimal、sim_nao、data、lista 或 texto',
        'a unidade (texto; vazio: nenhuma)' => '单位（文本；空：没有）',
        'o limite de carga geral (%): carregar quando a carga chega a ele (o campo carga_minima do relógio, se preenchido, vale no lugar)' => '总电量上限（%）：当电量到达该值时充电（若手表的 carga_minima 字段已填写，则改用它）',
        'os avisos "na hora" que já foram pelo Telegram e ainda estão vencidos (relogio_id:identificador, separados por vírgula): o cron não manda de novo' => '已经经 Telegram 发出且仍处于到期状态的“到点”提醒（relogio_id:identificador，以逗号分隔）：cron 不会再次发送',
        'até que dia vai a escala inteligente gerada (texto AAAA-MM-DD; vazio fora da escala)' => '已生成的智能排班表延伸到哪一天（文本 AAAA-MM-DD；不在排班表中则为空）',
        'o dia em que a escala foi gerada pela última vez (texto AAAA-MM-DD)' => '排班表最近一次生成的日期（文本 AAAA-MM-DD）',
        'a hora da rodada da manhã do cron: o relógio do dia e os avisos (HH:MM)' => 'cron 早晨轮次的时间：当天的手表和提醒（HH:MM）',
        'a hora da rodada da noite: preparar o relógio de amanhã (HH:MM)' => '夜晚轮次的时间：准备明天的手表（HH:MM）',
        'a garantia de rodízio: nenhum relógio passa desses dias sem uso (0 desliga)' => '轮换保障：没有任何手表会超过这么多天不被使用（0 则关闭）',
        'o que o gasto medido conta ("contar por"): dias (as medições dos últimos medicao_janela_dias) ou leituras (as últimas medicao_janela_leituras de cada tipo, em uso e em repouso)' => '测得消耗按什么计（“按什么计”）：dias（最近 medicao_janela_dias 天的测量）或 leituras（每类最近 medicao_janela_leituras 次，使用中和静置中）',
        'como calcular o gasto da bateria, para todos os relógios da coleção: horas (pelas horas registradas, o motor original), robusto (pelas horas registradas, com leituras e cadastro), marcacao (pela marcação das leituras: duas taxas separadas), cadastro (só o cadastro) ou formulas (pelas fórmulas taxa_uso e taxa_repouso); vazio: vale o do relógio (o campo gasto_motor do cadastro), senão o padrão desse campo (o grupo), senão horas' => '如何计算电池消耗，对收藏中所有手表：horas（按记录的小时数，原始引擎）、robusto（按记录的小时数，结合读数和档案）、marcacao（按读数的标记：两个独立的速率）、cadastro（仅档案）或 formulas（按 taxa_uso 和 taxa_repouso 公式）；空：以手表的为准（档案字段 gasto_motor），否则该字段的默认值（分组），否则 horas',
        'a cópia dos documentos no banco, para a coleção inteira: todos (todo arquivo vai também para o banco), nenhum (nenhum vai, nem o que o relógio ou o arquivo pedem) ou vazio (cada relógio e cada arquivo decidem)' => '文档在数据库中的副本，对整个收藏：todos（所有文件也存入数据库）、nenhum（都不存，即使手表或文件要求）或空（每块手表和每个文件自行决定）',
        'o DOCUMENTOS_COPIA_BANCO que o config.php ainda define (verdadeiro ou falso), que não vale mais (a Configuração mostra o aviso); null: não está lá' => 'config.php 仍定义的 DOCUMENTOS_COPIA_BANCO（真或假），已不再生效（设置页显示警告）；null：不存在',
        'o gasto medido pelas leituras usa as medições destes últimos dias, com "contar por" dias (sem nenhuma na janela, as de antes)' => '按读数测得的消耗使用最近这些天的测量，“按什么计”为天数（窗口内没有时，用之前的）',
        'o gasto medido usa as últimas tantas medições de cada tipo (em uso e em repouso), com "contar por" leituras (2 a 1000)' => '测得消耗使用每类（使用中和静置中）最近若干次测量，“按什么计”为读数（2 到 1000）',
        'o aviso Encostado: depois de quantos dias sem ir ao pulso um relógio da coleção é avisado (1 a 3650; padrão 30)' => '闲置提醒：收藏中的一块手表多少天没上手腕后会被告知（1 到 3650；默认 30）',
        '1 ou 0: o aviso Encostado está ligado (a caixa Avisar quando um relógio fica encostado, da Configuração: liga e desliga o aviso encostado do cadastro, o mesmo que a página Avisos; desligado, somem o aviso, a coluna Encostado da Hoje e o filtro)' => '1 或 0：闲置提醒已开启（设置中的“手表闲置时提醒”复选框：开启和关闭档案中的 encostado 提醒，与提醒页相同；关闭时，提醒、今日页的闲置列和筛选都会消失）',
        'o fuso horário da coleção ("Europe/Lisbon"): o de quem não escolheu o seu em Minha conta, e o do cron, das mensagens e das agendas dela; vazio: o do sistema (fuso_sistema)' => '收藏的时区（"Europe/Lisbon"）：在“我的账户”中未选择自己时区的人所用，以及收藏的 cron、消息和日历所用；空：系统的（fuso_sistema）',
        'o relógio da página Hora certa: analogico, digital, anadigi (o visor digital dentro do mostrador analógico) ou ambos (um ao lado do outro); vazio: ambos' => '准确时间页面的时钟：analogico、digital、anadigi（数字显示嵌在模拟表盘内）或 ambos（并排）；空：ambos',
        'o primeiro dia da semana do rodízio: segunda ou domingo (o plano vem montado até o último dia da semana; o ciclo, a próxima semana e o relógio para a semana inteira contam dela); vazio: segunda' => '轮换一周的第一天：segunda 或 domingo（计划编排到这一周的最后一天；循环、下一周和整周一块手表都按它来算）；空：segunda',
        'o idioma padrão da instalação (pt-BR, en, zh-CN, hi, es, fr; vazio: o do navegador, senão português)' => '安装的默认语言（pt-BR、en、zh-CN、hi、es、fr；空：浏览器的语言，否则为葡萄牙语）',
        'como o relógio abre na página Hoje: lado (no painel à direita da lista) ou flutuante (numa janela grande por cima da página); vazio: lado' => '手表在今天页面如何打开：lado（在列表右侧的面板中）或 flutuante（在页面上方的大窗口中）；空：lado',
        'o destaque no alto da página Hoje: dia (o relógio do dia, o do plano) ou pulso (o relógio no pulso agora; sem nenhum no pulso, o do dia); vazio: dia' => '今天页面顶部的突出显示：dia（当天的手表，即计划中的那块）或 pulso（现在在手腕上的手表；手腕上没有时，用当天的）；空：dia',
        'o reloginho da barra e da aba: hora (cada hora do dia tem o seu modelo), aleatorio (um sorteado a cada hora, podendo repetir) ou sem_repeticao (os 24 embaralhados, cada um uma vez por dia); vazio: hora' => '菜单栏和标签页的小手表：hora（一天中每个小时有自己的款式）、aleatorio（每小时抽一个，可能重复）或 sem_repeticao（24 种打乱，每天每种一次）；空：hora',
        'o "Mostrar até" dos Próximos dias da página Hoje: quantos dias por página (1 a 366; vazio: 7)' => '今天页面接下来的日子的“显示至”：每页多少天（1 到 366；空：7）',
        'o "Mostrar até" do dia a dia da página Plano: quantos dias por página (1 a 366; vazio: 31)' => '计划页面逐日内容的“显示至”：每页多少天（1 到 366；空：31）',
        'de quantos em quantos segundos as páginas (Hoje com o painel, Ficha, Plano, Totais e Histórico) leem tudo de novo sozinhas: 1 a 86400; 0, não leem; vazio: 60' => '页面（今天含面板、手表卡片、计划、合计和历史）每隔多少秒自动重新读取全部数据：1 到 86400；0 不读取；空：60',
        '1 (ou vazio): o relógio sai do pulso sozinho no fim do horário de uso (o "fecha às" do tipo No pulso); 0: só pelo Tirou' => '1（或空）：手表在使用时段结束时独自离开手腕（No pulso 类型的“结束于”）；0：只能通过摘下',
        '1 (ou vazio): o relógio do dia entra no pulso sozinho no início do horário de uso; 0: só pelo Pôs' => '1（或空）：当天的手表在使用时段开始时独自上手腕；0：只能通过戴上',
        'o limite de carga da previsão do smartwatch, em %' => '智能手表预测的电量下限，以 % 计',
        'no solar, a carga (%) em que ele deve ir para o sol' => '太阳能表应当去晒太阳时的电量（%）',
        'o dia da última rodada da manhã do cron (texto AAAA-MM-DD)' => 'cron 最近一次早晨轮次的日期（文本 AAAA-MM-DD）',
        'o dia da última rodada da noite do cron (texto AAAA-MM-DD)' => 'cron 最近一次夜晚轮次的日期（文本 AAAA-MM-DD）',
        'a hora em que ele sai do pulso (HH:MM)' => '它离开手腕的时间（HH:MM）',
        'a hora em que o relógio do dia vai para o pulso (HH:MM)' => '当天的手表上手腕的时间（HH:MM）',
        'os conjuntos de critérios, um por lugar que tem critérios próprios' => '标准集合，每个有自有标准的位置一个',
        'o lugar: "" (todos os relógios), g:<grupo> ou r:<relógio>' => '位置：""（全部手表）、g:<分组> 或 r:<手表>',
        'o lugar por extenso' => '位置的完整名称',
        'os parâmetros do conjunto, em ordem' => '集合的参数，按顺序',
        'o grupo do conjunto; null se não é de grupo' => '集合的分组；若不是分组的则为 null',
        'o relógio do conjunto; null se não é de relógio' => '集合的手表；若不是手表的则为 null',
        'o número do parâmetro' => '参数的编号',
        'o nome do parâmetro' => '参数的名称',
        'a posição dele no conjunto' => '它在集合中的位置',
        'o peso no conjunto, em % (os do conjunto somam 100)' => '在集合中的权重，以 % 计（集合中的合计为 100）',
        'os subparâmetros, em ordem' => '各子参数，按顺序',
        'as faixas: o valor medido vira uma nota de 0 a 100' => '各区间：测得的值变成 0 到 100 的分数',
        'o fim da faixa (não entra, menos na última); null: sem limite' => '区间的结束（不含，最后一档除外）；null：无上限',
        'a categoria (medida de lista); null numa faixa de números' => '类别（列表度量）；数字区间中为 null',
        'o começo da faixa (entra); null numa faixa de categoria' => '区间的开始（含）；类别区间中为 null',
        'o número da faixa' => '区间的编号',
        'a nota da faixa, de 0 a 100' => '区间的分数，0 到 100',
        'o número do subparâmetro' => '子参数的编号',
        'o nome do subparâmetro' => '子参数的名称',
        'a posição dele no parâmetro' => '它在参数中的位置',
        'o peso no parâmetro, em % (os do parâmetro somam 100)' => '在参数中的权重，以 % 计（该参数中的合计为 100）',
        'peso do subparâmetro × peso do parâmetro ÷ 100, em %' => '子参数权重 × 参数权重 ÷ 100，以 % 计',
        'o que ele mede: o identificador de um campo ou de uma fórmula' => '它所度量的：一个字段或一条公式的标识符',
        'os relógios disponíveis que usam este conjunto (ids)' => '使用此集合的可用手表（ids）',
        'os lugares que podem ter critérios: todos os relógios, cada grupo (em ordem de árvore) e cada relógio' => '可以有标准的位置：全部手表、每个分组（按树的顺序）和每块手表',
        'o lugar: "" (todos), g:<grupo> ou r:<relógio>' => '位置：""（全部）、g:<分组> 或 r:<手表>',
        'o lugar de quem ele herda os critérios quando não tem os seus; null: ninguém (nota neutra)' => '当它没有自有标准时，所继承标准的来源位置；null：没有（中性分数）',
        'esse lugar por extenso' => '该位置的完整名称',
        'o lugar por extenso, curto' => '位置的完整名称，简短',
        'verdadeiro ou falso: o lugar tem critérios próprios' => '真或假：该位置有自有标准',
        'o lugar como a lista da página mostra ("Grupo: Tradicional › Mecânico")' => '位置在页面列表中的显示方式（“分组：传统 › 机械”）',
        'a garantia de rodízio em dias (0: desligada)' => '轮换保障的天数（0：关闭）',
        'os modos de rodízio e a forma de escolher de cada um' => '轮换模式以及各自的选择方式',
        'verdadeiro ou falso: é o modo em uso' => '真或假：是当前使用的模式',
        'verdadeiro ou falso: o modo é escala inteligente (escolhe sempre pela maior nota)' => '真或假：该模式是智能排班表（始终按最高分数选择）',
        'o nome do modo' => '模式的名称',
        'o tipo do modo: semana, semana_fds, dia_semana, aleatorio, escala ou personalizado' => '模式的类型：semana、semana_fds、dia_semana、aleatorio、escala 或 personalizado',
        'a forma de escolha: inteligente (a maior nota), ponderado (sorteio pela nota), aleatorio ou fifo (o mais tempo sem uso)' => '选择方式：inteligente（最高分数）、ponderado（按分数抽签）、aleatorio 或 fifo（最久未使用）',
        'a nota de cada relógio agora, com a conta' => '每块手表现在的分数，含计算过程',
        'o lugar dos critérios usados: "" (todos), g:<grupo> ou r:<relógio>; null: nenhum (nota neutra, 50)' => '所用标准的位置：""（全部）、g:<分组> 或 r:<手表>；null：没有（中性分数，50）',
        'cada subparâmetro que entrou na conta' => '进入计算的每个子参数',
        'a faixa em que o valor caiu ("30 a 50", ou a categoria)' => '值落入的区间（“30 到 50”，或该类别）',
        'a nota da faixa, de 0 a 100 (número)' => '区间的分数，0 到 100（数字）',
        'o peso no conjunto: peso do subparâmetro × peso do parâmetro, reescalado sem os que não se aplicam, em % (número)' => '在集合中的权重：子参数权重 × 参数权重，去掉不适用的之后重新换算，以 % 计（数字）',
        'nota × peso efetivo ÷ 100 (número): quanto somou na nota' => '分数 × 有效权重 ÷ 100（数字）：对分数贡献了多少',
        'o valor medido (número, ou o texto de uma lista)' => '测得的值（数字，或列表的文本）',
        'o que o subparâmetro mede (o identificador do campo ou da fórmula)' => '子参数所度量的（字段或公式的标识符）',
        'verdadeiro ou falso: o relógio está disponível para o rodízio' => '真或假：手表可用于轮换',
        'o grupo do relógio (o caminho na árvore)' => '手表的分组（在树中的路径）',
        'a nota final, de 0 a 100 (número): a soma dos pontos' => '最终分数，0 到 100（数字）：各得分之和',
        'o nome do relógio' => '手表的名称',
        'o relógio' => '该手表',
        'o que um subparâmetro pode medir: cada campo (menos texto) e cada fórmula, pelo identificador' => '一个子参数可以度量的：每个字段（文本除外）和每条公式，按标识符',
        'o limite da medida (a última faixa vai até ele ou sem limite): o que o nome diz em "(0 a N)"; null: sem limite' => '度量上限（最后一档直到它，或没有上限）：名称在“(0 a N)”中所说的；null：无上限',
        'o nome (com a unidade)' => '名称（含单位）',
        'numero ou categoria (campo de lista)' => 'numero 或 categoria（列表字段）',
        'as categorias possíveis (campo de lista); vazio nos números' => '可能的类别（列表字段）；数字中为空',
        'o erro guardado (texto; vazio: sem erro; some na primeira execução sem erro)' => '已保存的错误（文本；空：无错误；第一次无错误的执行后消失）',
        'as execuções do cron guardadas (sem atividade: 7 dias; com atividade ou erro: 1 ano), da mais recente' => '已保存的 cron 执行（无活动：7 天；有活动或有错误：1 年），从最近的开始',
        'quanto durou, em milissegundos (número inteiro)' => '持续了多久，以毫秒计（整数）',
        'quando terminou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '结束时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o número da execução' => '执行的编号',
        'quando começou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '开始时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o que foi feito, linha por linha (texto; vazio: nada a fazer)' => '做了什么，逐行（文本；空：无事可做）',
        'verdadeiro ou falso: fez alguma coisa (rodada, plano, evento, sincronização)' => '真或假：做了某件事（轮次、计划、事件、同步）',
        'verdadeiro ou falso: houve erro' => '真或假：发生了错误',
        'quando o cron rodou pela última vez (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'cron 最近一次运行的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'os eventos personalizados (avisos seus, com horário e repetição próprios)' => '自定义事件（您自己的提醒，有自己的时间和重复）',
        'verdadeiro ou falso: o evento dispara' => '真或假：事件会触发',
        'quando o evento foi cadastrado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '事件登记的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'a data (uma vez só) ou o começo da contagem (a cada N dias) (texto AAAA-MM-DD); null nas outras' => '日期（仅一次）或计数的开始（每 N 天）（文本 AAAA-MM-DD）；其他情况下为 null',
        'a repetição por extenso ("seg, qua 20:00")' => '重复的文字形式（“seg, qua 20:00”）',
        'o dia do mês (mensal), de 1 a 31; null nas outras' => '月中的日期（每月），1 到 31；其他情况下为 null',
        'os dias da semana (semanal), de 1 (segunda) a 7 (domingo), separados por vírgula; null nas outras' => '星期几（每周），从 1（周一）到 7（周日），以逗号分隔；其他情况下为 null',
        'as vezes em que já disparou' => '已经触发过的各次',
        'quando o cron mandou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'cron 发送的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'a vez que disparou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema, a do cadastro)' => '触发的那一次（文本 AAAA-MM-DD HH:MM:SS，系统时区，档案中的那次）',
        'a hora do disparo (HH:MM)' => '触发的时间（HH:MM）',
        'o número do evento (o tipo dele nos canais é ev<id>)' => '事件的编号（它在各渠道中的类型是 ev<id>）',
        'de quantos em quantos dias (intervalo); null nas outras' => '每隔多少天（间隔）；其他情况下为 null',
        'o nome do evento (texto)' => '事件的名称（文本）',
        'as 10 próximas vezes em que dispara (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '接下来触发的 10 次（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o nome desse relógio; null: evento geral' => '该手表的名称；null：一般事件',
        'o relógio do evento (as âncoras dele funcionam na mensagem); null: evento geral' => '事件的手表（它的锚点在消息中有效）；null：一般事件',
        'quando dispara: uma (uma vez só), diaria, semanal, mensal ou intervalo (a cada N dias)' => '何时触发：uma（仅一次）、diaria、semanal、mensal 或 intervalo（每 N 天）',
        'as fórmulas (cada identificador pode ter uma versão por grupo; vale a do grupo mais perto do relógio)' => '各公式（每个标识符可以按分组有一个版本；采用离手表最近的分组的那一版）',
        'a conta (texto, na escrita das fórmulas do motor)' => '计算式（文本，按引擎公式的写法）',
        'o nome da fórmula nas outras fórmulas e nos critérios' => '公式在其他公式和标准中的名称',
        'o nome da fórmula' => '公式的名称',
        'a unidade do resultado (texto)' => '结果的单位（文本）',
        'os tipos de lançamento que a conta usa' => '计算式使用的记录类型',
        'os campos e fórmulas que a conta usa' => '计算式使用的字段和公式',
        'os tipos de lançamento: o que se registra num relógio' => '记录类型：在一块手表上登记的内容',
        'vale quando: uma fórmula que diz para quais relógios do grupo o tipo vale (1 vale, 0 não; ex.: corda_manual, só quem aceita corda); null: vale para todos' => '何时有效：一条公式，说明该类型对分组中的哪些手表有效（1 有效，0 无效；例：corda_manual，仅接受上链的）；null：对全部有效',
        'a sessão é exclusiva: o relógio fica num lugar só (abrir fecha a outra exclusiva)' => '时段是独占的：手表只处于一个地方（打开会结束另一个独占时段）',
        'sessão esquecida aberta fecha sozinha a essa hora do dia em que começou (HH:MM; null: não fecha)' => '忘记关闭的时段，在它开始的那一天的这个时刻自行结束（HH:MM；null：不结束）',
        'instantaneo (uma marcação: corda), valor (uma leitura: carga) ou sessao (com início e fim: pulso, sol)' => 'instantaneo（一次标记：上链）、valor（一次读数：电量）或 sessao（有开始和结束：手腕、晒太阳）',
        'o número do tipo' => '类型的编号',
        'o nome do tipo nas fórmulas (HORAS("pulso"; 30))' => '类型在公式中的名称（HORAS("pulso"; 30)）',
        'cada leitura desse tipo mede o gasto, comparando com a anterior (a função MEDIDO)' => '该类型的每次读数与上一次比较来测量消耗（函数 MEDIDO）',
        'o grupo em que o tipo vale; null: todos' => '类型生效的分组；null：全部',
        'o nome do tipo' => '类型的名称',
        'a posição do tipo' => '类型的位置',
        'a unidade do valor (texto)' => '值的单位（文本）',
        'as migrações do banco que faltam aplicar (vazio: em dia)' => '数据库中尚未应用的迁移（空：已是最新）',
        'o arquivo .sql' => '.sql 文件',
        'o que a migração traz' => '该迁移带入的内容',
        'a versão (v2, v3...)' => '版本（v2、v3……）',
        'os modos de rodízio' => '轮换模式',
        'os blocos de dias da semana do modo' => '模式中按星期几划分的区块',
        'os dias da semana do bloco, de 1 (segunda) a 7 (domingo)' => '区块的星期几，从 1（周一）到 7（周日）',
        'o número do bloco' => '区块的编号',
        'o grupo de onde sortear; null: todos' => '从哪个分组抽签；null：全部',
        'o nome do bloco' => '区块的名称',
        'o relógio fixo do bloco; null: sorteia' => '区块的固定手表；null：抽签',
        'dia (um relógio por dia) ou bloco (um para o bloco inteiro na semana)' => 'dia（每天一块手表）或 bloco（一周内整个区块同一块）',
        '(verdadeiro ou falso) o modo usa o ciclo: um relógio só volta depois que todos os disponíveis do bloco passaram na semana (na escala, pelo período dela); dentro do ciclo, a forma de escolha decide a ordem' => '（真或假）模式使用循环：一块手表要等该区块中全部可用手表都在本周出现过才再次出现（在排班表中，按其时段计算）；循环之内，由选择方式决定顺序',
        'escala inteligente com esse horizonte, em dias (7 a 730); null: sorteio pelos blocos' => '具有该时间跨度的智能排班表，以天计（7 到 730）；null：按区块抽签',
        'o número do modo' => '模式的编号',
        'a posição do modo' => '模式的位置',
        'a forma de escolha: inteligente, ponderado, aleatorio ou fifo' => '选择方式：inteligente、ponderado、aleatorio 或 fifo',
        'o roteiro escrito à mão (o personalizado); null nos outros tipos' => '手写的脚本（自定义）；其他类型为 null',
        'o roteiro que vale: o escrito, ou o gerado dos blocos e da forma de escolha' => '生效的脚本：手写的，或由区块和选择方式生成的',
        'quantas semanas à frente o plano vem montado (1 a 8; a escala usa o período dela)' => '计划提前生成多少周（1 到 8；排班使用自己的周期）',
        'cada formato de lançamento e o nome dele' => '每种记录格式及其名称',
        'cada função do motor de fórmulas e como usar (texto)' => '公式引擎的每个函数以及如何使用（文本）',
        'cada tipo de campo e o nome dele' => '每种字段类型及其名称',
        'o plano gravado: o relógio de cada dia' => '已保存的计划：每一天的手表',
        'o lembrete do dia (o que fazer antes: carregar, dar corda...); null: nada' => '当天的备忘（事先要做什么：充电、上链……）；null：没有',
        'o nome desse bloco' => '该区块的名称',
        'o bloco do modo que escolheu o dia; null: escala ou manual' => '选出该日的模式区块；null：排班表或手动',
        'quando o dia foi gravado no plano (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '该日被写入计划的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o dia (texto AAAA-MM-DD)' => '日期（文本 AAAA-MM-DD）',
        'por que este relógio saiu neste dia, numa frase (a garantia de rodízio, a nota, o sorteio, a escolha à mão); null: o dia foi gravado antes de o sistema guardar o motivo' => '为什么这块手表出现在这一天，一句话（轮换保障、分数、抽签、手动选择）；null：该日是在系统开始保存事由之前写入的',
        'sorteio (pelo modo) ou manual ("Usando hoje")' => 'sorteio（由模式）或 manual（“今天正在使用”）',
        'o nome dele' => '它的名称',
        'o relógio do dia' => '当天的手表',
        'os dias livres do plano (texto AAAA-MM-DD): sem relógio e sem sorteio, para escolher à mão (o "Deixar o período livre")' => '计划中的空闲日（文本 AAAA-MM-DD）：无手表且无抽签，供手动选择（“让该时段空闲”）',
        'os acessórios (como em recurso=acessorios): id, nome, tipo, tipo_texto, relogio_id (null: solto), relogio, observacao, criado' => '配件（与 recurso=acessorios 中相同）：id、nome、tipo、tipo_texto、relogio_id（null：未绑定）、relogio、observacao、criado',
        'o número do acessório' => '配件的编号',
        'o nome' => '名称',
        'pulseira, caixa, estojo, ferramenta, carregador, peca ou outro' => 'pulseira、caixa、estojo、ferramenta、carregador、peca 或 outro',
        'o tipo por extenso' => '类型的文字形式',
        'o relógio de que ele é; null: solto' => '它所属的手表；null：未绑定',
        'o nome desse relógio; null: solto' => '该手表的名称；null：未绑定',
        'a observação (null)' => '备注（null）',
        'quando foi cadastrado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '登记时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'os relógios, com tudo o que se sabe de cada um' => '各手表，以及每一块已知的全部内容',
        'quando acaba, em ISO 8601 com o fuso (texto, ex.: 2026-10-02T18:40:00-03:00); null com o motivo' => '何时耗尽，ISO 8601 带时区（文本，例：2026-10-02T18:40:00-03:00）；为 null 时带原因',
        'quantos segundos faltam para acabar, a partir de calculado_em_unixtimestamp (número inteiro, em segundos; igual a autonomia_estimada); null com o motivo' => '距离耗尽还差多少秒，从 calculado_em_unixtimestamp 起算（整数，以秒计；等于 autonomia_estimada）；为 null 时带原因',
        'quando a energia chega a zero seguindo o plano (número inteiro: instante Unix (segundos desde 01/01/1970 UTC)); null com o motivo' => '按计划能量何时到达零（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数））；为 null 时带原因',
        'quanto o relógio dura com a carga cheia, pela conta do sistema (número inteiro, em segundos): no smartwatch, pelo gasto em uso medido pelas leituras (a média da janela da Configuração), senão pelo informado; nos outros, igual à prevista; a diferença para a prevista mostra a bateria envelhecendo; a fórmula autonomia_atual' => '满电量时手表能持续多久，按系统的计算（整数，以秒计）：智能手表按读数测得的使用消耗（设置中窗口的平均值），否则按所填写的值；其他手表与预计值相同；与预计值的差表示电池在老化；公式 autonomia_atual',
        'quanto ainda dura a partir de agora, seguindo o plano (número inteiro, em segundos): usado nos dias em que está no rodízio, guardado nos outros; o mesmo número de acaba_em_segundos; null com o motivo em motivos' => '从现在起按计划还能持续多久（整数，以秒计）：在轮换中的日子按使用计算，其余日子按静止计算；与 acaba_em_segundos 是同一个数；为 null 时原因在 motivos 中',
        'quanto o relógio dura com a carga cheia, pelo cadastro (número inteiro, em segundos): a autonomia do smartwatch, a reserva de marcha do mecânico, a reserva do solar ou a vida da pilha; a fórmula autonomia_prevista; null se falta o dado no cadastro' => '满电量时手表能持续多久，按档案（整数，以秒计）：智能手表的续航、机械表的动力储存、太阳能表的储能或电池寿命；公式 autonomia_prevista；档案中缺少该数据时为 null',
        'os avisos do relógio agora (os que valem para ele e têm data prevista), do mais urgente ao mais distante' => '该手表现在的提醒（对它有效且有预计日期的），从最紧急到最远',
        'a data na agenda: janela (só dentro da antecedência da agenda) ou sempre (qualquer data); se vai pela agenda é a Configuração' => '在日历中的日期：janela（仅在日历提前量之内）或 sempre（任意日期）；是否走日历由设置决定',
        'verdadeiro: o aviso vai pelo Telegram no minuto em que vence (uma vez), além do alerta da manhã' => '真：提醒在到期的那一分钟经 Telegram 发出（一次），此外还有早晨警报',
        'a data prevista, pela fórmula do aviso (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '预计日期，由提醒的公式得出（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'na escala inteligente: nao, uso (conferido no relógio do dia) ou sempre (também nos guardados)' => '在智能排班表中：nao、uso（在当天的手表上核对）或 sempre（静止存放的也核对）',
        'atrasado (a data passou), em_breve (dentro da antecedência) ou ok' => 'atrasado（逾期：日期已过）、em_breve（在提前量之内）或 ok',
        'quanto falta para a data prevista, em dias (número; negativo: já passou)' => '距离预计日期还差多少天（数字；负数：已经过去）',
        'o aviso (corda, carregar, sol, pilha, revisao, garantia, carga_baixa, leitura, ou um que você cadastrou)' => '该提醒（corda、carregar、sol、pilha、revisao、garantia、carga_baixa、leitura，或您登记的一个）',
        'o texto do cadastro, sem trocar as âncoras (só o {limite})' => '档案中的文本，不替换锚点（只有 {limite}）',
        'o nome do aviso ("Dar corda") — a âncora {acao}' => '提醒的名称（“上链”）——锚点 {acao}',
        'o tipo de lançamento que resolve o aviso (o botão na tela Hoje); null: nenhum' => '用来解决该提醒的记录类型（今天界面上的按钮）；null：没有',
        'as horas da sessão que a escala simula para resolver o aviso (número; null: nenhuma)' => '排班表为解决该提醒而模拟的时段小时数（数字；null：没有）',
        'o valor do lançamento que a escala simula para resolver o aviso (leitura) (número; null: nenhum)' => '排班表为解决该提醒而模拟的记录值（读数）（数字；null：没有）',
        'o motivo por extenso, com {relogio}, {data}, {quando} e {limite} trocados — a âncora {motivo}' => '完整事由，其中 {relogio}、{data}、{quando} 和 {limite} 已被替换——锚点 {motivo}',
        'o lugar da árvore da versão do aviso usada (texto)' => '所用提醒版本在树中的位置（文本）',
        'o instante em que as autonomias foram calculadas (número inteiro: instante Unix (segundos desde 01/01/1970 UTC)); segundos que faltam agora = acaba_em_unixtimestamp − hora atual' => '各续航被计算的时刻（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数））；现在还差的秒数 = acaba_em_unixtimestamp − 当前时间',
        'os campos do cadastro que valem para ele' => '对它有效的档案字段',
        'o campo' => '该字段',
        'o tipo do campo (inteiro, decimal, sim_nao, data, lista, texto)' => '字段的类型（inteiro、decimal、sim_nao、data、lista、texto）',
        'a unidade' => '单位',
        'o valor gravado no relógio (texto; null: não preenchido)' => '保存在手表上的值（文本；null：未填写）',
        'o valor que as contas usam: o gravado, ou o padrão do campo' => '计算所使用的值：已保存的，或字段的默认值',
        'verdadeiro ou falso: entra no rodízio' => '真或假：进入轮换',
        'verdadeiro: o relógio pede a cópia no banco de todos os documentos dele (o segundo dos três níveis da cópia; a Configuração da coleção, documentos_copia, se escolhe, vale por cima)' => '真：手表要求将其所有文档复制到数据库（副本三级中的第二级；收藏的设置 documentos_copia 若已选择则优先）',
        'a situação na coleção: colecao (na coleção), desejado (a lista de desejos), emprestado, vendido ou arquivado; fora da coleção, disponivel é sempre falso' => '在收藏中的情况：colecao（在收藏中）、desejado（心愿单）、emprestado、vendido 或 arquivado；离开收藏后，disponivel 始终为假',
        'verdadeiro ou falso: o relógio está com uma sessão no pulso aberta agora' => '真或假：手表现在有一个在手腕上打开的时段',
        'a energia agora, em % inteiro (a fórmula energia: bateria, reserva, luz ou pilha); null sem dados para calcular' => '现在的能量，整数百分比（公式 energia：电池、动力储存、光线或原电池）；没有数据可计算时为 null',
        'o resultado agora de cada fórmula que vale para ele' => '对它有效的每条公式现在的结果',
        'a unidade do resultado' => '结果的单位',
        'o resultado agora (número ou texto; null: vazio)' => '现在的结果（数字或文本；null：空）',
        'o grupo da versão usada' => '所用版本的分组',
        'a foto; null: sem foto' => '照片；null：无照片',
        'quando a foto foi trocada (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '照片更换的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'a imagem em base64; null com foto=nao' => 'base64 图像；foto=nao 时为 null',
        'o tipo da imagem (image/jpeg, image/png, image/webp)' => '图像类型（image/jpeg、image/png、image/webp）',
        'o número (código) do relógio' => '手表的编号',
        'os identificadores dos tipos de lançamento que valem para ele (texto)' => '对它有效的记录类型的标识符（文本）',
        'todos os lançamentos do relógio, do mais antigo para o mais recente' => '该手表的全部记录，从最旧到最新',
        'quando foi gravado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '保存时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o fim da sessão (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema); null: marcação, leitura, ou sessão aberta' => '时段的结束（文本 AAAA-MM-DD HH:MM:SS，系统时区）；null：标记、读数，或已打开的时段',
        'o número do lançamento' => '记录的编号',
        'quando (a marcação ou a leitura), ou o começo da sessão (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '时间（标记或读数），或时段的开始（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'manual (lançado por alguém), rodizio (a sessão do dia, pelo cron) ou importado' => 'manual（由人记录）、rodizio（当天的时段，由 cron）或 importado',
        'o identificador do tipo' => '类型的标识符',
        'o valor da leitura (número); null nos outros' => '读数的值（数字）；其他情况下为 null',
        'os trechos da linha do tempo do relógio, do mais recente para o mais antigo: cada trecho é um período contínuo num estado, ou uma marcação (um lançamento instantâneo)' => '手表时间线的各片段，从最近到最旧：每个片段是某一状态上的一段连续时间，或一次标记（一条瞬时记录）',
        'a mesma duração por extenso ("2d 3h", "40min"); null numa marcação' => '同一段时长的文字形式（“2d 3h”、“40min”）；标记上为 null',
        'quanto o trecho durou, número inteiro, em segundos; null numa marcação' => '片段持续了多久，整数，以秒计；标记上为 null',
        'verdadeiro ou falso: o trecho ainda não terminou (o fim é o momento da consulta)' => '真或假：片段尚未结束（结束时刻就是查询时刻）',
        'o estado do trecho: rodizio (no pulso pelo rodízio), pulso (em uso fora do plano: no pulso sem ser o relógio do dia), o identificador de um tipo de sessão (winder, sol...), repouso (parado) ou marca (uma marcação)' => '片段的状态：rodizio（经轮换在手腕上）、pulso（计划之外的使用中：戴在手腕上但不是当天的手表）、某个时段类型的标识符（winder、sol……）、repouso（静止）或 marca（一次标记）',
        'quando o trecho terminou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema); null numa marcação' => '片段结束的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）；标记上为 null',
        'quando o trecho começou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '片段开始的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o trecho por extenso, como a tela mostra ("em uso", "no sol", "Leitura de carga 80%")' => '片段的文字形式，与界面所显示的一致（“使用中”、“在晒太阳”、“电量读数 80%”）',
        'o identificador do tipo de lançamento que originou o trecho (pulso, sol, corda, carga...); null no repouso' => '产生该片段的记录类型的标识符（pulso、sol、corda、carga……）；休息中为 null',
        'o grupo por extenso' => '分组的完整名称',
        'as medições do gasto pelas leituras (cada leitura de um tipo que mede o gasto, comparada com a anterior), da mais recente para a mais antiga' => '由读数测得的消耗测量（测量消耗的类型的每次读数，与上一次比较），从最近到最旧',
        'a leitura que fechou a medição (número)' => '结束该次测量的读数（数字）',
        'quando a medição foi gravada (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '测量被保存的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'a leitura de antes (número, na unidade da leitura)' => '之前的读数（数字，按读数的单位）',
        'quando foi a leitura que fechou a medição (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '结束该次测量的读数发生的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'as horas guardado entre as duas leituras (número)' => '两次读数之间静止存放的小时数（数字）',
        'as horas no pulso entre as duas leituras (número)' => '两次读数之间在手腕上的小时数（数字）',
        'o número da medição' => '测量的编号',
        'quando foi a leitura de antes (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '之前的读数发生的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o lançamento (a leitura) que fechou a medição' => '结束该次测量的记录（读数）',
        'o gasto do intervalo sozinho, no histórico: uso (o gasto por dia de uso, quando o intervalo teve meio dia de uso ou mais, ou mais dias de uso que fora) ou repouso (o gasto por dia fora do pulso); o gasto que vale sai de todas as medições juntas' => '该间隔单独的消耗，在历史中：uso（每天使用的消耗，当该间隔有半天或更多的使用，或者使用天数多于离开手腕的天数）或 repouso（离开手腕每天的消耗）；实际采用的消耗来自全部测量合在一起',
        'o quanto a conta de agora erra a leitura desta medição que menos bate com as outras (a do começo ou a do fim), em pontos de carga (número; null fora da janela ou só no histórico)' => '当前计算对这次测量中与其他最不一致的读数（开始或结束的那个）的误差，单位为电量百分点（数字；在窗口外或只在历史中时为 null）',
        'o valor da leitura desta medição que menos bate com as outras (a do começo ou a do fim) (número; null fora da conta)' => '这次测量中与其他最不一致的读数（开始或结束的那个）的值（数字；不在计算中时为 null）',
        'verdadeiro ou falso: uma leitura desta medição não bate com as outras e pesa menos da metade na conta (regressão robusta)' => '真或假：这次测量有一个读数与其他不一致，在计算中权重不到一半（稳健回归）',
        'a marcação da leitura do começo da medição: uso ou repouso (null fora da conta)' => '测量起始读数的标记：uso 或 repouso（不计入时为 null）',
        'a marcação da leitura do fim da medição: uso ou repouso (null fora da conta)' => '测量结束读数的标记：uso 或 repouso（不计入时为 null）',
        'verdadeiro ou falso, no motor pela marcação (e no das fórmulas): as duas leituras têm a mesma marcação, e a medição entra na conta daquele gasto; com marcações diferentes, não entra em nenhum dos dois. null nos outros motores (eles não escolhem pela marcação)' => '真或假，在按标记引擎（和公式引擎）中：两次读数标记相同，该测量计入那种消耗的计算；标记不同时，两种都不计入。其他引擎中为 null（它们不按标记选择）',
        'verdadeiro ou falso: entra na conta agora (usada e dentro da janela da Configuração, medicao_janela_dias)' => '真或假：现在计入计算（已使用且在设置的窗口 medicao_janela_dias 内）',
        'o peso, de 0 a 1, que a leitura desta medição que menos bate com as outras tem na conta (1: bate; menos: a regressão robusta a pesa menos) (número; null fora da conta)' => '这次测量中与其他最不一致的读数在计算中的权重，0 到 1（1：一致；更小：稳健回归降低了它的权重）（数字；不在计算中时为 null）',
        'as horas que a medição cobriu, no pulso (uso) ou guardado (repouso) (número; a conta não pesa mais por horas: todas as medições pesam igual)' => '测量覆盖的小时数，在手腕上（uso）或存放（repouso）（数字；计算不再按小时加权：所有测量权重相同）',
        'o gasto medido, em % por dia de uso (uso) ou por dia guardado (repouso) (número)' => '测得的消耗，以每个使用日的 % 计（uso）或以每个静止存放日的 % 计（repouso）（数字）',
        'verdadeiro ou falso: a caixa "Atualizar o gasto com esta medição" estava marcada (entra na média); falso: só histórico' => '真或假：“用这次测量更新消耗”复选框已勾选（计入平均值）；假：只留在历史中',
        'por que cada campo acima ficou null (objeto; vazio quando todos foram calculados)' => '上面每个字段为何为 null（对象；全部都算出时为空）',
        'o motivo de o campo <campo> estar null (texto), ex.: sem dados para calcular a energia; não chega a zero em até 10 anos' => '字段 <campo> 为 null 的原因（文本），例：没有数据可计算能量；在最多 10 年内不会到零',
        'o grupo do relógio; null: na raiz' => '手表的分组；null：在根',
        'a previsão da energia (só nos relógios com leitura, como o smartwatch): as frases da tela e os mesmos números' => '能量预测（仅带读数的手表，如智能手表）：界面上的句子以及同样的数字',
        'verdadeiro ou falso: o relógio tem leitura com valor (senão os outros campos ficam vazios)' => '真或假：手表有带值的读数（否则其他字段为空）',
        'com quanto ele entra nesse dia, em % (número)' => '它在那一天进入时是多少，以 % 计（数字）',
        'verdadeiro ou falso: a carga na entrada não basta (é preciso carregar antes)' => '真或假：进入时的电量不够（必须事先充电）',
        'quando, parado, a carga chega ao limite (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema); null se passa de um ano' => '静止时电量何时到达限值（文本 AAAA-MM-DD HH:MM:SS，系统时区）；超过一年则为 null',
        'a confiança da conta: alta (leitura de até 2 dias e nenhum dado vazio, ou gasto em uso medido), media ou baixa (leitura com mais de 7 dias)' => '计算的置信度：alta（读数在 2 天以内且没有空数据，或有实测的使用消耗）、media 或 baixa（读数超过 7 天）',
        'de onde vem cada número da conta: primeiro o gasto que vale no pulso e fora dele, depois o gasto medido pelas leituras e os campos do cadastro (os de um gasto em que vale o medido, com usado falso)' => '计算中每个数字的来源：首先是在手腕上和离开手腕时当前有效的消耗，然后是读数实测的消耗和档案字段（实测有效的消耗所对应的档案字段，usado 为假）',
        'verdadeiro: o número entra na conta; falso: um campo do cadastro que ficou fora, porque vale o gasto medido' => '真：该数字计入计算；假：档案字段未计入，因为采用实测消耗',
        'verdadeiro nas duas primeiras linhas: o gasto que vale no pulso (taxa_uso) e fora dele (taxa_repouso)' => '前两行为真：手腕上（taxa_uso）和离开手腕（taxa_repouso）当前有效的消耗',
        'o identificador do campo, ou MEDIDO("uso") / MEDIDO("repouso") para o gasto medido' => '字段的标识符，或 MEDIDO("uso") / MEDIDO("repouso") 表示实测消耗',
        'no gasto medido, como ele foi medido ("conta dos dois gastos juntos, com 3 medições dos últimos 90 dias"); null nos campos' => '对于实测消耗，它是如何测得的（“两种消耗合在一起计算，含最近 90 天的 3 次测量”）；字段上为 null',
        'o nome do campo, ou do gasto medido (Gasto em uso medido, Gasto fora do pulso medido)' => '字段的名称，或实测消耗的名称（实测使用消耗、实测离开手腕的消耗）',
        'de onde veio: informado (no cadastro do relógio), padrao (o padrão do campo), vazio (sem valor), medido (pelas leituras) ou cadastro (o gasto que vale saiu do cadastro)' => '来源：informado（手表档案中填写）、padrao（字段默认值）、vazio（无值）、medido（由读数实测）或 cadastro（有效消耗来自档案）',
        'de onde veio, no idioma, para mostrar ("informado", "padrão", "vazio", "medido", "cadastro")' => '来源，按语言，供显示用（“informado”“padrão”“vazio”“medido”“cadastro”）',
        'o valor usado na conta (número; null se vazio)' => '计算中使用的值（数字；空则为 null）',
        'até que dia a carga aguenta se usar a partir de hoje (texto AAAA-MM-DD)' => '如果从今天起使用，电量能撑到哪一天（文本 AAAA-MM-DD）',
        'quantos dias de uso a carga de agora aguenta (número, dias; a fórmula dias_de_carga)' => '现在的电量能撑多少个使用日（数字，天；公式 dias_de_carga）',
        'a energia agora, em % (número; null sem leitura)' => '现在的能量，以 % 计（数字；无读数则为 null）',
        'os dois gastos da bateria lado a lado (as fórmulas taxa_uso e taxa_repouso; null se o relógio não as tem)' => '电池的两种消耗并排（公式 taxa_uso 和 taxa_repouso；手表没有它们时为 null）',
        'true: os dois gastos saem juntos da conta das medições; false: a média das medições de cada um' => 'true：两种消耗由测量的计算一起得出；false：各自测量的平均值',
        'o motor que calculou o gasto: horas, robusto, marcacao, cadastro ou formulas (veja config.gasto_motor)' => '计算消耗的引擎：horas、robusto、marcacao、cadastro 或 formulas（见 config.gasto_motor）',
        'o nome do motor por extenso ("Pela marcação: duas taxas separadas")' => '引擎的完整名称（“按标记：两个独立的速率”）',
        'de onde veio a escolha: colecao (a Configuração), relogio (o campo gasto_motor do relógio), grupo (o padrão do campo) ou padrao (nada escolhido: horas)' => '选择的来源：colecao（设置）、relogio（手表的 gasto_motor 字段）、grupo（字段的默认值）或 padrao（未作选择：horas）',
        'o que a conta do gasto medido conta (o "contar por" da Configuração): dias ou leituras' => '测得消耗的计算按什么计（设置中的“按什么计”）：dias 或 leituras',
        'as últimas tantas medições de cada tipo que entram, com base leituras (número)' => '按 leituras 计时每类计入的最近测量次数（数字）',
        'a janela por extenso: "dos últimos 90 dias" ou "das últimas 20 leituras de cada tipo"' => '窗口的文字说明：“最近 90 天的”或“每类最近 20 次读数的”',
        'a janela do gasto medido (medicao_janela_dias da Configuração), em dias (número)' => '实测消耗的窗口（设置中的 medicao_janela_dias），以天计（数字）',
        'quantas medições da janela têm uma leitura que não bate com as outras e pesa menos da metade na conta (número)' => '窗口内有多少次测量有一个读数与其他不一致、在计算中权重不到一半（数字）',
        'quantas medições da janela entram na conta (número)' => '窗口内有多少次测量计入计算（数字）',
        'quantas medições há na janela anterior, a dos antes (número)' => '前一个窗口（更早的那些）有多少次测量（数字）',
        'o gasto em uso, em % por dia de uso, medido na janela anterior (número; null sem medição)' => '使用消耗，以每个使用日的 % 计，在前一个窗口中测得（数字；无测量则为 null）',
        'o gasto em uso, em % por dia de uso, pelo cadastro, sem as medições (número)' => '使用消耗，以每个使用日的 % 计，按档案，不含测量（数字）',
        'a incerteza do gasto em uso medido: um desvio padrão, na mesma unidade (número; null sem medição)' => '测得的使用中消耗的不确定度：一个标准差，单位相同（数字；没有测量时为 null）',
        'quantas medições em uso entram na conta (número; no motor da marcação, as de leituras marcadas em uso nas duas pontas)' => '计入计算的使用中测量数（数字；在按标记引擎中，指两端读数都标记为使用中的测量）',
        'o gasto em uso, em % por dia de uso, só pelas leituras: a mesma conta sem o cadastro como ponto de partida (número; null sem medição ou no motor só o cadastro)' => '仅凭读数得到的使用中消耗，单位为每使用日 %：不以档案为起点的同一计算（数字；没有测量或在仅档案引擎中为 null）',
        'verdadeiro: o medido ficou diferente do que só as leituras dão, porque com poucas medições o cadastro ainda puxa a conta' => 'true：实测值与仅凭读数得到的值不同，因为测量较少时档案仍在拉动计算',
        'o gasto em uso, em % por dia de uso, medido pelas leituras, como o MEDIDO (número; null se as leituras não medem esse gasto: sem medição ou, no motor da marcação, nenhuma desse tipo)' => '由读数测得的使用中消耗，单位为每使用日 %，同 MEDIDO（数字；读数没有测到这项消耗时为 null：没有测量，或在按标记引擎中没有这种类型的测量）',
        'o gasto em uso, em % por dia de uso que vale na conta: o medido, senão o cadastro (número)' => '计算中有效的使用消耗，以每个使用日的 % 计：有实测则用实测，否则用档案（数字）',
        'os campos do cadastro de onde sai o gasto em uso do cadastro (o decaimento, a autonomia...): o painel mostra o medido ao lado deles' => '档案中得出使用中消耗所依据的字段（衰减、续航……）：面板在其旁边显示测得值',
        'o identificador do campo' => '字段的标识符',
        'de onde veio: informado (no cadastro do relógio), padrao (o padrão do campo) ou vazio (sem valor)' => '来源：informado（手表档案中填写）、padrao（字段默认值）或 vazio（无值）',
        'a unidade do campo (texto)' => '字段的单位（文本）',
        'o identificador da fórmula do gasto em uso (taxa_uso)' => '使用中消耗公式的标识符（taxa_uso）',
        'o gasto fora do pulso, em % por dia, medido na janela anterior (número; null sem medição)' => '离开手腕的消耗，以每天的 % 计，在前一个窗口中测得（数字；无测量则为 null）',
        'o gasto fora do pulso, em % por dia, pelo cadastro, sem as medições (número)' => '离开手腕的消耗，以每天的 % 计，按档案，不含测量（数字）',
        'a incerteza do gasto fora do pulso medido: um desvio padrão, na mesma unidade (número; null sem medição)' => '测得的未佩戴消耗的不确定度：一个标准差，单位相同（数字；没有测量时为 null）',
        'quantas medições em repouso entram na conta (número; no motor da marcação, as de leituras marcadas em repouso nas duas pontas)' => '计入计算的静置中测量数（数字；在按标记引擎中，指两端读数都标记为静置中的测量）',
        'o gasto fora do pulso, em % por dia, só pelas leituras: a mesma conta sem o cadastro como ponto de partida (número; null sem medição ou no motor só o cadastro)' => '仅凭读数得到的未佩戴消耗，单位为每天 %：不以档案为起点的同一计算（数字；没有测量或在仅档案引擎中为 null）',
        'o gasto fora do pulso, em % por dia, medido pelas leituras, como o MEDIDO (número; null se as leituras não medem esse gasto: sem medição ou, no motor da marcação, nenhuma desse tipo)' => '由读数测得的未佩戴消耗，单位为每天 %，同 MEDIDO（数字；读数没有测到这项消耗时为 null：没有测量，或在按标记引擎中没有这种类型的测量）',
        'o gasto fora do pulso, em % por dia que vale na conta: o medido, senão o cadastro (número)' => '计算中有效的离开手腕的消耗，以每天的 % 计：有实测则用实测，否则用档案（数字）',
        'os campos do cadastro de onde sai o gasto fora do pulso do cadastro (o decaimento, a autonomia...): o painel mostra o medido ao lado deles' => '档案中得出不在手腕上消耗所依据的字段（衰减、续航……）：面板在其旁边显示测得值',
        'o identificador da fórmula do gasto fora do pulso (taxa_repouso)' => '不在手腕上消耗公式的标识符（taxa_repouso）',
        'a última leitura, no valor informado (número)' => '最近一次读数，按所填写的值（数字）',
        'quando foi a última leitura (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '最近一次读数的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o limite de carga da Configuração (previsao_limite), em % (número)' => '设置中的电量下限（previsao_limite），以 % 计（数字）',
        'as frases da previsão, como a tela mostra (texto)' => '预测的句子，与界面所显示的一致（文本）',
        'quanto ele precisa ter na entrada para os dias seguidos no pulso, em % (número)' => '为了连续几天在手腕上，进入时需要有多少，以 % 计（数字）',
        'o próximo dia em que o relógio entra no rodízio (texto AAAA-MM-DD); null se não está no plano' => '手表下一次进入轮换的日期（文本 AAAA-MM-DD）；不在计划中则为 null',
        'quanto ainda dura a partir de agora se ficar no pulso sem tirar, o dia todo (número inteiro, em segundos); null com o motivo (ex.: o automático no pulso se recarrega e não acaba)' => '如果一直戴在手腕上不摘下、全天如此，从现在起还能持续多久（整数，以秒计）；为 null 时带原因（例：自动表戴在手腕上会自行上链，不会走停）',
        'quanto ainda dura a partir de agora se ficar parado depois do que já está lançado (número inteiro, em segundos); null com o motivo' => '在已经记录的内容之后如果保持静止，从现在起还能持续多久（整数，以秒计）；为 null 时带原因',
        'quantas marcações de cada tipo (corda, carga, pilha...) (número)' => '每种类型有多少次标记（corda、carga、pilha……）（数字）',
        'a parte desse estado no tempo total, em %' => '该状态在总时间中的占比，以 % 计',
        'quanto tempo o relógio passou no estado <estado> (rodizio, pulso, winder, sol, repouso...), número inteiro, em segundos' => '手表在状态 <estado> 中度过的时间（rodizio、pulso、winder、sol、repouso……），整数，以秒计',
        'o mesmo tempo por extenso' => '同一段时间的文字形式',
        'quem acessa o site, com o hash da senha (a senha não existe no sistema)' => '访问网站的人，带密码的 hash（密码在系统中不存在）',
        'quando foi criado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '创建时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o login' => '登录名',
        'o cálculo do hash: bcrypt (o padrão do password_hash do PHP), ou argon2i/argon2id' => 'hash 的算法：bcrypt（PHP password_hash 的默认），或 argon2i/argon2id',
        'o custo do bcrypt (quantas rodadas: 2 elevado a ele), que também está escrito no próprio hash ($2y$12$...: 12); null no argon2' => 'bcrypt 的代价（多少轮：2 的该次方），它也写在 hash 自身里（$2y$12$...：12）；argon2 中为 null',
        'o hash da senha (a senha não existe no sistema): $2y$<custo>$ seguido do sal (22 caracteres) e do resultado (31). Não se desfaz em senha: confere-se a senha digitada contra ele (veja senhas na ajuda). Levado para outro sistema que confira por bcrypt, o usuário entra lá com a mesma senha; e volta para cá por usuarios/salvar com senha_hash' => '密码的 hash（密码在系统中不存在）：$2y$<代价>$ 后接盐（22 个字符）和结果（31）。不能还原成密码：把输入的密码与它核对（见帮助中的 senhas）。带到另一个按 bcrypt 核对的系统后，用户在那边用同一密码进入；回到这里则通过 usuarios/salvar 并带 senha_hash',
        'as categorias dos documentos, na ordem' => '文档的类别，按顺序',
        'os tipos de arquivo que ela aceita (imagem, video, audio, pdf, xml); lista vazia: qualquer arquivo' => '它所接受的文件类型（imagem、video、audio、pdf、xml）；空列表：任意文件',
        'quantos documentos ela tem' => '它有多少份文档',
        'o número da categoria' => '类别的编号',
        'o identificador (minúsculas, números e _)' => '标识符（小写字母、数字和 _）',
        'a ordem em que ela aparece (número)' => '它出现的顺序（数字）',
        'os documentos do relógio (o manual, a nota fiscal, fotos, vídeos...): os dados de cada um; o arquivo vem pelo recurso=documento' => '该手表的文档（说明书、发票、照片、视频……）：每一份的数据；文件通过 recurso=documento 获取',
        'a categoria dele (as categorias dos documentos)' => '它的类别（文档的类别）',
        'quando foi enviado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '上传时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'a data do documento: a ocasião da foto, a data da nota (texto AAAA-MM-DD; null: sem data)' => '文档的日期：照片的场合、发票的日期（文本 AAAA-MM-DD；null：无日期）',
        'a descrição (texto; null: sem descrição)' => '描述（文本；null：无描述）',
        'como ele abre, pelo tipo do arquivo: imagem (a galeria), video (o player), audio, pdf (o visualizador), xml (o resumo da nota e o download) ou outro (o download)' => '它如何打开，按文件类型：imagem（图库）、video（播放器）、audio、pdf（查看器）、xml（发票摘要和下载）或 outro（下载）',
        'o número do documento (para recurso=documento e para alterar ou excluir)' => '文档的编号（用于 recurso=documento 以及修改或删除）',
        'verdadeiro: a foto tem miniatura (recurso=documento com mini=1)' => '真：照片有缩略图（recurso=documento 且 mini=1）',
        'o nome do arquivo enviado' => '所上传文件的名称',
        'verdadeiro: o arquivo está inteiro na pasta dos documentos, com o tamanho do envio (falso: sumiu ou está cortado, e volta do banco quando for pedido ou na próxima rodada do cron; sem a cópia no banco, está perdido)' => '真：文件完整地在文档文件夹中，大小与上传时一致（假：已消失或被截断，被请求时或 cron 下一轮会从数据库恢复；若没有数据库中的副本，则已丢失）',
        'verdadeiro: a cópia de segurança do arquivo está completa no banco (se ele sumir da pasta, volta dali)' => '真：文件的备份已完整存放在数据库中（若它从文件夹消失，会从那里恢复）',
        'verdadeiro: o próprio arquivo pede a cópia no banco (o terceiro nível; o relógio e a Configuração da coleção, se pedem, valem por cima)' => '真：文件本身要求数据库副本（第三级；手表和收藏的设置若有要求则优先）',
        'quem pede a cópia no banco: sistema (a Configuração da coleção, documentos_copia = todos), relogio (a marca do relógio) ou arquivo (a marca do próprio arquivo); null: ninguém' => '谁要求数据库副本：sistema（收藏的设置，documentos_copia = todos）、relogio（手表的标记）或 arquivo（文件自身的标记）；null：没有',
        'o relógio dele' => '它所属的手表',
        'o tamanho do arquivo, em bytes (número inteiro)' => '文件大小，以字节计（整数）',
        'o tipo do arquivo (MIME): image/jpeg, video/mp4, application/pdf, application/xml...' => '文件类型（MIME）：image/jpeg、video/mp4、application/pdf、application/xml……',
        'o título' => '标题',
        'o endereço do arquivo, relativo à pasta do sistema (api.php?recurso=documento&id=...)' => '文件地址，相对于系统文件夹（api.php?recurso=documento&id=...）',
        'sempre null aqui: o resumo da NF-e vem no recurso=documentos' => '这里始终为 null：NF-e 摘要在 recurso=documentos 中',
        'os destinos das mensagens da coleção (webhook, e-mail, Web Push)' => '收藏的消息推送目标（webhook、电子邮件、Web Push）',
        'o id do destino' => '推送目标的 id',
        'o nome (Telegram, E-mail da família...)' => '名称（Telegram、家庭邮箱……）',
        'webhook, email ou webpush' => 'webhook、email 或 webpush',
        'o nome do tipo, por extenso' => '类型的完整名称',
        'verdadeiro ou falso: manda (desligado, não sai nada por ele)' => '真或假：是否发送（关闭时不会通过它发出任何内容）',
        'a mensagem padrão dele, com as âncoras ({acao}, {relogio}, {motivo}...): cada item vira uma linha por ela' => '它的默认消息，带占位符（{acao}、{relogio}、{motivo}……）：每一项按它生成一行',
        'o idioma das mensagens dele (pt-BR, en, zh-CN, hi, es ou fr); null: o da coleção' => '它的消息语言（pt-BR、en、zh-CN、hi、es 或 fr）；null：收藏的语言',
        'o fuso das horas no texto das mensagens dele ("Europe/Lisbon"); null: o da coleção' => '其消息文本中时间的时区（"Europe/Lisbon"）；null：收藏的',
        'os fusos horários que o PHP conhece (a lista Fuso horário de cada destino)' => 'PHP 认识的时区（每个推送目标的时区列表）',
        'o nome ("America/Sao_Paulo")' => '名称（"America/Sao_Paulo"）',
        'a diferença para o UTC agora ("-03:00")' => '当前与 UTC 的差（"-03:00"）',
        'o que ele recebe: cada tipo de aviso (o relógio do dia, a véspera, cada aviso do cadastro, cada evento personalizado)' => '它接收的内容：每种提醒类型（当天的手表、前一天、定义中的每个提醒、每个自定义事件）',
        'o tipo: dia, vespera, o identificador do aviso, ou ev<id> (evento personalizado)' => '类型：dia、vespera、提醒的标识符，或 ev<id>（自定义事件）',
        'quando sai (manhã, noite, na hora...)' => '何时发出（早上、晚上、准时……）',
        'verdadeiro ou falso: recebe esse tipo' => '真或假：接收此类型',
        'o texto próprio desse tipo (com as âncoras); null: a mensagem padrão' => '此类型专用的文本（带占位符）；null：默认消息',
        'o que é do webhook (null nos outros tipos)' => 'webhook 特有的内容（其他类型为 null）',
        'GET, POST ou PUT' => 'GET、POST 或 PUT',
        'o endereço' => '地址',
        'como a mensagem vai: query (na URL), form (formulário) ou json' => '消息的发送方式：query（在 URL 中）、form（表单）或 json',
        'o corpo JSON próprio, com {titulo} e {mensagem} (null: os campos viram o objeto)' => '自定义 JSON 正文，带 {titulo} 和 {mensagem}（null：字段组成对象）',
        'os campos do pedido' => '请求的字段',
        'o valor, com {titulo} e {mensagem}' => '值，带 {titulo} 和 {mensagem}',
        'os cabeçalhos do pedido (o valor fica cifrado no banco e nunca sai)' => '请求的请求头（值加密保存在数据库中，永不输出）',
        'o nome do cabeçalho' => '请求头名称',
        'verdadeiro ou falso: tem valor guardado' => '真或假：有已保存的值',
        'o que é do e-mail (null nos outros tipos)' => '电子邮件特有的内容（其他类型为 null）',
        'para quem (um ou mais endereços, separados por vírgula)' => '收件人（一个或多个地址，以逗号分隔）',
        'o que é do Web Push (null nos outros tipos)' => 'Web Push 特有的内容（其他类型为 null）',
        'o usuário que recebe (nos aparelhos dele)' => '接收的用户（在其设备上）',
        'o login dele' => '他的登录名',
        'quantos aparelhos dele estão inscritos' => '他已订阅的设备数量',
        'as agendas da coleção (Google Agenda, CalDAV, Outlook, link ICS)' => '收藏的日历（Google 日历、CalDAV、Outlook、ICS 链接）',
        'o id da agenda' => '日历的 id',
        'google, caldav, outlook ou ics' => 'google、caldav、outlook 或 ics',
        'verdadeiro ou falso: o sistema mantém os eventos nela' => '真或假：系统在其中维护事件',
        'quantos dias à frente ficam na agenda' => '日历中保留未来多少天',
        'o modelo do evento: a primeira linha é o título, o resto a descrição, com as âncoras' => '事件模板：第一行是标题，其余是描述，带占位符',
        'o idioma dos eventos dela; null: o da coleção' => '其事件的语言；null：收藏的语言',
        'o fuso das horas no texto dos eventos dela ("Europe/Lisbon"); null: o da coleção (o instante do evento no calendário não depende disto)' => '其事件文本中时间的时区（"Europe/Lisbon"）；null：收藏的（日历中事件的时刻不依赖于此）',
        'os fusos horários que o PHP conhece (a lista Fuso horário de cada agenda)' => 'PHP 认识的时区（每个日历的时区列表）',
        'quantos eventos o sistema criou nela (e acompanha)' => '系统在其中创建（并跟踪）的事件数量',
        'o id do evento de teste nela; null: nenhum' => '其中测试事件的 id；null：没有',
        'o que é do Google Agenda (null nos outros tipos)' => 'Google 日历特有的内容（其他类型为 null）',
        'o id da agenda do Google' => 'Google 日历的 id',
        'a chave da conta de serviço: json (colada, cifrada no banco), caminho (um arquivo no servidor) ou nenhuma' => '服务账户密钥：json（粘贴的，在数据库中加密）、caminho（服务器上的文件）或 nenhuma',
        'o caminho do arquivo da chave (só quando a chave é um caminho)' => '密钥文件的路径（仅当密钥是路径时）',
        'o e-mail da conta de serviço (compartilhe a agenda com ele, com permissão de alterar)' => '服务账户的电子邮件（把日历共享给它，并授予修改权限）',
        'o que é do CalDAV (null nos outros tipos)' => 'CalDAV 特有的内容（其他类型为 null）',
        'o endereço do calendário' => '日历地址',
        'o usuário' => '用户名',
        'verdadeiro ou falso: tem senha guardada (cifrada; nunca sai)' => '真或假：有已保存的密码（加密；永不输出）',
        'o que é do Outlook (null nos outros tipos)' => 'Outlook 特有的内容（其他类型为 null）',
        'a conta Microsoft conectada; null: ainda não' => '已连接的 Microsoft 账户；null：尚未连接',
        'o id do calendário; null: o principal' => '日历的 id；null：主日历',
        'verdadeiro ou falso: a conta Microsoft está conectada' => '真或假：Microsoft 账户已连接',
        'verdadeiro ou falso: o servidor tem o aplicativo da Microsoft (OUTLOOK_CLIENTE_ID)' => '真或假：服务器有 Microsoft 应用（OUTLOOK_CLIENTE_ID）',
        'o endereço de retorno para registrar no aplicativo da Microsoft' => '需在 Microsoft 应用中注册的回调地址',
        'o que é do link ICS (null nos outros tipos)' => 'ICS 链接特有的内容（其他类型为 null）',
        'o link para assinar no app de agenda (quem tem o link vê os eventos)' => '在日历应用中订阅的链接（持有链接者可看到事件）',
        'os eventos que o sistema criou nela' => '系统在其中创建的事件',
        'a identificação do evento (a mesma dos desejados)' => '事件的标识（与 desejados 中的相同）',
        'o id do evento no serviço da agenda' => '事件在日历服务中的 id',
        'o dia do evento (texto AAAA-MM-DD)' => '事件的日期（文本 AAAA-MM-DD）',
        'o título com que foi criado' => '创建时所用的标题',
        'a marca do título e da descrição com que foi criado (mudou: o sistema atualiza o evento)' => '创建时所用标题和描述的标记（发生变化：系统会更新该事件）',
        'o que tem de estar em cada agenda agora, pelo que ela recebe' => '按每个日历接收的内容，现在应在其中的内容',
        'o nome da agenda' => '日历名称',
        'os eventos' => '事件',
        'a identificação do evento na agenda (a mesma enquanto nada mudar; é o que o sistema usa para atualizar ou remover)' => '日历中事件的标识（只要没有变化就保持不变；系统用它来更新或删除）',
        'o relógio do evento; null num evento geral' => '事件的手表；一般事件中为 null',
        'o nome do relógio; vazio num evento geral' => '手表的名称；一般事件中为空',
        'o dia do evento na agenda (texto AAAA-MM-DD)' => '日历中事件的日期（文本 AAAA-MM-DD）',
        'a hora do evento na agenda (HH:MM)' => '日历中事件的时间（HH:MM）',
        'a ação ("Dar corda", "Usar hoje", o nome do evento): a âncora {acao}' => '动作（“上链”“今天佩戴”、事件名称）：占位符 {acao}',
        'o porquê ("a reserva acaba em 3h, 28/09 10:53"): a âncora {motivo}' => '原因（“动力储备 3 小时后耗尽，28/09 10:53”）：占位符 {motivo}',
        'o instante previsto do que motivou o evento (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '引发该事件之事的预计时刻（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o título do evento, montado pelo modelo da agenda (a primeira linha)' => '事件标题，按日历模板生成（第一行）',
        'a descrição do evento, montada pelo modelo da agenda (o resto)' => '事件描述，按日历模板生成（其余部分）',
        'os nomes dos destinos que recebem o evento' => '接收该事件的推送目标名称',
        'os nomes das agendas que recebem o evento' => '接收该事件的日历名称',
        'o instante da conta (número inteiro: instante Unix (segundos desde 01/01/1970 UTC))' => '计算的时刻（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数））',
        'um relógio por item, com as autonomias' => '每项一块手表，含各续航',
        'o número (código)' => '编号',
        'o instante da resposta (número inteiro: instante Unix (segundos desde 01/01/1970 UTC))' => '响应的时刻（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数））',
        'os avisos de hoje (atrasados ou em breve), um por relógio e aviso' => '今天的提醒（逾期的或即将到期的），每块手表的每条提醒一个',
        'atrasado ou em_breve' => 'atrasado（逾期）或 em_breve',
        'o aviso' => '该提醒',
        'o nome do aviso' => '提醒的名称',
        'o lançamento do botão que resolve; null: nenhum' => '解决它的按钮所对应的记录；null：没有',
        'o formato (instantaneo, valor, sessao)' => '格式（instantaneo、valor、sessao）',
        'o tipo de lançamento' => '记录类型',
        'a unidade do valor' => '值的单位',
        'o que o botão manda (recurso=lancamento): iniciar (a sessão está fechada), encerrar (a sessão está aberta: o Tirar do carregador) ou lancar (instantâneo ou leitura)' => '按钮所发送的内容（recurso=lancamento）：iniciar（时段已关闭）、encerrar（时段已打开：从充电器取下）或 lancar（瞬时或读数）',
        'true numa leitura que mede o gasto, num relógio que vai ao pulso: a tela mostra dois botões, Em uso e Em repouso (o estado da leitura, no campo estado do lancar)' => '在测量消耗的读数上、且手表会戴上手腕时为 true：界面显示两个按钮，使用中和静置（读数的状态，放在 lancar 的 estado 字段中）',
        'o texto do botão ("Pôs no sol", "Tirou do carregador", "Informar leitura de carga", "Corda")' => '按钮的文本（“已去晒太阳”、“已从充电器取下”、“填写电量读数”、“上链”）',
        'o motivo por extenso' => '完整事由',
        'os nomes dos avisos da manutenção (o filtro "O que fazer" da tabela; sem o Encostado, que tem a coluna dele)' => '保养提醒的名称（表格的“要做什么”筛选；不含闲置，闲置有自己的列）',
        'true ou false: o aviso Encostado está ligado (a caixa Avisar quando um relógio fica encostado, da Configuração); false, a página esconde a coluna Encostado e o filtro, e nenhum relógio vem com encostado' => 'true 或 false：闲置提醒已开启（设置中的“手表闲置时提醒”复选框）；为 false 时，页面隐藏闲置列和筛选，且没有手表带 encostado',
        'os relógios fora da coleção (desejados, vendidos, arquivados), fora da tabela: a página Desejos e o seletor da ficha' => '收藏之外的手表（心愿中、已售出、已归档），不在表格中：心愿单页面以及详情的选择器',
        'um relógio fora da coleção' => '一块收藏之外的手表',
        'a versão da foto (número inteiro: instante Unix (segundos desde 01/01/1970 UTC)); null: sem foto' => '照片的版本（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数））；null：无照片',
        'a situação: desejado, vendido ou arquivado' => '情况：desejado、vendido 或 arquivado',
        'a mesma por extenso ("Desejado", "Vendido", "Arquivado")' => '同一内容的文字形式（“心愿中”、“已售出”、“已归档”）',
        'o grupo do relógio (o nome; "—": na raiz)' => '手表的分组（名称；“—”：在根）',
        'os estados da tabela, na ordem (o filtro Estado): "Em uso", o nome de cada sessão que não é o pulso ("No sol", "No winder", "No carregador"...), "Em repouso", "Indisponível" e "Emprestado"' => '表格的各状态，按顺序（状态筛选）：“使用中”、每个非手腕时段的名称（“在晒太阳”、“在上链盒”、“在充电器”……）、“休息中”、“不可用”和“已借出”',
        'verdadeiro ou falso: o dia já começou no pulso (há relógio do dia e: pondo no pulso sozinho, passou do uso_inicio; senão, ele já foi posto no pulso hoje)' => '真或假：当天已经在手腕上开始（有当天的手表，并且：若会独自上手腕，则已过 uso_inicio；否则，它今天已经被戴上手腕）',
        'verdadeiro: o relógio do dia entra no pulso sozinho no início do horário de uso; falso: só pelo Pôs' => '真：当天的手表在使用时段开始时独自上手腕；假：只能通过戴上',
        'verdadeiro: o relógio sai do pulso sozinho no fim do horário de uso; falso: só pelo Tirou' => '真：手表在使用时段结束时独自离开手腕；假：只能通过摘下',
        'hoje (texto AAAA-MM-DD)' => '今天（文本 AAAA-MM-DD）',
        'o relógio de hoje; null: nenhum' => '今天的手表；null：没有',
        'o lembrete do dia; null: nada' => '当天的备忘；null：没有',
        'até quando ele fica ("só hoje", "até sexta, 02/10")' => '它会留到何时（“只有今天”、“直到周五，02/10”）',
        'por que ele saiu hoje, numa frase (a garantia de rodízio, a nota, o sorteio, a escolha à mão); null: não foi guardado' => '为什么它今天被选出，一句话（轮换保障、分数、抽签、手动选择）；null：没有保存',
        'o relógio de hoje' => '今天的手表',
        'o relógio do destaque no alto da página (a Configuração destaque_hoje), já escolhido pela API' => '页面顶部突出显示的手表（设置 destaque_hoje），已由 API 选定',
        'verdadeiro: o relógio do destaque é o relógio do dia' => '真：突出显示的手表就是当天的手表',
        'o que o relógio do destaque é: dia (o relógio do dia, no pulso ou não) ou pulso (outro relógio, no pulso agora; o do dia fica no dia)' => '突出显示的手表是什么：dia（当天的手表，无论是否在手腕上）或 pulso（另一块手表，现在在手腕上；当天的仍留在当天）',
        'o que a Configuração pede: dia (o relógio do dia) ou pulso (o relógio no pulso agora)' => '设置所要求的：dia（当天的手表）或 pulso（现在在手腕上的手表）',
        'verdadeiro: o relógio do destaque está no pulso agora (havendo mais de um no pulso, conta o que foi por último)' => '真：突出显示的手表现在在手腕上（若手腕上有不止一块，算最后戴上的那块）',
        'o relógio do destaque; null: nenhum (sem relógio do dia e ninguém no pulso). No pulso: o que está no pulso agora (havendo mais de um, o que foi ao pulso por último); ninguém no pulso, o relógio do dia' => '突出显示的手表；null：没有（没有当天的手表，也没有人戴在手腕上）。在手腕上时：现在在手腕上的那块（若不止一块，取最后上手腕的）；手腕上没有人时，用当天的手表',
        'numa frase, por que é ele: O relógio do dia. / O relógio do dia, no pulso agora. / No pulso agora; o relógio do dia é outro. / No pulso agora; hoje não tem relógio do dia. / Nenhum relógio no pulso agora: aqui, o relógio do dia. / Nenhum relógio para hoje e nenhum no pulso.' => '一句话说明为什么是它：当天的手表。 / 当天的手表，现在在手腕上。 / 现在在手腕上；当天的手表是另一块。 / 现在在手腕上；今天没有当天的手表。 / 现在手腕上没有手表：这里是当天的手表。 / 今天没有手表，手腕上也没有。',
        'até que dia vai a escala (texto AAAA-MM-DD); null fora da escala' => '排班表延伸到哪一天（文本 AAAA-MM-DD）；不在排班表中则为 null',
        'o caminho' => '路径',
        'o número' => '编号',
        'o nível (0: raiz)' => '层级（0：根）',
        'a garantia de rodízio em dias' => '轮换保障的天数',
        'o modo de rodízio em uso' => '当前使用的轮换模式',
        'o horizonte da escala inteligente, em dias; null: sorteio pelos blocos' => '智能排班表的时间跨度，以天计；null：按区块抽签',
        'a forma de escolha (inteligente, ponderado, aleatorio, fifo)' => '选择方式（inteligente、ponderado、aleatorio、fifo）',
        'o tipo por extenso, no idioma do pedido' => '类型的文字说明，使用请求的语言',
        'os modos de rodízio (o quadro Modo de rodízio)' => '轮换模式（轮换模式框）',
        'os blocos' => '各区块',
        'os dias da semana, de 1 a 7, separados por vírgula' => '星期几，从 1 到 7，以逗号分隔',
        'o grupo de onde sortear (0: todos)' => '从哪个分组抽签（0：全部）',
        'o relógio fixo; null: sorteia' => '固定的手表；null：抽签',
        'dia ou bloco' => 'dia 或 bloco',
        'o horizonte da escala; null: sorteio' => '排班表的时间跨度；null：抽签',
        'a forma de escolha' => '选择方式',
        'quantas semanas à frente o plano vem montado (1 a 8)' => '计划提前生成多少周（1 到 8）',
        'os próximos 62 dias do plano' => '计划中接下来的 62 天',
        'o lembrete do dia; null' => '当天的备忘；null',
        'sorteio (pelo modo) ou manual (escolhido à mão: "trocar por…" ou "Usando hoje")' => 'sorteio（由模式）或 manual（手动选择：“换成……”或“今天正在使用”）',
        'o dia' => '日期',
        'os dias livres dos próximos 62 dias (texto AAAA-MM-DD): sem relógio e sem sorteio, para escolher à mão; a tela os põe entre os dias do plano' => '接下来 62 天中的空闲日（文本 AAAA-MM-DD）：无手表且无抽签，供手动选择；界面把它们插在计划的日子之间',
        'verdadeiro: hoje é um dia livre (o Sem relógio hoje, ou um período livre): sem relógio do dia; a tela mostra "Hoje sem relógio" com o escolher…' => '真：今天是空闲日（今天无手表，或一个空闲时段）：没有当天的手表；界面显示“今天没有手表”并带选择……',
        'os Próximos dias da página, uma página por vez (proximos_pagina=N; por_pagina=N, sem ele o "Mostrar até" da Configuração, proximos_por_pagina, padrão 7), de hoje até o fim do plano, com os dias livres no meio; a troca de página lê só eles (recurso=proximos)' => '页面上的接下来的日子，每次一页（proximos_pagina=N；por_pagina=N，不传则用设置中的“显示至”，proximos_por_pagina，默认 7），从今天直到计划结束，中间含空闲日；翻页只读取这些（recurso=proximos）',
        'quantos dias vêm por página (o "Mostrar até" da Configuração, ou o por_pagina pedido)' => '每页来多少天（设置中的“显示至”，或所请求的 por_pagina）',
        'a página que veio (1: a primeira)' => '所返回的页（1：第一页）',
        'quantas páginas há' => '一共有多少页',
        'quantos dias há, somando todas as páginas (com os dias livres)' => '一共有多少天，各页相加（含空闲日）',
        'o filtro de relógio (o id; null: todos)' => '手表筛选（id；null：全部）',
        'os dias desta página, na ordem das datas, com os dias livres no meio' => '这一页的日子，按日期顺序，中间含空闲日',
        'o dia (AAAA-MM-DD)' => '日期（AAAA-MM-DD）',
        'o dia da semana: 1 segunda ... 7 domingo' => '星期几：1 周一 …… 7 周日',
        'o dia da semana curto: seg, ter, qua, qui, sex, sáb, dom' => '星期几的短写：seg、ter、qua、qui、sex、sáb、dom',
        'verdadeiro no dia de hoje' => '在今天这一天为真',
        'o relógio do dia (null num dia livre)' => '当天的手表（空闲日为 null）',
        'o nome dele (null num dia livre)' => '它的名称（空闲日为 null）',
        'sorteio, manual (escolhido à mão) ou livre (dia livre: sem relógio e sem sorteio, para escolher à mão)' => 'sorteio、manual（手动选择）或 livre（空闲日：无手表且无抽签，供手动选择）',
        'o lembrete do dia (o que fazer antes: carregar, dar corda...); null: nenhum' => '当天的备忘（事先要做什么：充电、上链……）；null：没有',
        'por que o relógio está no dia; null: nenhum' => '为什么这块手表在这一天；null：没有',
        'o último dia dela (texto AAAA-MM-DD: o domingo, ou o sábado com a semana começando no domingo)' => '它的最后一天（文本 YYYY-MM-DD：星期日；每周从星期日开始时为星期六）',
        'o primeiro dia da próxima semana (texto AAAA-MM-DD: a segunda-feira, ou o domingo com a semana começando no domingo)' => '下一周的第一天（文本 YYYY-MM-DD：星期一；每周从星期日开始时为星期日）',
        'verdadeiro ou falso: a próxima semana já está no plano' => '真或假：下一周已经在计划中',
        'o dia em que a semana do rodízio começa (a Configuração, semana_inicio): segunda ou domingo' => '轮换一周开始的那天（设置 semana_inicio）：segunda 或 domingo',
        'a tabela dos relógios' => '手表表',
        'o estado por extenso, desde quando ("Em uso desde 07:00", "No sol desde 09:12", "Em repouso desde 21:40")' => '状态的文字形式，从何时起（“使用中，自 07:00”、“在晒太阳，自 09:12”、“休息中，自 21:40”）',
        'a energia agora, em % inteiro; null: indisponível ou sem dados' => '现在的能量，整数百分比；null：不可用或无数据',
        'de onde vem a energia ("bateria do smartwatch") ou por que não há' => '能量从何而来（“智能手表的电池”）或为何没有',
        'verdadeiro ou falso: tem aviso hoje' => '真或假：今天有提醒',
        'a data da compra (texto AAAA-MM-DD; null)' => '购买日期（文本 AAAA-MM-DD；null）',
        'até quando vai a garantia (texto AAAA-MM-DD; null)' => '保修到何时（文本 AAAA-MM-DD；null）',
        'onde comprou (null)' => '在哪里购买（null）',
        'o valor pago (número; null)' => '已付金额（数字；null）',
        'verdadeiro ou falso: é o relógio de hoje' => '真或假：是今天的手表',
        'verdadeiro ou falso: é o relógio do destaque no alto da página (o mesmo de destaque.relogio_id)' => '真或假：是页面顶部突出显示的手表（与 destaque.relogio_id 相同）',
        'a situação na coleção: colecao ou emprestado (os desejados, vendidos e arquivados ficam em fora_da_colecao)' => '在收藏中的情况：colecao 或 emprestado（心愿中、已售出和已归档的在 fora_da_colecao 中）',
        'a mesma por extenso: "Na coleção" ou "Emprestado"' => '同一内容的文字形式：“在收藏中”或“已借出”',
        'verdadeiro ou falso: no pulso agora' => '真或假：现在在手腕上',
        'o estado na tabela: uso (no pulso), sessao (numa sessão que não é o pulso: no sol, no winder, no carregador...), repouso ou indisponivel (o indisponível parado; no pulso ou numa sessão, vale o que ele está fazendo)' => '表格中的状态：uso（在手腕上）、sessao（在一个非手腕的时段中：在晒太阳、在上链盒、在充电器……）、repouso 或 indisponivel（停着的不可用；在手腕上或在某个时段中时，以它正在做的为准）',
        'o estado como a tabela mostra: "Em uso", o nome da sessão aberta ("No sol", "No carregador"; duas juntas: "No sol · No winder"), "Em repouso", "Indisponível" ou "Emprestado" (o emprestado parado)' => '表格所显示的状态：“使用中”、已打开时段的名称（“在晒太阳”、“在充电器”；两个一起：“在晒太阳 · 在上链盒”）、“休息中”、“不可用”或“已借出”（停着的已借出）',
        'a ordem do estado na tabela: 0 em uso, 1 numa sessão, 2 em repouso, 3 indisponível' => '状态在表格中的顺序：0 使用中，1 在某个时段中，2 休息中，3 不可用',
        'a versão da foto (número inteiro: instante Unix (segundos desde 01/01/1970 UTC), para o endereço dela); null: sem foto' => '照片的版本（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数），用于它的地址）；null：无照片',
        'a última leitura com valor; null: nenhuma' => '最近一次带值的读数；null：没有',
        'quando (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o valor' => '值',
        'o aviso Encostado deste relógio (não entra na manutenção); null: sem data (nunca foi ao pulso e sem data da compra)' => '这块手表的闲置提醒（不计入保养）；null：无日期（从未上过手腕且没有购买日期）',
        'a data (texto AAAA-MM-DD; hoje se já passou)' => '日期（文本 AAAA-MM-DD；若已过去则为今天）',
        'atrasado (passou do limite de dias sem ir ao pulso), em_breve (vence agora) ou ok (ainda dentro do prazo)' => 'atrasado（逾期：已超过多少天没上手腕的上限）、em_breve（现在到期）或 ok（仍在期限内）',
        'quanto falta, por extenso ("12d", "atrasado 40d")' => '还差多少，文字形式（“12d”、“逾期 40d”）',
        'o instante previsto (número inteiro: instante Unix (segundos desde 01/01/1970 UTC))' => '预计时刻（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数））',
        'o aviso de manutenção mais perto, sem o Encostado; null: nenhum' => '最近的保养提醒，不含闲置；null：没有',
        'quanto falta, por extenso ("10h 49min", "atrasado 2d")' => '还差多少，文字形式（“10h 49min”、“逾期 2d”）',
        'as frases de situação: as sessões abertas que o estado não mostra e a autonomia restante ("Autonomia restante 1d 23min")' => '情况的句子：状态未显示的已打开时段以及剩余续航（“剩余续航 1d 23min”）',
        'o grupo do relógio (o nome)' => '手表的分组（名称）',
        'a última vez no pulso (número inteiro: instante Unix (segundos desde 01/01/1970 UTC); 0: nunca)' => '最近一次在手腕上（整数：Unix 时刻（自 1970-01-01 UTC 起的秒数）；0：从未）',
        'a mesma por extenso ("agora · 14:32", "25/09 21:53", "nunca")' => '同一内容的文字形式（“现在 · 14:32”、“25/09 21:53”、“从未”）',
        'os totais da coleção inteira (a tabela da página Hoje soma só os relógios que os filtros dela deixam à mostra)' => '整个收藏的合计（今天页面的表格只加总其筛选所显示的手表）',
        'quantos estão disponíveis para o rodízio' => '有多少块可用于轮换',
        'quantos relógios estão na lista de desejos' => '心愿单中有多少块手表',
        'quantos estão em uso agora' => '现在有多少块处于使用中',
        'quantos estão fora da coleção (desejados, vendidos e arquivados: os de fora_da_colecao)' => '有多少块在收藏之外（心愿中、已售出和已归档：即 fora_da_colecao 中的那些）',
        'quantos relógios há' => '有多少块手表',
        'a soma do valor pago (valor_compra) de todos, em R$ (os sem valor contam 0)' => '全部已付金额（valor_compra）之和，以 R$ 计（没有金额的按 0 计）',
        'os campos do cadastro' => '档案的字段',
        'o grupo em que vale (0: todos)' => '生效的分组（0：全部）',
        'as opções (lista)' => '选项（列表）',
        'o valor padrão' => '默认值',
        'verdadeiro: o campo vale só nos relógios desejados (o preço-alvo, a prioridade); no cadastro, aparece só com a situação "Desejado"' => '真：该字段仅对心愿中的手表有效（目标价格、优先级）；在档案中，只在情况为“心愿中”时出现',
        'o tipo' => '类型',
        'o valor do relógio (null)' => '手表的值（null）',
        'os grupos (o seletor do cadastro)' => '各分组（档案的选择器）',
        'as situações na coleção, na ordem (o menu "Situação na coleção" do cadastro)' => '在收藏中的各种情况，按顺序（档案的“在收藏中的情况”菜单）',
        'o nome ("Na coleção", "Desejado", "Emprestado", "Vendido", "Arquivado")' => '名称（“在收藏中”、“心愿中”、“已借出”、“已售出”、“已归档”）',
        'o valor que vai na gravação (posse): colecao, desejado, emprestado, vendido ou arquivado' => '写入时使用的值（posse）：colecao、desejado、emprestado、vendido 或 arquivado',
        'os ids do grupo e dos de cima' => '该分组及其上级的 ids',
        'a cópia no banco pela Configuração da coleção (documentos_copia), que vale sobre o relógio e o arquivo: verdadeiro (todos), todo arquivo vai; falso (nenhum), nenhum vai; null (vazio), cada relógio decide (a caixa do cadastro só aparece então)' => '由收藏的设置（documentos_copia）决定的数据库副本，优先于手表和文件：真（todos），所有文件都存；假（nenhum），都不存；null（空），每块手表自行决定（只有此时档案中的复选框才出现）',
        'como o relógio abre na página Hoje (a Configuração): lado (no painel à direita da lista, o padrão) ou flutuante (numa janela grande por cima da página); no celular, os dois cobrem a tela' => '手表在今天页面如何打开（设置）：lado（在列表右侧的面板中，默认）或 flutuante（在页面上方的大窗口中）；在手机上，两者都盖住屏幕',
        'o relógio; null: o cadastro de um relógio novo' => '该手表；null：新手表的档案',
        'as autonomias do relógio (as mesmas do recurso autonomia)' => '手表的各续航（与 recurso autonomia 相同）',
        'o resultado agora de cada fórmula que vale para o relógio' => '对这块手表有效的每条公式现在的结果',
        'a unidade do resultado (s: segundos)' => '结果的单位（s：秒）',
        'o grupo da versão da fórmula usada' => '所用公式版本的分组',
        'a energia agora, em %; null sem dados' => '现在的能量，以 % 计；无数据则为 null',
        'de onde vem a energia' => '能量从何而来',
        'a data da compra' => '购买日期',
        'até quando vai a garantia' => '保修到何时',
        'onde comprou' => '在哪里购买',
        'o valor pago' => '已付金额',
        'há quantos dias foi a compra (número inteiro); null: sem a data' => '购买是多少天前（整数）；null：无日期',
        'em quantos dias ele foi ao pulso (a fórmula dias_de_uso); null: sem a fórmula' => '它有多少天上过手腕（公式 dias_de_uso）；null：没有该公式',
        'o valor pago dividido pelos dias de uso, em R$ (a fórmula custo_por_uso); null: sem o valor pago ou sem nenhum dia de uso' => '已付金额除以使用天数，以 R$ 计（公式 custo_por_uso）；null：没有已付金额或没有任何使用日',
        'os campos do cadastro que valem para o relógio (os do grupo dele e dos de cima), com o valor que as contas usam' => '对这块手表有效的档案字段（它的分组及其上级的），带计算所使用的值',
        'de onde vem o valor usado: informado, padrao (o padrão do campo) ou vazio' => '所用值的来源：informado、padrao（字段默认值）或 vazio',
        'a unidade (texto)' => '单位（文本）',
        'o valor informado no relógio (texto; null: não preenchido)' => '在手表上填写的值（文本；null：未填写）',
        'o valor que as contas usam: o informado, senão o padrão do campo (null: nenhum)' => '计算所使用的值：已填写的，否则字段的默认值（null：没有）',
        'desde quando (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '从何时起（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'a situação na coleção: colecao, desejado, emprestado, vendido ou arquivado (fora da coleção, disponivel é sempre falso)' => '在收藏中的情况：colecao、desejado、emprestado、vendido 或 arquivado（离开收藏后，disponivel 始终为假）',
        'a mesma por extenso ("Na coleção", "Desejado"...)' => '同一内容的文字形式（“在收藏中”、“心愿中”……）',
        'verdadeiro: é da coleção agora (na coleção ou emprestado); falso: desejado, vendido ou arquivado' => '真：现在属于收藏（在收藏中或已借出）；假：心愿中、已售出或已归档',
        'os acessórios dele (o quadro Acessórios), pelo tipo e pelo nome' => '它的配件（配件框），按类型和名称',
        'este relógio' => '这块手表',
        'o que a lista de desejos mostra (o quadro Desejo do painel): só no desejado; null nos outros' => '心愿单所显示的内容（面板的心愿框）：仅在心愿中；其他情况下为 null',
        'o link da página do relógio (o campo link; null)' => '手表页面的链接（字段 link；null）',
        'a marca (o campo marca; null)' => '品牌（字段 marca；null）',
        'até quanto pagar, em R$ (o campo preco_alvo; número; null)' => '最多付多少，以 R$ 计（字段 preco_alvo；数字；null）',
        'a prioridade (o campo prioridade_desejo: Alta, Média, Baixa...; null)' => '优先级（字段 prioridade_desejo：高、中、低……；null）',
        'a ordem da prioridade nas opções do campo (1 é a mais alta; sem prioridade: depois de todas)' => '优先级在字段选项中的顺序（1 为最高；无优先级：排在全部之后）',
        'a referência, o modelo (o campo referencia; null)' => '型号（字段 referencia；null）',
        'o estado agora: uso (no pulso), sessao (numa sessão que não é o pulso: no sol, no winder, no carregador...) ou repouso' => '现在的状态：uso（在手腕上）、sessao（在一个非手腕的时段中：在晒太阳、在上链盒、在充电器……）或 repouso',
        'o estado como a tela mostra: "Em uso", o nome da sessão aberta ("No sol", "No carregador"; duas juntas: "No sol · No winder") ou "Em repouso"' => '界面所显示的状态：“使用中”、已打开时段的名称（“在晒太阳”、“在充电器”；两个一起：“在晒太阳 · 在上链盒”）或“休息中”',
        'até que dia vai a escala (null fora da escala)' => '排班表延伸到哪一天（不在排班表中则为 null）',
        'a dica da foto no painel (aparece com o mouse parado em cima dela), em linhas: o nome, o grupo e o código; o estado e a carga; a nota e o próximo dia no rodízio (ou indisponível); a compra (data e valor); e a frase: Duplo clique (ou "Abrir foto", embaixo): a foto em tamanho grande.' => '面板上照片的提示（鼠标停在上面时出现），分行：名称、分组和编号；状态和电量；分数以及下一次进入轮换的日期（或不可用）；购买（日期和金额）；以及这句话：双击（或下方的“打开照片”）：大尺寸照片。',
        'as 40 últimas leituras com valor (o gráfico)' => '最近 40 次带值的读数（图表）',
        'verdadeiro ou falso: a leitura é de uso (a marcação dela, ou, sem marcação, o pulso registrado naquele instante)' => '真或假：读数为使用中（其标记，或无标记时那一刻记录的佩戴状态）',
        'a marcação da leitura: uso ou repouso (a gravada, ou, sem marcação, a do pulso registrado naquele instante)' => '读数的标记：uso 或 repouso（已保存的，或无标记时那一刻记录的佩戴状态）',
        'verdadeiro ou falso: a marcação foi gravada na leitura (falso: veio do pulso registrado)' => '真或假：标记已保存在读数中（假：来自记录的佩戴状态）',
        'os lançamentos dos últimos 14 dias e a sessão ainda aberta, do mais recente ao mais antigo (até 40): o que o quadro "Corrigir marcações" do painel mostra' => '最近 14 天的记录以及仍打开的时段，从最近到最旧（最多 40）：面板“更正标记”框所显示的内容',
        'quando a sessão terminou (texto AAAA-MM-DD HH:MM:SS); null: ainda aberta, ou um lançamento instantâneo' => '时段结束的时间（文本 AAAA-MM-DD HH:MM:SS）；null：仍打开，或一条瞬时记录',
        'instantaneo, valor ou sessao' => 'instantaneo、valor 或 sessao',
        'o número do lançamento (para recurso=lancamento, acao=alterar ou excluir)' => '记录的编号（用于 recurso=lancamento，acao=alterar 或 excluir）',
        'quando foi (a sessão: quando começou), texto AAAA-MM-DD HH:MM:SS' => '发生的时间（时段：开始的时间），文本 AAAA-MM-DD HH:MM:SS',
        'o nome do tipo de lançamento' => '记录类型的名称',
        'manual, rodizio (a sessão do dia) ou importado' => 'manual、rodizio（当天的时段）或 importado',
        'numa leitura, a marcação gravada: uso, repouso ou null (sem marcação)' => '在读数中保存的标记：uso、repouso 或 null（无标记）',
        'o identificador do tipo de lançamento (pulso, carga, corda...)' => '记录类型的标识符（pulso、carga、corda……）',
        'a unidade do valor (texto; vazio sem valor)' => '值的单位（文本；无值时为空）',
        'o valor (número), num lançamento com valor; null nos outros' => '值（数字），在带值的记录中；其他情况下为 null',
        'os trechos da linha do tempo do relógio, os 5 mais recentes: cada trecho é um período contínuo num estado, ou uma marcação (um lançamento instantâneo)' => '手表时间线的各片段，最近 5 个：每个片段是某一状态上的一段连续时间，或一次标记（一条瞬时记录）',
        'o aviso Encostado deste relógio (o quadro Agora; não entra nas próximas manutenções); null: sem data' => '这块手表的闲置提醒（现在框；不计入各项下次保养）；null：无日期',
        'as 5 próximas manutenções (avisos, sem o Encostado)' => '接下来的 5 项下次保养（提醒，不含闲置）',
        'a data (texto AAAA-MM-DD)' => '日期（文本 AAAA-MM-DD）',
        'a janela da conta do gasto medido por extenso (o "contar por" da Configuração: dias ou leituras)' => '测得消耗计算窗口的文字说明（设置中的“按什么计”：天数或读数）',
        'a janela da média do gasto medido, em dias (a da Configuração)' => '实测消耗平均值的窗口，以天计（设置中的）',
