        'o número da categoria (para documentos.php?relogio=...&cat=...)' => '类别的编号（用于 documentos.php?relogio=...&cat=...）',
        'o nome da categoria' => '类别的名称',
        'verdadeiro: a pasta dos documentos (DOCUMENTOS_PASTA do config.php) está pronta para receber arquivos' => '真：文档文件夹（config.php 的 DOCUMENTOS_PASTA）已准备好接收文件',
        'a cópia no banco pela Configuração da coleção (documentos_copia), que vale sobre o relógio e o arquivo: verdadeiro (todos), todo arquivo vai; falso (nenhum), nenhum vai; null (vazio), cada relógio e cada arquivo decidem' => '由收藏的设置（documentos_copia）决定的数据库副本，优先于手表和文件：真（todos），所有文件都存；假（nenhum），都不存；null（空），每块手表和每个文件自行决定',
        'quantos documentos ele tem' => '它有多少份文档',
        'quantos dias as listas mostram por página (o "Mostrar até" da Configuração, já com o padrão)' => '各列表每页显示多少天（设置中的“显示至”，已带上默认值）',
        'o intervalo de atualização das páginas, já com o padrão (a Configuração, atualizar_segundos: 1 a 86400; 0, não se atualizam sozinhas; padrão 60)' => '页面的刷新间隔，已含默认值（设置中的 atualizar_segundos：1 到 86400；0 不自动刷新；默认 60）',
        'o reloginho da barra e da aba (relojinho.js)' => '菜单栏和标签页的小手表（relojinho.js）',
        'o modo, já com o padrão: hora, aleatorio ou sem_repeticao (a Configuração relojinho_modo)' => '模式，已套用默认值：hora、aleatorio 或 sem_repeticao（设置 relojinho_modo）',
        'quantos modelos o reloginho tem (24, um para cada hora do dia)' => '小手表有多少种款式（24 种，一天每小时一种）',
        'os Próximos dias da página Hoje (proximos_por_pagina; padrão 7)' => '今天页面的接下来的日子（proximos_por_pagina；默认 7）',
        'o dia a dia da página Plano (plano_por_pagina; padrão 31)' => '计划页面的逐日内容（plano_por_pagina；默认 31）',
        'de onde vêm os números dos sorteios: RANDOM.ORG (ruído atmosférico); fora do ar, ANU QRNG (quântico); sem os dois, o gerador seguro do PHP (random_int)' => '抽签数字的来源：RANDOM.ORG（大气噪声）；离线时为 ANU QRNG（量子）；两者都没有时，为 PHP 的安全随机生成器（random_int）',
        'as fontes, na ordem em que o sistema tenta: RANDOM.ORG, ANU QRNG, gerador seguro do PHP (random_int)' => '各来源，按系统尝试的顺序：RANDOM.ORG、ANU QRNG、PHP 的安全随机生成器（random_int）',
        'a fonte do último lote de números e quando ("RANDOM.ORG em AAAA-MM-DD HH:MM:SS"); null: nenhum ainda' => '最近一批数字的来源和时间（“RANDOM.ORG 于 AAAA-MM-DD HH:MM:SS”）；null：还没有',
        'desde quando os dois serviços estão sem responder (AAAA-MM-DD HH:MM:SS): por 10 minutos o sistema nem tenta e usa o gerador do PHP; null: no ar (ou não se sabe)' => '两个服务从何时起没有响应（AAAA-MM-DD HH:MM:SS）：在 10 分钟内系统甚至不再尝试，而使用 PHP 的生成器；null：在线（或未知）',
        'a situação do cron, como a Configuração mostra (o cron roda a cada minuto)' => 'cron 的情况，与设置所显示的一致（cron 每分钟运行）',
        'a linha do crontab que roda o sistema (com a pasta dele)' => '运行本系统的 crontab 行（含它的文件夹）',
        'o erro guardado da última execução com erro (null: sem erro; some na primeira execução sem erro)' => '最近一次有错误的执行所保存的错误（null：无错误；第一次无错误的执行后消失）',
        'há quantos minutos ele rodou pela última vez (null: nunca rodou)' => '它最近一次运行是多少分钟前（null：从未运行）',
        'nunca (ainda não rodou), parado (mais de 10 minutos sem rodar) ou rodando' => 'nunca（尚未运行）、parado（超过 10 分钟没有运行）或 rodando',
        'a frase da Configuração ("Cron rodando: última execução às 10:41."; parado e nunca trazem a linha do crontab)' => '设置中的句子（“Cron 运行中：最近一次执行在 10:41。”；parado 和 nunca 会带上 crontab 行）',
        'quando rodou pela última vez (AAAA-MM-DD HH:MM:SS, no fuso do sistema; null: nunca rodou)' => '最近一次运行的时间（AAAA-MM-DD HH:MM:SS，系统时区；null：从未运行）',
        'o idioma padrão da instalação (pt-BR, en, zh-CN, hi, es, fr): o de quem não escolheu outro no menu, o das mensagens do cron e o da API sem lingua= (vazio: o do navegador, senão português)' => '安装的默认语言（pt-BR、en、zh-CN、hi、es、fr）：没有在菜单中另选语言的人所用的、cron 消息所用的，以及不带 lingua= 时 API 所用的（空：浏览器的语言，否则为葡萄牙语）',
        'o fuso do sistema (o FUSO do config.php, ou o do PHP): o das datas gravadas no banco e o de quem não escolheu outro' => '系统的时区（config.php 的 FUSO，或 PHP 的）：数据库中保存的日期所用，以及未另选的人所用',
        'os fusos horários que o PHP conhece, em ordem alfabética (as listas Fuso horário da Configuração e de Minha conta)' => 'PHP 认识的时区，按字母顺序（设置和“我的账户”的时区列表）',
        'os idiomas do sistema, na ordem (o menu Idioma padrão)' => '系统的语言，按顺序（默认语言菜单）',
