        'sorteio (pelo modo) ou manual (escolhido à mão: "Usando hoje" ou trocar_dia)' => 'sorteio（由模式）或 manual（手动选择：“今天正在使用”或 trocar_dia）',
        'o último dia gravado no plano (AAAA-MM-DD; null: plano vazio), qualquer que seja o período pedido' => '计划中最后保存的一天（AAAA-MM-DD；null：计划为空），与所请求的时段无关',
        'o resumo do período (os dias da resposta de hoje em diante), como a página Plano mostra' => '该时段的摘要（响应中从今天起的日子），与计划页面所显示的一致',
        'o último dia contado (null: nenhum)' => '计入的最后一天（null：没有）',
