        'quantos dias o período tem no plano' => '该时段在计划中有多少天',
        'cada relógio com dia no período, do que tem mais dias ao que tem menos (no empate, pelo nome)' => '在该时段有日子的每块手表，从天数最多到最少（并列时按名称）',
