        'o nome do aparelho (o que o Lembrar mandou: "Android Chrome", "iPhone Safari"); null: sem nome' => '设备名称（“记住”发送的内容：“Android Chrome”“iPhone Safari”）；null：无名称',
        'o último pedido que entrou por ele; null: nunca' => '最近一次通过它进入的请求；null：从未',
        'verdadeiro: é o aparelho por que este pedido entrou (o cookie)' => '真：本次请求通过它进入的设备（cookie）',
        'o Web Push' => 'Web Push',
        'verdadeiro ou falso: o servidor tem as chaves VAPID' => '真或假：服务器有 VAPID 密钥',
        'a chave pública VAPID (o navegador inscreve com ela); null: não configurado' => 'VAPID 公钥（浏览器用它订阅）；null：未配置',
        'os seus aparelhos inscritos' => '你已订阅的设备',
        'o nome do aparelho (o navegador)' => '设备名称（浏览器）',
        'a marca do endereço do aparelho (para o navegador saber se já está inscrito)' => '设备地址的标记（让浏览器知道是否已订阅）',
        'verdadeiro ou falso: o servidor manda e-mail' => '真或假：服务器发送电子邮件',
        '(só o master; null para os outros) a configuração do e-mail que o sistema leu do config.php, para o quadro Servidor de e-mail' => '（仅 master；其他人为 null）系统从 config.php 读到的电子邮件配置，用于“邮件服务器”框',
        'smtp, mail ou null (o envio está desligado)' => 'smtp、mail 或 null（发送已关闭）',
        'o EMAIL_METODO como está no config.php; null: não está lá' => 'config.php 中原样的 EMAIL_METODO；null：其中没有',
        'o remetente (EMAIL_REMETENTE, senão o SMTP_USUARIO); vazio: falta' => '发件人（EMAIL_REMETENTE，否则为 SMTP_USUARIO）；空：缺少',
        'o SMTP: host, porta, seguranca (ssl, tls ou nada), usuario e senha (verdadeiro ou falso: se está definida; a senha mesma nunca sai)' => 'SMTP：host、porta、seguranca（ssl、tls 或 nada）、usuario 和 senha（真或假：是否已设置；密码本身从不输出）',
        'o servidor (SMTP_HOST)' => '服务器（SMTP_HOST）',
        'a porta (SMTP_PORTA; sem ela, 465 no ssl e 587 no resto)' => '端口（SMTP_PORTA；没有时，ssl 为 465，其他为 587）',
        'ssl, tls ou nada (SMTP_SEGURANCA)' => 'ssl、tls 或 nada（SMTP_SEGURANCA）',
        'o usuário (SMTP_USUARIO)' => '用户（SMTP_USUARIO）',
        'verdadeiro ou falso: a SMTP_SENHA está definida' => '真或假：SMTP_SENHA 已设置',
        'o IMAP da cópia em Enviados (host, porta, seguranca, usuario, senha e pasta); null: não configurado' => '用于在“已发送”中保存副本的 IMAP（host、porta、seguranca、usuario、senha 和 pasta）；null：未配置',
        'o servidor (IMAP_HOST)' => '服务器（IMAP_HOST）',
        'a porta (IMAP_PORTA; sem ela, 993 no ssl e 143 no resto)' => '端口（IMAP_PORTA；没有时，ssl 为 993，其他为 143）',
        'ssl, tls ou nada (IMAP_SEGURANCA)' => 'ssl、tls 或 nada（IMAP_SEGURANCA）',
        'o usuário (IMAP_USUARIO, senão o SMTP_USUARIO)' => '用户（IMAP_USUARIO，否则为 SMTP_USUARIO）',
        'verdadeiro ou falso: a senha do IMAP está definida' => '真或假：IMAP 密码已设置',
        'a pasta Enviados (IMAP_PASTA_ENVIADOS, padrão Sent)' => '“已发送”文件夹（IMAP_PASTA_ENVIADOS，默认 Sent）',
        'o POP, só para testar a conta (host, porta, seguranca, usuario e senha); null: não configurado' => 'POP，仅用于测试账户（host、porta、seguranca、usuario 和 senha）；null：未配置',
        'o servidor (POP_HOST)' => '服务器（POP_HOST）',
        'a porta (POP_PORTA; sem ela, 995 no ssl e 110 no resto)' => '端口（POP_PORTA；没有时，ssl 为 995，其他为 110）',
        'ssl, tls ou nada (POP_SEGURANCA)' => 'ssl、tls 或 nada（POP_SEGURANCA）',
        'o usuário (POP_USUARIO)' => '用户（POP_USUARIO）',
        'verdadeiro ou falso: a POP_SENHA está definida' => '真或假：POP_SENHA 已设置',
        'verdadeiro ou falso: o PHP do servidor tem a extensão openssl (o ssl e o tls precisam dela)' => '真或假：服务器的 PHP 有 openssl 扩展（ssl 和 tls 需要它）',
        'verdadeiro ou falso: o mail() do PHP está ligado neste servidor' => '真或假：此服务器启用了 PHP 的 mail()',
        'o que está errado ou faltando na configuração, achado sem conectar em nada (cada um, uma frase dizendo o que corrigir no config.php)' => '配置中错误或缺少的内容，无需连接任何服务器即可发现（每条一句话，说明要在 config.php 中修改什么）',
        'os dias da conta de demonstração' => '演示账户的天数',
        '(parte=menu) verdadeiro ou falso: quem pede é o master (ou o master vendo como outro)' => '（parte=menu）真或假：请求者是 master（或以他人身份查看的 master）',
        '(parte=menu) de quantos em quantos segundos a página lê tudo de novo sozinha (a Configuração da coleção; 0: não lê; sem coleção, 0)' => '(parte=menu) 页面每隔多少秒自动重新读取全部数据（收藏的设置；0：不读取；没有收藏时为 0）',
        '(parte=menu) o reloginho da barra e da aba, no modo da Configuração da coleção (sem coleção, null: o modelo da hora)' => '（parte=menu）菜单栏和标签页的小手表，按收藏设置的模式（没有收藏时为 null：用该小时的款式）',
        'hora, aleatorio ou sem_repeticao (a Configuração relojinho_modo)' => 'hora、aleatorio 或 sem_repeticao（设置 relojinho_modo）',
        'o dia da ordem (AAAA-MM-DD, no fuso da coleção): o sorteio muda a cada dia' => '顺序对应的日期（YYYY-MM-DD，按收藏的时区）：抽取每天变化',
        'o modelo de cada hora do dia, a hora 0 primeiro (24 números de 0 a 23; no modo hora, a própria hora; no aleatório, um sorteio por hora, podendo repetir; sem repetição, os 24 embaralhados). O sorteio sai de um resumo da coleção, do dia e da hora: o mesmo o dia inteiro, em toda página e aparelho' => '一天中每个小时的款式，0 点在前（0 到 23 的 24 个数字；hora 模式下就是该小时本身；随机模式每小时抽一次，可能重复；不重复时为 24 种打乱）。抽取来自收藏、日期和小时的摘要：一整天相同，在每个页面和设备上都一样',
        '(parte=menu) o idioma de quem não escolheu no menu: o da conta (Minha conta), senão o da coleção (a Configuração), senão o da instalação; null: nenhum (vale o do navegador). As páginas seguem este, que vem a cada abertura: o padrao do script do dicionário (recurso=textos&formato=js) fica em cache' => '（parte=menu）未在菜单中选择语言者的语言：账户的（我的账户），否则收藏的（设置），否则安装的；null：无（以浏览器的为准）。页面跟随此项，它在每次打开时返回：词典脚本（recurso=textos&formato=js）里的 padrao 会被缓存',
        'o seu papel nela: dono, membro ou master' => '你在其中的角色：dono、membro 或 master',
        'o fuso horário em que este pedido roda (as datas e horas que a API mostra e recebe). O dia do rodízio (o plano, o relógio do dia, as rodadas do cron) é sempre o da coleção, no fuso dela' => '本请求运行所在的时区（API 显示和接收的日期与时间）。轮换的日子（计划、当日手表、cron 的轮次）始终以收藏为准，按其时区',
        'de onde veio: usuario (o seu, de Minha conta), navegador (o do aparelho: o cookie fuso_navegador das páginas, ou fuso_pedido= no pedido), colecao (o da Configuração) ou sistema (o FUSO do config.php)' => '来源：usuario（你的，来自“我的账户”）、navegador（设备的：页面的 fuso_navegador cookie，或请求中的 fuso_pedido=）、colecao（设置的）或 sistema（config.php 的 FUSO）',
        'o fuso do sistema (o das datas gravadas no banco)' => '系统的时区（数据库中保存的日期所用）',
        'o fuso da coleção do pedido; null: não tem (vale o do sistema)' => '请求所在收藏的时区；null：没有（系统的生效）',
        'os fusos horários que o PHP conhece, em ordem alfabética (a lista Fuso horário de Minha conta)' => 'PHP 认识的时区，按字母顺序（“我的账户”的时区列表）',
        'os pedidos de acesso que você aprova' => '由你审批的访问申请',
        'quem pede' => '申请人',
        'o e-mail de quem pede' => '申请人的电子邮件',
        'a coleção pedida; null: tudo de um dono' => '所申请的收藏；null：某个所有者的全部内容',
        'o dono de quem se pede tudo; null: uma coleção' => '被申请全部内容的所有者；null：一个收藏',
        'o que foi pedido, por extenso' => '所申请的内容，完整描述',
        'o recado de quem pede' => '申请人的留言',
        'os convites que membros fizeram para as suas coleções, esperando você' => '成员为你的收藏发出、正在等你处理的邀请',
        'os convites que você fez' => '你发出的邀请',
        'para quem' => '发给谁',
        'o login de quem convidou' => '邀请人的登录名',
        'o id de quem convidou' => '邀请人的 id',
        'pendente (espera o dono) ou aprovado (enviado)' => 'pendente（等待所有者）或 aprovado（已发送）',
        'a coleção; null: tudo de um dono' => '收藏；null：某个所有者的全部内容',
        'o dono; null: uma coleção' => '所有者；null：一个收藏',
        'o seu login' => '你的登录名',
        'o seu id' => '你的 id',
        'quem vê as suas coleções' => '谁能看到你的收藏',
        'cada coleção sua' => '你的每个收藏',
        'os membros dela' => '它的成员',
        'o id do membro' => '成员的 id',
        'quem vê tudo seu' => '能看到你全部内容的人',
        'as suas coleções' => '你的收藏',
        'as coleções para onde você pode convidar' => '你可以邀请到的收藏',
        'o seu papel nela' => '你在其中的角色',
        'verdadeiro ou falso: o servidor manda e-mail (sem ele, o link do convite aparece para você mandar)' => '真或假：服务器发送电子邮件（否则邀请链接会显示出来，由你发送）',
        'quantos dias um convite ou um pedido espera (CONVITE_DIAS)' => '邀请或申请的等待天数（CONVITE_DIAS）',
        'verdadeiro ou falso: o cadastro está aberto (CADASTRO_ABERTO); fechado, só com convite' => '真或假：注册已开放（CADASTRO_ABERTO）；关闭时只能凭邀请',
        'os dias da conta de demonstração (0: a conta nasce oficial)' => '演示账户的天数（0：账户一创建即为正式）',
        'verdadeiro ou falso: o servidor manda e-mail (o Esqueci a senha precisa dele)' => '真或假：服务器发送电子邮件（“忘记密码”需要它）',
        'com convite=<token>: o convite; false: não vale mais; null: sem convite' => '带 convite=<token> 时：邀请；false：已失效；null：没有邀请',
        'o que ele dá' => '它授予的内容',
        'verdadeiro ou falso: o e-mail já tem conta (então é entrar e aceitar)' => '真或假：该电子邮件已有账户（只需登录并接受）',
        'quem acessa' => '谁在访问',
        'o login de quem pediu (pelo site; vazio pelo token)' => '请求者的登录名（通过网站；通过 token 时为空）',
        'o id (só o master vê)' => 'id（只有 master 能看到）',
        'o e-mail (para recuperar a senha, os convites e os avisos)' => '电子邮件（用于找回密码、邀请和通知）',
        'master (cuida do sistema inteiro) ou comum' => 'master（管理整个系统）或 comum',
        'o idioma dele; null: o da coleção' => '他的语言；null：收藏的语言',
        'o fuso horário dele ("America/Sao_Paulo"; "navegador": o do aparelho); null: o da coleção, senão o do sistema' => '他的时区（"America/Sao_Paulo"；"navegador"：设备的）；null：收藏的，否则系统的',
        '(só o master) os fusos horários que o PHP conhece (a lista Fuso horário do quadro Alterar)' => '（仅限 master）PHP 认识的时区（修改面板的时区列表）',
        'o último acesso (texto AAAA-MM-DD HH:MM:SS); null: nunca entrou' => '最后访问（文本 AAAA-MM-DD HH:MM:SS）；null：从未登录',
        'quando a conta de demonstração vence (texto AAAA-MM-DD HH:MM:SS); null: a conta é oficial' => '演示账户的到期时间（文本 AAAA-MM-DD HH:MM:SS）；null：账户是正式的',
        'verdadeiro ou falso: é de demonstração' => '真或假：是演示账户',
        'quantos dias faltam para vencer; null: oficial' => '距到期的剩余天数；null：正式账户',
        'verdadeiro ou falso: bloqueada pelo master (não entra)' => '真或假：被 master 封禁（无法进入）',
        'as coleções dele (o dono)' => '他的收藏（所有者）',
        'as coleções de outros de que ele é membro' => '他作为成员的他人收藏',
        'os logins dos donos de quem ele vê tudo' => '他能看到其全部内容的所有者的登录名',
        'quantos pedidos de acesso dele esperam' => '他有多少访问申请在等待',
        'quantos tokens de API ele tem' => '他有多少 API 令牌',
        'todas as coleções (para transferir e dar acesso)' => '所有收藏（用于转移和授予访问）',
        'o papel de quem pede nela: dono, membro ou master' => '请求者在其中的角色：dono、membro 或 master',
        'os dias da conta de demonstração (DEMO_DIAS; 0: as contas novas já nascem oficiais)' => '演示账户的天数（DEMO_DIAS；0：新账户一创建即为正式）',
        'o banco do config.php: mysql, pgsql, sqlite ou firebird' => 'config.php 中的数据库：mysql、pgsql、sqlite 或 firebird',
        'instalado e sem migração pendente' => '已安装且没有待处理的迁移',
        'o banco tem as tabelas do sistema' => '数据库具有系统的各表',
        'as versões das migrações que faltam aplicar (vazio com o banco vazio ou em dia)' => '尚未应用的迁移版本（数据库为空或已是最新时为空）',
        'o que fazer agora: instalar (POST recurso=instalacao, acao=instalar), aplicar as migrações, criar o primeiro usuário (POST recurso=usuarios, acao=salvar, com o token) ou nada' => '现在要做什么：安装（POST recurso=instalacao, acao=instalar）、应用迁移、创建第一个用户（POST recurso=usuarios, acao=salvar，带 token）或无',
        'quantas tabelas o banco tem' => '数据库有多少张表',
        'quantos usuários existem (0: o login das páginas ainda não tem como entrar)' => '有多少个用户（0：页面登录还无法进入）',
        'o banco não tem nenhuma tabela: só a instalação responde, pelo token' => '数据库没有任何表：只有安装会响应，通过 token',
        'o PHP tem a extensão do MySQL (mysqli), que a importação usa para ler o banco antigo' => 'PHP 具有 MySQL 扩展（mysqli），导入用它来读取旧数据库',
        'este banco já tem relógios: a importação pede substituir=1 (apaga antes os relógios e o histórico)' => '此数据库已有手表：导入要求 substituir=1（先删除手表和历史）',
        'quantos relógios este banco tem agora' => '此数据库现在有多少块手表',
        'onde a importação procura o banco antigo (MySQL/MariaDB); a senha nunca sai' => '导入在何处查找旧数据库（MySQL/MariaDB）；密码从不输出',
        'de onde vêm esses dados: os ANTIGO_* do config.php, ou os DB_* (com este sistema no MySQL)' => '这些数据从何而来：config.php 的 ANTIGO_*，或 DB_*（当本系统使用 MySQL 时）',
        'o servidor' => '服务器',
        'a porta (null: a padrão)' => '端口（null：默认端口）',
        'o usuário que lê o banco antigo' => '读取旧数据库的用户',
        'o que a importação traz, em texto' => '导入会带入的内容，文本',
        'como o pedido entrou: login (o do site, HTTP Basic) ou token' => '请求如何进入：login（网站的，HTTP Basic）或 token',
        'o login de quem entrou (null pelo token)' => '进入者的登录名（通过 token 时为 null）',
        'a página para onde ele foi mandado (302), ou null' => '他被送到的页面（302），或 null',
        'o relógio pedido: {id, nome, copia_banco}; null: os documentos de todos' => '所请求的手表：{id, nome, copia_banco}；null：全部手表的文档',
        'verdadeiro: a pasta dos documentos (DOCUMENTOS_PASTA do config.php) existe e aceita gravar' => '真：文档文件夹（config.php 的 DOCUMENTOS_PASTA）存在且允许写入',
        'o motivo de a pasta não servir (texto); null: ela serve' => '文件夹不可用的原因（文本）；null：它可用',
        'o maior arquivo aceito, em bytes (número inteiro): o DOCUMENTOS_LIMITE do config.php (sem ele, 100 MB), ou menos pelo upload_max_filesize e o post_max_size do PHP; null: sem limite' => '接受的最大文件，以字节计（整数）：config.php 的 DOCUMENTOS_LIMITE（没有则为 100 MB），或更小，受 PHP 的 upload_max_filesize 和 post_max_size 限制；null：无上限',
        'todos os relógios, pelo nome (para escolher outro)' => '全部手表，按名称（用于改选另一块）',
        'quantos documentos ela tem (com relogio: só os daquele relógio)' => '它有多少份文档（带 relogio：只计该手表的）',
        'o resumo da NF-e, quando o arquivo é o XML de uma nota fiscal eletrônica; null: não é' => 'NF-e 摘要，当文件是电子发票的 XML 时；null：不是',
        'a chave de acesso da nota (44 dígitos)' => '发票的访问密钥（44 位数字）',
        'o CNPJ (ou o CPF) do emitente' => '开票方的 CNPJ（或 CPF）',
        'a data de emissão (texto AAAA-MM-DD)' => '开票日期（文本 AAAA-MM-DD）',
        'o nome do emitente (a loja)' => '开票方的名称（商店）',
        'o número da nota' => '发票号码',
        'os produtos da nota' => '发票上的商品',
        'a descrição do produto' => '商品描述',
        'a quantidade (número)' => '数量（数字）',
        'o valor do produto (número, em R$)' => '商品金额（数字，以 R$ 计）',
        'a série da nota' => '发票的系列',
        'o valor total da nota (número, em R$)' => '发票总金额（数字，以 R$ 计）',
        'de onde vem o texto: README.md (em português) ou textos/manual/<idioma>.md (a tradução do idioma do pedido)' => '文本从何而来：README.md（葡萄牙语）或 textos/manual/<idioma>.md（所请求语言的译文）',
        'os trechos do README que entram, na ordem: cada um da seção "de" até antes da seção "ate"' => '纳入的 README 片段，按顺序：每一段从“de”节直到“ate”节之前',
        'o título da seção em que o trecho começa' => '片段开始处的节标题',
        'o título da seção em que o trecho para (ela fica de fora)' => '片段停止处的节标题（该节本身不包括）',
        'cada título do manual (## a ####), na ordem' => '手册的每个标题（## 到 ####），按顺序',
        'o nível do título: 2 (seção), 3 ou 4 (dentro dela)' => '标题的级别：2（节）、3 或 4（节内）',
        'o título, como no README (em markdown)' => '标题，与 README 中相同（markdown）',
        'a âncora do título, como a do GitHub e a da página Ajuda (ajuda.php#ancora)' => '标题的锚点，与 GitHub 的以及帮助页面的相同（ajuda.php#ancora）',
        'o texto da seção até o próximo título, em markdown (tabelas, listas, código, imagens)' => '直到下一个标题为止的节文本，markdown（表格、列表、代码、图像）',
        'o manual inteiro, em markdown: o que a página Ajuda converte para HTML' => '整本手册，markdown：帮助页面把它转成 HTML 的内容',
        'o manual inteiro já em HTML, como a página Ajuda mostra: títulos com âncora, parágrafos, listas, tabelas, código, imagens e as legendas (o diagrama mermaid fica de fora)' => '整本手册已是 HTML，与帮助页面所显示的一致：带锚点的标题、段落、列表、表格、代码、图像和说明文字（mermaid 图除外）',
        'o sumário da página Ajuda: os títulos de nível 2 e 3, na ordem' => '帮助页面的目录：级别为 2 和 3 的标题，按顺序',
        'a âncora do título (ajuda.php#ancora)' => '标题的锚点（ajuda.php#ancora）',
        'o nível do título: 2 ou 3' => '标题的级别：2 或 3',
        'o título em texto puro (sem a marcação do markdown)' => '纯文本标题（不含 markdown 标记）',
        'o que o sistema é e faz, num parágrafo' => '系统是什么、做什么，一段话',
        'como ler esta resposta e onde está o resto (a API em recurso=ajuda, o cadastro inicial no schema.sql e em recurso=cadastros e recurso=criterios, o README, os testes)' => '如何阅读本响应以及其余内容在哪里（API 在 recurso=ajuda，初始档案在 schema.sql 以及 recurso=cadastros 和 recurso=criterios，还有 README 和测试）',
        'as partes do roteiro, na ordem: os princípios, a arquitetura, a ordem de construção e as regras de cada parte do sistema' => '路线的各部分，按顺序：原则、架构、构建顺序以及系统每一部分的规则',
        'o nome curto da parte (principios, arquitetura, ordem, arvore_campos, lancamentos, formulas, avisos, gasto, criterios, rodizio, pulso, cron, mensagens, documentos, telas, seguranca, testes)' => '部分的短名称（principios、arquitetura、ordem、arvore_campos、lancamentos、formulas、avisos、gasto、criterios、rodizio、pulso、cron、mensagens、documentos、telas、seguranca、testes）',
        'o título da parte' => '部分的标题',
        'as regras e as explicações daquela parte, uma por texto' => '该部分的规则和说明，每条一个文本',
        'a especificação visual que a reescrita tem de reproduzir, tela por tela: o que está lá existe, o que não está não existe' => '重写必须逐屏复现的视觉规格：存在的就存在，不存在的就不存在',
        'como ler a especificação (os textos entre aspas são os da tela, palavra por palavra; o estilo.css é a referência de cada medida)' => '如何阅读该规格（引号中的文本是界面上的，逐字相同；estilo.css 是每项尺寸的参考）',
        'o sistema visual, comum a todas as páginas, em partes: cores, letras, controles, componentes, layout (larguras e tamanhos de tela) e comportamento' => '视觉系统，所有页面共用，分部分：颜色、字体、控件、组件、布局（宽度和屏幕尺寸）和行为',
        'o nome curto da parte (cores, letras, controles, componentes, layout, comportamento)' => '部分的短名称（cores、letras、controles、componentes、layout、comportamento）',
        'uma regra do visual, com os valores exatos (cores em hexadecimal, tamanhos em px ou rem, os textos da tela)' => '一条视觉规则，带确切值（颜色为十六进制，尺寸为 px 或 rem，以及界面文本）',
        'o menu do topo' => '顶部菜单',
        'como o menu aparece no computador e no celular, e as páginas que não estão nele' => '在电脑和手机上菜单如何显示，以及不在菜单中的页面',
        'os itens do menu, na ordem da barra' => '菜单项，按栏中的顺序',
        'o arquivo da página (index.php, plano.php...)' => '页面文件（index.php、plano.php……）',
        'o texto do item no menu' => '菜单项的文本',
        'o grupo do menu em que o item fica (Rodízio, Coleção, Sistema, Conta); vazio: solto na barra' => '该项所在的菜单分组（轮换、收藏、系统、账户）；为空：单独位于栏中',
        'cada página do sistema, na ordem do menu e depois as que abrem do relógio' => '系统的每个页面，先按菜单顺序，然后是从手表打开的那些',
        'o nome curto da página (hoje, ficha, plano, configuracao, criterios, grupos, execucoes, historico, documentos, cadastros, usuarios, ajuda)' => '页面的短名称（hoje、ficha、plano、configuracao、criterios、grupos、execucoes、historico、documentos、cadastros、usuarios、ajuda）',
        'o arquivo da página' => '页面文件',
        'o título da página (o da aba do navegador)' => '页面标题（浏览器标签上的）',
        'o endereço, com os parâmetros que a página aceita' => '地址，含页面所接受的参数',
        'o que a página lê da API' => '页面从 API 读取什么',
        'o que a página grava pela API (o recurso e as ações); vazio: só lê' => '页面通过 API 写入什么（资源和操作）；空：只读',
        'as partes da página, de cima para baixo' => '页面的各部分，从上到下',
        'o nome da parte (e quando ela aparece)' => '部分的名称（以及它何时出现）',
        'o que a parte tem: cada tabela com as colunas, cada formulário com os campos (rótulo, tipo, padrão e limites), cada botão com o texto e o que ele manda para a API, e cada mensagem' => '该部分有什么：每个表格及其列、每个表单及其字段（标签、类型、默认值和限制）、每个按钮及其文本和它发给 API 的内容，以及每条消息',
        'os arquivos da página, lidos dela na hora (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega): o código de cada um em recurso=codigo&arquivo=<nome>' => '页面的文件，当场从它读取（pagina.php、estilo.css、页面本身以及它加载的脚本）：每一个的代码在 recurso=codigo&arquivo=<名称>',
        'as capturas de tela no repositório, para conferir o resultado' => '仓库中的界面截图，用于核对结果',
        'o caminho da imagem (docs/telas/...)' => '图像的路径（docs/telas/...）',
        'o que ela mostra' => '它显示什么',
        'a lista do código do sistema, como em recurso=codigo (sem o conteúdo: cada arquivo pelo recurso=codigo&arquivo=<nome>)' => '系统代码的清单，与 recurso=codigo 中相同（不含内容：每个文件通过 recurso=codigo&arquivo=<名称>）',
        'como pedir um arquivo, o arquivo puro, o HTML de uma página e todos de uma vez' => '如何请求一个文件、纯文件、一个页面的 HTML 以及一次全部',
