        'a data da última alteração do arquivo no servidor (AAAA-MM-DD HH:MM:SS)' => '文件在服务器上的最后修改日期（AAAA-MM-DD HH:MM:SS）',
        'o endereço deste arquivo na API, com o conteúdo, em JSON' => '此文件在 API 中的地址，含内容，JSON',
        'o endereço do arquivo puro, sem JSON (texto como text/plain; imagem como imagem)' => '纯文件的地址，无 JSON（文本为 text/plain；图像作为图像）',
        'só nas páginas: os arquivos que ela usa, na ordem (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega)' => '仅页面：它使用的文件，按顺序（pagina.php、estilo.css、页面本身以及它加载的脚本）',
        'só nas páginas: o endereço do HTML que o navegador recebe, puro' => '仅页面：浏览器收到的 HTML 的地址，纯文本',
