        'onde está o que a reescrita precisa saber dele' => '重写需要知道的关于它的内容在哪里',
        'o modelo de dados, lido do próprio banco em uso (o que vale agora, depois de todas as migrações)' => '数据模型，从正在使用的数据库本身读出（现在有效的，在全部迁移之后）',
        'o banco de onde o modelo foi lido: mysql, pgsql, sqlite ou firebird (os tipos das colunas vêm no dialeto dele)' => '模型所读取的数据库：mysql、pgsql、sqlite 或 firebird（列类型用它的方言）',
        'como ler as tabelas, e as três referências que ficam pelo nome, de propósito' => '如何阅读各表，以及故意按名称保留的三处引用',
