        'o que acontece ao apagar a linha de cima: CASCADE (some junto) ou SET NULL (a ligação se desfaz)' => '删除上面那一行时发生什么：CASCADE（一并消失）或 SET NULL（关联解除）',
        'cada chave única: a lista das colunas dela' => '每个唯一键：它的列的列表',
