        'quantos argumentos ela aceita ("2", "1 a 2", "3 ou mais")' => '它接受多少个参数（“2”、“1 到 2”、“3 个或更多”）',
        'o que ela devolve' => '它返回什么',
        'verdadeiro: lê os lançamentos do relógio (o primeiro argumento é um tipo de lançamento, entre aspas)' => '真：读取手表的记录（第一个参数是一个记录类型，放在引号里）',
        'os tipos de campo do cadastro' => '档案的字段类型',
