        'os formatos dos tipos de lançamento' => '记录类型的格式',
        'o que ele é' => '它是什么',
        'as repetições dos eventos personalizados' => '自定义事件的重复方式',
        'a repetição (uma, diaria, semanal, mensal, intervalo)' => '重复（uma、diaria、semanal、mensal、intervalo）',
        'como ela aparece na tela' => '它在界面上如何显示',
        'os dias da semana como o sistema numera' => '系统如何给星期几编号',
