        'com arquivo=: o SHA-256 do arquivo: para conferir a cópia, ou saber se mudou desde a última leitura' => '带 arquivo=：文件的 SHA-256：用于核对副本，或得知自上次读取以来是否改变',
        'com arquivo=: a data da última alteração do arquivo no servidor (AAAA-MM-DD HH:MM:SS)' => '带 arquivo=：文件在服务器上的最后修改日期（AAAA-MM-DD HH:MM:SS）',
        'com arquivo=: o endereço deste arquivo na API, com o conteúdo, em JSON' => '带 arquivo=：此文件在 API 中的地址，含内容，JSON',
