        'com arquivo=: só nas páginas: os arquivos que ela usa, na ordem (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega)' => '带 arquivo=：仅页面：它使用的文件，按顺序（pagina.php、estilo.css、页面本身以及它加载的脚本）',
        'com arquivo=: só nas páginas: o endereço do HTML que o navegador recebe, puro' => '带 arquivo=：仅页面：浏览器收到的 HTML 的地址，纯文本',
        'com arquivo=: o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => '带 arquivo=：文件的内容，按原样（文本）；仅在带 arquivo= 或 conteudo=1 时',
        'com arquivo=: o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => '带 arquivo=：图像的内容，base64；仅在带 arquivo= 或 conteudo=1 时',
        'com arquivo=: só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => '带 arquivo=：仅页面，且带 arquivo= 或 conteudo=1：浏览器收到的 HTML，已经组装好（带菜单的顶部、页面骨架和脚本）',
        'aparece quando a consulta usa filtros (incluir, excluir, f, busca, ordem, limite, pagina, mostrar)' => '当查询使用筛选时出现（incluir、excluir、f、busca、ordem、limite、pagina、mostrar）',
        'o que foi pedido e não existe (caminho sem lista, parte que não existe)' => '所请求但不存在的内容（没有列表的路径、不存在的部分）',
        'quantos itens a lista tinha' => '列表原来有多少项',
        'quantos vieram (a página)' => '返回了多少项（该页）',
        'o limite por página; null: sem' => '每页上限；null：没有',
        'quantos passaram nos filtros' => '有多少项通过了筛选',
        'o recurso (vazio: tudo)' => '资源（空：全部）',
        'a ação (escrita)' => '操作（写入）',
        'json (padrão) ou xml' => 'json（默认）或 xml',
        'o token da API (o pessoal, de Minha conta, ou o do servidor); também no cabeçalho X-Api-Token, ou o login do site (HTTP Basic) no lugar dele' => 'API 令牌（个人令牌，来自我的账户，或服务器令牌）；也可放在 X-Api-Token 请求头中，或用网站登录（HTTP Basic）代替',
        'o id da coleção do pedido (sem ele: o cookie colecao, senão a primeira que você vê); uma que você não vê: 404' => '请求所在收藏的 id（不传：colecao cookie，否则你看到的第一个）；你看不到的：404',
        '1: confirma uma exclusão (sem ele, a API só diz o que sai junto: 409)' => '1：确认删除（不传时，API 只说明会一并删除什么：409）',
        '(só o master) o login de outro usuário: o pedido vale como se fosse dele (a faixa Vendo como das páginas)' => '（仅限 master）另一个用户的登录名：请求如同由他发出（页面上的“以他人身份查看”横条）',
        'o idioma da resposta: pt-BR, en, zh-CN, hi, es ou fr' => '响应的语言：pt-BR、en、zh-CN、hi、es 或 fr',
        'pedido recusado: uma escrita que não passou nas validações ({ok: false, mensagem, erros: [...]}, um erro por motivo) ou uma fórmula mal escrita no recurso=calcular ({erro, erros})' => '请求被拒绝：一次未通过校验的写入（{ok: false, mensagem, erros: [...]}，每个原因一条错误）或 recurso=calcular 中书写错误的公式（{erro, erros}）',
        'recurso=entrar com o login certo e volta=<página>: vai para a página' => 'recurso=entrar 且登录正确并带 volta=<页面>：前往该页面',
        'sem o token nem o login do site, ou com eles errados; sem nenhum usuário (ou com o banco vazio), também sem_usuarios: true e como (o que fazer: instalar, criar o primeiro usuário pelo token)' => '没有 token 也没有网站登录，或它们不正确；没有任何用户时（或数据库为空），还有 sem_usuarios: true 以及怎么做（要做什么：安装、通过 token 创建第一个用户）',
        'a cópia de segurança e as migrações: só o master' => '备份和迁移：仅限 master',
        'recurso desconhecido (com recursos, a lista deles), ou a coleção que você não vê (colecao=), o relógio, a foto, o documento (ou o arquivo dele), o link ICS ou o README.md (recurso=manual) que não existe, ou um arquivo que não sai pelo recurso=codigo ({erro, e o_que_ver no que fica de fora de propósito, como o config.php, ou arquivos, os que saem)' => '未知资源（带 recursos，即资源列表），或你看不到的收藏（colecao=），或不存在的手表、照片、文档（或其文件）、ICS 链接或 README.md（recurso=manual），或不通过 recurso=codigo 输出的文件（{erro, 对于故意排除的内容如 config.php 带 o_que_ver，或带 arquivos，即可以输出的文件）',
        'uma exclusão sem confirmar=1 ({ok: false, confirmar: true, impacto: o que sai junto}: nada foi apagado); a conta sem coleção nenhuma (sem_colecao: true; só a conta responde); ou o banco recusou a gravação (um registro que outro ainda usa, um valor repetido, ou um valor fora das regras de validação do banco: o nome da regra, ck_<tabela>_<o quê>, vem no detalhe)' => '没有 confirmar=1 的删除（{ok: false, confirmar: true, impacto：一并删除的内容}：什么都没删）；没有任何收藏的账户（sem_colecao: true；只有账户会响应）；或数据库拒绝了保存（另一条记录仍在使用的记录、重复的值，或违反数据库校验规则的值：规则名 ck_<tabela>_<o quê> 在详情中给出）',
        'o envio passou do limite do PHP do servidor (post_max_size): um arquivo grande demais' => '上传超过了服务器 PHP 的上限（post_max_size）：文件太大',
        'sistema parado (token ou fuso inválido no config.php) ou erro interno' => '系统停止（config.php 中的 token 或时区无效）或内部错误',
        'banco desatualizado (só recurso=migracoes responde, e o recurso=manual e o recurso=codigo, que não usam o banco), banco vazio (antes da instalação só recurso=instalacao responde, e o manual e o código) ou banco fora do ar' => '数据库过期（只有 recurso=migracoes 会响应，以及不使用数据库的 recurso=manual 和 recurso=codigo），数据库为空（安装之前只有 recurso=instalacao 会响应，以及手册和代码）或数据库离线',
        'números com vírgula ou ponto; textos entre aspas; argumentos separados por ponto e vírgula; operações + - * / ^; comparações = <> < <= > >= (dão 1 ou 0); variáveis: os identificadores dos campos e das fórmulas; vazio se propaga; divisão por zero: vazio' => '数字可用逗号或点；文本放在引号里；参数用分号分隔；运算 + - * / ^；比较 = <> < <= > >=（结果为 1 或 0）；变量：字段和公式的标识符；空值会传递；除以零：空值',
    ],
    'reconstrucao' => [
        'quem vê todas as coleções de um dono, também as que ele criar depois, e desde quando' => '谁能看到某个所有者的全部收藏（包括他以后创建的），以及从何时起',
        'os acessórios de uma coleção: o nome, o tipo e a observação' => '收藏的配件：名称、类型和备注',
        'o relógio de que um acessório é (sem linha: solto)' => '配件所属的手表（没有行：未分配）',
        'as agendas de uma coleção: o tipo (google, caldav, outlook, ics), o nome, se está ativa, a janela em dias, o modelo do evento, o idioma e o evento de teste' => '收藏的日历：类型（google、caldav、outlook、ics）、名称、是否启用、以天为单位的时间窗口、事件模板、语言和测试事件',
        'o que uma agenda recebe: cada tipo de aviso, se envia' => '日历接收的内容：每种提醒类型，是否发送',
        'o CalDAV de uma agenda: o endereço do calendário, o usuário e a senha (cifrada)' => '日历的 CalDAV：日历地址、用户名和密码（加密）',
        'os eventos personalizados que uma agenda recebe' => '日历接收的自定义事件',
        'o Google Agenda de uma agenda: o id da agenda e a chave da conta de serviço (cifrada)' => '日历的 Google 日历：日历 id 和服务账户密钥（加密）',
        'o link ICS de uma agenda: o token secreto do link' => '日历的 ICS 链接：链接的秘密令牌',
        'o Outlook de uma agenda: a conta, o calendário e o token de renovação (cifrado)' => '日历的 Outlook：账户、日历和刷新令牌（加密）',
        'os eventos que o sistema criou em cada agenda: a chave (o que o evento é: o tipo, o relógio e o dia), o id no serviço, a data, o título e a assinatura (o resumo do conteúdo, para saber se mudou)' => '系统在每个日历中创建的事件：键（事件是什么：类型、手表和日期）、在服务中的 id、日期、标题和签名（内容摘要，用于判断是否有变化）',
        'os tokens de API de cada conta: o nome e o hash (o token só aparece ao criar), quando foi criado e o último uso' => '每个账户的 API 令牌：名称和哈希（令牌只在创建时出现）、创建时间和最后使用',
        'os avisos do cadastro: o identificador, o nome, a fórmula da data prevista (expressao), a condição (vale quando), a antecedência em dias, o texto, se está ativo, o grupo da versão, a escala, a simulação, se vai para a agenda, o tipo de lançamento que o resolve e se avisa na hora' => '定义中的提醒：标识符、名称、预计日期的公式（expressao）、条件（何时生效）、提前天数、文本、是否启用、版本所属分组、排班表、模拟、是否进入日历、解决它的记录类型以及是否准时提醒',
        'os campos do cadastro dos relógios, por árvore: o identificador (o nome nas fórmulas), o nome, o tipo, a unidade, o valor padrão, o grupo em que vale (a raiz: todos), a ordem e se vale só nos desejados' => '手表定义中的字段，按树：标识符（在公式中的名称）、名称、类型、单位、默认值、生效的分组（根：全部）、顺序以及是否只对心愿单手表生效',
        'as opções de um campo do tipo lista, em ordem (sem repetir, sem diferenciar maiúsculas e acentos)' => '列表类型字段的选项，按顺序（不重复，不区分大小写和重音）',
        'o valor de cada campo em cada relógio (texto normalizado pelo tipo do campo: número com ponto, data AAAA-MM-DD, sim/não 1 ou 0)' => '每块手表每个字段的值（按字段类型规范化的文本：数字用点，日期 AAAA-MM-DD，是/否为 1 或 0）',
        'as coleções: o dono, a raiz da árvore que ela usa (uma árvore do mesmo dono), o nome (sem repetir entre as do dono) e quando foi criada' => '收藏：所有者、它所用树的根（同一所有者的树）、名称（在该所有者的收藏间不重复）和创建时间',
        'os membros de uma coleção (o dono não entra aqui) e desde quando' => '收藏的成员（所有者不在此列）以及从何时起',
        'os valores soltos da Configuração de cada coleção (horários, limites, o idioma), chave e valor' => '每个收藏设置中的零散值（时间、限值、语言），键和值',
        'os convites para uma coleção ou para tudo de um dono (um ou outro): o e-mail, quem convidou, o estado (pendente: espera o dono; aprovado: enviado), o hash do token do link e até quando vale' => '对某个收藏或某个所有者全部内容的邀请（二者之一）：电子邮件、邀请人、状态（pendente：等待所有者；aprovado：已发送）、链接令牌的哈希以及有效期',
        'as faixas de um subparâmetro: de um número até outro (ou sem limite) ou uma categoria, e a nota (0 a 100) que o valor ganha nela' => '一个子参数的区间：从一个数字到另一个（或无上限）或一个类别，以及值在其中得到的分数（0 到 100）',
        'os parâmetros de um conjunto de critérios: o lugar (um grupo da árvore, a raiz para todos, ou um relógio: um ou outro), o nome, o peso (%) e a ordem' => '一组标准的参数：位置（树中的一个分组，根表示全部，或一只手表：二者之一）、名称、权重（%）和顺序',
        'os subparâmetros de um parâmetro: o nome, a variável que mede (um campo ou uma fórmula), o peso dentro do parâmetro (%) e a ordem' => '一个参数的子参数：名称、所度量的变量（一个字段或一条公式）、在参数内的权重（%）和顺序',
        'cada execução do cron que registrou algo: início, fim, duração, o registro do sistema em texto, se teve erro e se teve atividade' => '每次记录了内容的 cron 执行：开始、结束、时长、系统日志文本、是否出错以及是否有活动',
        'o registro de cada coleção numa execução do cron, se teve erro e se teve atividade' => '每个收藏在一次 cron 执行中的日志、是否出错以及是否有活动',
        'os destinos das mensagens de uma coleção: o tipo (webhook, email, webpush), o nome, se está ligado, a mensagem padrão e o idioma' => '收藏的消息推送目标：类型（webhook、email、webpush）、名称、是否启用、默认消息和语言',
        'o que um destino recebe: cada tipo de aviso (dia, vespera, o identificador de um aviso), se envia e o texto próprio' => '推送目标接收的内容：每种提醒类型（dia、vespera、某个提醒的标识符）、是否发送以及专用文本',
        'para quem vai o e-mail de um destino' => '推送目标的电子邮件发给谁',
        'os eventos personalizados que um destino recebe, com o texto próprio' => '推送目标接收的自定义事件，带专用文本',
        'o webhook de um destino: o método, o endereço, o formato (query, form, json) e o corpo JSON opcional' => '推送目标的 webhook：方法、地址、格式（query、form、json）和可选的 JSON 正文',
        'os cabeçalhos do pedido de um webhook (o valor cifrado: pode ter um token)' => 'webhook 请求的请求头（值加密：可能含令牌）',
        'os campos do pedido de um webhook, em ordem, com {titulo} e {mensagem} no valor' => 'webhook 请求的字段，按顺序，值中可含 {titulo} 和 {mensagem}',
        'o usuário cujos aparelhos recebem o Web Push de um destino' => '其设备接收推送目标 Web Push 的用户',
        'os documentos de cada relógio: a categoria, o título, a data, a descrição, o nome e o tipo do arquivo, o tamanho, o caminho na pasta (arquivo e miniatura), se a cópia no banco está completa e se o arquivo pede a cópia' => '每只手表的文档：分类、标题、日期、描述、文件名和类型、大小、文件夹中的路径（文件和缩略图）、数据库中的副本是否完整以及该文件是否要求副本',
        'as categorias dos documentos (Manual, Nota fiscal, Fotos...), por árvore: identificador, nome e ordem' => '文档分类（说明书、发票、照片……），按树：标识符、名称和顺序',
        'as famílias de arquivo que uma categoria aceita (imagem, video, audio, pdf, xml); nenhuma: qualquer arquivo' => '一个类别所接受的文件族（imagem、video、audio、pdf、xml）；一个都没有：任意文件',
        'a cópia de um documento dentro do banco, em pedaços de 4 MB (parte 0, 1, 2...; a parte -1 é a miniatura)' => '文档在数据库内的副本，以 4 MB 分块（部分 0、1、2……；部分 -1 是缩略图）',
        'os dias da semana de um evento personalizado semanal (1 segunda a 7 domingo)' => '每周自定义事件的星期几（1 周一到 7 周日）',
        'cada ocorrência de um evento personalizado que já disparou (para não disparar duas vezes)' => '已经触发过的自定义事件的每次发生（以免触发两次）',
        'os lembretes de uma coleção: nome, se está ativo, a repetição (uma vez, todo dia, em dias da semana, todo mês, a cada N dias), a data de início, a hora, o dia do mês e o intervalo' => '收藏的备忘：名称、是否启用、重复方式（一次、每天、每周某几天、每月、每 N 天）、开始日期、时间、每月第几天和间隔',
        'o relógio de um evento personalizado (sem linha: um evento geral)' => '自定义事件的手表（没有行：通用事件）',
        'as fórmulas do cadastro: o identificador (o nome nas outras fórmulas, nos avisos e nos critérios), o nome, a expressão, a unidade e o grupo da versão (a raiz: todos). A mesma fórmula pode ter uma versão por grupo; vale a do grupo mais perto do relógio' => '定义中的公式：标识符（在其他公式、提醒和标准中的名称）、名称、表达式、单位和版本所属分组（根：全部）。同一公式可以每个分组一个版本；以离手表最近的分组的版本为准',
        'a foto de cada relógio (a imagem inteira, o tipo e quando foi trocada)' => '每块手表的照片（完整图像、类型以及更换时间）',
        'o histórico de cada relógio: o tipo, o início (o instante, num instantâneo), o fim (numa sessão; vazio: aberta), o valor (numa leitura), a marcação da leitura de carga (uso ou repouso; vazio: vale o pulso registrado naquele instante) e a origem (manual, rodizio, importado)' => '每块手表的历史：类型、开始（瞬时记录的时刻）、结束（会话中；空：进行中）、值（读数中）、电量读数的标记（uso 或 repouso；空：以那一刻记录的佩戴状态为准）和来源（manual、rodizio、importado）',
        'os tipos de lançamento: identificador, nome, formato (instantâneo, com valor ou sessão), unidade, a hora em que a sessão esquecida fecha sozinha (fecha_as), o grupo, a ordem, se a sessão é exclusiva, se a leitura mede o gasto e a condição (vale quando)' => '记录类型：标识符、名称、格式（瞬时、带值或时段）、单位、被遗忘的时段自动结束的时间（fecha_as）、分组、顺序、时段是否独占、读数是否测量消耗以及条件（何时生效）',
        'cada medição do gasto: o lançamento (a leitura) que a fechou, se mede o uso ou o repouso, o gasto achado (% por dia), as duas leituras, o intervalo, as horas no pulso e fora, o peso (horas) e se entra na média' => '每次消耗测量：结束它的记录（读数）、测量的是使用还是静止、得到的消耗（每天 %）、两次读数、间隔、在手腕上和离开手腕的小时数、权重（小时）以及是否计入平均值',
        'os modos de rodízio de uma coleção: nome, o tipo (semana, semana_fds, dia_semana, aleatorio, escala ou personalizado), a forma de escolha, a ordem, o horizonte da escala inteligente (escala_dias; vazio: não é escala), as semanas à frente (1 a 8), o ciclo, o roteiro escrito à mão (só no personalizado) e a marca do modo em uso (1 no ativo, vazio nos outros)' => '一个收藏的轮换模式：名称、类型（semana、semana_fds、dia_semana、aleatorio、escala 或 personalizado）、选择方式、顺序、智能排班的范围（escala_dias；空：不是排班）、提前周数（1 到 8）、循环、手写脚本（仅自定义）和使用中模式的标记（激活的为 1，其他为空）',
        'os blocos de um modo: nome, de onde sortear (um grupo; a raiz: todos), um relógio por dia ou um para o bloco inteiro e a ordem' => '模式的区块：名称、从哪里抽签（一个分组；根：全部）、每天一只手表还是整个区块一只，以及顺序',
        'os dias da semana de um bloco (1 segunda a 7 domingo; um dia em um bloco só)' => '一个区块的星期几（1 周一到 7 周日；一天只属于一个区块）',
        'o relógio fixo de um bloco (sem linha: sorteia)' => '区块的固定手表（没有行：抽签）',
        'a árvore dos grupos: a raiz (sem pai) é a árvore inteira e guarda o dono; cada grupo aponta para o de cima; o nome e a ordem entre irmãos. Uma árvore serve a várias coleções do mesmo dono' => '分组树：根（没有父节点）就是整棵树并保存所有者；每个分组指向上一级；名称和同级之间的顺序。一棵树可供同一所有者的多个收藏使用',
        'os pedidos de acesso de uma conta a uma coleção ou a tudo de um dono (um ou outro), com o recado e até quando espera' => '某个账户对某个收藏或某个所有者全部内容（二者之一）的访问申请，带留言和等待截止时间',
        'o relógio de cada dia de uma coleção: o relógio, a origem (sorteio ou manual), a ação do dia (o que fazer antes de usar), o motivo da escolha e quando foi gravado' => '收藏每一天的手表：手表、来源（抽签或手动）、当天的动作（佩戴前要做什么）、选择原因和保存时间',
        'o bloco do modo que escolheu o relógio do dia (sem linha: escolhido à mão)' => '选出当天手表的模式区块（没有行：手动选择）',
        'os dias livres do plano de uma coleção: sem relógio e sem sorteio (nem a escala), para escolher à mão' => '收藏计划中的空闲日：没有手表也不抽签（排班表也不排），留待手动选择',
        'os aparelhos (navegadores) de cada conta inscritos no Web Push: o endereço, as chaves do navegador (p256dh, auth) e o nome do aparelho' => '每个账户订阅了 Web Push 的设备（浏览器）：地址、浏览器的密钥（p256dh、auth）和设备名称',
        'os relógios de uma coleção: nome, apelido (para distinguir dois iguais), grupo, se está disponível para o rodízio, a situação na coleção (posse), se pede a cópia no banco de todos os documentos e quando foi cadastrado' => '收藏的手表：名称、昵称（用于区分两只相同的手表）、分组、是否可参与轮换、在收藏中的状态（持有情况）、是否要求所有文档在数据库中保留副本以及登记时间',
        'os valores do sistema inteiro: as marcas do cron, da cópia de segurança, do aleatório, das migrações, o endereço do sistema, o idioma da instalação e os avisos de vencimento já mandados' => '整个系统的值：cron、备份、随机数、迁移的标记，系统地址，安装语言以及已发送的到期提醒',
        'as contas: o login, o e-mail (para recuperar a senha, os convites e os avisos da conta), o hash da senha (password_hash), o papel (master: cuida do sistema inteiro; comum), o idioma, quando vence (a conta de demonstração; vazio: oficial), se está bloqueada, quando foi criada e o último acesso' => '账户：登录名、电子邮件（用于找回密码、邀请和账户通知）、密码哈希（password_hash）、角色（master：管理整个系统；comum）、语言、到期时间（演示账户；空：正式）、是否被封禁、创建时间和最后访问',
        'os links de Esqueci a senha: o hash do token e até quando vale (2 horas)' => '“忘记密码”的链接：令牌哈希和有效期（2 小时）',
        'mysql (MySQL ou MariaDB, o padrão), pgsql (PostgreSQL), sqlite ou firebird (Firebird 3+)' => 'mysql（MySQL 或 MariaDB，默认）、pgsql（PostgreSQL）、sqlite 或 firebird（Firebird 3+）',
        'o servidor do banco (MySQL, PostgreSQL e Firebird; no Firebird, DB_NOME é o caminho do arquivo .fdb no servidor ou um apelido, e DB_HOST vazio abre o arquivo direto)' => '数据库服务器（MySQL、PostgreSQL 和 Firebird；在 Firebird 中，DB_NOME 是服务器上 .fdb 文件的路径或一个别名，DB_HOST 为空则直接打开文件）',
        'o arquivo do banco (SQLite), fora da pasta publicada' => '数据库文件（SQLite），位于已发布文件夹之外',
        'obrigatório, com pelo menos 10 caracteres: o token do servidor (vale como o master mais antigo); sem ele o sistema inteiro para (as páginas, a API e o cron dizem o motivo)' => '必填，至少 10 个字符：服务器令牌（等同于最早的 master）；没有它整个系统都会停止（页面、API 和 cron 会说明原因）',
        'opcional: a chave que cifra os segredos guardados no banco (as senhas do CalDAV, as chaves do Google, os tokens do Outlook, os cabeçalhos dos webhooks); sem ela, o API_TOKEN (trocar a chave perde os segredos guardados)' => '可选：加密数据库中保存的机密（CalDAV 密码、Google 密钥、Outlook 令牌、webhook 请求头）的密钥；没有它则用 API_TOKEN（更换密钥会丢失已保存的机密）',
        'o fuso horário do sistema e das datas gravadas (vazio: o do PHP); cada coleção (config fuso) e cada usuário (usuario.fuso) pode escolher o seu, e o pedido roda nele (lib.php fuso_definir; banco.php converte as datas com hora ao ler e ao gravar)' => '系统和已保存日期的时区（空：PHP 的）；每个收藏（config fuso）和每个用户（usuario.fuso）可以选择自己的，请求在其中运行（lib.php fuso_definir；banco.php 在读写时转换带时间的日期）',
        'opcional: false fecha o cadastro aberto (cadastro.php): só entra quem o master cria ou quem tem um convite; sem a linha, aberto' => '可选：false 关闭公开注册（cadastro.php）：只有 master 创建的人或持有邀请的人才能进入；没有这一行则开放',
        'opcional: os dias da conta de demonstração, a criada pelo cadastro aberto (padrão 30; 0: a conta já nasce oficial). Vencida, o cron a apaga com tudo' => '可选：演示账户（公开注册创建的账户）的天数（默认 30；0：账户一创建即为正式）。到期后由 cron 连同一切删除',
        'opcional: quantos dias um convite ou um pedido de acesso espera (padrão 7); depois, o cron apaga' => '可选：邀请或访问申请等待多少天（默认 7）；之后由 cron 删除',
        'o envio de e-mail (os destinos de e-mail, o Esqueci a senha, os convites, os avisos da conta): smtp ou mail (o mail() do PHP); o remetente (sem ele, o SMTP_USUARIO). Sem EMAIL_METODO e com SMTP_HOST, vale smtp' => '电子邮件发送（电子邮件推送目标、“忘记密码”、邀请、账户通知）：smtp 或 mail（PHP 的 mail()）；发件人（没有则用 SMTP_USUARIO）。没有 EMAIL_METODO 但有 SMTP_HOST 时，使用 smtp',
        'o servidor SMTP: o endereço, a porta (padrão 587, ou 465 com ssl), a segurança (tls: STARTTLS, o padrão; ssl: TLS desde o começo; nenhuma) e o login' => 'SMTP 服务器：地址、端口（默认 587，ssl 时 465）、安全方式（tls：STARTTLS，默认；ssl：从一开始就用 TLS；nenhuma）和登录',
        'opcional: guarda uma cópia de cada e-mail enviado na pasta Enviados (padrão Sent) da conta, por IMAP' => '可选：通过 IMAP 把每封已发送邮件的副本保存到账户的“已发送”文件夹（默认 Sent）',
        'opcional: só para o teste do e-mail conferir a caixa por POP3 (alguns provedores pedem o POP antes do SMTP)' => '可选：仅供邮件测试通过 POP3 检查邮箱（有些服务商要求先 POP 后 SMTP）',
        'o Web Push: o par de chaves VAPID em base64url (o master gera em Minha conta) e o assunto (mailto: ou o endereço do sistema)' => 'Web Push：base64url 格式的 VAPID 密钥对（master 在“我的账户”中生成）和主题（mailto: 或系统地址）',
        'o aplicativo registrado na Microsoft (Entra ID) para as agendas do Outlook; o endereço de retorno é api.php?recurso=outlook_retorno. Sem eles, o Outlook fica de fora (use o link ICS)' => '为 Outlook 日历在 Microsoft（Entra ID）注册的应用；回调地址是 api.php?recurso=outlook_retorno。没有它们，Outlook 就不可用（请用 ICS 链接）',
        'só para a migração v25: a API de mensagem antiga (Telegram) vira o primeiro destino webhook da coleção; MSG_TITULO continua sendo o título das mensagens' => '仅用于 v25 迁移：旧的消息 API（Telegram）成为收藏的第一个 webhook 推送目标；MSG_TITULO 仍是消息的标题',
        'a pasta dos arquivos dos documentos, fora da pasta publicada, com escrita para o PHP' => '文档文件的文件夹，位于已发布文件夹之外，PHP 可写',
        'a constante antiga da cópia dos documentos no banco para o servidor inteiro: não vale mais (a escolha é a chave documentos_copia da Configuração de cada coleção); o código só a lê para a Configuração avisar que ela ainda está no config.php' => '整个服务器文档数据库副本的旧常量：已不再生效（选择是每个收藏设置中的 documentos_copia 键）；代码只读取它以便设置页提示它仍在 config.php 中',
        'o maior documento aceito, em bytes (sem ele: 100 MB; 0 ou -1: sem limite do sistema)' => '接受的最大文档，以字节计（没有：100 MB；0 或 -1：系统无上限）',
        'opcional, para quem traduz: true faz a tradução que falta parar com erro (na API e no cron; nas telas, o texto aparece entre ⟦ ⟧ e o erro vai para o console)' => '可选，供翻译者使用：true 让缺少的翻译报错停止（在 API 和 cron 中；在界面上，文本显示在 ⟦ ⟧ 之间，错误写入控制台）',
        'opcional: false desliga a cópia de segurança (sem cópia automática, sem a escrita fazer e sem o quadro da Configuração); sem a linha, ligada' => '可选：false 关闭备份（没有自动备份、没有写入操作 fazer，设置中也没有该框）；没有这一行时为开启',
        'a cópia de segurança do banco: a pasta (fora da publicada; sem ela, não há cópia automática), quantas ficam (padrão 7) e se leva o conteúdo dos documentos guardado no banco' => '数据库备份：文件夹（在发布目录之外；没有它就没有自动备份）、保留多少份（默认 7）以及是否包含数据库中保存的文档内容',
        'só para importar o sistema anterior (importar.php)' => '仅用于导入旧系统（importar.php）',
        'só para testes: as fontes dos números aleatórios (RANDOM.ORG e ANU QRNG); trocadas, os sorteios pedem os números a um servidor de teste' => '仅用于测试：随机数来源（RANDOM.ORG 和 ANU QRNG）；换掉之后，抽签会向测试服务器请求数字',
        'só para testes: os endereços do Google e da Microsoft que as agendas usam; trocados, a sincronização conversa com um servidor de teste' => '仅用于测试：日历使用的 Google 和 Microsoft 地址；改掉后，同步会与测试服务器通信',
        'A interface que a reescrita tem de reproduzir, tela por tela: o visual (cores, letras, controles e componentes, com os valores exatos), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem, com cada tabela (as colunas), cada formulário (os campos com o rótulo, o tipo, o padrão e os limites), cada botão (o texto e o que ele manda para a API) e cada mensagem. Os textos entre aspas são os da tela, palavra por palavra. As capturas em docs/telas/ mostram o resultado; o estilo.css é a referência de cada medida. O código de cada página, como está agora, sai pelo recurso=codigo (os arquivos dela em codigo; o HTML que ela entrega ao navegador em recurso=codigo&arquivo=<página>&html=1&cru=1).' => '重写必须逐屏复现的界面：视觉（颜色、字体、控件和组件，带确切值）、菜单，以及每个页面的地址、它从 API 读取和写入什么、按顺序的各部分，含每个表格（列）、每个表单（字段及其标签、类型、默认值和限制）、每个按钮（文本以及它发给 API 的内容）和每条消息。引号中的文本是界面上的，逐字相同。docs/telas/ 中的截图显示结果；estilo.css 是每项尺寸的参考。每个页面现在的代码通过 recurso=codigo 输出（它的文件在 codigo 中；它交给浏览器的 HTML 在 recurso=codigo&arquivo=<页面>&html=1&cru=1）。',
        'Fundo da página: aço #e4e8ec. Bordas: aço escuro #c3cad2. Texto: tinta #1c2530 (também o fundo da barra do menu). Rótulos e notas: cinza #6b7684. Botões, links, aba ativa, barras de carga: safira #1f4f8f. O que fazer, recados e carga baixa: âmbar #a8661a. Fundo de cartões, quadros e tabelas: papel #fbfcfd.' => '页面背景：钢灰 #e4e8ec。边框：深钢灰 #c3cad2。文本：墨色 #1c2530（也是菜单栏的背景）。标签和说明：灰色 #6b7684。按钮、链接、活动标签、电量条：蓝宝石色 #1f4f8f。要做什么、提示和低电量：琥珀色 #a8661a。卡片、框和表格的背景：纸白 #fbfcfd。',
        'Etiquetas de estado (pílulas): em uso: fundo #e3f3e6, texto #1e6b2e, borda #a9d8b3. Em repouso e erro: fundo #fbe8e6, texto #9b2c22, borda #efb5ae. Indisponível e sem atividade: fundo #eef1f4, texto cinza, borda aço escuro. Atividade, "você" e "relógio de hoje": fundo #e6eef8, texto #1f4f8f, borda #b8cbe6. Numa sessão que não é o pulso (no sol, no winder, no carregador), outras sessões e carga: fundo #fff4e0, texto #8a5a00, borda #efd29a.' => '状态标签（胶囊）：使用中：背景 #e3f3e6，文本 #1e6b2e，边框 #a9d8b3。休息中和错误：背景 #fbe8e6，文本 #9b2c22，边框 #efb5ae。不可用和无活动：背景 #eef1f4，文本灰色，边框深钢灰。活动、“你”和“今天的手表”：背景 #e6eef8，文本 #1f4f8f，边框 #b8cbe6。非手腕的时段（在晒太阳、在上链盒、在充电器）、其他时段和电量：背景 #fff4e0，文本 #8a5a00，边框 #efd29a。',
        'Origem de um valor do cadastro: "informado" em azul (#e6eef8 / #1f4f8f / #b8cbe6), "padrão" em bege (#fbf1e3 / #8a5a00 / #ecd2a8), "vazio" sem etiqueta e com a linha em cinza.' => '档案中一个值的来源：“已填写”为蓝色（#e6eef8 / #1f4f8f / #b8cbe6），“默认”为米色（#fbf1e3 / #8a5a00 / #ecd2a8），“空”无标签且该行为灰色。',
        'Atrasado (um prazo vencido, "faltam" e "passa" das somas): texto #9b2c22 em negrito. Caixa de erros de gravação: fundo #fdf0ee, borda #e3b4ae, texto #7a2419, cantos 10px. Linha de execução com erro: fundo #fdf2f1.' => '逾期（一个已到期的期限，合计中的“还差”和“超过”）：文本 #9b2c22 粗体。保存错误框：背景 #fdf0ee，边框 #e3b4ae，文本 #7a2419，圆角 10px。有错误的执行行：背景 #fdf2f1。',
        'Letras e números' => '字体和数字',
        'Fonte: "Segoe UI", "Helvetica Neue", Arial, sans-serif, 16px, entrelinha 1,5.' => '字体："Segoe UI", "Helvetica Neue", Arial, sans-serif，16px，行高 1.5。',
        'Título da página (h1): grande, de 2rem a 3,4rem conforme a largura (clamp(2rem, 6vw, 3.4rem)), negrito 700, espaçamento -0,02em, entrelinha 1,05. Título de seção (h2): 1,1rem. Notas e explicações: 0,92rem, cinza. Título dos quadros do painel do relógio: 0,78rem, maiúsculas, negrito, espaçado 0,06em, cinza, com uma linha embaixo. Números em tabelas e valores com algarismos de largura igual (tabular).' => '页面标题（h1）：大，按宽度从 2rem 到 3.4rem（clamp(2rem, 6vw, 3.4rem)），粗体 700，字距 -0.02em，行高 1.05。节标题（h2）：1.1rem。说明和解释：0.92rem，灰色。手表面板各框的标题：0.78rem，大写，粗体，字距 0.06em，灰色，下方有一条线。表格中的数字和等宽数字的值（tabular）。',
        'Formatos: data DD/MM/AAAA (curta: DD/MM); hora HH:MM; números com vírgula e sem zeros sobrando (1 casa por padrão); dinheiro "R$ 1.234,56"; porcentagem "12,5%"; duração pelas duas maiores partes: "1a 5m", "5d 3h", "12h 22min", "40min", "menos de 1min"; dia da semana curto: seg, ter, qua, qui, sex, sáb, dom.' => '格式：日期 DD/MM/AAAA（短：DD/MM）；时间 HH:MM；数字用逗号且不保留多余的零（默认 1 位小数）；金额“R$ 1.234,56”；百分比“12,5%”；时长取最大的两部分：“1a 5m”、“5d 3h”、“12h 22min”、“40min”、“不足 1min”；星期几短写：seg、ter、qua、qui、sex、sáb、dom。',
        'Campos, listas e botões' => '字段、列表和按钮',
        'Uma altura só para campo, lista e botão: 2,4rem, para ficarem alinhados lado a lado. Cantos 8px; campo e lista com borda 1px aço escuro e fundo branco; textarea com a mesma borda. Foco visível: contorno 2px safira afastado 2px. Campo numérico curto: 5,5rem. Números digitados aceitam vírgula ou ponto (teclado decimal no celular). No celular, os campos têm letra de 16px (o iPhone não aproxima a tela).' => '字段、列表和按钮同一高度：2.4rem，以便并排对齐。圆角 8px；字段和列表边框 1px 深钢灰、背景白色；textarea 同样的边框。可见焦点：2px 蓝宝石色轮廓，偏移 2px。短数字字段：5.5rem。输入的数字接受逗号或点（手机上为小数键盘）。在手机上，字段字号为 16px（iPhone 不会放大页面）。',
        'Botão principal: fundo safira, texto branco, borda safira, preenchimento 0,3rem 1rem. Botão "leve": fundo transparente, texto e borda safira (as ações secundárias). Botão "discreto": sem borda, 0,85rem, preenchimento lateral 0,45rem (↑, ↓ e Excluir das linhas). O Excluir das ações de linha é vermelho: texto #9b2c22, borda #efb5ae, fundo #fbe8e6 ao passar o mouse.' => '主按钮：背景蓝宝石色，文本白色，边框蓝宝石色，内边距 0.3rem 1rem。“浅色”按钮：背景透明，文本和边框蓝宝石色（次要操作）。“低调”按钮：无边框，0.85rem，左右内边距 0.45rem（行内的 ↑、↓ 和删除）。行操作中的删除为红色：文本 #9b2c22，边框 #efb5ae，悬停时背景 #fbe8e6。',
        'Caixa de marcar (checkbox) sempre à esquerda do texto, na mesma linha. Rótulo de campo: acima do campo nas grades de formulário; à esquerda na Configuração (veja os componentes). Botões desativados durante o envio de um formulário.' => '复选框始终在文本左侧，同一行。字段标签：在表单网格中位于字段上方；在设置中位于左侧（见各组件）。表单发送期间按钮禁用。',
        'Barra do menu: fundo tinta, links #b9c3ce sem sublinhado; o da página atual em branco com uma linha branca de 2px embaixo.' => '菜单栏：背景墨色，链接 #b9c3ce 无下划线；当前页面的为白色，下方有 2px 白线。',
        'Cartão (as seções das páginas de cadastro): fundo papel, borda 1px aço escuro, cantos 12px, preenchimento 1rem, título h2 em cima.' => '卡片（档案页面的各节）：背景纸白，边框 1px 深钢灰，圆角 12px，内边距 1rem，上方为 h2 标题。',
        'Quadro (o painel do relógio): igual ao cartão (cantos 12px, preenchimento 0,85rem 1rem), com o título em maiúsculas pequenas, o corpo, e um rodapé opcional (linha em cima, botões à direita, alinhados no pé: os quadros da mesma linha da grade têm a mesma altura). Quadro "largo" ocupa a linha inteira da grade.' => '框（手表面板）：与卡片相同（圆角 12px，内边距 0.85rem 1rem），标题为小型大写，有正文，以及可选页脚（上方一条线，按钮在右侧，对齐到底部：网格同一行的框高度相同）。“宽”框占网格的整行。',
        'Pares (rótulo e valor): duas colunas, o rótulo em cinza 0,85rem à esquerda (até 55% da largura), o valor à direita; uma linha fina aço entre os pares (a última sem); um texto menor (0,78rem, cinza) embaixo do valor é a explicação dele; rótulo vazio continua a linha de cima.' => '成对（标签和值）：两列，标签在左侧为灰色 0.85rem（最多占宽度的 55%），值在右侧；成对之间有一条细钢灰线（最后一对没有）；值下方更小的文本（0.78rem，灰色）是它的说明；空标签延续上一行。',
        'Tabela: fundo papel, cantos 10px, cabeçalho em cinza 0,9rem negrito, células com preenchimento 0,55rem 0,75rem e uma linha aço embaixo. Linha clicável: o fundo muda para #f1f4f8 ao passar e fica #e3eaf5 quando selecionada; fim de semana em #f4f6f8; o relógio de hoje com uma faixa safira de 3px na borda esquerda, e um com aviso pendente com a faixa âmbar. Tabela compacta (dos cadastros): 0,88rem, sem fundo próprio.' => '表格：背景纸白，圆角 10px，表头灰色 0.9rem 粗体，单元格内边距 0.55rem 0.75rem，下方一条钢灰线。可点击的行：悬停时背景变为 #f1f4f8，选中时为 #e3eaf5；周末为 #f4f6f8；今天的手表在左边框有 3px 蓝宝石色条，有待处理提醒的为琥珀色条。紧凑表格（定义中的）：0.88rem，无自身背景。',
        'Etiqueta de estado: pílula com cantos arredondados por inteiro, 0,8rem negrito, preenchimento 0,12rem 0,55rem, cores em "cores". Numa linha só; nos pares rótulo/valor (o quadro Agora do painel estreito) e nas marcas da cabeça, a comprida ("Em repouso desde 25/09 20:40") quebra a linha nos espaços (nunca no meio da palavra), com cantos de 0,8rem, e fica dentro do quadro.' => '状态标签：完全圆角的胶囊，0.8rem 粗体，内边距 0.12rem 0.55rem，颜色见“颜色”。单行；在标签/值成对中（窄面板的现在框）以及头部的标记里，较长的（“休息中，自 25/09 20:40”）在空格处换行（绝不在词中间断开），圆角 0.8rem，并留在框内。',
        'Barra de carga: trilho aço com 7px de altura (44px na tabela, 56 a 70px nos quadros), preenchido em safira até a porcentagem (âmbar com carga até 20%), seguido do número em negrito ("68%"; estimado: "~68%") e, menor, de onde a carga vem.' => '电量条：钢灰轨道高 7px（表格中 44px，框中 56 到 70px），按百分比填充蓝宝石色（电量到 20% 为止为琥珀色），随后是粗体数字（“68%”；估计值：“~68%”），以及更小的电量来源。',
        'Janela de data (o "só hoje" / "até sexta, 02/10" do relógio do dia): caixa branca, borda 2px tinta, cantos 3px, negrito, sombra interna fina, como a janela de data de um mostrador.' => '日期窗（当天手表的“只有今天”/“直到周五，02/10”）：白底盒子，边框 2px 墨色，圆角 3px，粗体，细内阴影，像表盘上的日期窗。',
        'Recado (o resultado de uma gravação): um parágrafo âmbar em negrito no topo da área (ou do painel do relógio). Erros de gravação: a caixa vermelha clara com "Não foi salvo:" e um parágrafo por erro, no topo da página.' => '提示（一次保存的结果）：区域内（或手表面板内）顶部的一段琥珀色粗体。保存错误：浅红色盒子，带“未保存：”以及每个错误一段，位于页面顶部。',
        'Abas (Cadastros e Documentos): links lado a lado com borda aço e cantos 0,4rem, preenchimento 0,35rem 0,8rem, texto safira; a ativa com fundo safira e texto branco.' => '标签页（定义和文档）：链接并排，边框钢灰、圆角 0.4rem、内边距 0.35rem 0.8rem、文本蓝宝石色；活动的背景蓝宝石色、文本白色。',
        'Grade de formulário (form-grade): colunas de no mínimo 14rem lado a lado, o rótulo acima de cada campo; textareas, grupos de caixas e botões na linha inteira. Linha de inclusão: campos com o rótulo em cima, lado a lado, separados do resto por uma linha tracejada acima.' => '表单网格（form-grade）：最少 14rem 的列并排，每个字段上方有标签；textarea、复选框组和按钮占整行。添加行：字段标签在上方，并排，与其余部分以上方一条虚线分隔。',
        'Barra de salvar (Configuração): presa no pé da tela enquanto a página rola (sticky), fundo papel quase opaco, borda, cantos 12px, sombra para cima; à esquerda "As mudanças desta página valem depois de salvar.", à direita o botão.' => '保存栏（设置）：页面滚动时固定在屏幕底部（sticky），背景几乎不透明的纸白，有边框，圆角 12px，向上的阴影；左侧“本页的更改在保存后生效。”，右侧是按钮。',
        'Sem foto: quadrado tracejado (2px aço escuro, cantos 14px) com "Sem foto" em cinza no meio. Foto: quadrada (recortada), cantos 14px, borda aço escuro. Miniatura na tabela: 28px (36px no celular), cantos 5px.' => '无照片：虚线方块（2px 深钢灰，圆角 14px），中间灰色“无照片”。照片：正方形（裁切），圆角 14px，边框深钢灰。表格中的缩略图：28px（手机上 36px），圆角 5px。',
        'Ações de uma linha (Editar, ↑, ↓, Excluir): numa linha só, à direita da linha da tabela.' => '一行的操作（编辑、↑、↓、删除）：单行，位于表格行的右侧。',
        'Resumo em números (Execuções e Histórico): uma grade de caixinhas (4 colunas; 2 no celular), cada uma com o número grande (1,4rem) e o que ele é embaixo em cinza; a de erros com fundo vermelho claro.' => '数字摘要（执行和历史）：一格小盒子的网格（4 列；手机上 2 列），每个有大号数字（1.4rem）以及下方灰色的含义；错误的那个背景浅红。',
        'Larguras e tamanhos de tela' => '宽度和屏幕尺寸',
        'Conteúdo centrado com margens de 1,25rem: largura máxima 56rem nas páginas comuns (Plano, Usuários), 72rem na Ficha, 76rem na Configuração, Cadastros, Critérios, Grupos, Execuções e Histórico, 60rem na Ajuda. A página Hoje usa a largura toda.' => '内容居中，边距 1.25rem：普通页面最大宽度 56rem（计划、用户），详情 72rem，设置、定义、标准、分组、执行和历史 76rem，帮助 60rem。今天页面使用全部宽度。',
        'Página Hoje: duas colunas, o meio e o painel do relógio com 22rem à direita, preso ao rolar (sticky) e com rolagem própria; sem relógio aberto, o meio ocupa tudo. Com a Configuração "Numa janela flutuante, grande": o relógio abre no meio da tela, até 78rem ou 94% da largura, de 3% do alto a 3% de baixo, cantos 16px, sombra forte, com o fundo escurecido (rgba(16, 22, 29, .55)) e os quadros lado a lado; fecha no ×, no Esc ou num clique no fundo.' => '今天页面：两列，中间以及右侧 22rem 的手表面板，滚动时固定（sticky）并有自己的滚动；没有打开的手表时，中间占满。设置设为“在大的浮动窗口中”时：手表在屏幕中央打开，最大 78rem 或宽度的 94%，从顶部 3% 到底部 3%，圆角 16px，强阴影，背景变暗（rgba(16, 22, 29, .55)），各框并排；用 ×、Esc 或点击背景关闭。',
        'Até 900px (celular e tablet de pé): o menu recolhido; as tabelas viram fichas (cada linha numa caixa com borda e cantos de 8px: a primeira célula é a cabeça, em fundo aço, e cada outra tem o título da coluna numa casa cinza-clara à esquerda, de 36%, separada por um traço) ou cartões; o painel do relógio cobre a tela inteira, com o botão "× Fechar" preso no alto, e o voltar do aparelho fecha o painel; as grades viram uma coluna. De 901 a 1199px (tablet deitado): o painel "ao lado" desliza por cima, pela direita, com até 30rem, cantos 16px à esquerda e o fundo escurecido. De 1200px em diante: o painel ao lado.' => '到 900px（手机和竖屏平板）：菜单收起；表格变成卡片（每一行在一个带边框、圆角 8px 的框里：第一个单元格是表头，钢灰底色，其余每个单元格左侧有一个浅灰色格子写着列标题，宽 36%，用一条线隔开）或卡片；手表面板盖住整个屏幕，顶部固定“× 关闭”按钮，设备的返回也会关闭面板；网格变成一列。901 到 1199px（横屏平板）：“在旁边”的面板从右侧滑出盖住，最大 30rem，左侧圆角 16px，背景变暗。1200px 起：面板在旁边。',
        'Nenhuma página rola de lado, em nenhum tamanho. A mesma informação em todos os tamanhos: nada é escondido por falta de espaço (a tabela dos relógios vira cartões com todos os campos quando as 12 colunas não cabem).' => '任何页面在任何尺寸下都不横向滚动。所有尺寸上信息相同：不因空间不足而隐藏任何内容（手表表在 12 列放不下时变成带全部字段的卡片）。',
        'As tabelas de um quadro se arrumam pela largura do quadro (container queries), não pela da tela: o mesmo quadro é estreito no painel ao lado e largo na ficha. Até 40rem, as Medições do gasto viram cartões; até 26rem, as tabelas dos Dados do relógio ficam mais justas e o valor quebra a linha.' => '一个框里的表格按框的宽度排列（container queries），而不是按屏幕宽度：同一个框在旁边的面板里是窄的，在详情里是宽的。到 40rem，消耗测量变成卡片；到 26rem，手表数据的表格更紧凑，值会换行。',
        'Nada sai da caixa em que está, de 320px (celular pequeno) a 1920px: as grades de colunas automáticas encolhem a coluna mínima até a largura da tela; um grupo de campos (fieldset) e os menus dentro dele encolhem com a tela (um menu de nome comprido não vaza); o menu de escolher o relógio da Ficha fica na largura da tela; o código comprido da Ajuda (uma URL de exemplo) quebra a linha. Os botões nunca partem o texto em duas linhas: os da foto (Abrir, Trocar, Remover foto) ficam numa linha, na largura da foto (6,5rem no painel ao lado e no celular); o botão de marcar do quadro Marcar fica numa linha própria, embaixo dos campos. Até 420px, as tabelas do painel e o resumo do Plano ficam mais justas (0,82rem, 0,3rem entre as colunas) e quebram dentro da célula. No Histórico do celular, as colunas são 25%, 25%, 18% e 32% (o Estado, a mais larga).' => '从 320px（小手机）到 1920px，没有任何东西溢出它所在的盒子：自动列网格会把最小列宽缩到屏幕宽度；一组字段（fieldset）以及其中的菜单随屏幕缩小（名称很长的菜单不会溢出）；详情中选择手表的菜单保持在屏幕宽度内；帮助中很长的代码（一条示例 URL）会换行。按钮从不把文本拆成两行：照片的按钮（打开、更换、移除照片）在一行内，宽度为照片的宽度（旁边的面板和手机上为 6.5rem）；标记框的标记按钮单独占一行，在字段下方。到 420px，面板的表格和计划的摘要更紧凑（0.82rem，列间距 0.3rem）并在单元格内换行。在手机的历史中，列宽为 25%、25%、18% 和 32%（状态，最宽的一列）。',
        'Comportamento comum' => '共同行为',
        'Cada página entrega só o esqueleto; o JavaScript dela lê a API e monta a tela. Gravar é um formulário que manda um POST para a API (recurso e acao nos campos); depois a página se remonta com os dados novos, sem recarregar, e mostra a mensagem da API no topo (ou no painel do relógio, se a gravação era dele).' => '每个页面只交付骨架；它的 JavaScript 读取 API 并组装界面。保存是一个向 API 发送 POST 的表单（字段中带 recurso 和 acao）；然后页面用新数据重新组装，不重新加载，并把 API 的消息显示在顶部（若保存属于手表面板，则显示在面板中）。',
        'Antes de toda exclusão e de toda ação que refaz o plano, uma confirmação do navegador com o texto do que vai acontecer (os textos estão em cada página). Durante o envio os botões do formulário ficam desativados; se a conexão falhar: "Não consegui gravar: <motivo>. Confira a conexão e tente de novo."' => '在每次删除以及每次会重做计划的操作之前，浏览器确认框说明将要发生的事（文本在每个页面中）。发送期间表单按钮禁用；若连接失败：“无法保存：<原因>。请检查连接并再试一次。”',
        'Sem login, nada da página sai: o topo() confere o usuário e a senha no servidor (pagina_login(), no lib.php) antes da primeira linha e responde 401 com o pedido de senha do navegador (realm "Relogios", o mesmo da API); cancelado, só a página mínima "Entrar" com "Tentar de novo" e "Criar conta". Passam sem login só a Criar conta e, sem nenhum usuário (ou com o banco vazio ou fora do ar), as páginas, que não têm dado nenhum. Se o login cair com a página aberta, a API responde 401 e a página manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e volta. Banco desatualizado (503 com pendentes): a página vai para a Configuração, que mostra só o aviso e o "Aplicar agora". Erro ao ler: "Não consegui ler <o quê>: <motivo>" em âmbar, no lugar da página.' => '未登录时，页面的任何内容都不会输出：topo() 在输出第一行之前就在服务器上检查用户和密码（lib.php 中的 pagina_login()），未通过则以 401 回应并弹出浏览器的密码框（realm "Relogios"，与 API 相同）；如果取消，只显示最简的“登录”页面，带“重试”和“创建账户”。只有“创建账户”，以及在还没有任何用户（或数据库为空或无法连接）时的页面无需登录，这些页面没有任何数据。如果页面打开后登录失效，API 返回 401，页面转到 api.php?recurso=entrar&volta=<该页面>，浏览器要求输入用户和密码然后返回。数据库过期（503 且有待处理项）：页面转到设置，那里只显示提醒和“立即应用”。读取出错：“无法读取<是什么>：<原因>”，琥珀色，出现在页面的位置。',
        'Fotos reduzidas no navegador antes de enviar: no máximo 1200px no lado maior, JPEG 85%, com a prévia na tela; imagem que não abre: alerta "Não consegui abrir essa imagem. Use JPEG ou PNG.".' => '照片在发送前于浏览器中缩小：长边最大 1200px，JPEG 85%，并在屏幕上预览；打不开的图像：警报“无法打开这张图像。请使用 JPEG 或 PNG。”',
        'A foto do relógio ampliada, só no detalhe do relógio (o painel, ou a ficha): duplo clique na foto (o cursor é a lupa de ampliar) ou o botão "Abrir foto" embaixo dela abre por cima de tudo uma janela flutuante (nas outras fotos, como a do "Hoje é dia de" e as miniaturas da lista, o clique abre o relógio e o duplo clique não faz nada a mais): fundo rgba(10,14,20,.82) na tela inteira, a foto no meio, no tamanho dela (os pixels da imagem em px da página), cantos 6px, fundo branco e sombra; maior que a área que se vê, em escala, sem deformar: a escala é o menor entre 1, (largura − 32px) ÷ a largura da foto e (altura − 72px) ÷ a altura da foto, com a largura e a altura sendo o menor entre o monitor (screen.availWidth/availHeight) e a janela do navegador; refeita quando a janela muda de tamanho ou de monitor. Embaixo, em branco, "<nome> · <largura> × <altura> px" e, em escala, "(mostrada a N%)". Um botão redondo "×" (branco, 2,4rem) no canto de cima, à direita. Fecha com o ×, com um clique fora da foto ou com Esc (o Esc fecha só a foto: o painel por baixo continua aberto); enquanto aberta, a página não rola.' => '手表照片的放大，仅在手表详情中（面板或详情页）：双击照片（光标是放大镜）或它下方的“打开照片”按钮，会在一切之上打开一个浮动窗口（其他照片，如“今天轮到”的照片和列表缩略图，单击打开手表，双击没有额外作用）：整个屏幕背景 rgba(10,14,20,.82)，照片在中间，按其尺寸（图像像素对应页面的 px），圆角 6px，白底和阴影；大于可见区域时按比例缩放、不变形：比例是 1、(宽度 − 32px) ÷ 照片宽度、(高度 − 72px) ÷ 照片高度三者中的最小者，宽度和高度取显示器（screen.availWidth/availHeight）与浏览器窗口中的较小者；窗口改变大小或更换显示器时重算。下方，白色，“<名称> · <宽度> × <高度> px”，以及在缩放时“（显示为 N%）”。一个圆形按钮“×”（白色，2.4rem）在右上角。用 ×、点击照片外部或 Esc 关闭（Esc 只关闭照片：下面的面板保持打开）；打开期间页面不滚动。',
        'O título da aba do navegador é o título da página ("Relógio de hoje", "Plano", "Configuração", "Critérios de escolha", "Grupos de relógios", "Execuções do cron", "Usuários", "Cadastros", "Ajuda", "Ficha do relógio", "Documentos", "Desejos", "Estatísticas", "Hora certa", "Acessórios", "Galeria", "Passaporte do relógio" ("Passaporte — <relógio>" depois de ler); no histórico, "Histórico — <relógio>").' => '浏览器标签的标题是页面标题（“今天的手表”、“计划”、“设置”、“选择标准”、“手表分组”、“cron 执行”、“用户”、“定义”、“帮助”、“手表详情”、“文档”、“心愿单”、“统计”、“准确时间”、“配件”、“图库”、“手表护照”（读取后为“护照 — <手表>”）；在历史中为“历史 — <手表>”）。',
        'O navegador de páginas (Próximos dias, Dia a dia do Plano, Rodízio manual): botões leves pequenos (padding .3rem .65rem, letra .9rem) numa linha que quebra: "<" (dica "Anterior"; desativado na primeira), os números (a 1, a última e até 2 de cada lado da atual, com "…" sem borda nos saltos; dica "Página N"; a atual em safira com letra branca, sem ser botão) e ">" (dica "Próximo"; desativado na última). Uma página só: sem navegador. Cada botão relê a API com a página.' => '页面浏览器（接下来的日子、计划的逐日、手动轮换）：一行可换行的浅色小按钮（padding .3rem .65rem，字号 .9rem）：“<”（提示“上一页”；第一页禁用）、数字（第 1 页、最后一页以及当前页两侧最多 2 页，跳跃处为无边框的“…”；提示“第 N 页”；当前页为蓝宝石色白字，不是按钮）和“>”（提示“下一页”；最后一页禁用）。只有一页：没有浏览器。每个按钮用该页重新读取 API。',
        'Na barra escura do topo, em todas as páginas, nessa ordem: Hoje, Avisos e Hora certa soltos; os grupos Rodízio, Coleção, Sistema e Conta; e a Ajuda. No computador, cada grupo é um botão com "▾" que abre embaixo dele uma caixa escura com as páginas do grupo, uma por linha (abre uma de cada vez; fecha num clique fora ou no Esc); o grupo da página atual e a página atual em branco e sublinhados. A Ficha, o Histórico, os Documentos, os Destinos e as Agendas não estão no menu: os três primeiros abrem do painel do relógio (o histórico e os documentos numa aba nova), os Destinos e as Agendas da página Avisos. No celular (até 900px): a barra, presa no alto ao rolar, mostra o nome da página atual à esquerda e o botão "☰ Menu" à direita; aberto, ele vira "✕ Menu" e os itens aparecem em duas colunas, cada um num botão escuro (#27323f), o atual em safira; os grupos ficam abertos, com o nome do grupo em letras pequenas maiúsculas em cima das páginas dele, e os itens soltos depois de um grupo ocupam a linha inteira. Depois do último item, o seletor do idioma: uma caixa pequena com o código curto de cada idioma (PT, EN, 中文, हिं, ES, FR; o nome inteiro na dica); escolher grava o cookie lingua (um ano, o caminho todo), apaga o cookie lingua_auto e abre a página de novo nele; sem escolha, o api.js grava o cookie lingua sozinho com o padrão (o idioma_padrao de recurso=conta&parte=menu, lido a cada página: o do script do dicionário fica em cache) e marca lingua_auto com o mesmo valor, e enquanto os dois forem iguais a página segue o padrão quando ele muda; gravar outro idioma na Configuração (o padrão da coleção) ou em Minha conta (o da conta) vale como escolher no seletor: grava o cookie lingua com ele, apaga lingua_auto (em "O da coleção", apaga os dois) e abre a página de novo nele. Os rótulos abaixo são os do português: em outro idioma, as traduções do dicionário das telas. À direita, antes do idioma, o que é de quem entrou (recurso=conta, parte=menu): com mais de uma coleção, o seletor da coleção (grava o cookie colecao e abre a página de novo; o nome, e "· <dono>" nas dos outros); "Aprovações (N)" em âmbar quando há pedidos ou convites esperando; "Demo: N dias" em âmbar na conta de demonstração. O Usuários só aparece para o master. O master vendo como outro usuário: uma faixa âmbar acima de tudo, "Vendo como <login>: o que aparece e o que se grava é da conta dele." e o botão "Voltar a ser <master>". A conta sem coleção nenhuma (409 sem_colecao) vai para Minha conta. A página pública (cadastro.php) não tem menu, só o idioma.' => '位于顶部的深色栏中，出现在所有页面，按此顺序：单独的“今天”“提醒”和“准确时间”；“轮换”“收藏”“系统”“账户”四个分组；以及“帮助”。在电脑上，每个分组是一个带“▾”的按钮，点击后在其下方打开一个深色框，列出该组的页面，每行一个（一次只打开一个；点击外部或按 Esc 关闭）；当前页面所在的分组和当前页面为白色并带下划线。档案、历史、文档、推送目标和日历不在菜单中：前三个从手表面板打开（历史和文档在新标签页中），推送目标和日历从“提醒”页面打开。在手机上（最多 900px）：该栏滚动时固定在顶部，左侧显示当前页面名称，右侧是“☰ Menu”按钮；展开后变为“✕ Menu”，各项分两列显示，每项是一个深色按钮（#27323f），当前项为蓝宝石色；分组保持展开，组名以小号大写字母显示在其页面上方，分组之后的单独项占满整行。最后一项之后是语言选择器：一个小框，显示每种语言的简码（PT、EN、中文、हिं、ES、FR；完整名称在提示中）；选择后保存 lingua cookie（一年，整个路径）、删除 lingua_auto cookie 并以该语言重新打开页面；未做选择时，api.js 自行用默认语言（recurso=conta&parte=menu 的 idioma_padrao，每个页面都会读取：词典脚本里的那个会被缓存）写入 lingua cookie 并以相同的值标记 lingua_auto，只要两者相同，页面就会在默认语言改变时跟随它；在设置中（收藏的默认语言）或在我的账户中（账户的语言）保存另一种语言相当于在选择器中选择：把 lingua cookie 写为该语言、删除 lingua_auto（选“收藏的”时删除两者）并以该语言重新打开页面。下面的标签是葡萄牙语的：在其他语言中使用界面词典的翻译。右侧、语言之前，是登录者自己的内容（recurso=conta，parte=menu）：有多个收藏时显示收藏选择器（保存 colecao cookie 并重新打开页面；显示名称，他人的收藏后加“· <dono>”）；有申请或邀请等待时显示琥珀色的“审批（N）”；演示账户显示琥珀色的“演示：N 天”。“用户”只对 master 显示。master 以其他用户身份查看时：最上方有一条琥珀色横条，“正在以 <login> 的身份查看：显示和保存的都是该账户的数据。”以及“切换回 <master>”按钮。没有任何收藏的账户（409 sem_colecao）会转到“我的账户”。公开页面（cadastro.php）没有菜单，只有语言。',
        'Avisos' => '提醒',
        'Hora certa' => '准确时间',
        'Rodízio' => '轮换',
        'Modos de rodízio' => '轮换模式',
        'Critérios de escolha' => '选择规则',
        'Coleção' => '收藏',
        'Acessórios' => '配件',
        'Estatísticas' => '统计',
        'Totais' => '合计',
        'Configuração' => '设置',
        'Sistema' => '系统',
        'Execuções do cron' => 'cron 运行记录',
        'Usuários' => '用户',
        'Minha conta' => '我的账户',
        'Conta' => '账户',
        'Aprovações' => '审批',
        'Relógio de hoje' => '今日手表',
        'index.php; index.php?r=<id> abre o relógio no painel; index.php?novo=1 abre o cadastro de um novo; index.php#manual abre o quadro Modo de rodízio no Rodízio manual' => 'index.php；index.php?r=<id> 在面板中打开手表；index.php?novo=1 打开新建的档案；index.php#manual 在手动轮换中打开轮换模式框',
        'recurso=hoje (com proximos_pagina)' => 'recurso=hoje（带 proximos_pagina）',
        'recurso=proximos (a troca de página dos Próximos dias)' => 'recurso=proximos（接下来的日子的翻页）',
        'recurso=ficha (o painel)' => 'recurso=ficha（面板）',
        'recurso=rodizio_manual (o Rodízio manual, de 7 em 7 dias)' => 'recurso=rodizio_manual（手动轮换，每 7 天）',
        'lancamento: iniciar, encerrar, lancar, periodo, alterar, excluir' => 'lancamento：iniciar、encerrar、lancar、periodo、alterar、excluir',
        'rodizio: trocar_dia, modo, resortear, resortear_hoje, proxima_semana, usando, sem_relogio, manual, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio：trocar_dia、modo、resortear、resortear_hoje、proxima_semana、usando、sem_relogio、manual、periodo_sortear、periodo_livre、apagar_tudo',
        'relogio: salvar, foto, remover_foto, excluir' => 'relogio：salvar、foto、remover_foto、excluir',
        'O relógio do dia (um cartão grande, no alto do meio)' => '当天的手表（一张大卡片，在中间的顶部）',
        'O relógio do cartão é o de destaque.relogio_id da API (o que tem relogios[].destaque): o relógio do dia, ou, com a Configuração "Destaque no alto da página Hoje" em "O relógio no pulso agora" (destaque_hoje = pulso), o que está no pulso agora. Quando ele não é o do dia (destaque.e = pulso): o nome dele em h1 (link que abre o painel), a janela de data com "no pulso agora" e o tipo dele, e em âmbar "Relógio do dia: <nome, link que abre o painel> (<até>)" (ou "Hoje não tem relógio do dia."), sem o motivo. Embaixo da foto (dentro do link dela), a tabelinha do destaque (table.destaque-tab, largura da foto, duas casas iguais, cantos de 8px, borda cinza, negrito pequeno): "Do dia" | "No pulso". A casa acesa tem um ✓ antes do texto: "Do dia" com destaque.do_dia (fundo azul-claro, texto safira), "No pulso" com destaque.no_pulso (fundo verde-claro, texto verde); a apagada fica cinza-clara, sem ✓; as duas podem acender. O título da tabela é o destaque.texto ("No pulso agora; o relógio do dia é outro."). Na coluna estreita (até 34rem, com a foto de 6,5rem do celular), as duas casas ficam uma em cima da outra; até 62rem (a foto de 9rem), a letra fica um pouco menor. Os pares, o botão Pôs/Tirou do pulso e a foto são do relógio do cartão.' => '卡片上的手表是 API 的 destaque.relogio_id（即带 relogios[].destaque 的那块）：当天的手表，或者，当设置“今天页面顶部的突出显示”为“现在在手腕上的手表”（destaque_hoje = pulso）时，是现在在手腕上的那块。当它不是当天的（destaque.e = pulso）：它的名称作为 h1（打开面板的链接），日期窗写着“现在在手腕上”以及它的类型，琥珀色“当天的手表：<名称，打开面板的链接>（<直到>）”（或“今天没有当天的手表。”），没有事由。照片下方（在其链接内）是焦点的小表格（table.destaque-tab，与照片同宽，两个等宽格子，8px 圆角，灰色边框，小号粗体）：“当天” | “在手腕上”。点亮的格子在文字前有 ✓：destaque.do_dia 时为“当天”（浅蓝背景，宝石蓝文字），destaque.no_pulso 时为“在手腕上”（浅绿背景，绿色文字）；未点亮的为浅灰色，没有 ✓；两个可以同时点亮。表格的标题为 destaque.texto（“现在在手腕上；当天的手表是另一块。”）。在窄栏中（不超过 34rem，手机上照片为 6.5rem），两个格子上下排列；不超过 62rem（照片为 9rem）时，字体稍小。成对、手腕的戴上/摘下按钮和照片都属于卡片上的手表。',
        'À esquerda: "<Dia da semana>, DD/MM/AAAA · <nome do modo>" em cinza; o nome do relógio do dia em h1 (link que abre o painel); a janela de data com o "até" ("só hoje", "até sexta, 02/10") e o tipo dele; o lembrete do dia em âmbar ("Pôr no winder: <relógio> (8 h)"); "Por que ele: <motivo>" (o motivo em cinza); embaixo, o botão leve discreto "Sem relógio hoje" (rodizio sem_relogio; confirma "Hoje sem relógio? O dia fica livre: ...").' => '左侧：灰色“<星期几>，DD/MM/AAAA · <模式名称>”；当天手表的名称作为 h1（打开面板的链接）；日期窗带“直到”（“只有今天”、“直到周五，02/10”）以及它的类型；当天的备忘为琥珀色（“放上上链盒：<手表>（8 h）”）；“为什么是它：<事由>”（事由为灰色）；下方，低调的浅色按钮“今天无手表”（rodizio sem_relogio；确认“今天没有手表？该日变为空闲：……”）。',
        'No meio, em pares: Agora (a etiqueta "Em uso desde 07:00", "No sol desde 09:12" ou "Em repouso desde ...", na cor do estado, e o botão leve "Pôs no pulso" / "Tirou do pulso", que manda lancamento iniciar/encerrar do tipo pulso); Carga (a barra, o % e de onde vem, ou só o texto); Última leitura ("89% em 06/10 21:30", se houver); Situação (as linhas da API); Próxima manutenção ("<nome> · <data ou hoje> (<falta>)", a falta em vermelho se atrasada, ou "nenhuma prevista"; o aviso mais perto, sem o Encostado); Encostado (só quando o aviso já venceu: a falta em vermelho); Compra ("R$ valor · loja · data"); Garantia ("até DD/MM/AAAA", "(vencida)" se passou); Código.' => '中间，成对：现在（标签“使用中，自 07:00”、“在晒太阳，自 09:12”或“休息中，自 ……”，按状态的颜色，以及浅色按钮“戴到手腕上”/“从手腕上摘下”，发送 tipo pulso 的 lancamento iniciar/encerrar）；电量（条、% 和来源，或只有文本）；最近一次读数（“89%，于 06/10 21:30”，若有）；情况（API 的各行）；下次保养（“<名称> · <日期或今天>（<还差>）”，若逾期则还差为红色，或“没有预计的”；最近的提醒，不含闲置）；闲置（仅当提醒已经到期：还差为红色）；购买（“R$ 金额 · 商店 · 日期”）；保修（“至 DD/MM/AAAA”，若已过则为“（已到期）”）；编号。',
        'À direita: a foto do relógio (ou o quadrado "Sem foto"), que abre o painel.' => '右侧：手表的照片（或“无照片”方块），它打开面板。',
        'Hoje livre (hoje_livre da API: o Sem relógio hoje, ou um período livre): h1 "Hoje sem relógio", a janela "dia livre", "Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? ..." e o "escolher…" dos dias livres (trocar_dia de hoje: o escolhido vai para o pulso a partir de agora); sem os pares nem a foto (a não ser com o destaque no pulso).' => '今天空闲（API 的 hoje_livre：今天无手表，或一个空闲时段）：h1“今天没有手表”，窗口“空闲日”，“今天没有任何手表会经轮换上手腕。要用一块吗？……”以及空闲日的“选择……”（今天的 trocar_dia：所选的从现在起上手腕）；没有成对也没有照片（除非突出显示在手腕上）。',
        'Sem relógio para hoje: h1 "Nenhum relógio para hoje" e "Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível."' => '今天没有手表：h1“今天没有手表”以及“这一天的分组中没有可用的手表。请在轮换模式中更改分组，或把一块手表标为可用。”',
        'Hoje é dia de (só quando há aviso)' => '今天轮到（仅当有提醒时）',
        'Tabela com as colunas "O que fazer" (o nome do aviso; atrasado em vermelho), "Relógio" (link que abre o painel), "Por quê" (o texto do aviso) e, à direita, o botão do lançamento que resolve, com o texto e a ação que a API dá (resolve.botao e resolve.acao): sessão fechada: "Pôs <nome em minúsculas>" (lancamento iniciar); sessão aberta: "Tirou do carregador" (lancamento encerrar); com valor: um campo curto com a unidade de dica ("%") e "Informar <nome>" (lancamento lancar com valor), ou, com resolve.estados (a leitura que mede o gasto num relógio que vai ao pulso), os dois botões leves "Em uso" e "Em repouso" no lugar dele (o lancar com estado=uso ou estado=repouso); instantâneo: o nome do tipo (lancamento lancar).' => '表格，列为“要做什么”（提醒的名称；逾期为红色）、“手表”（打开面板的链接）、“为什么”（提醒的文本），右侧是解决它的记录按钮，文本和操作由 API 给出（resolve.botao 和 resolve.acao）：时段已关闭：“已<小写名称>”（lancamento iniciar）；时段已打开：“已从充电器取下”（lancamento encerrar）；带值：一个短字段，提示为单位（“%”），以及“填写<名称>”（lancamento lancar 带值）；瞬时：类型的名称（lancamento lancar）。有 resolve.estados 时（会戴上手腕的手表上测量消耗的读数），用两个浅色按钮“使用中”和“静置”代替“填写<名称>”（lancar 带 estado=uso 或 estado=repouso）。',
        'Próximos dias' => '接下来的日子',
        'Título "Próximos dias" com o link "ver o plano inteiro →" (plano.php). Tabela: Dia ("DD/MM" e o dia da semana curto, menor), Relógio (o nome; "à mão" pequeno quando escolhido à mão; o motivo embaixo, menor), Lembrete, e o "trocar por…". Fim de semana com fundo #f4f6f8. Sem plano: "Neste modo o sorteio é feito dia a dia." Os dias livres entram no meio, como na página Plano ("livre: escolha à mão", "escolher…"). Os dias vêm da API (hoje.proximos), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 7); passando disso, embaixo o navegador de páginas (recurso=proximos com pagina; só a lista se remonta) e "Página N de M · <total> dias no plano, <n> por página (o "Mostrar até" da Configuração)." (link para configuracao.php). A página à mostra fica a mesma quando a página Hoje se remonta depois de uma gravação.' => '标题“接下来的日子”，带链接“查看整个计划 →”（plano.php）。表格：日（“DD/MM”和更小的星期几短写）、手表（名称；手动选择时有小字“手动”；事由在下方，更小）、备忘，以及“换成……”。周末背景 #f4f6f8。没有计划：“在此模式下抽签是逐日进行的。”空闲日插在中间，与计划页面相同（“空闲：手动选择”、“选择……”）。日子来自 API（hoje.proximos），数量为“显示至”中的“显示至”（设置，默认 7）；超过之后，下方是页面浏览器（recurso=proximos 带 pagina；只重新组装列表）以及“第 N 页，共 M 页 · 计划中 <total> 天，每页 <n> 天（设置中的“显示至”）。”（链接到 configuracao.php）。今天页面在一次保存后重新组装时，当前显示的页保持不变。',
        '"trocar por…": uma lista com o grupo "Um relógio" (os disponíveis, menos o do dia), o grupo "Sortear este dia por" (a maior nota, sorteio pela nota, aleatório, fila: valor sortear:<forma>; o dia é sorteado na hora por essa forma, entre os do bloco do modo, e fica à mão com o motivo "Sorteado à mão (<forma>): ...") e, num dia de amanhã em diante escolhido à mão, "↺ voltar a sortear" (valor 0); escolhido um, aparece o botão leve "Trocar" (rodizio trocar_dia com data e relogio_id). O mesmo grupo nos "escolher…" dos dias livres e no seletor do Rodízio manual (opcoesSortearDia, api.js).' => '“换成…”：一个列表，含分组“一块手表”（可用的，除当天那块）、分组“按以下方式为这一天抽签”（最高分数、按分数抽签、随机、排队：值 sortear:<方式>；当场按该方式为该日抽签，在模式区块的手表中，并保持手动，事由为“手动抽签（<方式>）：……”），以及在明天起手动选定的日子上的“↺ 恢复抽签”（值 0）；选定一项后出现浅色按钮“更换”（rodizio trocar_dia，带 data 和 relogio_id）。空闲日的“选择…”和手动轮换的选择器中有同一分组（opcoesSortearDia，api.js）。',
        'Modo de rodízio (um quadro que abre e fecha)' => '轮换模式（一个可展开和收起的框）',
        'Fechado: "Modo de rodízio" (cinza) e o nome do modo em negrito, "· <tipo> · <critério>" (na escala: "pela maior nota"; no personalizado: "pelo roteiro") e, à direita, o link "editar".' => '折叠时：“轮换模式”（灰色）和加粗的模式名称，“· <类型> · <标准>”（排班：“按最高评分”；自定义：“按脚本”），右侧是“编辑”链接。',
        'Aberto, em duas colunas: à esquerda a lista "Modo de rodízio" (os modos e, por último, "Rodízio manual") e, abaixo dela, a explicação do modo escolhido: o tipo em negrito, "· esta semana" / "· N semanas à frente" / "· período de N dias" (a escala), "· com ciclo" se usa, a frase do tipo (um por semana: "Um relógio para a semana inteira..."; escala: "Monta o plano do período inteiro de uma vez..."; personalizado: "O roteiro escrito à mão decide...") e o link "editar o modo" (modos.php?editar=<id>#form). Os blocos, as semanas e o roteiro não se editam aqui.' => '展开时，两列：左侧是“轮换模式”列表（各模式，最后是“手动轮换”），其下是所选模式的说明：加粗的类型、“· 本周”/“· 提前 N 周”/“· N 天周期”（排班）、使用时的“· 带循环”、类型的说明句（每周一块：“整周一块手表...”；排班：“一次生成整个周期的计划...”；自定义：“手写脚本决定...”）和“编辑模式”链接（modos.php?editar=<id>#form）。区块、周数和脚本不在这里编辑。',
        'À direita: "Como escolher o relógio" (Inteligente; Inteligente com sorteio; Totalmente aleatório; Fila (FIFO)) com a explicação de cada uma, só nos tipos um por semana, semana e fim de semana e por dia da semana; nos outros, a linha fixa "Como escolher o relógio: pela maior nota" (escala), "todos com a mesma chance" (aleatório) ou "pelo roteiro do modo" (personalizado) com a explicação; "Garantia de rodízio: dias sem uso, no máximo" (número de 0 a 365; some no aleatório) com "Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota." e "A nota vem dos critérios, que você cadastra."' => '右侧：“如何选择手表”（智能；智能加抽签；完全随机；队列（FIFO））及每种的说明，仅在每周一块、工作日和周末、按星期几类型中；其他类型显示固定行“如何选择手表：按最高评分”（排班）、“所有手表机会相同”（随机）或“按模式的脚本”（自定义）及说明；“轮换保证：最多闲置天数”（0 到 365 的数字；随机类型中隐藏），附“超过限制的优先，闲置最久的先上。0 关闭。同一个值适用于所有使用评分的模式。”和“评分来自你登记的标准。”',
        'Botão "Aplicar modo" (rodizio modo: modo, selecao e max_sem_uso), sem confirmação: só grava o critério e a garantia e marca o modo, o plano gravado continua (a nota: "Aplicar só marca o modo (e grava o critério e a garantia): o plano gravado continua como está, e o modo vale para os próximos sorteios. Para refazer o plano com ele, use "Sortear de novo", embaixo. Os modos, as semanas e o roteiro se cadastram em Modos de rodízio." com o link).' => '“应用模式”按钮（rodizio modo：modo、selecao 和 max_sem_uso），无需确认：只保存标准和保证并标记模式，已保存的计划继续有效（注释：“应用只标记模式（并保存标准和保证）：已保存的计划保持不变，模式用于后续抽签。要用它重做计划，请使用下方的“重新抽签”。模式、周数和脚本在轮换模式中登记。”附链接）。',
        '"Sortear de novo": uma lista com as ações possíveis agora e o botão leve "Sortear": "a partir de amanhã" (resortear) e "inclusive hoje" (resortear_hoje) com o dia já começado no pulso, ou "a partir de hoje" (resortear); fora da escala e só com mais de uma semana no modo (semanas > 1), "a próxima semana (DD/MM a DD/MM)" (proxima_semana; em qualquer dia: a semana seguinte, do primeiro ao último dia pela Configuração semana_inicio, sorteada com os dias que faltam desta já contados como uso; o "Sortear de novo" de depois refaz até o fim dela). Embaixo, a explicação da opção escolhida; cada uma tem a sua confirmação. Depois, a caixa "Sobrescrever tudo" (sobrescrever=1) com a nota: marcada, sai tudo o que o plano tem do começo do sorteio em diante (à mão, livre ou sorteado: plano e plano_livre) e o modo monta de novo, e a confirmação ganha o aviso; desmarcada, os dias à mão e os livres ficam, e a mensagem diz quantos ficaram (dias_guardados e dias_guardados_texto no lib).' => '“重新抽签”：列出当前可用的操作和轻量“抽签”按钮：“从明天起”（resortear）和“包括今天”（resortear_hoje，当天已开始佩戴时），或“从今天起”（resortear）；排班之外且模式多于一周（semanas > 1）时，“下一周（DD/MM 到 DD/MM）”（proxima_semana；任何一天：下一周，按设置 semana_inicio 从第一天到最后一天，本周剩余的日子已算作使用来抽签；之后的“重新抽签”重做到它结束）。下方是所选选项的说明；每个都有自己的确认。之后是“全部覆盖”复选框（sobrescrever=1）及说明：勾选时，计划中从抽签开始那天起的所有内容都会被清除（手动、空闲或抽出的：plano 和 plano_livre），模式重新编排，确认框加上警告；不勾选时，手动的日子和空闲日保留，消息说明保留了多少（lib 中的 dias_guardados 和 dias_guardados_texto）。',
        'Rodízio manual: a última opção da lista "Modo de rodízio" (não é um modo: o modo de sempre continua valendo fora do período). Escolhida, a explicação diz "Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe), "Sortear este dia por" (uma forma de escolha) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre (<modo>)."; somem a coluna da direita, o "Aplicar modo" com a nota e o "Sortear de novo"; aparece, abaixo de uma linha, o formulário do período: "De" (data, de hoje em diante, já com hoje), "Até" (data) e o botão "OK". O endereço index.php#manual abre o quadro já no Rodízio manual (o link da página Plano).' => '手动轮换：列表“轮换模式”的最后一项（它不是一个模式：时段之外仍然是原来的模式）。选中后，说明为“你为一个时段的每一天选择手表。填上开始和结束并点击确定：日子每 7 天出现，每一天带手表列表、“帮我决定”（由系统选择）、“按以下方式为这一天抽签”（一种选择方式）和“无手表（空闲日）”。时段之外，仍然是原来的轮换模式（<模式>）。”；右侧一列、“应用模式”及其说明和“重新抽签”消失；一条线下方出现时段表单：“从”（日期，从今天起，已填今天）、“到”（日期）和按钮“确定”。地址 index.php#manual 打开已经位于手动轮换的框（计划页面的链接）。',
        'OK lê recurso=rodizio_manual (de, ate, pagina) e mostra a tabela compacta (até 46rem): Dia ("DD/MM" e o dia da semana por extenso, menor, com " · hoje"; o número em safira no fim de semana), No plano agora (o relógio com "à mão" ou "sorteado" pequeno em âmbar, "dia livre" ou "—" em cinza) e Relógio do dia (uma lista: "Decida por mim", o grupo "Relógios" com os disponíveis por nome, o grupo "Sortear este dia por" (a maior nota, sorteio pela nota, aleatório, fila: valor sortear:<forma>) e, menos hoje, "Sem relógio (dia livre)"; de partida, a escolha que a API manda). Mais de 7 dias: embaixo, os botões leves "‹ Anterior", os números das páginas (a 1, a última e até 2 de cada lado da atual, com "…" nos saltos; a atual em safira) e "Próxima ›"; cada um relê a API. O que se escolhe fica guardado na tela ao trocar de página. Embaixo, "Página N de M · <n> dias, de DD/MM/AAAA a DD/MM/AAAA. O que você escolhe fica guardado enquanto você anda pelas páginas; nada muda antes de gravar.", os botões "Gravar o rodízio manual" (rodizio manual com de, ate e dias[data] dos que você mudou; confirma "Gravar o rodízio manual de DD/MM/AAAA a DD/MM/AAAA? Os dias ficam com os relógios escolhidos; os de "Decida por mim" são decididos agora pelo sistema."); e as notas com o critério do Decida por mim (o texto da API) e "Para apagar o que um período tem (e sortear de novo, ou deixar os dias livres): "Apagar um período", embaixo deste quadro, ou na página Plano." (link). Recusado: o motivo em âmbar acima da tabela, e as escolhas ficam; gravado: o recado no alto da página e a página remontada.' => '确定读取 recurso=rodizio_manual（de、ate、pagina）并显示紧凑表格（最大 46rem）：日（“DD/MM”以及更小的星期几文字，带“ · 今天”；周末数字为蓝宝石色）、计划中现在（手表带琥珀色小字“手动”或“已抽签”，“空闲日”或灰色“—”）和当天的手表（一个列表：“帮我决定”、分组“手表”含按名称的可用手表、分组“按以下方式为这一天抽签”（最高分数、按分数抽签、随机、排队：值 sortear:<方式>），以及除今天外的“无手表（空闲日）”；初始为 API 所给的选择）。超过 7 天：下方浅色按钮“‹ 上一页”、页码（第 1 页、最后一页以及当前页两侧最多 2 页，跳跃处为“…”；当前页为蓝宝石色）和“下一页 ›”；每一个都重新读取 API。翻页时屏幕上的选择会保留。下方，“第 N 页，共 M 页 · <n> 天，从 DD/MM/AAAA 到 DD/MM/AAAA。你的选择在翻页期间保留；保存之前什么都不会改变。”，按钮“保存手动轮换”（rodizio manual，带 de、ate 以及你改过的 dias[data]；确认“保存从 DD/MM/AAAA 到 DD/MM/AAAA 的手动轮换？这些日子使用所选的手表；“帮我决定”的由系统现在决定。”）；以及带帮我决定标准的说明（API 的文本）和“要删除一个时段已有的内容（并重新抽签，或让日子空闲）：此框下方的“删除一个时段”，或在计划页面。”（链接）。被拒绝：事由以琥珀色出现在表格上方，选择保留；已保存：提示在页面顶部，页面重新组装。',
        'Abaixo do Sortear de novo, cada um abaixo de uma linha, os mesmos dois formulários da página Plano: "Apagar um período" e "Apagar tudo" (veja a página Plano).' => '在重新抽签的下方，各自在一条线下方，与计划页面相同的两个表单：“删除一个时段”和“全部删除”（见计划页面）。',
        'Relógios (a tabela da coleção)' => '手表（收藏的表格）',
        'Título "Relógios" com "<mostrados> de <total> relógios · <n> em uso" em cinza e, à direita, os botões "Limpar filtros" (leve) e "Novo relógio" (abre o cadastro no painel).' => '标题“手表”，灰色“<所显示的> / <总计> 块手表 · <n> 使用中”，右侧按钮“清除筛选”（浅色）和“新手表”（在面板中打开档案）。',
        '12 colunas, todas ordenáveis clicando no título (▲ ou ▼ ao lado; clicar de novo inverte; vazios sempre por último): Código, Relógio (miniatura e nome em negrito), Tipo, Estado (o estado_texto da API em etiqueta, na cor do estado: Em uso verde, a sessão aberta (No sol, No winder, No carregador) laranja, Em repouso vermelho, Indisponível cinza), Carga (barra e %, ou o texto de por que não tem), Última vez usado, Próxima manutenção (data ou "hoje"), Em (quanto falta; atrasado em vermelho negrito; atualizado a cada minuto), O que fazer (em âmbar negrito; o aviso de manutenção mais perto, sem o Encostado), Encostado (quanto falta para o limite de dias sem ir ao pulso, ou "atrasado …" em vermelho negrito quando já passou; "—" sem data; atualizado a cada minuto; com a caixa "Avisar quando um relógio fica encostado" desmarcada na Configuração (encostado_ativo false na API), a coluna e o filtro dela somem, em qualquer tamanho de tela, e o filtro guardado não vale), Comprado em, Valor (à direita, "R$ 1.234,56").' => '12 列，点击标题都可排序（旁边 ▲ 或 ▼；再点一次反向；空的始终在最后）：编号、手表（缩略图和粗体名称）、类型、状态（API 的 estado_texto 作为标签，按状态的颜色：使用中绿色，已打开的时段（在晒太阳、在上链盒、在充电器）橙色，休息中红色，不可用灰色）、电量（条和 %，或为什么没有的文本）、最近一次使用、下次保养（日期或“今天”）、还差（还差多少；逾期为红色粗体；每分钟更新）、要做什么（琥珀色粗体；最近的保养提醒，不含闲置）、闲置（距离多少天没上手腕的上限还差多少，或已经过去时红色粗体“逾期 …”；无日期为“—”；每分钟更新；在设置中取消勾选“手表闲置时提醒”复选框时（API 中 encostado_ativo 为 false），该列及其筛选在任何屏幕尺寸下都消失，且保存的筛选不生效）、购买于、金额（靠右，“R$ 1.234,56”）。',
        'Uma linha de filtros embaixo dos títulos: Código ("nº"), Relógio ("buscar" no nome), Tipo (os tipos que existem), Estado (Todos e os estados da API, na ordem: Em uso, cada sessão, Em repouso, Indisponível), Carga (Todas, ≤ 20%, ≤ 50%), Última vez usado (Todos, 7 dias, +7 dias, nunca), Próxima manutenção (Todas, até hoje, 7 dias, 30 dias), O que fazer (os avisos de manutenção, sem o Encostado), Encostado (Todos, Encostados, Dentro do prazo, sem data), Comprado em (Todas, 30 dias, 90 dias, este ano, sem data), Valor (Todos, ≤ 500, 500–1.500, > 1.500, sem valor). A ordem e os filtros ficam guardados na sessão do navegador.' => '标题下方一行筛选：编号（“号”）、手表（在名称中“搜索”）、类型（现有的类型）、状态（全部以及 API 的状态，按顺序：使用中、每个时段、休息中、不可用）、电量（全部、≤ 20%、≤ 50%）、最近一次使用（全部、7 天、+7 天、从未）、下次保养（全部、直到今天、7 天、30 天）、要做什么（保养提醒，不含闲置）、闲置（全部、闲置、期限内、无日期）、购买于（全部、30 天、90 天、今年、无日期）、金额（全部、≤ 500、500–1.500、> 1.500、无金额）。排序和筛选保存在浏览器会话中。',
        'Ordem inicial: os disponíveis primeiro (o de hoje, depois os com aviso), os indisponíveis no fim e em cinza. A linha do relógio de hoje tem a faixa safira à esquerda; a de um com aviso, a âmbar. Clicar numa linha (ou Enter nela) abre o relógio no painel. Rodapé (recurso=totais, parte=rodape, relogios=os ids das linhas à mostra, pedido de novo 250 ms depois de cada filtro): embaixo de cada coluna, os totais dela (os do cadastro com rodape), cada um numa tabelinha (.mini-total: o nome em cima em maiúsculas pequenas e cinza; as linhas de altura fixa com o rótulo à esquerda, terminando em "…" quando não cabe, e o número à direita, nunca cortado; a linha "Total" em negrito com o traço escuro em cima); a primeira tabelinha de cada coluna ganha linhas vazias em cima até a maior delas, em branco e sem borda (a caixa é só das linhas com dado e do total), para os totais ficarem todos na mesma altura; um número ou um relógio é uma tabelinha só com o pé. Embaixo, "Ver todos os totais" (totais.php, com ?relogios= quando o filtro esconde algum) e o link "montar os totais" (cadastros.php?aba=totais); sem nenhum total no rodapé, a linha das tabelinhas some e aparece o recado. Em cartões, as tabelinhas ficam na grade dos cartões, cada uma com o nome da coluna em cima, sem as linhas vazias. Sem relógios: "Nenhum relógio cadastrado. Use o botão Novo relógio."; com filtros que não deixam nenhum: "Nenhum relógio com esses filtros."' => '初始顺序：可用的在前（今天的，然后有提醒的），不可用的在末尾且为灰色。今天的手表那一行左侧有蓝宝石色条；有提醒的为琥珀色。点击一行（或在其上按 Enter）在面板中打开手表。页脚（recurso=totais、parte=rodape、relogios=可见行的 id，每次筛选后 250 毫秒重新请求）：每列下方是该列的合计（定义中带 rodape 的），每个是一个小表（.mini-total：名称在上方，灰色小号大写；固定高度的行，标签在左，放不下时以“…”结尾，数字在右，从不截断；“合计”行加粗，上方有深色线）；每列的第一个小表在上方补空行到最大的那个，空白且无边框（边框只围住有数据的行和合计行），使所有合计在同一高度；数字或手表是只有底行的小表。下方是“查看所有合计”（totais.php，筛选隐藏了一些时带 ?relogios=）和链接“设置合计”（cadastros.php?aba=totais）；底部没有合计时，小表那一行消失并出现提示。卡片模式下，小表放在卡片网格中，每个上方有列名，没有空行。没有手表：“没有已登记的手表。请使用新手表按钮。”；筛选后一个都不剩：“没有符合这些筛选的手表。”',
        'Quando as 12 colunas não cabem na largura que a tabela tem: cada relógio vira um cartão, com a foto e o nome na linha de cima e embaixo os mesmos campos, cada um numa casinha com borda (cantos de 6px) e o nome da coluna numa faixa cinza-clara em cima, em colunas iguais (5; 2 no celular); os títulos viram botões "Ordenar por" e os filtros ficam todos, com o nome em cima.' => '当 12 列在表格现有宽度中放不下时：每块手表变成一张卡片，照片和名称在上面一行，下方是同样的字段，每个放在一个带边框（圆角 6px）的小格子里，列名在上方的浅灰色条中，等宽列（5 列；手机上 2 列）；标题变成“排序依据”按钮，筛选全部保留，名称在上方。',
        'O painel do relógio (à direita, flutuante ou em tela cheia)' => '手表面板（在右侧、浮动或全屏）',
        'Um botão redondo "×" no canto (no celular "× Fechar") fecha o painel; Esc também. O endereço vira index.php?r=<id>.' => '角落一个圆形按钮“×”（手机上“× 关闭”）关闭面板；Esc 也可以。地址变为 index.php?r=<id>。',
        'Cabeça: a foto (ou "Sem foto"; com o mouse parado em cima, a dica relogio.dica_foto da API, em linhas: o nome, o grupo e o código; o estado e a carga; a nota e o próximo dia no rodízio; a compra; e "Duplo clique (ou "Abrir foto", embaixo): a foto em tamanho grande.") com os botões leves "Abrir foto" (só com foto: abre a foto ampliada), "Escolher foto" / "Trocar foto" (abre o seletor de arquivo; escolhida, aparece a prévia e o botão "Salvar foto": relogio foto) e, com foto, "Remover foto" (discreto; confirma "Remover a foto?"); ao lado "<tipo> · <caminho no grupo>" em cinza, o nome em h1, a observação, e as etiquetas: em uso/em repouso, "indisponível", "relógio de hoje" e, fora da coleção, a situação (etiqueta lilás: "desejado", "emprestado", "vendido", "arquivado"; no desejado, sem a etiqueta do estado). Embaixo das etiquetas, o atalho do pulso (não no desejado; só havendo a sessão "pulso"): "Pulso" em letras pequenas maiúsculas cinza e um botão só, "Pôr" (cheio, lancamento iniciar tipo=pulso, agora) quando ele não está no pulso, ou "Tirar" (leve, lancamento encerrar tipo=pulso, agora) com "desde HH:MM (N h M min)" em cinza ao lado quando está; a dica do botão é o "Pôr no pulso" / "Tirar do pulso" inteiro. A hora certa, e o resto, ficam no quadro Marcar.' => '头部：照片（或“无照片”；鼠标停在上面时，API 的 relogio.dica_foto 提示，分行：名称、分组和编号；状态和电量；分数以及下一次进入轮换的日期；购买；以及“双击（或下方的“打开照片”）：大尺寸照片。”），带浅色按钮“打开照片”（仅有照片时：打开放大的照片）、“选择照片”/“更换照片”（打开文件选择器；选定后出现预览和按钮“保存照片”：relogio foto），有照片时还有“移除照片”（低调；确认“移除照片？”）；旁边灰色“<类型> · <分组中的路径>”，名称作为 h1，备注，以及标签：使用中/休息中、“不可用”、“今天的手表”，以及离开收藏时的情况（淡紫色标签：“心愿中”、“已借出”、“已售出”、“已归档”；在心愿中时，没有状态标签）。标签下方是手腕快捷按钮（心愿中的手表没有；仅当存在“pulso”时段时）：灰色小号大写的“手腕”和一个按钮，不在手腕上时为“戴上”（实心，lancamento iniciar tipo=pulso，当前时间），在手腕上时为“取下”（浅色，lancamento encerrar tipo=pulso，当前时间），旁边灰色显示“自 HH:MM 起（N 小时 M 分钟）”；按钮提示是完整的“戴上手腕”/“从手腕取下”。准确时间及其他内容仍在“标记”框中。',
        'Num relógio desejado, no lugar dos quadros abaixo (Agora, Previsão, Gasto, Autonomia, Rodízio, Compra, Manutenções, Marcar), só o quadro Desejo (pares: Marca, Referência, Preço-alvo "R$ ...", Prioridade, Link "abrir a página" numa aba nova; vazio: "—"; no rodapé "Comprou? Em "Editar cadastro", mude a situação para "Na coleção" e preencha a compra.") e o de Documentos; os quadros largos (Dados, Histórico) e o Editar cadastro continuam.' => '对于心愿中的手表，下面这些框（现在、预测、消耗、续航、轮换、购买、保养、标记）的位置只放心愿框（成对：品牌、型号、目标价格“R$ ...”、优先级、链接“打开页面”于新标签页；空：“—”；页脚“买了？在“编辑档案”中把情况改为“在收藏中”并填写购买。”）和文档框；宽框（数据、历史）和编辑档案仍然保留。',
        'Os quadros, numa grade (lado a lado onde cabem): Agora (pares: Estado ("No carregador desde 06:30", na cor do estado); Carga com a barra e "~68%" e de onde vem; Encostado (a falta, em vermelho negrito se já passou do limite de dias sem ir ao pulso; só quando há data); Situação, uma linha por item; Última leitura); Previsão (só nos que têm leitura: as frases da API, ou "Informe a carga atual para o sistema começar a prever."; embaixo, "De onde vem a conta" (título pequeno em maiúsculas cinza) e a tabela da previsao.conta, uma linha por número: o nome (e, menor, embaixo, o detalhe de como o gasto foi medido), o valor (com a unidade menor embaixo; "—" se vazio, a linha em cinza) e a origem em etiqueta: informado azul, padrão e cadastro âmbar, medido verde, vazio cinza; em cima, em negrito, as duas linhas do gasto que vale, no pulso e fora dele, com a origem medido ou cadastro; os campos do cadastro de um gasto em que vale o medido ficam em cinza, com o valor riscado e o detalhe "fora da conta: vale o gasto medido"; com o relógio numa sessão agora (no pulso, no carregador, no sol...), a frase do limite é "Continuando no pulso, chega a…" (com o nome da sessão), senão "Parado, chega a…"); Gasto da bateria (No pulso, Fora do pulso: o que vale "% por dia" e embaixo se é medido ou do cadastro e, menor, "no cadastro: <campo>: <valor> <unidade> (<origem>)" com os campos de onde sai o gasto do cadastro (previsao.gasto.<medida>.campos), separados por " · ", e, quando o cadastro ainda puxa a conta (previsao.gasto.<medida>.puxado), "só as leituras dariam 15,57% (1 medição): com poucas medições, o cadastro ainda puxa a conta"; Janela anterior; Medições (no motor da marcação, "pela marcação: 1 em uso e 1 em repouso"); no rodapé "Medições mais velhas que a janela saem da conta..."); Autonomia (Cheio, pelo cadastro; Cheio, pela conta; Acaba, seguindo o plano (data e hora, e "em <duração>"); No pulso sem tirar; Guardado; sem dado, o motivo em cinza); Rodízio (Nota com o link "ver a conta" (Critérios, numa aba nova); Critérios de; Próxima vez; no rodapé o botão leve "Usando hoje" (rodizio usando, com confirmação), se ele está disponível e não é o de hoje); Compra (Valor pago, Loja, Comprado em com "há N dias", Garantia "até" ou "vencida em"; sem nada: "Sem dados da compra. Preencha em "Editar cadastro"."); Compra também com "Custo por uso" ("R$ 100,00" em negrito e "3 dias de uso" embaixo; sem: "sem o valor pago" ou "ainda não foi ao pulso" em cinza) e o "há N dias" da compra vindo da API (compra.ha_dias). Documentos (cada categoria com "N arquivos", link para a página Documentos numa aba nova; o botão "Enviar documentos" ou "Abrir os documentos"); Próximas manutenções (data em negrito e o nome; ou "Nada previsto."). Depois de Documentos, Acessórios (pares: o tipo e o nome, com a observação menor embaixo; sem nenhum, "Nenhum: a pulseira extra, a caixa, o estojo, a ferramenta..."; o botão leve "Cadastrar acessórios" ou "Ver os acessórios", que abre acessorios.php?relogio=<id> numa aba nova). No rodapé de Documentos, ao lado do botão dele, o botão leve "Passaporte" (passaporte.php?id=<id> numa aba nova).' => '各框排成网格（能并排就并排）：现在（成对：状态（“在充电器中，自 06:30”，按状态的颜色）；电量带条和“~68%”以及来源；闲置（还差多少，若已超过多少天没上手腕的上限则为红色粗体；仅当有日期时）；情况，每项一行；最近一次读数）；预测（仅带读数的：API 的句子，或“请填写当前电量，系统才能开始预测。”；下方，“计算从何而来”（灰色大写小标题）以及 previsao.conta 的表，每个数字一行：名称（以及更小的、在下方的消耗如何测得的细节）、值（单位更小地在下方；空则为“—”，该行灰色）以及来源标签：已填写蓝色、默认和档案琥珀色、实测绿色、空灰色；最上方加粗显示两行当前有效的消耗（在手腕上和离开手腕），来源为实测或档案；在实测值有效的消耗中，档案字段显示为灰色，数值带删除线，细节为“不计入：采用实测消耗”；手表此刻处于某个时段（在手腕上、在充电器上、晒太阳……）时，限值那句为“继续在手腕上，将在……降到”（带时段名称），否则为“放着不动，将在……降到”）；电池消耗（在手腕上、离开手腕：有效的“每天 %”以及下方是实测还是来自档案；前一窗口；测量；页脚“比窗口更旧的测量退出计算……”）；续航（满电量，按档案；满电量，按计算；耗尽，按计划（日期和时间，以及“还有 <时长>”）；戴在手腕上不摘下；静止存放；无数据时，原因用灰色）；轮换（分数带链接“查看计算”（标准，新标签页）；标准来自；下一次；页脚有浅色按钮“今天正在使用”（rodizio usando，带确认），若它可用且不是今天的）；购买（已付金额、商店、购买于带“N 天前”、保修“至”或“已于……到期”；什么都没有：“没有购买数据。请在“编辑档案”中填写。”）；购买还带“每次使用成本”（“R$ 100,00”粗体，下方“3 天使用”；没有时：“没有已付金额”或“还没上过手腕”，灰色）以及购买的“N 天前”来自 API（compra.ha_dias）。文档（每个类别带“N 个文件”，链接到文档页面的新标签页；按钮“上传文档”或“打开文档”）；各项下次保养（日期粗体和名称；或“没有预计的。”）。文档之后，配件（成对：类型和名称，备注更小地在下方；一个都没有，“没有：备用表带、表盒、收纳盒、工具……”；浅色按钮“登记配件”或“查看配件”，在新标签页打开 acessorios.php?relogio=<id>）。在文档的页脚，其按钮旁边，浅色按钮“护照”（在新标签页打开 passaporte.php?id=<id>）。在“电池消耗”中，每行下方用较小字显示：“档案中：<字段>：<值> <单位>（<来源>）”，即档案消耗所依据的字段（previsao.gasto.<medida>.campos），以“ · ”分隔。当档案仍在拉动计算时（previsao.gasto.<medida>.puxado），再加一行：“仅凭读数会得到 15.57%（1 次测量）：测量较少时，档案仍在拉动计算”；在按标记引擎中，“测量”一行显示“按标记：使用中 1 次，静置中 1 次”。',
        'Marcar (um quadro na largura toda): "O que você quer marcar?" com uma lista em grupos: "Agora, ou numa hora que você disser" (cada sessão como verbo: "Pôr no sol" / "Tirar do sol" conforme está aberta; cada tipo com valor pelo nome; cada instantâneo pelo nome), "Algo que já passou" ("Um período que já passou (<sessões>)") e "Corrigir" ("Corrigir ou excluir uma marcação (últimos 14 dias)"). Escolhido um, aparecem só os campos dele: sessão: o estado aberto e "Pôs às" / "Tirou às" (data e hora, "Anda com o relógio até você mudar (vazio: agora).") e o botão com o verbo; com valor: "Agora em uso/em repouso" e a estimativa, "Leitura" (com a unidade), "Lida às", a caixa "Atualizar o gasto com esta medição" (marcada; só nos tipos que medem o gasto) e "Informar <nome>"; o tipo que mede o gasto, num relógio que vai ao pulso, entra na lista duas vezes, "Informar <nome> em uso" e "Informar <nome> em repouso" (o lancar com estado=uso ou repouso; o botão, mais curto, "Informar em uso" / "Informar em repouso"), e quando o escolhido não bate com o estado de agora aparecem, em âmbar, "O sistema tem ele no pulso agora (<desde ...>). Lendo em repouso, a medição deste intervalo fica só no histórico (ele estava registrado errado)." (ou "O sistema tem ele fora do pulso agora. Lendo em uso, ...") e a caixa marcada "Tirar do pulso na hora da leitura" / "Pôr no pulso na hora da leitura" (ajustar=1; desmarcada, 0); instantâneo: "Quando" e "Marcar <nome>"; período: "Onde" (se houver mais de uma sessão), "De" (uma hora atrás) e "Até" (agora) e "Registrar o período"; corrigir: "Qual marcação" ("DD/MM HH:MM · nome até HH:MM", "(aberta)", ": 68 %", "(rodízio)") e os campos dela com "Salvar" e "Excluir" (confirma). Nada pode ser no futuro. Os campos de data e hora andam com o relógio do navegador: "Pôs às", "Tirou às", "Lida às", "Quando" e o "Até" do período vêm com a hora de agora e acompanham o relógio (a cada 15 s e ao clicar no campo) até a pessoa mexer, e daí ficam no que ela pôs; sem mexer, "Pôs às", "Tirou às", "Lida às" e "Quando" vão vazios (a API usa o agora dela, com os segundos) e o "Até" vai com o minuto de agora; o máximo de todos (nada no futuro) também anda.' => '标记（占整行的一个框）：“你想标记什么？”带一个分组列表：“现在，或你指定的一个时间”（每个时段用动词：“晒太阳”/“结束晒太阳”，视是否已打开；每个带值的类型用名称；每个瞬时的用名称）、“已经过去的事”（“一段已经过去的时段（<各时段>）”）和“更正”（“更正或删除一次标记（最近 14 天）”）。选定一个后，只出现它的字段：时段：已打开的状态以及“戴上于”/“摘下于”（日期和时间，“在你修改之前随手表走（空：现在）。”）和带动词的按钮；带值：“现在使用中/休息中”和估计，“读数”（带单位），“读于”，复选框“用这次测量更新消耗”（已勾选；仅测量消耗的类型）和“填写<名称>”；瞬时：“何时”和“标记<名称>”；时段段：“在哪里”（若有不止一个时段）、“从”（一小时前）和“到”（现在）以及“登记该时段”；更正：“哪一次标记”（“DD/MM HH:MM · 名称直到 HH:MM”、“（已打开）”、“：68 %”、“（轮换）”）以及它的字段，带“保存”和“删除”（确认）。不能是将来。日期和时间字段随浏览器的时钟走：“戴上于”、“摘下于”、“读于”、“何时”和时段的“到”带上现在的时间，并跟随时钟（每 15 秒以及点击字段时），直到人去改，然后停在他所填的值上；不改的话，“戴上于”、“摘下于”、“读于”和“何时”发送为空（API 用它自己的现在，含秒），“到”发送现在的分钟；所有字段的最大值（不能是将来）也跟着走。会戴上手腕的手表上测量消耗的类型在列表中出现两次：“填写<名称>（使用中）”和“填写<名称>（静置）”（lancar 带 estado=uso 或 repouso；按钮较短：“填写（使用中）”/“填写（静置）”）；所选项与当前状态不符时，以琥珀色显示“系统现在记录它在手腕上（<自……>）。按静置读数，这段时间的测量只留在历史中（之前记录有误）。”（或“系统现在记录它不在手腕上。按使用中读数，……”），以及已勾选的“在读数时间从手腕取下”/“在读数时间戴上手腕”（ajustar=1；取消勾选为 0）。',
        'Editar cadastro (um quadro que abre e fecha; no relógio novo, já aberto com o título "Novo relógio"): Nome (obrigatório); Grupo ("(na raiz)" e cada grupo pelo caminho, com a nota "os campos, os lançamentos e os critérios de um grupo valem para tudo abaixo dele"); depois os campos do cadastro, só os que valem para o grupo escolhido (mudar o grupo mostra e esconde na hora): sim/não como caixa; lista como menu (com "—"); data como campo de data; texto como campo; número como campo decimal, com o padrão de dica ("vazio: 5"); a Compra num grupo com título (Data da compra, Valor pago, Onde comprou, Garantia até); a Observação; no novo, a Foto; "Situação na coleção" (menu: Na coleção, Desejado, Emprestado, Vendido, Arquivado; no novo, a do endereço, index.php?novo=1&posse=desejado, senão Na coleção; os campos só nos desejados, como o Preço-alvo e a Prioridade, aparecem só com Desejado, e a caixa do disponível só com Na coleção, na hora); "Disponível para o rodízio" (marcada no novo); "Guardar no banco a cópia de todos os documentos dele" (só quando o config.php não decide); botão "Cadastrar relógio" ou "Salvar alterações" (relogio salvar). Embaixo, "Excluir este relógio" (discreto; confirma "Excluir <nome> com todo o histórico e a foto?").' => '编辑档案（一个可展开和收起的框；新手表时已经打开，标题“新手表”）：名称（必填）；分组（“（在根）”以及每个分组的路径，说明“一个分组的字段、记录和标准对其下的全部有效”）；然后是档案字段，只含对所选分组有效的（更换分组会立即显示和隐藏）：是/否为复选框；列表为菜单（带“—”）；日期为日期字段；文本为字段；数字为小数字段，提示中有默认值（“空：5”）；购买在一个带标题的组中（购买日期、已付金额、在哪里购买、保修至）；备注；新建时的照片；“在收藏中的情况”（菜单：在收藏中、心愿中、已借出、已售出、已归档；新建时用地址中的，index.php?novo=1&posse=desejado，否则为在收藏中；仅用于心愿的字段，如目标价格和优先级，只在心愿中时出现，可用复选框只在在收藏中时立即出现）；“可用于轮换”（新建时已勾选）；“在数据库中保存其全部文档的副本”（仅当 config.php 不决定时）；按钮“登记手表”或“保存更改”（relogio salvar）。下方，“删除这块手表”（低调；确认“删除 <名称> 及其全部历史和照片？”）。',
        'Carga ao longo do tempo (largo; nos que têm leitura): um gráfico de linha das leituras (eixo de 0 a 100%, guias em 0, 50 e 100%, pontos verdes em uso e vermelhos em repouso, a linha em safira), com a legenda em pares rótulo/valor, menores (Pontos: as bolinhas "leitura em uso" e "leitura em repouso"; Período: "DD/MM a DD/MM"; Escala: "de 0 a 100%"; A conta: "de onde vem cada número: no quadro Previsão"); com menos de duas leituras, "O gráfico aparece a partir de duas leituras de carga." Embaixo, "Medições do gasto" (no quadro estreito, até 40rem, como no painel ao lado: cada medição vira uma tabelinha com borda e cantos de 8px: a data em negrito numa faixa cinza em cima e, embaixo, uma linha por coluna, o nome dela em maiúsculas cinza numa casa à esquerda (36%, fundo cinza-claro) e o valor na outra, com uma linha fina entre elas; o botão ocupa a última linha inteira): tabela Quando, Leituras, Horas, Gasto medido, cada um dos três uma tabelinha (table.par: largura toda, bordas aço, o título em cima em cinza pequeno sobre fundo cinza-claro, o valor embaixo, centralizados): Leituras com a marcação de cada leitura no título ("Em repouso" | "Em uso"; sem marcação, "Antes" | "Depois") e as leituras embaixo ("62" | "57"); Horas com "No pulso" | "Fora do pulso" e "3 h" | "15,5 h"; Gasto medido com uma casa só, o título "Em uso" ou "Fora do pulso" e "6,46% por dia", Na conta (sim; "em parte: pesa N%" quando uma leitura dela pesa menos, em vermelho negrito abaixo de 50%, e embaixo, menor, "a leitura de 100% não bate bem com as outras (a conta erra 4,5 pontos nela)"; não (fora da janela); não (só histórico); não (as duas leituras marcadas de jeitos diferentes, no motor pela marcação); não (o motor só o cadastro)), e um botão leve por linha, "Tirar da conta" (na usada) ou "Pôr na conta" (lancamento medicao com usada 0 ou 1), as 10 mais recentes. A nota em cima, conforme o motor: "... das leituras dos últimos N dias (ou das últimas N leituras de cada tipo), todas com o mesmo peso, partindo do cadastro ..." (robusto), a conta por marcação (duas taxas separadas), o original (pelas horas), só o cadastro (as medições ficam no histórico) ou as fórmulas; A leitura que não bate bem com as outras pesa menos na conta, e o botão de cada linha tira ou põe a medição na conta." No quadro Gasto da bateria, a primeira linha é "Calculado por": o nome do motor (gasto.motor_nome) e, menor, de onde veio a escolha ("a escolha da coleção, na Configuração", "a escolha deste relógio, no cadastro", "a escolha do grupo, no cadastro" ou "o padrão: nada escolhido"); o gasto medido ganha "± <incerteza>" em cinza depois do valor, e a linha Medições ganha, em vermelho, "N com uma leitura que não bate com as outras e pesa pouco na conta (veja Medições do gasto)".' => '电量随时间变化（宽；在有读数的手表中）：读数折线图（纵轴 0 到 100%，参考线在 0、50 和 100%，使用中为绿点、静置中为红点，线为蓝宝石色），图例为较小的标签/值对（点：“使用中读数”和“静置中读数”的圆点；期间：“DD/MM 到 DD/MM”；刻度：“0 到 100%”；计算：“每个数字的来源：在预测框中”）；少于两次读数时，“有两次电量读数后图表才出现。”下方是“消耗测量”（在窄框中，最多 40rem，如同侧面板：每次测量变成一个带边框、8px 圆角的小表格：顶部灰色条上是粗体日期，下方每一列一行，左边一格是灰色大写的列名（36%，浅灰背景），另一格是值，中间有细线；按钮占满最后一整行）：表格 何时、读数、小时、测得消耗，三者各是一个小表格（table.par：占满宽度，钢灰边框，标题在上方，浅灰背景上的灰色小字，值在下方，居中）：读数的标题是每次读数的标记（“静置中” | “使用中”；没有标记时为“之前” | “之后”），下方是读数（“62” | “57”）；小时为“佩戴” | “未佩戴”和“3 小时” | “15.5 小时”；测得消耗只有一格，标题为“使用中”或“未佩戴”，值为“每天 6.46%”、计入（是；“部分：权重 N%”当其中一次读数权重较低，低于 50% 时为红色加粗，下方较小的“100% 的读数与其他不吻合（计算在它上面偏差 4.5 点）”；否（窗口之外）；否（仅历史）；否（两次读数标记不同，在按标记引擎中）；否（仅档案引擎）），每行一个轻量按钮，“移出计算”（已计入的）或“放回计算”（lancamento medicao，usada 0 或 1），最近 10 条。上方的说明随引擎而异：“……来自最近 N 天的读数（或每类最近 N 次读数），全部权重相同，以档案为起点……”（稳健）、按标记计算（两个独立的速率）、原始（按小时数）、仅档案（测量留在历史中）或公式；与其他不吻合的读数在计算中权重较低，每行的按钮可将该测量移出或放回计算。”在电池消耗框中，第一行是“计算方式”：引擎名称（gasto.motor_nome）以及较小的选择来源（“收藏的选择（在设置中）”、“这块手表的选择（在档案中）”、“分组的选择（在档案中）”或“默认：未作选择”）；测得消耗在值后面以灰色加上“± <不确定度>”，测量行以红色加上“N 次有与其他不吻合、在计算中权重很低的读数（见消耗测量）”。',
        'Dados do relógio (largo): duas tabelas lado a lado (o valor numérico, a data e o sim/não numa linha só; o valor de texto, como a observação ou uma fórmula que dá texto, quebra a linha dentro da coluna, sem invadir a tabela do lado): Cadastro (Campo, Valor, Origem com a etiqueta informado/padrão/vazio) e Calculado agora (Fórmula com o identificador em código, Valor com a unidade (segundos por extenso), Versão). O calculado junto do informado, numa linha cinza menor embaixo do valor: no campo de onde sai um gasto (previsao.gasto.<medida>.campos: o decaimento, a autonomia), "calculado pelas leituras: 5,57% por dia de uso" (ou "calculado pelas leituras: ainda sem medição (em uso)") e " · na conta: <o que vale>"; na fórmula do gasto (previsao.gasto.<medida>.formula), "medido: <medido ou sem medição> · do cadastro: <o do cadastro>".' => '手表数据（宽）：两张表并排（数字值、日期和是/否占一行；文本值，如备注或给出文本的公式，在列内换行，不侵入旁边的表）：档案（字段、值、来源，标签为已填写/默认/空）和现在算出的（公式，标识符用代码字体，值带单位（秒用文字），版本）。算出值与填写值放在一起，在值下方用较小的灰色一行显示：在得出消耗的字段上（previsao.gasto.<medida>.campos：衰减、续航），显示“由读数算出：每使用一天 5.57%”（或“由读数算出：还没有测量（使用中）”）以及“ · 计算中：<有效值>”；在消耗公式上（previsao.gasto.<medida>.formula），显示“测得：<测得值或没有测量> · 档案：<档案值>”。',
        'Histórico (largo): "<n> registros desde DD/MM/AAAA HH:MM. Agora <estado> há <duração>." e a tabela das 5 linhas mais recentes (Quando com "até ..." embaixo, Duração, Estado em etiqueta ou o texto da marcação) e o botão leve "Abrir o histórico completo" (historico.php numa aba nova).' => '历史（宽）：“<n> 条记录，自 DD/MM/AAAA HH:MM。现在 <状态> 已 <时长>。”以及最近 5 行的表（何时，下方“直到 ……”、时长、状态标签或标记的文本）和浅色按钮“打开完整历史”（historico.php，新标签页）。',
        'Depois de gravar no painel, o recado aparece no topo do painel e a página e o painel se remontam sem perder os quadros abertos nem a rolagem; excluir o relógio recarrega a página.' => '在面板中保存之后，提示出现在面板顶部，页面和面板重新组装，不丢失已打开的框也不丢失滚动位置；删除手表会重新加载页面。',
        'Ficha do relógio' => '手表档案',
        'ficha.php?id=<id> (sem id: o primeiro)' => 'ficha.php?id=<id>（无 id：第一块）',
        'recurso=hoje (a lista)' => 'recurso=hoje（列表）',
        'as mesmas do painel do relógio' => '与手表面板相同的那些',
        'Escolha e painel' => '选择和面板',
        'No alto, "Relógio" e uma lista com todos (os disponíveis primeiro, o estado entre parênteses nos outros: "(indisponível)", "(emprestado)"); havendo relógios fora da coleção, a lista vem em dois grupos, "Na coleção" e "Fora da coleção" (cada um com a situação: "(desejado)", "(vendido)", "(arquivado)"); trocar abre o escolhido. Embaixo, o mesmo painel do relógio da página Hoje, numa página própria de até 72rem, com os quadros lado a lado e sem o ×. Sem relógios: "Nenhum relógio cadastrado. Cadastre o primeiro." (link para index.php?novo=1).' => '顶部，“手表”以及包含全部的列表（可用的在前，其他的状态在括号中：“（不可用）”、“（已借出）”）；若有收藏之外的手表，列表分成两组，“在收藏中”和“收藏之外”（各自带情况：“（心愿中）”、“（已售出）”、“（已归档）”）；更换即打开所选的。下方，与今天页面相同的手表面板，在自己的页面上，最大 72rem，各框并排，没有 ×。没有手表：“没有已登记的手表。请登记第一块。”（链接到 index.php?novo=1）。',
        'relogio: salvar (id e posse=colecao: o Comprei e o Voltar para a coleção)' => 'relogio：salvar（id 且 posse=colecao：我买了，以及回到收藏）',
        'Lista de desejos' => '心愿单',
        'h1 "Lista de desejos" com o botão "Novo desejo" à direita (index.php?novo=1&posse=desejado: o cadastro de um relógio novo já como Desejado). A nota: sem desejados, como um relógio entra na lista ("Novo desejo" ou a "Situação na coleção" do cadastro) e que ele não entra no rodízio nem nos avisos; com desejados, "<n> relógios desejados, a prioridade mais alta primeiro. Somando os preços-alvo: R$ <total> (<n> sem preço-alvo). Comprou? ...".' => 'h1“心愿单”，右侧按钮“新心愿”（index.php?novo=1&posse=desejado：新手表的档案，已经是心愿中）。说明：没有心愿时，一块手表如何进入列表（“新心愿”或档案的“在收藏中的情况”），以及它不进入轮换也不进入提醒；有心愿时，“<n> 块心愿中的手表，优先级最高的在前。目标价格合计：R$ <总计>（<n> 块没有目标价格）。买了？……”。',
        'Tabela (vira fichas até 900px) Relógio (a miniatura, o nome com o link da ficha e, embaixo, menor, "marca · referência"), Prioridade, Preço-alvo ("R$ 1.234,56" ou —), Grupo (o caminho; — na raiz), Link ("abrir a página" numa aba nova, só para http:// e https://; outro texto, como está; —) e o botão leve "Comprei" (confirma "Comprou o <nome>? Ele entra na coleção, disponível para o rodízio, e a ficha dele abre para você preencher a compra."; gravado, abre ficha.php?id=<id>).' => '表格（到 900px 变成卡片）手表（缩略图，名称带详情链接，下方更小的“品牌 · 型号”）、优先级、目标价格（“R$ 1.234,56”或 —）、分组（路径；在根为 —）、链接（“打开页面”于新标签页，仅 http:// 和 https://；其他文本原样；—）以及浅色按钮“我买了”（确认“买了 <名称>？它进入收藏，可用于轮换，并打开它的详情供你填写购买。”；保存后打开 ficha.php?id=<id>）。',
        'Fora da coleção' => '收藏之外',
        'h2 "Fora da coleção", a nota (fora do rodízio, do plano e dos avisos; o emprestado continua na tabela da página Hoje e no valor da coleção; a ficha, os documentos e o histórico ficam) e a tabela Relógio (miniatura e nome), Situação (etiqueta lilás: emprestado, vendido, arquivado), Grupo e o botão leve "Voltar para a coleção" (confirma; gravado, abre a ficha).' => 'h2“收藏之外”，说明（在轮换、计划和提醒之外；已借出的仍在今天页面的表格中和收藏金额中；详情、文档和历史保留）以及表格 手表（缩略图和名称）、情况（淡紫色标签：已借出、已售出、已归档）、分组和浅色按钮“回到收藏”（确认；保存后打开详情）。',
        'Na página Hoje, ao lado do "Novo relógio", o botão leve "Desejos (<n>) · Fora da coleção (<n>)" (só as partes que têm algum; sem nenhum, o botão some) leva a esta página.' => '在今天页面，“新手表”旁边，浅色按钮“心愿单（<n>）· 收藏之外（<n>）”（只含有内容的部分；一个都没有则按钮消失）通往此页面。',
        'totais.php?relogios=1,2,3 (os relógios que o filtro da página Hoje deixou; sem: todos)' => 'totais.php?relogios=1,2,3（今天页面筛选后留下的手表；不填：全部）',
        'Os quadros' => '各框',
        'h1 "Totais" e a nota "Contando os N relógios da coleção." (ou "Contando N de M relógios (o filtro da página Hoje). Contar todos", com o link) com o link "Montar os totais" (cadastros.php?aba=totais). Os totais com pagina, na ordem do cadastro, numa grade de quadros brancos com borda e cantos arredondados (cada um com pelo menos 17rem: três ou quatro por linha no computador, um no celular; o largo pega a linha inteira): o nome (h2), "coluna <nome>" em cinza quando tem coluna, e o resultado: a tabelinha (as linhas, o rótulo à esquerda e o número à direita, "sem valor" em cinza, o "Total" em negrito sobre fundo cinza com o traço escuro em cima), o número grande, ou o número grande e o nome do relógio (link para a página Hoje com ele aberto). Sem nenhum: "Nenhum total na página: crie os seus na aba Totais dos Cadastros...".' => 'h1“合计”和说明“统计收藏中的 N 块手表。”（或“统计 M 块中的 N 块手表（今天页面的筛选）。全部统计”，带链接），以及链接“设置合计”（cadastros.php?aba=totais）。带 pagina 的合计，按定义的顺序，放在白色方框的网格中，带边框和圆角（每个至少 17rem：电脑上每行三到四个，手机上一个；宽的占整行）：名称（h2）、有列时灰色的“列 <名称>”，以及结果：小表（各行，标签在左、数字在右，“无值”为灰色，“合计”加粗在灰色背景上，上方有深色线）、大数字，或大数字和手表名称（链接到今天页面并打开它）。一个都没有时：“页面上没有合计：在定义的“合计”标签中创建你自己的……”。',
        'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD (de=tudo: desde o primeiro uso; sem nada: os últimos 90 dias)' => 'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD（de=tudo：从第一次使用起；什么都不传：最近 90 天）',
        'Período e resumo' => '时段和摘要',
        'h1 "Estatísticas" com "de DD/MM/AAAA a DD/MM/AAAA · N dias" em cinza à direita. Filtro num cartão: De, Até (máximo hoje), "Ver" e os atalhos 30 dias, 90 dias, 1 ano, desde o começo.' => 'h1“统计”，右侧灰色“从 DD/MM/AAAA 到 DD/MM/AAAA · N 天”。卡片中的筛选：从、到（最晚今天）、“查看”以及快捷方式 30 天、90 天、1 年、从一开始。',
        'Quatro caixas (duas por linha até 900px): "<n>" dias com relógio no pulso (de <dias>); "<h> h" no pulso · <h> h por dia com relógio; "<usados> de <coleção>" relógios usados · <n> sem uso; "R$ <custo médio>" custo por uso, em média · coleção: R$ <valor>. Embaixo, "Mais usado: <link> (<h> h, <n> dias). Menos usado (dos que foram ao pulso): <link> (<h> h)."' => '四个盒子（到 900px 每行两个）：“<n>”天有手表在手腕上（共 <天数>）；“<h> h”在手腕上 · 有手表的每天 <h> h；“<用过的> / <收藏>”块手表用过 · <n> 未使用；“R$ <平均成本>”平均每次使用成本 · 收藏：R$ <金额>。下方，“使用最多：<链接>（<h> h，<n> 天）。使用最少（上过手腕的之中）：<链接>（<h> h）。”',
        'Cada relógio' => '每块手表',
        'Cartão com a nota do que cada coluna é e a tabela (fichas até 900px) Relógio (o link da ficha e, embaixo, menor, o grupo e a situação fora da coleção), Dias de uso, Horas ("12,5 h"), A parte (a barra horizontal safira com a largura relogios[].barra e "56,8%"), Custo por uso ("R$ 83,30" ou —), Sem uso há ("3 dias", "usado hoje", "nunca usado"), Tendência ("↑ usando mais" em verde, "↓ usando menos" em vermelho, "→ estável", "· poucos dados" em cinza; a dica com as horas de cada metade).' => '卡片，说明每一列是什么，以及表格（到 900px 为卡片）手表（详情链接，下方更小的分组和收藏之外的情况）、使用天数、小时（“12,5 h”）、占比（蓝宝石色水平条，宽度为 relogios[].barra，以及“56,8%”）、每次使用成本（“R$ 83,30”或 —）、多久未使用（“3 天”、“今天用过”、“从未使用”）、趋势（绿色“↑ 用得更多”、红色“↓ 用得更少”、“→ 稳定”、灰色“· 数据很少”；提示中有每一半的小时数）。',
        'Gráficos' => '图表',
        'Dois cartões lado a lado (um embaixo do outro até 900px): Por dia da semana e Por mês, cada um um gráfico de barras verticais em SVG (largura 100%, as barras safira com a altura da barra da API, o valor "14 h" em cima de cada uma quando são até 8, os rótulos embaixo: seg...dom, set/26..., no máximo uns 7 rótulos) e a nota com os números (a média por dia de cada dia da semana; as horas e quantos relógios em cada mês).' => '两张卡片并排（到 900px 上下排列）：按星期几和按月，各自是 SVG 垂直柱状图（宽度 100%，蓝宝石色柱，高度为 API 的柱高，不超过 8 根时每根上方有值“14 h”，下方标签：seg...dom、set/26...，最多大约 7 个标签）以及带数字的说明（每个星期几的日均；每个月的小时数和多少块手表）。',
        'A coleção' => '收藏',
        'Cartão com a nota e as divisões em grade (lado a lado onde cabem, cada uma com pelo menos 22rem): h3 com o título e a tabela nome, "<n> relógios", a barra com a porcentagem e as horas; numa divisão estreita (até 26rem), cada linha em duas: o nome em negrito em cima e os números embaixo.' => '卡片，带说明，以及网格中的划分（能并排就并排，每个至少 22rem）：h3 标题和表格 名称、“<n> 块手表”、带百分比的条和小时数；窄的划分（到 26rem）中，每行分成两行：名称粗体在上，数字在下。',
        'recurso=hora_certa (ao abrir e a cada minuto)' => 'recurso=hora_certa（打开时以及每分钟）',
        'O relógio' => '手表',
        'h1 "Hora certa" com "<fuso> · UTC<deslocamento>" em cinza. Um cartão (classe modo-<relogio>) com o relógio escolhido na Configuração (hora_certa.relogio): analogico, digital, anadigi ou ambos (centralizados: o analógico à esquerda e o digital à direita; um embaixo do outro no celular).' => 'h1“准确时间”，带灰色的“<时区> · UTC<偏移>”。一张卡片（类 modo-<relogio>），显示在设置中选择的时钟（hora_certa.relogio）：analogico、digital、anadigi 或 ambos（居中：模拟在左、数字在右；手机上上下排列）。',
        'O analógico, em SVG (viewBox 240×240, até 17rem, com sombra): a caixa de aço (um degradê claro-escuro-claro com borda cinza), o aro escuro (#27323f), o mostrador claro (degradê radial branco a cinza-claro), 60 marcas (as das horas são índices retangulares escuros, as outras traços finos), os numerais 12, 6 e 9 em serifa negrito, a janela da data no 3 (retângulo branco de borda escura com o dia do mês), "RELOJOEIRO" em letras pequenas azuis espaçadas sob o 12 e "HORA CERTA" em itálico cinza sobre o 6 (não no anadigi); os ponteiros das horas e dos minutos em lança escura com a faixa luminosa clara no meio, o dos segundos vermelho fino com o contrapeso redondo, todos com sombra; o eixo escuro com o centro vermelho.' => '模拟表，SVG（viewBox 240×240，最大 17rem，带阴影）：钢表壳（亮-暗-亮渐变，灰色边框）、深色表圈（#27323f）、浅色表盘（白到浅灰的径向渐变）、60 个刻度（小时刻度为深色矩形时标，其余为细线）、粗体衬线数字 12、6 和 9、3 点位置的日期窗（白色矩形、深色边框，显示月份中的日子）、12 下方小号间距蓝色字母“RELOJOEIRO”和 6 上方灰色斜体“准确时间”（指针数字两用表上没有）；时针和分针为深色剑形，中间有浅色夜光条，秒针为细红色带圆形配重，全部带阴影；深色轴心带红色中心。',
        'O digital: uma caixa escura arredondada (degradê #3a434e a #1c2530) com "RELOJOEIRO" e a abreviação do fuso em cima, e dentro o visor de cristal líquido (verde-acinzentado, borda escura, fonte de largura fixa): a linha "<DIA> DD/MM" e "24H", a hora grande HH:MM:SS com os "88:88:88" apagados atrás (opacidade 9%), e a linha "HH:MM:SS UTC" e o símbolo da fase da lua.' => '数字表：深色圆角外壳（#3a434e 到 #1c2530 渐变），顶部有“RELOJOEIRO”和时区缩写，内部为液晶显示屏（灰绿色、深色边框、等宽字体）：一行“<星期> DD/MM”和“24H”，大号时间 HH:MM:SS，背后是淡化的“88:88:88”（不透明度 9%），以及一行“HH:MM:SS UTC”和月相符号。',
        'O anadigi: o mostrador analógico com um visor de cristal líquido (92×40, no meio de baixo, entre o centro e o 6) com a data curta em cima e a hora HH:MM:SS embaixo.' => '指针数字两用表：模拟表盘带一个液晶显示屏（92×40，下方居中，位于中心和 6 之间），上方为短日期，下方为时间 HH:MM:SS。',
        'Embaixo dos relógios, centralizado, o bloco de texto: no analógico e no anadigi a hora grande HH:MM:SS (números de largura fixa); a data por extenso; a hora UTC em cinza; a nota "O relógio deste aparelho está certo (menos de meio segundo de diferença)." ou "... está <n> s adiantado/atrasado.", de onde vem a hora e "Fuso horário: <fuso> (o seu, de Minha conta | o do seu navegador, por Minha conta | o da coleção, da Configuração | o do sistema, do config.php)".' => '时钟下方居中的文字块：模拟和指针数字两用表显示大号时间 HH:MM:SS（等宽数字）；完整日期；灰色的 UTC 时间；说明“此设备的时钟准确（相差不到半秒）。”或“……快/慢 <n> 秒。”、时间来源以及“时区：<时区>（你的，来自“我的账户” | 你浏览器的，通过“我的账户” | 收藏的，来自设置 | 系统的，来自 config.php）”。',
        'O relógio da página: a diferença é agora_ms menos o meio do pedido (antes e depois); a cada virada de segundo do relógio acertado, os ponteiros (rotate nos grupos p-hora, p-min e p-seg), as horas digitais (digital, anadigi-hora), as datas dos visores (lcd-data, anadigi-data: "SÁB 17/10") e o dia da janela (data-dia) andam, no fuso.segundos da API; a cada minuto, lê a API de novo.' => '页面上的时钟：差值是 agora_ms 减去请求的中点（前后）；对好的时钟每过一秒，指针（p-hora、p-min 和 p-seg 组上的 rotate）、数字时间（digital、anadigi-hora）、显示屏的日期（lcd-data、anadigi-data：“SÁB 17/10”）和日期窗的日子（data-dia）走动，按 API 的 fuso.segundos；每分钟重新读取 API。',
        'Três cartões lado a lado (um embaixo do outro até 900px), com pares rótulo/valor: Fuso e UTC (Fuso com a abreviação, Deslocamento, UTC (Zulu), Letra militar "P (Papa)", Grupo data-hora local e Zulu em código, ISO 8601), Calendário (Hoje, Dia do ano "286 de 365 · faltam 79", Semana (ISO), Trimestre, Dia juliano, Unix) e Lua (Fase com o símbolo, Idade, Iluminada, Próxima cheia, Próxima nova e a nota do ciclo médio). Embaixo, o cartão Como acertar com o texto da API.' => '三张卡片并排（到 900px 上下排列），标签/值成对：时区和 UTC（时区带缩写、偏移、UTC（Zulu）、军用字母“P（Papa）”、本地和 Zulu 的日期时间组用代码、ISO 8601）、日历（今天、年中第几天“365 天中的第 286 天 · 还差 79”、周（ISO）、季度、儒略日、Unix）和月亮（月相带符号、月龄、被照亮、下次满月、下次新月以及平均周期的说明）。下方，如何对时的卡片，带 API 的文本。',
        'acessorios.php?relogio=<id> (0: os soltos; sem ele: todos)&editar=<id do acessório>' => 'acessorios.php?relogio=<id>（0：未绑定的；不传：全部）&editar=<配件的 id>',
        'recurso=acessorios (com relogio)' => 'recurso=acessorios（带 relogio）',
        'acessorios: salvar, excluir' => 'acessorios：salvar、excluir',
        'Lista e cadastro' => '列表和档案',
        'h1 "Acessórios" com "<n> acessórios [do <relógio> | soltos] · 1 pulseira, 2 caixas..." em cinza. Um cartão com o filtro Relógio (Todos, Soltos (de nenhum relógio) e cada relógio; trocar abre o filtrado).' => 'h1“配件”，灰色“<n> 个配件 [属于 <手表> | 未绑定] · 1 条表带、2 个表盒……”。一张卡片，带手表筛选（全部、未绑定（不属于任何手表）以及每块手表；更换即打开筛选结果）。',
        'Tabela (fichas até 900px) Acessório, Tipo, Relógio (o link da ficha, ou "solto" em cinza), Observação (cinza; —) e as ações Editar (link: editar=<id>#form) e Excluir (botão leve discreto; confirma "Excluir o acessório <nome>?"). Vazia: "Nenhum acessório. Cadastre abaixo."' => '表格（到 900px 为卡片）配件、类型、手表（详情链接，或灰色“未绑定”）、备注（灰色；—）以及操作 编辑（链接：editar=<id>#form）和删除（低调浅色按钮；确认“删除配件 <名称>？”）。空：“没有配件。请在下方登记。”',
        'Cartão Novo acessório (ou "Alterar <nome>", que a página rola até ele), em grade: Nome (obrigatório, até 120, a dica "Pulseira de couro marrom"), Tipo (Pulseira, Caixa, Estojo, Ferramenta, Carregador, Peça, Outro), Relógio ("— solto (serve a vários) —" e cada relógio; no novo, o do filtro), Observação (texto, até 1000) e "Cadastrar" ou "Salvar" e "cancelar". Gravou: volta à lista, com o mesmo filtro; recusou: o alerta com os erros.' => '卡片 新配件（或“修改 <名称>”，页面会滚到它），网格：名称（必填，最多 120，提示“棕色皮革表带”）、类型（表带、表盒、收纳盒、工具、充电器、零件、其他）、手表（“— 未绑定（可供多块使用）—”以及每块手表；新建时用筛选中的）、备注（文本，最多 1000）以及“登记”或“保存”和“取消”。已保存：回到列表，保持同一筛选；被拒绝：带错误的警报。',
        'galeria.php (posse=todos: também os de fora da coleção)' => 'galeria.php（posse=todos：也包括收藏之外的）',
        'Fotos por grupo' => '按分组的照片',
        'Uma barra com o botão "Imprimir" (window.print) e o leve "Também os de fora da coleção" / "Só a coleção". h1 "Galeria" com "<n> relógios · R$ <valor> · <n> com foto" em cinza. Um cartão por grupo (h2 com o caminho) com a grade das fotos (colunas de pelo menos 9rem: duas no celular): a foto quadrada (ou o quadrado "Sem foto"), com o link da ficha, e embaixo o nome em negrito, "marca · referência" e, menor, "ano · R$ valor · <n> dias de uso" em cinza, e a etiqueta lilás da situação fora da coleção. No pé, "Gerado em ... pelo Relojoeiro." No papel (@media print): sem o menu e sem a barra, fundo branco, quatro fotos por linha, nenhuma partida entre páginas.' => '一条栏，带按钮“打印”（window.print）和浅色“也包括收藏之外的”/“只看收藏”。h1“图库”，灰色“<n> 块手表 · R$ <金额> · <n> 块有照片”。每个分组一张卡片（h2 为路径），照片网格（列至少 9rem：手机上两列）：正方形照片（或“无照片”方块），带详情链接，下方粗体名称、“品牌 · 型号”，以及更小的灰色“年份 · R$ 金额 · <n> 天使用”，还有收藏之外情况的淡紫色标签。页脚，“由 Relojoeiro 于 …… 生成。”在纸上（@media print）：没有菜单也没有栏，白底，每行四张照片，不在页面之间被拆开。',
        'Passaporte do relógio' => '手表护照',
        'A ficha para imprimir' => '供打印的详情',
        'Uma barra com "Imprimir", o leve "Voltar para a ficha" e a nota de que no papel saem só os dados. A cabeça: a foto (9rem), "Passaporte do relógio · código N", o nome em h1, "marca · referência · caminho", a situação ("Na coleção · no rodízio · no sistema desde DD/MM/AAAA") e a observação.' => '一条栏，带“打印”、浅色“回到详情”以及说明纸上只输出数据。头部：照片（9rem）、“手表护照 · 编号 N”、名称作为 h1、“品牌 · 型号 · 路径”、情况（“在收藏中 · 在轮换中 · 自 DD/MM/AAAA 进入系统”）和备注。',
        'Cartões (largura até 60rem; os pares lado a lado onde cabem, um embaixo do outro até 700px): Compra e Uso; Cadastro (os valores já em texto); Manutenções (cada tipo: "<n> vezes · a última em DD/MM/AAAA", e a lista das revisões e trocas de pilha); Acessórios e Documentos; Próximos avisos. Vazios: "Sem dados da compra.", "Ainda não foi ao pulso.", "Nada preenchido.", "Nenhuma marcação.", "Nenhum." No pé, "Gerado em ...". No papel: só os cartões, nenhum partido entre páginas.' => '卡片（宽度最大 60rem；成对的能并排就并排，到 700px 则上下排列）：购买和使用；档案（值已经是文本）；保养（每种类型：“<n> 次 · 最近一次于 DD/MM/AAAA”，以及检修和更换电池的列表）；配件和文档；即将到来的提醒。空：“没有购买数据。”、“还没上过手腕。”、“什么都没填。”、“没有任何标记。”、“没有。”页脚，“生成于 ……”。在纸上：只有卡片，不在页面之间被拆开。',
        'recurso=plano (com dias=30, 90, 365, 730 ou todos; pagina e relogio)' => 'recurso=plano（dias=30、90、365、730 或 todos；pagina 与 relogio）',
        'rodizio: trocar_dia, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio：trocar_dia、periodo_sortear、periodo_livre、apagar_tudo',
        'Cabeça e filtros' => '页眉与筛选',
        'h1 "Plano" e a nota "Modo: <modo> · a escala vai até DD/MM/AAAA · o plano gravado vai até DD/MM/AAAA. Troque o relógio de qualquer dia em "trocar por…": o dia fica escolhido à mão (e a escala é refeita a partir dele)." Filtros lado a lado: Período (Próximos 30 dias, Próximos 90 dias (o padrão), Próximo ano, Próximos 2 anos, Tudo; trocar relê a API) e Relógio (Todos e cada um; filtra o dia a dia na tela).' => 'h1“计划”，以及说明“模式：<modo> · 排班表延伸至 DD/MM/AAAA · 已保存的计划延伸至 DD/MM/AAAA。在“换成……”中更换任意一天的手表：该日即变为手动选定（并从该日起重做排班表）。”并排筛选：时段（接下来 30 天、接下来 90 天（默认）、下一年、接下来 2 年、全部；更换会重新读取 API）和手表（全部以及每一只；在屏幕上筛选逐日列表）。',
        'O período à mão' => '手动时段',
        'Uma nota: "Para escolher os relógios de um período, dia a dia: na página Hoje, no quadro Modo de rodízio, escolha "Rodízio manual". Para apagar a programação, veja o fim desta página." (o link Hoje vai para index.php#manual).' => '一条说明：“要逐日选择某一时段的手表：在今天页面的轮换模式框中，选择“手动轮换”。要清除安排，请看本页末尾。”（“今天”链接指向 index.php#manual）。',
        'Resumo do período (<n> dias)' => '时段摘要（<n> 天）',
        'Tabela Relógio, Dias, %, Próximo dia ("DD/MM/AAAA seg"), À mão; do que tem mais dias ao que tem menos. Embaixo, "Sem nenhum dia no período: <relógios>." Sem dias: "Nenhum dia no plano neste período."' => '表格：手表、天数、%、下一天（“DD/MM/AAAA seg”）、手动；从天数最多排到最少。下方，“本时段没有任何一天：<各手表>。”没有天数时：“本时段的计划中没有任何一天。”',
        'Dia a dia' => '逐日',
        'Os dias livres (livres, da API) entram entre os do plano, na ordem das datas: no lugar do relógio, "livre: escolha à mão" em cinza com a marca "livre", e a lista do dia começa em "escolher…" (com "↺ voltar a sortear"). Um título por mês ("Outubro de 2026") e uma tabela de dias: o dia ("DD/MM" e o dia da semana, "hoje" no de hoje, com a faixa safira), o relógio (com "à mão" e o motivo embaixo), o lembrete e o "trocar por…" (como na página Hoje). Fim de semana com fundo cinza claro. Sem dias: "Neste modo o sorteio é feito semana a semana: o plano tem só a semana atual." ou "Nenhum dia." Os dias vêm da API (plano.dia_a_dia, com pagina e relogio: o filtro de relógio relê a API), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 31); passando disso, o navegador de páginas embaixo (cada página relê a API e rola até o dia a dia) e "Página N de M · <total> dias, <n> por página (o "Mostrar até" da Configuração)."' => '空闲日（livres，来自 API）按日期顺序插入计划日之间：手表的位置是灰色的“空闲：请手动选择”，并带“livre”标记，当天的列表从“选择……”开始（带“↺ 重新抽签”）。每月一个标题（“2026 年 10 月”）和一张日表：日期（“DD/MM”和星期，“今天”标在当天，蓝宝石色色带）、手表（下方带“手动”和事由）、备忘以及“换成……”（与今天页面相同）。周末浅灰底。没有日期时：“此模式下抽签按周进行：计划只有当前这一周。”或“没有任何一天。”日期来自 API（plano.dia_a_dia，带 pagina 与 relogio：手表筛选会重新读取 API），来自“显示至”中的“显示至”（设置，默认 31）；超过之后，下方是翻页（每一页重新读取 API 并滚动到逐日）以及“第 N 页，共 M 页 · <total> 天，每页 <n> 天（设置中的“显示至”）。”',
        'Rodapé: Apagar a programação (um cartão no fim da página, depois do dia a dia, separado por uma margem grande e uma borda de 3px aço escuro em cima)' => '页脚：清除安排（页面末尾一张卡片，在逐日之后，以较大外边距和上方 3px 深钢灰边框分隔）',
        'Título h2 "Apagar a programação". "Apagar um período" (o rótulo em cinza): numa linha que quebra, "De" e "Até" (datas, de hoje em diante; um dos dois pode ficar vazio) e o botão leve "Apagar" (rodizio periodo_sortear). Embaixo, a nota "Os dias do período saem do plano, de amanhã em diante (os escolhidos à mão, os sorteados e os livres), e o modo de rodízio monta esses dias de novo. Pode deixar um lado vazio: só o começo apaga dele até o fim do plano; só o fim apaga de amanhã até ele." Confirma "Apagar os dias deste período do plano (escolhidos à mão, sorteados e livres)? O modo de rodízio monta esses dias de novo." Sem nenhuma das datas, a API recusa ("Dê o começo, o fim ou os dois ...").' => 'h2 标题“清除安排”。“清除一个时段”（灰色标签）：在一行中（可换行）有“从”和“到”（日期，从今天起；其中一个可以留空）以及浅色按钮“清除”（rodizio periodo_sortear）。下方是说明“时段内的日子从明天起从计划中删除（手动选择的、抽签的和空闲的），轮换模式会重新安排这些日子。可以只填一边：只填开始，从开始删除到计划结束；只填结束，从明天删除到结束。”确认提示“从计划中删除这个时段的日子（手动选择的、抽签的和空闲的）？轮换模式会重新安排这些日子。”两个日期都不填时，API 会拒绝（“请填写开始、结束或两者……”）。',
        'Abaixo de uma linha, "Apagar tudo": a caixa "Excluindo hoje (apaga também o dia de hoje)" e o botão leve "Apagar tudo" (rodizio apagar_tudo, com hoje=1 marcada), e a nota "Limpa toda a programação, de amanhã em diante: os dias escolhidos à mão, os sorteados e os livres. Marcando "Excluindo hoje", apaga de hoje em diante (se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora). Depois, o modo de rodízio monta o plano de novo, do zero." Confirma (com hoje: "Apagar toda a programação, de hoje em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo, e hoje pode sair outro relógio, que passa a ser o do pulso a partir de agora."; sem: "... de amanhã em diante ...; hoje continua como está.").' => '一条分隔线下方，“全部清除”：复选框“排除今天（也清除今天这一天）”和浅色按钮“全部清除”（rodizio apagar_tudo，勾选时 hoje=1），以及说明“清除从明天起的全部安排：手动选定的日子、抽签的日子和空闲日。勾选“排除今天”则从今天起清除（若今天改派另一只手表，它从现在起成为手腕上的那只）。之后，轮换模式从零重新编制计划。”确认（含今天：“清除全部安排，从今天起（手动选定、抽签和空闲日）？轮换模式会重新编制计划，今天可能改派另一只手表，并从现在起成为手腕上的那只。”；不含：“……从明天起……；今天保持不变。”）。',
        'avisos.php; ?editar=<id>#form abre um aviso para alterar; ?evento=<id>#lembretes, um lembrete; #avisos-relogios, #lembretes e #para-onde vão direto a cada parte' => 'avisos.php；?editar=<id>#form 打开一个提醒进行修改；?evento=<id>#lembretes 打开一个定时提醒；#avisos-relogios、#lembretes 和 #para-onde 直接跳到各部分',
        'recurso=cadastros (os avisos, os grupos e os tipos de lançamento)' => 'recurso=cadastros（提醒、分组和记录类型）',
        'recurso=config (os lembretes, os relógios, as repetições, os destinos e as agendas)' => 'recurso=config（定时提醒、手表、重复方式、目的地和日历）',
        'avisos: novo, alterar, excluir' => 'avisos: novo, alterar, excluir',
        'config: evento_salvar, evento_excluir' => 'config: evento_salvar, evento_excluir',
        'No alto' => '顶部',
        'h1 "Avisos", as abas-âncora Avisos dos relógios, Lembretes e Para onde vão (levam a cada parte da mesma página) e a nota "Tudo o que o sistema lembra: os avisos dos relógios, que ele calcula sozinho... os lembretes, que você marca com hora e repetição; e para onde vão os dois...". Depois de gravar, o recado e a página volta na parte gravada; recusado, os erros em cima, e o que foi digitado fica.' => 'h1“提醒”，锚点标签 手表提醒、定时提醒 和 发往何处（跳到同一页面的各部分），以及说明“系统会提醒的一切：手表提醒，由系统自动计算……定时提醒，由你设定时间和重复方式；以及两者发往何处……”。保存后显示提示，页面回到保存的部分；被拒绝时，错误显示在顶部，已输入的内容保留。',
        'Avisos dos relógios' => '手表提醒',
        'Tabela Aviso, Versão para, Data prevista, Vale quando, Antecedência ("N d"), Resolve, Na escala (com o valor ou as horas simuladas), Na agenda, Na hora (sim/não), Ativo, ações. Formulário: Identificador (na novo), Nome, Antecedência (dias), Resolve (os tipos), Versão para, ativo, "na hora (Telegram no minuto em que vence)" (caixa), Na escala inteligente (não; no relógio do dia; sempre), Escala: valor do lançamento simulado, Escala: horas da sessão simulada, Data na agenda (só dentro da antecedência; qualquer data), Data prevista (fórmula), Vale quando (fórmula), Texto (até 300).' => '表格：提醒、版本适用于、预计日期、何时有效、提前量（“N d”）、解决、在排班表中（带数值或模拟小时）、在日历中、准时（是/否）、启用、操作。表单：标识符（新建时）、名称、提前量（天）、解决（各类型）、版本适用于、启用、“准时（到期的那一分钟发 Telegram）”（复选框）、智能排班表（否；在当天的手表上；始终）、排班表：模拟记录的数值、排班表：模拟时段的小时、日历中的日期（仅在提前量之内；任意日期）、预计日期（公式）、何时有效（公式）、文本（最多 300）。',
        'Lembretes (eventos personalizados)' => '定时提醒（自定义事件）',
        'A tabela dos eventos: Evento (o nome), Quando (a repetição por extenso), Relógio, Vai para (os destinos e as agendas que recebem) e as ações Editar e Excluir (Excluir mostra o que sai junto e pede a confirmação). Embaixo, o quadro que abre e fecha ("Novo evento" ou "Editar o evento <nome>"): Nome (obrigatório), Relógio (opcional), Quando dispara (uma vez, todo dia, toda semana, todo mês, a cada N dias), e só os campos da repetição escolhida. O evento novo já vai para todos os destinos.' => '事件表格：事件（名称）、时间（重复方式的文字描述）、手表、发往（接收它的推送目标和日历）以及“编辑”和“删除”操作（“删除”会显示一并删除的内容并要求确认）。下方是可展开收起的面板（“新事件”或“编辑事件 <nome>”）：名称（必填）、手表（可选）、何时触发（一次、每天、每周、每月、每 N 天），以及只显示所选重复方式的字段。新事件会自动发往所有推送目标。',
        'Para onde vão: destinos e agendas' => '发往何处：目的地和日历',
        'Um quadro com dois lados: "Destinos das mensagens" (cada destino com o nome, o tipo e "(desligado)" quando está; o link para a página Destinos; vazio: "Nenhum ainda: as mensagens da manhã, da noite e os avisos não saem para lugar nenhum.") e "Agendas" (cada agenda; o link para a página Agendas; vazio: "Nenhuma ainda."), e a explicação "Um destino é um webhook (Telegram, n8n...), um e-mail ou o Web Push do navegador; uma agenda é o Google, um CalDAV (Nextcloud, iCloud, Fastmail), o Outlook ou um link ICS...".' => '一个分为两边的面板：“消息推送目标”（每个推送目标显示名称、类型，关闭时显示“（已关闭）”；推送目标页面的链接；为空时：“还没有：早晨、晚上的消息和提醒都不会发往任何地方。”）和“日历”（每个日历；日历页面的链接；为空时：“还没有。”），以及说明“推送目标可以是 webhook（Telegram、n8n……）、电子邮件或浏览器的 Web Push；日历可以是 Google、CalDAV（Nextcloud、iCloud、Fastmail）、Outlook 或 ICS 链接……”。',
        'configuracao.php (o ?evento=<id> e o #personalizados antigos levam para a página Avisos)' => 'configuracao.php（旧的 ?evento=<id> 和 #personalizados 会转到“提醒”页面）',
        'recurso=migracoes (antes de tudo)' => 'recurso=migracoes（在一切之前）',
        'config: salvar' => 'config: salvar',
        'migracoes: aplicar (só o master)' => 'migracoes: aplicar（仅限 master）',
        'backup: fazer, restaurar (só o master)' => 'backup: fazer, restaurar（仅限 master）',
        'Banco desatualizado (só quando há migração pendente)' => '数据库未更新（仅当有待应用的迁移时）',
        'Um cartão só: "O banco está desatualizado", a explicação ("Esta versão do sistema precisa de migrações que ainda não foram aplicadas... as páginas, a API e o cron ficam parados..."), a tabela das pendentes (versão em negrito, o que traz, o arquivo em código) e o botão "Aplicar as migrações" (só o master aplica; a v25 guarda antes uma cópia do banco antigo em relojoeiro-antes-da-v25.jsonl.gz).' => '只有一张卡片：“数据库已过期”、说明（“此版本的系统需要尚未应用的迁移……页面、API 和 cron 都会停止……”）、待处理迁移的表格（版本加粗、带来的内容、代码格式的文件名）以及“应用迁移”按钮（只有 master 能应用；v25 会先把旧数据库的副本保存到 relojoeiro-antes-da-v25.jsonl.gz）。',
        'Os quadros do alto (uma grade de 3 colunas; um formulário só, salvo pela barra do pé)' => '顶部的框（三列网格；只有一个表单，由页脚栏保存）',
        'Cada opção numa linha: o rótulo à esquerda e o campo à direita, alinhados na mesma coluna em todos os quadros; caixas de marcar no lugar do campo; textos longos com o rótulo em cima e o campo na largura toda. Cada quadro com a explicação embaixo.' => '每个选项占一行：标签在左、字段在右，所有框对齐到同一列；复选框位于字段位置；长文本把标签放在上方、字段占满宽度。每个框下方有说明。',
        'Rotina do dia: Manhã: relógio do dia e avisos (hora); Noite: preparar o de amanhã (hora); No pulso a partir de (hora); Pôr no pulso sozinho (caixa); No pulso até (hora); Tirar do pulso sozinho (caixa); Sessão no sol esquecida fecha às (hora); A semana começa (Na segunda-feira ou No domingo: semana_inicio).' => '每日例程：早晨：当天的手表和提醒（时刻）；夜晚：准备明天的（时刻）；从……起上手腕（时刻）；独自上手腕（复选框）；在手腕上直到（时刻）；独自离开手腕（复选框）；忘记的晒太阳时段关闭于（时刻）；每周开始于（星期一或星期日：semana_inicio）。',
        'Limites e contas: Carregar quando a carga chegar a (%); Solar: pôr no sol quando chegar a (%); Gasto da bateria: como calcular (válido para todos os relógios) (uma lista: "Individual (no relógio ou no grupo)" e os cinco motores numerados, "1. Pelas horas registradas (o motor original)" a "5. Pelas fórmulas do cadastro"); Gasto medido: contar por (Dias (os últimos dias) ou Leituras (as últimas de cada tipo)); Gasto medido: média dos últimos (dias); Gasto medido: últimas leituras (de cada tipo); Avisar quando um relógio fica encostado (uma caixa: liga e desliga o aviso encostado do cadastro inteiro); Aviso Encostado: dias sem ir ao pulso; Máximo de dias sem uso; Previsão: limite (%); Cópia dos documentos no banco (válido para todos os relógios) (Individual (no relógio ou no arquivo), Todos os arquivos, Nenhum arquivo). Embaixo, a nota explicando o limite por relógio, os cinco motores e a cópia (e, em vermelho, o aviso de que o config.php ainda define DOCUMENTOS_COPIA_BANCO, que não vale mais, quando é o caso).' => '限制与计算：电量到达多少时充电（%）；太阳能：到达多少时晒太阳（%）；电池消耗：如何计算（对所有手表有效）（一个列表：“单独（在手表或分组上）”和五个编号引擎，从“1. 按记录的小时数（原始引擎）”到“5. 按档案的公式”）；测得消耗：按什么计（天数（最近的天数）或读数（每类最近的几次））；测得消耗：最近几天的平均（天）；测得消耗：最近读数（每类）；手表闲置时提醒（一个复选框：开启和关闭档案中的整个闲置提醒）；闲置提醒：多少天没戴；最多多少天不用；预测：下限（%）；文档在数据库中的副本（对所有手表有效）（单独（在手表或文件上）、所有文件、不复制任何文件）。下方的说明解释按手表的下限、五种引擎和副本（并在适用时以红色提示 config.php 仍定义了已不再生效的 DOCUMENTOS_COPIA_BANCO）。',
        'Telas: Abrir o relógio na página Hoje (Ao lado da lista; Numa janela flutuante, grande); Destaque no alto da página Hoje; Reloginho da barra (um dos 24 modelos por hora) (Normal: cada hora tem o seu; Aleatório: sorteia um a cada hora (pode repetir); Aleatório sem repetição: os 24 embaralhados, cada um uma vez por dia); Próximos dias e Plano: mostrar até (dias); Intervalo de atualização das páginas (segundos; 0 desliga: número de 0 a 86400, padrão 60, a nota explica); Idioma padrão da coleção; Fuso horário (quem não escolheu outro em Minha conta) (uma lista: "O do sistema (<fuso>)" e todos os fusos que o PHP conhece, cada um com o deslocamento de agora, "America/Sao Paulo (UTC−03:00)"); Relógio da Hora certa (Analógico e digital (um ao lado do outro), Analógico, Digital, Anadigi (o visor digital dentro do analógico)); embaixo, na nota, a explicação do fuso (o da coleção vale para quem não escolheu o seu, o cron, as mensagens e as agendas; cada pessoa vê e digita no seu; no banco fica tudo no do sistema) e do relógio; Endereço do sistema (a âncora {link}: só o master muda; para os outros, o texto).' => '界面：在今天页面中打开手表（在列表旁；在大的浮动窗口中）；今天页面顶部的突出显示；菜单栏的小手表（每小时 24 种款式之一）（正常：每个小时有自己的；随机：每小时抽一个（可能重复）；不重复随机：24 种打乱，每天每种一次）；接下来的日子和计划：显示至（天）；页面刷新间隔（秒；0 关闭：0 到 86400 的数字，默认 60，说明中有解释）；收藏的默认语言；时区（在“我的账户”中未另选的人）（一个列表：“系统的（<时区>）”以及 PHP 认识的所有时区，每个带当前偏移，“America/Sao Paulo (UTC−03:00)”）；准确时间的时钟（模拟和数字（并排）、模拟、数字、指针数字两用（数字显示嵌在模拟表盘内））；下方说明中解释时区（收藏的适用于未选择自己时区的人、cron、消息和日历；每个人按自己的时区查看和输入；数据库中一切保持系统时区）和时钟；系统地址（占位符 {link}：只有 master 能改；其他人看到文本）。',
        'Cron: "Cron rodando: última execução às HH:MM." (nota) ou, em âmbar, "O cron ainda não rodou" / "O cron não roda desde ..." com a linha do crontab em código; o erro guardado numa caixa; o link "Ver todas as execuções do cron" e o registro da última rodada (o master vê o do sistema; os outros, o da coleção).' => 'Cron：“Cron 运行中：最后一次执行于 HH:MM。”（说明）或琥珀色的“cron 尚未运行”/“cron 自 …… 起未运行”，并附代码格式的 crontab 行；保存的错误显示在框中；“查看所有 cron 运行记录”链接以及最后一轮的日志（master 看到系统的；其他人看到收藏的）。',
        'Sorteios (só leitura): de onde vêm os números (RANDOM.ORG, ANU QRNG, o gerador seguro do PHP) e o último lote.' => '抽签（只读）：数字的来源（RANDOM.ORG、ANU QRNG、PHP 的安全生成器）以及最近一批。',
        'Avisos, lembretes e mensagens' => '提醒、定时提醒和消息',
        'Um quadro pequeno na grade: "N lembretes · N destinos · N agendas" e a nota "Os avisos dos relógios, os lembretes (os eventos personalizados) e para onde eles vão ficam juntos na página Avisos." (o link). O endereço antigo de um lembrete (?evento=<id> ou #personalizados) leva para a página Avisos.' => '网格中的一个小框：“N 个定时提醒 · N 个目的地 · N 个日历”以及说明“手表提醒、定时提醒（自定义事件）以及它们发往何处，都集中在提醒页面。”（链接）。定时提醒的旧地址（?evento=<id> 或 #personalizados）会转到“提醒”页面。',
        'A barra de salvar no pé: "As mudanças desta página valem depois de salvar." e o botão "Salvar configuração" (config salvar). Salvou: "Configuração salva." numa janelinha flutuante embaixo da tela (clara, borda safira, o botão ×; some sozinha em 6 s) e o formulário fica como está, sem remontar: a rolagem, o foco e os quadros abertos ficam onde estavam, nada volta ao alto. Recusado: os erros na mesma janelinha (borda vermelha; fica até fechar) e o que foi digitado fica. Salvou outro idioma padrão: o pedido já vai com lingua= (a resposta vem traduzida), o cookie lingua passa a ele e lingua_auto some (como no seletor do menu), e a página abre de novo nele voltando ao mesmo campo (a âncora guardada no sessionStorage), com o recado na janelinha.' => '页脚保存栏：“本页的更改在保存后生效。”以及按钮“保存设置”（config salvar）。保存后：“设置已保存。”显示在屏幕底部的浮动小窗口中（浅色，蓝宝石色边框，带 × 按钮；6 秒后自动消失），表单保持原样、不重新构建：滚动位置、焦点和展开的方框都保持不变，不会回到顶部。被拒绝时：错误显示在同一个小窗口中（红色边框；保留到关闭为止），已输入的内容保留。保存了另一种默认语言时：请求已带上 lingua=（响应以该语言返回），lingua cookie 改为该语言、lingua_auto 被删除（与菜单选择器相同），页面以该语言重新打开并回到同一个字段（锚点保存在 sessionStorage 中），消息显示在小窗口中。',
        'Cópia de segurança (no fim da página; só o master)' => '备份（页面底部；仅限 master）',
        'Título "Cópia de segurança". Com a pasta: a nota "Uma cópia do banco inteiro por dia, na rodada da noite, guardando as N mais novas, sem (ou com) o conteúdo dos documentos... Última: DD/MM/AAAA HH:MM."; sem a pasta, em âmbar, o aviso de que falta a BACKUP_PASTA.' => '标题“备份”。有文件夹时：说明“每天在晚间一轮中备份整个数据库一次，保留最新的 N 份，不含（或含）文档内容……最近一次：DD/MM/AAAA HH:MM。”；没有文件夹时，琥珀色提示缺少 BACKUP_PASTA。',
        'A tabela compacta das cópias (da mais nova para a mais velha): Cópia (o nome do arquivo em fonte fixa), Feita em, Tamanho, Documentos (com/sem) e, à direita, "Baixar" e "Restaurar" (confirma antes). Com BACKUP_ATIVO = false, a seção inteira não aparece.' => '备份的紧凑表格（从新到旧）：副本（等宽字体的文件名）、生成时间、大小、文档（含/不含），右侧是“下载”和“恢复”（先确认）。BACKUP_ATIVO = false 时，整个部分不显示。',
        'criterios.php?escopo=<"", g:<grupo> ou r:<relógio>>; ?relogio=<id> abre a conta dele' => 'criterios.php?escopo=<""、g:<grupo> 或 r:<手表>>；?relogio=<id> 打开它的计算',
        'criterios: todas as ações' => 'criterios：全部操作',
        'Explicações' => '说明',
        'h1 "Critérios de escolha do relógio". Cartão "Como a nota funciona" (lugar, conjunto, parâmetro, subparâmetro, faixas, peso efetivo e nota final, em negrito os termos). Cartão "Como a nota vira escolha": as quatro formas com a explicação, a tabela Modo de rodízio / Forma de escolha ("(o modo atual)") e a garantia de rodízio.' => 'h1“手表选择标准”。卡片“分数如何运作”（位置、集合、参数、子参数、区间、有效权重和最终分数，术语加粗）。卡片“分数如何变成选择”：四种方式及其说明、表格轮换模式 / 选择方式（“（当前模式）”）以及轮换保障。',
        'Onde há critérios' => '哪里有规则',
        'Tabela Lugar, Parâmetros (quantos), Usado por ("N relógios" e os nomes em cinza) e o link "editar". Em vermelho: "Há relógios sem conjunto nenhum (nota neutra, 50): ..."' => '表格：位置、参数（多少个）、使用者（“N 块手表”以及灰色名称）和链接“编辑”。红色：“有手表没有任何集合（中性分数 50）：……”',
        'O conjunto do lugar escolhido' => '所选位置的集合',
        '"Editar os critérios de" com a lista de todos os lugares ("Todos os relógios", "Grupo: <caminho>", "Relógio: <nome>"; "— com critérios próprios" nos que têm) e "Abrir". Sem critérios próprios: "<Lugar> não tem critérios próprios: usa os de <lugar de cima>." e os botões "Criar critérios próprios, copiando os de <lugar>" e "Criar vazio" (leve).' => '“编辑……的标准”，带全部位置的列表（“全部手表”、“分组：<路径>”、“手表：<名称>”；有自己标准的标“— 有自己的标准”）和“打开”。没有自己的标准：“<位置> 没有自己的标准：使用 <上级位置> 的。”以及按钮“创建自己的标准，复制自 <位置>”和浅色的“创建空白”。',
        'Com critérios: "Critérios de <lugar>", "Usado por N relógios: ..." e a tabela Parâmetro (o nome editável), Peso no conjunto (campo curto e "%"), Subparâmetros (link para a seção; "(fora da conta)" em vermelho se nenhum), e ↑ ↓ Excluir; no rodapé "Soma" com a soma ao vivo e "fecha 100%" ou, em vermelho, "faltam N%" / "passa N%"; botão "Salvar parâmetros". Excluir confirma mostrando como o peso se divide entre os que ficam. Linha de inclusão: Novo parâmetro, Peso (%), "Incluir". Embaixo, "Excluir os critérios próprios de <lugar>" (discreto, confirma).' => '有标准时：“<位置> 的标准”、“由 N 块手表使用：……”以及表格：参数（可编辑的名称）、在集合中的权重（短字段和“%”）、子参数（链到该节；若一个都没有则红色“（不计入）”），以及 ↑ ↓ 删除；页脚“合计”带实时合计，以及“正好 100%”或红色“还差 N%”/“超出 N%”；按钮“保存参数”。删除时确认并显示权重如何分给留下的那些。添加行：新参数、权重（%）、“添加”。下方，“删除 <位置> 的自有标准”（低调，需确认）。',
        'Cada parâmetro' => '每个参数',
        'Um cartão por parâmetro: "<nome> <peso> do conjunto de <lugar>"; a tabela Subparâmetro, Mede, Peso no parâmetro, Peso efetivo no conjunto (atualizado ao digitar), ↑ ↓ Excluir, com a soma no rodapé e "Salvar subparâmetros".' => '每个参数一张卡片：“<名称> 占 <位置> 集合的 <权重>”；表格：子参数、测量、在参数中的权重、在集合中的有效权重（输入时更新）、↑ ↓ 删除，页脚有合计和“保存子参数”。',
        'Para cada subparâmetro, "Faixas de <nome>" (abre e fecha, com quantas faixas e o que mede): numa medida numérica, a tabela De, Até, Nota, Apagar; numa de categoria, Categoria (lista), Nota, Apagar; sempre uma linha em branco para incluir, o botão "+ faixa" (mais uma linha) e "Salvar faixas"; a regra das faixas em nota. Embaixo, "Trocar a medida para" (confirma: as faixas recomeçam) e "Mover para o parâmetro".' => '对每个子参数，“<名称> 的区间”（展开和收起，带区间数量和测量内容）：数值测量时，表格为从、到、分数、删除；类别测量时，类别（列表）、分数、删除；始终有一空白行用于添加，按钮“+ 区间”（再加一行）和“保存区间”；区间规则写在说明里。下方，“把测量改为”（确认：区间重新开始）和“移到参数”。',
        'Linha de inclusão: Novo subparâmetro, Mede (lista das medidas), Peso (%), "Incluir". Sem subparâmetros, em vermelho: "Sem subparâmetros: este parâmetro não entra na conta até ganhar um."' => '添加行：新子参数、测量（测量列表）、权重（%）、“添加”。没有子参数时，红色：“没有子参数：此参数在获得一个之前不计入。”',
        'A nota de cada relógio agora' => '每块手表现在的评分',
        'Um quadro que abre e fecha por relógio disponível, da maior nota para a menor: o nome em negrito, "<grupo> · critérios de <lugar>" e a nota à direita; aberto, a tabela Parâmetro, Subparâmetro, Valor medido, Faixa, Nota, Puxa (a seta de cada critério, centralizada, em negrito: ↑ verde quando a nota passa de 50, o neutro, e puxa a nota final para cima; ↓ vermelha abaixo de 50, puxa para baixo; ↔ marrom com 50 em ponto ou sem peso efetivo, neutra; o title explica: "puxa a nota para cima", "puxa a nota para baixo", "neutro: não puxa para nenhum lado"), Peso efetivo, Pontos, com a nota final no rodapé, e os links "editar os critérios de <lugar>" e "critérios só deste relógio". Por fim, o cartão "Restaurar os critérios iniciais" com o botão leve "Restaurar" (confirma).' => '每个可用手表一个可展开的框，从分数最高到最低：名称加粗，“<分组> · <位置> 的标准”以及右侧分数；展开后，表格：参数、子参数、测得的值、区间、分数、拉动（每条标准的箭头，居中、粗体：分数超过 50（中性点）时为绿色 ↑，把最终分数往上拉；低于 50 为红色 ↓，往下拉；恰好 50 或没有有效权重时为棕色 ↔，中性；title 说明：“把评分往上拉”“把评分往下拉”“中性：不往任何一边拉”）、有效权重、得分，页脚为最终分数，以及链接“编辑 <位置> 的标准”和“仅这块手表的标准”。最后，卡片“恢复初始标准”，带浅色按钮“恢复”（需确认）。',
        'Grupos de relógios' => '手表分组',
        'arvore: novo, renomear, mover, ordem, excluir, relogios' => 'arvore：novo、renomear、mover、ordem、excluir、relogios',
        'Árvore' => '树',
        'A explicação; a árvore como lista com recuo por nível. Cada grupo: o nome num campo com "Renomear" (discreto), "N relógios" ("· critérios próprios" com link), ↑ ↓ e Excluir (confirma dizendo para onde vão os subgrupos, os relógios e o que acontece com os critérios); os relógios dele em cinza embaixo; e "subgrupo e mover" (abre e fecha): Novo subgrupo + "Criar", Mover para dentro de (só onde não forma ciclo) + "Mover". No fim: linha de inclusão "Novo grupo", "dentro de" e "Criar". Sem grupos: "Nenhum grupo ainda."' => '说明；树是按层级缩进的列表。每个分组：名称在一个字段里，带“重命名”（低调）、“N 块手表”（“· 自有标准”带链接）、↑ ↓ 和删除（确认时说明子分组、手表会去哪里，以及标准会怎样）；它的手表以灰色列在下方；以及“子分组和移动”（展开和收起）：新子分组 + “创建”、移入（仅不会形成环的位置）+ “移动”。末尾：添加行“新分组”、“位于……之内”和“创建”。没有分组：“还没有任何分组。”',
        'O grupo de cada relógio' => '每块手表的分组',
        'Tabela Relógio ("(indisponível)" em cinza) e Grupo (lista com "(na raiz)" e os caminhos), e o botão "Salvar grupos" (arvore relogios, todos de uma vez).' => '表格：手表（灰色“（不可用）”）和分组（列表含“（在根）”和各路径），以及按钮“保存分组”（arvore relogios，一次保存全部）。',
        'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina= (os filtros no endereço)' => 'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina=（地址中的筛选）',
        'Título com "Última execução: DD/MM/AAAA HH:MM:SS". Filtros num cartão: De, Até (padrão: os últimos 7 dias), Situação (Com atividade (padrão), Com erro, Sem atividade, Todas), Texto no registro, Por página (25, 50, 100, 200), "Filtrar" e os atalhos hoje, 7 dias, 30 dias, erros do último ano.' => '标题带“最近一次执行：DD/MM/AAAA HH:MM:SS”。筛选在一张卡片中：从、到（默认：最近 7 天）、情况（有活动（默认）、有错误、无活动、全部）、记录中的文本、每页（25、50、100、200）、“筛选”以及快捷方式：今天、7 天、30 天、最近一年的错误。',
        'Resumo em 4 caixas: execuções no período, com atividade, com erro (vermelho se houver), a mais lenta. A nota com quantas e a retenção. Tabela Início (data e a hora em negrito embaixo), Duração ("850 ms" ou "1,5 s"), Situação (etiqueta erro / atividade / sem atividade), Registro (o texto em fonte fixa, ou "nada a fazer neste minuto"); linha com erro em vermelho claro. Paginação: « primeira, ‹ anterior, até 3 números de cada lado, próxima ›, última ».' => '四格摘要：时段内的执行次数、有活动、有错误（若有则为红色）、最慢的一次。说明中有数量和保留期限。表格：开始（日期，下方粗体时刻）、时长（“850 ms”或“1,5 s”）、情况（标签：错误 / 活动 / 无活动）、记录（等宽文本，或“这一分钟无事可做”）；错误行浅红底。分页：« 第一页、‹ 上一页、两侧最多 3 个数字、下一页 ›、最后一页 »。',
        'Histórico — <relógio>' => '历史 — <手表>',
        'Cabeça com a foto, "Histórico · <tipo> · código N", o nome em h1 e "<n> registros desde ...". Filtros num cartão: De, Até, Estado (Todos, Em uso, Fora do rodízio, cada tipo de sessão, Em repouso, Marcações), Por página (25, 50, 100, Todos), "Filtrar" e os atalhos 7 dias, 30 dias, desde o começo.' => '页眉带照片、“历史 · <类型> · 编号 N”、h1 中的名称以及“自……起 <n> 条记录”。筛选在一张卡片中：从、到、状态（全部、使用中、轮换之外、每种时段类型、休息中、标记）、每页（25、50、100、全部）、“筛选”以及快捷方式 7 天、30 天、从一开始。',
        'Resumo em caixas: o tempo em cada estado ("5d 7h" e "em uso · 13%") e a contagem de cada marcação. A nota de quantos e de como ler os trechos. Tabela Início, Fim, Duração, Estado (etiqueta verde para uso, vermelha para repouso, laranja para as outras sessões; marcação em cinza, só o texto; "em andamento: o fim é o momento desta consulta"). Paginação: « mais recentes, ‹ anterior, números, próxima ›, mais antigos » e "ver tudo".' => '方框摘要：每种状态的时间（“5d 7h”和“使用中 · 13%”）以及每种标记的计数。说明有多少条以及如何阅读片段。表格：开始、结束、时长、状态（使用为绿色标签，休息为红色，其他时段为橙色；标记为灰色，只有文本；“进行中：结束时刻是本次查询的时刻”）。分页：« 较新、‹ 上一页、数字、下一页 ›、较旧 » 以及“查看全部”。',
        'documentos.php?relogio=<id>&cat=<categoria> (sem relógio: de todos)' => 'documentos.php?relogio=<id>&cat=<类别>（无手表：全部的）',
        'recurso=documento (cada arquivo)' => 'recurso=documento（每个文件）',
        'documentos: enviar, alterar, excluir' => 'documentos：enviar、alterar、excluir',
        'relogio: salvar (a cópia no banco do relógio)' => 'relogio：salvar（该手表在数据库中的副本）',
        'Cabeça' => '页眉',
        'h1 "Documentos do <relógio>" (ou "de todos os relógios"); a lista "Relógio" (Todos e cada um, com "(N)") e "Abrir a ficha do relógio". A situação da cópia no banco (quem decide: o config.php, o relógio, com o botão "Guardar todos os dele no banco" / "Só os marcados"). Sem a pasta: o motivo em âmbar.' => 'h1“<手表> 的文档”（或“全部手表的”）；列表“手表”（全部以及每一只，带“（N）”）和“打开手表详情”。在数据库中的副本的情况（由谁决定：config.php、手表，带按钮“把他的全部保存在数据库中”/“只保存已标记的”）。没有文件夹：琥珀色的原因。',
        'Enviar arquivos (abre e fecha; aberto quando não há nenhum; só com um relógio escolhido)' => '上传文件（展开和收起；一个都没有时展开；仅在已选择一块手表时）',
        'Categoria (com o que ela aceita), Título ("vazio: o nome do arquivo"), Data, Descrição, Arquivos (vários; o seletor só deixa os tipos da categoria), "Guardar a cópia destes arquivos também no banco" (só quando cabe ao arquivo decidir), o limite de tamanho, "Enviar" e o andamento ("Enviando 2 de 5: foto.jpg — 40%"). Um arquivo por vez, cada foto com a miniatura feita no navegador (480px, JPEG 80%). No fim: "N documentos guardados." e os erros.' => '类别（以及它接受什么）、标题（“空：文件名”）、日期、描述、文件（多个；选择器只允许该类别的类型）、“也把这些文件的副本保存在数据库中”（仅当由文件决定时）、大小限制、“上传”以及进度（“正在上传 5 个中的第 2 个：foto.jpg — 40%”）。一次一个文件，每张照片在浏览器中生成缩略图（480px，JPEG 80%）。结束时：“已保存 N 个文档。”以及错误。',
        'Abas e conteúdo' => '标签页与内容',
        'Abas "Todos (N)" e cada categoria "(N)". Fotos: a galeria (quadrados de 140px, 100px no celular, com o título e a data) e o botão "▶ Apresentação"; tocar numa foto abre o visor em tela cheia (fundo #080b0f): "N de M", "▶ Apresentação" / "❚❚ Parar" (troca a cada 4 s), "Baixar", "×"; ‹ e › nos lados, setas do teclado, deslizar o dedo, Esc fecha, espaço liga a apresentação; a legenda embaixo.' => '标签“全部（N）”以及每个类别“（N）”。照片：图库（140px 方块，手机上 100px，带标题和日期）以及按钮“▶ 放映”；点一张照片打开全屏查看器（背景 #080b0f）：“N / M”、“▶ 放映”/“❚❚ 停止”（每 4 秒切换）、“下载”、“×”；两侧 ‹ 和 ›、键盘方向键、手指滑动、Esc 关闭、空格开关放映；说明在下方。',
        'Vídeos: o player e a lista para marcar e ordenar (↑ ↓), "▶ Assistir os marcados" (tocam em sequência; "‹ Anterior", "Próximo ›", "Fechar"). Arquivos: um cartão por arquivo com o título, a data, a categoria em etiqueta, a descrição, o nome, o tamanho e onde está guardado; PDF: "Ver aqui" (abre embutido), "Abrir noutra aba", "Baixar"; XML de NF-e: a tabela Emitente, Nota, Valor, Produto(s), Chave e "Baixar o XML"; áudio: o player; o resto: "Baixar".' => '视频：播放器以及用于勾选和排序的列表（↑ ↓）、“▶ 播放已勾选的”（按顺序播放；“‹ 上一个”、“下一个 ›”、“关闭”）。文件：每个文件一张卡片，含标题、日期、标签中的类别、描述、名称、大小以及存放位置；PDF：“在此查看”（内嵌打开）、“在另一标签页打开”、“下载”；NF-e 的 XML：表格开票方、发票、金额、产品、密钥以及“下载 XML”；音频：播放器；其余：“下载”。',
        'Cada foto (no canto de cima da miniatura), cada vídeo da lista, cada cartão de arquivo e o visor das fotos têm o botão redondo "⋮" (a dica "Abrir, baixar, editar ou excluir"): ele abre o menu Abrir (a foto no visor, o vídeo no player, o PDF e o resto noutra aba; não aparece no visor), Baixar, Editar e Excluir (em vermelho). Um menu aberto de cada vez; um clique fora ou Esc fecha. Editar abre uma janela por cima da página ("Editar <título>", o nome do arquivo, e Título, Data, Categoria, Descrição, a cópia no banco quando cabe, "Salvar" e "Cancelar"); com ela aberta, as setas e o espaço do visor não agem. Excluir mostra o que sai junto ("Sai junto: o arquivo no disco (6 KB).") e pede a confirmação; excluiu no visor, o visor fecha.' => '每张照片（缩略图的上角）、列表中的每个视频、每张文件卡片以及照片查看器都有圆形“⋮”按钮（提示“打开、下载、编辑或删除”）：它打开菜单“打开”（照片在查看器中、视频在播放器中、PDF 和其他在新标签页中；在查看器中不显示此项）、“下载”、“编辑”和“删除”（红色）。一次只打开一个菜单；点击外部或按 Esc 关闭。“编辑”在页面上方打开一个窗口（“编辑 <título>”、文件名，以及标题、日期、分类、描述、适用时的数据库副本、“保存”和“取消”）；窗口打开时，查看器的方向键和空格不起作用。“删除”显示一并删除的内容（“一并删除：磁盘上的文件（6 KB）。”）并要求确认；在查看器中删除后，查看器关闭。',
        'modos.php; ?editar=<id>#form abre um modo para alterar' => 'modos.php；?editar=<id>#form 打开一个模式进行修改',
        'recurso=cadastros (os modos, os grupos e os relógios)' => 'recurso=cadastros（模式、分组和手表）',
        'modos: novo, alterar, ativar, excluir' => 'modos: novo, alterar, ativar, excluir',
        'Os modos' => '模式',
        'h1 "Modos de rodízio" e um cartão: a explicação (cada modo tem um tipo; todos geram o mesmo roteiro; o de ontem fora, a garantia, o ciclo; escolher o modo ou o critério não mexe no plano), a tabela e o formulário ("Novo modo" ou "Alterar o modo ...", botão "Criar o modo" / "Salvar o modo" e "cancelar"). Gravou: o recado na janelinha flutuante e a edição acaba; recusado: o que foi digitado fica e os erros aparecem na janelinha.' => 'h1“轮换模式”和一张卡片：说明（每种模式有一个类型；都生成同样的脚本；昨天的排除、保证、循环；选择模式或标准不动计划）、表格和表单（“新模式”或“修改模式 ...”，按钮“创建模式”/“保存模式”和“取消”）。保存成功：浮动提示里显示消息，编辑结束；被拒绝：输入的内容保留，错误显示在浮动提示里。',
        'Tabela Modo ("(ativo)"), Tipo, Critério (a forma de escolha; "a maior nota" na escala, "todos com a mesma chance" no aleatório, "pelo roteiro" no personalizado; "· com ciclo"), Semanas (o número; na escala, o período: Uma semana, Um mês, Dois meses, Meio ano, Um ano, Dois anos), Escolhe de (por bloco: os dias e o grupo, o relógio fixo ou "todos os relógios", com "(um para o bloco)"; "pelo roteiro" no personalizado), ações (Editar; nos outros: Ativar e Excluir).' => '表格列：模式（“(激活)”）、类型、标准（选择方式；排班为“最高评分”，随机为“所有手表机会相同”，自定义为“按脚本”；“· 带循环”）、周数（数字；排班显示周期：一周、一个月、两个月、半年、一年、两年）、选自（每个区块：日子和分组、固定手表或“所有手表”，附“(整段一块)”；自定义为“按脚本”）、操作（编辑；其他模式：激活和删除）。',
        'Formulário: Nome e Tipo (a lista dos tipos; trocar o tipo remonta a tela do tipo, com o nome digitado). Um por semana: "Escolher de" (Toda a coleção, o grupo "Um grupo" com cada ponto da árvore pelo caminho, o grupo "Um relógio fixo" com cada relógio). Semana e fim de semana: dois quadros, "Segunda a sexta" e "Sábado e domingo", cada um com "Escolher de" e as caixas "um relógio para os cinco dias" / "um relógio para os dois dias" ou "um relógio por dia". Por dia da semana: uma tabela Dia / Escolher de com os sete dias (a lista tem também "Sem relógio (dia livre)"). Aleatório todo dia: "Escolher de". Escala inteligente: "Escolher de" e "Período". Personalizado: a caixa de texto "O roteiro" (monoespaçada, 10 linhas), a explicação das cinco saídas e do padrão (o roteiro_padrao da API), a lista das funções do rodízio, o botão leve "Testar em todos os relógios" com "no dia" (hoje e os 13 dias seguintes) e, embaixo, a tabela do teste (recurso=roteiro): Relógio e uma coluna por linha do roteiro e por saída (quem não é candidato em cinza), e a frase "Sairia <relógio> em DD/MM: <motivo>" ou "Nenhum relógio seria escolhido...". Ao enviar, os campos da tela viram os blocos da API (montarBlocos: um por semana e aleatório, um bloco com os sete dias; semana e fim de semana, dois; por dia da semana, um bloco por dia sem "livre").' => '表单：名称和类型（类型列表；切换类型会重建该类型的界面，保留已输入的名称）。每周一块：“选自”（整个收藏、“一个分组”组内按路径列出树的每个节点、“固定一块手表”组内列出每块手表）。工作日和周末：两个面板，“周一到周五”和“周六周日”，各有“选自”和复选项“五天一块手表”/“两天一块手表”或“每天一块手表”。按星期几：一个“日子 / 选自”表格，含七天（列表里还有“无手表（空闲日）”）。每天随机：“选自”。智能排班：“选自”和“周期”。自定义：“脚本”文本框（等宽字体，10 行）、五个输出和默认值的说明（API 的 roteiro_padrao）、轮换函数列表、轻量按钮“在所有手表上测试”附“在哪天”（今天和之后 13 天），下方是测试表格（recurso=roteiro）：手表，以及脚本每一行和每个输出各一列（非候选显示为灰色），以及句子“DD/MM 会选 <手表>：<理由>”或“没有手表会被选中...”。提交时，界面字段转为 API 的区块（montarBlocos：每周一块和随机，一个含七天的区块；工作日和周末，两个；按星期几，每天一个区块，不含“空闲”）。',
        'Depois, fora da escala, "Planejar N semanas à frente" (1 a 8) com a lista das semanas (número da semana do ano (a ISO da segunda-feira dela), do primeiro ao último dia pela semana_inicio, "(esta)" na atual; remontada ao mudar o número) e a nota de até quando o plano vem montado; nos tipos um por semana, semana e fim de semana e por dia da semana, "Critério de escolha (o sorteio)" (as quatro formas) e a nota da garantia (o valor da Configuração, que se muda no quadro Modo de rodízio); na escala, a nota "Critério de escolha: a maior nota do dia simulado"; fora do aleatório, a caixa "ciclo"; num modo pronto que já existe, o quadro que abre "O roteiro que este modo gera (só leitura)" com o roteiro efetivo e o link "copiar este roteiro" (modos.php?tipo=personalizado&copiar=<id>#form: um Personalizado novo com esse roteiro). ?tipo=<tipo> começa um modo novo desse tipo.' => '然后，排班之外，“提前规划 N 周”（1 到 8）附周列表（年度周数（按其星期一的 ISO 周），按 semana_inicio 从第一天到最后一天，当前周标“(本周)”；数字改变时重建）和计划生成到何时的注释；在每周一块、工作日和周末、按星期几类型中，“选择标准（抽签）”（四种方式）和保证的注释（设置中的值，在轮换模式面板中修改）；排班中，注释“选择标准：模拟当天的最高评分”；随机之外，“循环”复选框；在已存在的预设模式中，可展开面板“此模式生成的脚本（只读）”显示生效脚本和“复制此脚本”链接（modos.php?tipo=personalizado&copiar=<id>#form：带该脚本的新自定义模式）。?tipo=<类型> 开始一个该类型的新模式。',
        'cadastros.php?aba=<campos|lancamentos|formulas|totais|documentos>&editar=<id>#form (o ?aba=avisos antigo leva para a página Avisos; o ?aba=modos, para a página Modos de rodízio)' => 'cadastros.php?aba=<campos|lancamentos|formulas|totais|documentos>&editar=<id>#form（旧的 ?aba=avisos 会转到“提醒”页面；?aba=modos 会转到“轮换模式”页面）',
        'recurso=calcular (o testar)' => 'recurso=calcular（测试用）',
        'recurso=totais (a aba Totais e o testar dela)' => 'recurso=totais（合计标签及其测试）',
        'campos, lancamento_tipos, formulas, totais, documento_categorias' => 'campos, lancamento_tipos, formulas, totais, documento_categorias',
        'Em todas as abas' => '在所有标签页中',
        'h1 "Cadastros" e as abas Campos, Tipos de lançamento, Fórmulas, Totais, Categorias de documentos. Cada aba é um cartão: o título, a explicação, a tabela com "Editar" (link que abre o formulário embaixo com os dados, no #form) e Excluir em cada linha, e o formulário ("Novo ..." ou "Alterar ...", botão "Criar" / "Salvar" e "cancelar"). Gravou: o recado no alto e a edição acaba; recusado: o que foi digitado fica e os erros aparecem no topo.' => 'h1“定义”以及标签：字段、记录类型、公式、合计、文档类别。每个标签是一张卡片：标题、说明、表格，每行有“编辑”（链接，在下方 #form 处打开已填数据的表单）和删除，以及表单（“新建……”或“修改……”，按钮“创建”/“保存”和“取消”）。保存成功：顶部提示，编辑结束；被拒绝：所输入的内容保留，错误出现在顶部。',
        'Tabela Campo ("(unidade)"), Identificador (fonte fixa), Tipo, Vale para, Padrão, ações (Editar, ↑, ↓, Excluir com confirmação "Excluir o campo <nome> e os valores dele?"). Formulário: Nome (até 120), Identificador (a-z, 0-9 e _; começa com letra; até 40), Tipo (Número inteiro, Número decimal, Sim ou não, Data, Lista de opções, Texto), Unidade (até 20), Valor padrão, Vale para ("todos os relógios" e os grupos), Opções (lista: uma por linha).' => '表格：字段（“（单位）”）、标识符（等宽）、类型、适用于、默认、操作（编辑、↑、↓、删除，确认“删除字段 <名称> 及其值？”）。表单：名称（最多 120）、标识符（a-z、0-9 和 _；以字母开头；最多 40）、类型（整数、小数、是或否、日期、选项列表、文本）、单位（最多 20）、默认值、适用于（“全部手表”以及各分组）、选项（列表：每行一个）。',
        'Tipos de lançamento' => '记录类型',
        'Tabela Tipo, Identificador, Formato (com a unidade), Fecha sozinho às, Exclusiva, Mede o gasto, Vale quando (fonte fixa), Vale para, Lançamentos (quantos), ações. Formulário: Nome, Identificador, Formato (Instantâneo; Instantâneo com valor; Sessão, com início e fim), Unidade (com valor), Fecha sozinho às (hora; vazio: não fecha), Vale para, Vale quando (fórmula), as caixas "sessão exclusiva (o relógio num lugar só)" e "mede o gasto".' => '表格：类型、标识符、格式（带单位）、自动结束于、独占、测量消耗、何时有效（等宽）、适用于、记录（多少条）、操作。表单：名称、标识符、格式（瞬时；带数值的瞬时；时段，有开始和结束）、单位（有数值时）、自动结束于（时刻；空：不结束）、适用于、何时有效（公式）、复选框“独占时段（手表只在一个地方）”和“测量消耗”。',
        'A explicação (cada total é uma expressão sobre os relógios mostrados; vai para o rodapé, embaixo da coluna, e/ou para a página de totais, link) e a tabela Coluna ("nenhuma" em cinza), Nome, Expressão (fonte fixa), Rodapé (✓), Página (✓, "largo" pequeno), Dá agora (o resultado nos relógios todos: o texto, ou a tabelinha com o total), ações (↑ ↓ Editar Excluir). Formulário "Novo total" / "Alterar o total <nome>": Coluna (Nenhuma (só na página de totais) e as colunas da tabela), Nome (até 120), Expressão (fonte fixa, a linha toda), as caixas "Exibir no rodapé do totalizador (embaixo da coluna)" (apagada com a coluna Nenhuma) e "Exibir na página de totais", Largura na página (Estreito, Largo), Formato dos números (Número, Inteiro, Com 2 casas, Dinheiro (R$), Porcentagem (%), Data, Dias), a nota "Só os totais de uma coluna vão para o rodapé..." e os botões Criar/Salvar e "Testar em todos os relógios" (recurso=totais, parte=teste, expressao, formato: o resultado num quadro "Dá agora, em N relógios", sem gravar). Embaixo, as listas "As funções de total" e "As variáveis da tabela" (vêm da API).' => '说明（每个合计都是基于显示手表的表达式；它进入底部、列的下方，和/或合计页面，带链接）以及表格：列（灰色的“无”）、名称、表达式（等宽字体）、底部（✓）、页面（✓，小号“宽”）、当前结果（在全部手表上的结果：文本，或带合计的小表）、操作（↑ ↓ 编辑 删除）。表单“新合计”/“修改合计 <名称>”：列（无（仅在合计页面）以及表格的列）、名称（最多 120）、表达式（等宽字体，占整行）、复选框“显示在合计底部（列的下方）”（列为“无”时禁用）和“显示在合计页面”、页面上的宽度（窄、宽）、数字格式（数字、整数、两位小数、金额（R$）、百分比（%）、日期、天数）、说明“只有属于某列的合计才会进入底部……”以及按钮创建/保存和“在所有手表上测试”（recurso=totais、parte=teste、expressao、formato：结果显示在方框“当前结果，N 块手表”中，不保存）。下方是列表“合计函数”和“表格变量”（来自 API）。',
        'Fórmulas' => '公式',
        'Tabela Fórmula (o nome e o identificador com a unidade), Versão para, Cálculo (fonte fixa), ações. Formulário: Identificador (só na nova), Nome, Unidade, Versão para, Cálculo (textarea, fonte fixa). "Testar uma fórmula (sem gravar)": o texto da fórmula e "Testar em todos os relógios" (recurso=calcular): a tabela Relógio, Resultado, As partes da conta, ou os erros. "As funções do motor" (abre e fecha): cada função em negrito e a explicação.' => '表格：公式（名称和带单位的标识符）、版本适用于、计算（等宽）、操作。表单：标识符（仅新建）、名称、单位、版本适用于、计算（textarea，等宽）。“测试一个公式（不保存）”：公式文本和“在全部手表上测试”（recurso=calcular）：表格手表、结果、计算的各部分，或错误。“引擎的函数”（展开和收起）：每个函数加粗并附说明。',
        'Categorias de documentos' => '文档类别',
        'Tabela Categoria, Identificador, Aceita ("qualquer arquivo" ou as famílias), Ordem, Documentos, ações (Excluir só sem documentos). Formulário: Nome, Identificador (na nova), Ordem ("vazio: no fim"), Aceita (caixas imagens, vídeos, áudios, PDF, XML).' => '表格：类别、标识符、接受（“任意文件”或各系列）、顺序、文档、操作（仅在没有文档时才能删除）。表单：名称、标识符（新建时）、顺序（“空：放在末尾”）、接受（复选框：图像、视频、音频、PDF、XML）。',
        'usuarios: salvar, alterar, oficializar, prorrogar, voltar_demo, bloquear, transferir, dar_acesso, excluir' => 'usuarios: salvar, alterar, oficializar, prorrogar, voltar_demo, bloquear, transferir, dar_acesso, excluir',
        'O painel do master' => 'master 面板',
        'h1 "Usuários". Cartão "Contas (N)": a tabela Login (com os selos "master" em azul, "demo" e "bloqueada" e "você"), E-mail, Criada em, Último acesso, Vence (a data e "(N dias)", ou "não vence"), Coleções (cada uma com "(N relógios)"), Vê também (as coleções de outros e "tudo de <dono>") e, à direita, "Ações", que abre: "Ver como <login>" (grava o cookie como e abre o Hoje como ele), "Tornar oficial" (na demo) ou "Voltar a demo (dias)", "Prorrogar (dias)", "Bloquear"/"Desbloquear", o quadro Alterar (Login, E-mail, Idioma, Fuso horário (O da coleção, O do navegador dele e os fusos do PHP), Papel, "Salvar"), a senha nova com "Trocar a senha", "Transferir a coleção" (a coleção e o novo dono), "Dar acesso" (uma coleção de outro ou "Tudo de <dono>") e "Excluir" (mostra o que sai junto: as coleções, os relógios, os arquivos).' => 'h1“用户”。卡片“账户（N）”：表格包含登录名（带徽章：蓝色的“master”、“演示”、“已封禁”和“你”）、电子邮件、创建时间、最后访问、到期（日期和“（N 天）”，或“不会到期”）、收藏（每个带“（N 块手表）”）、还能看到（他人的收藏和“<dono> 的全部”），右侧是“操作”，展开后有：“以 <login> 身份查看”（保存 como cookie 并以他的身份打开今天页面）、“转为正式”（演示账户）或“改回演示（天）”、“延长（天）”、“封禁”/“解除封禁”、修改面板（登录名、电子邮件、语言、时区（收藏的、他浏览器的以及 PHP 的时区）、角色、“保存”）、新密码及“修改密码”、“转移收藏”（收藏和新所有者）、“授予访问权限”（他人的一个收藏或“<dono> 的全部”）以及“删除”（显示一并删除的内容：收藏、手表、文件）。',
        'Cartão "Criar conta": Login, Senha (pelo menos 6 caracteres), E-mail, Coleção (uma com o conjunto inicial; uma vazia; nenhuma), a nota "A conta criada aqui é oficial (não vence). Se o login já existir, só a senha dele é trocada." e "Criar conta".' => '卡片“创建账户”：登录名、密码（至少 6 个字符）、电子邮件、收藏（带初始集合的；空的；不建），说明“在这里创建的账户是正式账户（不会到期）。如果登录名已存在，只会修改其密码。”以及“创建账户”。',
        'Quem não é o master vê só "Só o administrador (master) cuida das contas. As suas coisas ficam em Minha conta.".' => '不是 master 的人只会看到“只有管理员（master）管理账户。你的内容在“我的账户”中。”。',
        'conta.php; ?convite=<token> aceita o convite ao abrir' => 'conta.php；?convite=<token> 在打开时接受邀请',
        'recurso=conta' => 'recurso=conta',
        'recurso=cadastro (a lista das coleções e dos donos)' => 'recurso=cadastro（收藏和所有者的列表）',
        'conta: alterar, token_criar, token_revogar, aparelho_lembrar, aparelho_esquecer, push_inscrever, push_cancelar, push_testar, email_testar, vapid_gerar, excluir' => 'conta: alterar, token_criar, token_revogar, aparelho_lembrar, aparelho_esquecer, push_inscrever, push_cancelar, push_testar, email_testar, vapid_gerar, excluir',
        'colecoes: criar, renomear, excluir, arvore_copiar, arvore_renomear, arvore_excluir' => 'colecoes: criar, renomear, excluir, arvore_copiar, arvore_renomear, arvore_excluir',
        'pedidos: pedir, cancelar' => 'pedidos: pedir, cancelar',
        'acessos: sair' => 'acessos: sair',
        'convites: aceitar' => 'convites: aceitar',
        'Coleções' => '收藏',
        'Tabela Coleção, Código (o id, que o dono passa a quem quer pedir acesso), Dono, Você é (sua, membro, master) e as ações: "Abrir" (grava o cookie colecao) ou "aberta"; nas suas, "Renomear" (abre o nome e "Salvar") e "Excluir" (mostra o que sai junto); nas dos outros, "Sair". Sem nenhuma: o aviso âmbar "Você ainda não vê nenhuma coleção: crie uma aqui embaixo, ou peça acesso à de alguém (e espere a aprovação)." Embaixo da tabela, a nota "Para alguém pedir acesso a uma coleção sua, passe o código dela...". Depois, "Nova coleção": Nome, Começa (com o conjunto inicial; vazia; com uma árvore minha que já existe, que abre a escolha da Árvore) e "Criar coleção" (a nova passa a ser a do menu).' => '表格：收藏、编号（id，所有者把它给想申请访问的人）、所有者、你的身份（自己的、成员、master）以及操作：“打开”（保存 colecao cookie）或“已打开”；自己的收藏有“重命名”（展开名称和“保存”）和“删除”（显示一并删除的内容）；他人的收藏有“退出”。一个都没有时：琥珀色提示“你还看不到任何收藏：在下面创建一个，或申请访问别人的收藏（并等待批准）。”表格下方是说明“要让别人申请访问你的某个收藏，把该收藏的编号给他……”。再下面是“新收藏”：名称、起点（带初始集合；空的；使用我已有的一棵树，此时展开树的选择）以及“创建收藏”（新收藏成为菜单中的当前收藏）。',
        'Árvores de grupos' => '分组树',
        'Só quando há: a explicação ("A árvore guarda os grupos e o cadastro deles... Uma árvore pode servir a várias coleções suas: o que muda nela vale para todas.") e a tabela Árvore, Grupos, Usada por, com "Renomear ou copiar" (o nome e "Renomear"; "Cópia de <nome>" e "Copiar") e "Excluir" (mostra as coleções que saem junto).' => '仅在有树时显示：说明（“树保存分组及其定义……一棵树可以供你的多个收藏使用：对它的修改对所有收藏生效。”）以及表格：树、分组、使用者，带“重命名或复制”（名称和“重命名”；“<nome> 的副本”和“复制”）以及“删除”（显示一并删除的收藏）。',
        'Pedir acesso' => '申请访问',
        'Os pedidos esperando (O quê, Pedido em, Vence em, "Cancelar"), quantos convites há para o seu e-mail ("aceite pelo link que chegou nele"), e o formulário: Acesso a ("uma coleção (o código da coleção)" ou "todas as coleções de um dono (o código do dono)"), Código (número), o quadro recolhido "Como pedir acesso (e por que pelo código)" (uma lista numerada: por que o código, como pedir o código ao dono e onde ele o encontra, o que preencher, o que acontece depois), Recado para o dono e "Pedir acesso". Nenhuma lista de contas nem de coleções; os pedidos esperando mostram só o código ("a coleção de código 7") até a aprovação. A nota "O dono (ou o administrador) aprova...".' => '等待中的申请（内容、申请时间、到期时间、“取消”），有多少邀请发往你的电子邮件（“通过邮件中的链接接受”），以及表单：访问对象（“一个收藏（收藏的编号）”或“某个所有者的所有收藏（所有者的编号）”）、编号（数字）、折叠的框“如何申请访问（以及为什么用编号）”（编号列表：为什么用编号、如何向所有者索取编号以及他在哪里找到、填写什么、之后会发生什么）、给所有者的留言和“申请访问”。没有任何账户或收藏的列表；等待中的申请在批准前只显示编号（“编号为 7 的收藏”）。说明“所有者（或管理员）批准……”。',
        'Seus dados' => '你的资料',
        'Login, os selos master e demonstração, desde quando e "seu código: N" (o id, para pedirem acesso a todas as suas coleções), e a nota "Alguém quer ver as suas coleções? Passe o seu código..." (como passar o código e o que acontece depois); na demonstração, o aviso âmbar "Conta de demonstração: vence em N dias (data)..."; o formulário E-mail, Idioma (O da coleção e os seis), Fuso horário (largo: "O da coleção (<fuso>)" ou "O do sistema (<fuso>)", "O do navegador (neste aparelho: <fuso do aparelho>)" e todos os fusos do PHP com o deslocamento), Senha atual (só para trocar a senha), Senha nova, a nota (o e-mail, a senha, e "O fuso horário vale para tudo o que você vê e digita...; O dia do rodízio (o plano, o relógio do dia, as rodadas) é sempre o da coleção. Agora: <fuso em vigor>") e "Salvar". Gravou (aqui e em todos os quadros da página): o recado na janelinha flutuante embaixo da tela (clara, borda safira, o botão ×; some sozinha em 6 s; os erros, com borda vermelha, ficam até fechar) e a página remontada sem sair do lugar, a rolagem onde estava (salvarSemMover, api.js). Outro idioma na conta: o cookie lingua passa a ele e lingua_auto some (em "O da coleção", os dois somem) e a página abre de novo no idioma que vale agora, com o recado na janelinha.' => '登录名、master 和演示徽章、注册时间以及“你的编号：N”（id，供别人申请访问你的全部收藏），以及说明“有人想看你的收藏？把你的编号给他……”（如何提供编号以及之后会发生什么）；演示账户显示琥珀色提示“演示账户：N 天后到期（日期）……”；表单：电子邮件、语言（收藏的语言及六种语言）、时区（宽：“收藏的（<时区>）”或“系统的（<时区>）”、“浏览器的（本设备：<设备时区>）”以及 PHP 的所有时区带偏移）、当前密码（仅在修改密码时）、新密码、说明（电子邮件、密码，以及“时区适用于你查看和输入的一切……轮换的日子（计划、当日手表、各轮次）始终以收藏为准。当前：<生效的时区>”）和“保存”。保存后（此处以及页面上的所有方框）：消息显示在屏幕底部的浮动小窗口中（浅色，蓝宝石色边框，带 × 按钮；6 秒后自动消失；错误为红色边框，保留到关闭为止），页面原地重新构建，滚动位置保持不变（salvarSemMover，api.js）。账户换了另一种语言时：lingua cookie 改为该语言、lingua_auto 被删除（选“收藏的”时两者都删除），页面以现在生效的语言重新打开，消息显示在小窗口中。',
        'Aplicativo no celular' => '手机上的应用',
        'A nota ("O sistema vira um aplicativo no seu celular ou tablet: um ícone na tela inicial, abrindo em tela cheia, entrando sem pedir a senha e recebendo as notificações. Três passos...") e a lista numerada: 1. Lembrar este aparelho (o botão, com o nome do aparelho montado do navegador: "Android Chrome", "iPhone Safari"; lembrado, "Este aparelho está lembrado desde DD/MM/AAAA: o aplicativo (e este navegador) entra sem pedir a senha." e "Esquecer este aparelho"); 2. Instalar (dentro do aplicativo, "Você já está no aplicativo."; com o pedido de instalação do navegador guardado pelo api.js (beforeinstallprompt), o botão "Instalar o aplicativo"; no iPhone e no iPad, o caminho do Safari (Compartilhar, Adicionar à Tela de Início); senão, o do menu do navegador); 3. Ligar as notificações (o link para o quadro Notificações neste aparelho; no iPhone, só de dentro do aplicativo). Embaixo, com algum, "Os aparelhos lembrados (trocar a senha esquece todos):" e a tabela Aparelho lembrado (com "(este)" no deste navegador), Desde, Último uso e "Esquecer".' => '说明（“系统会变成你手机或平板上的应用：主屏幕上的图标、全屏打开、无需密码进入并接收通知。三步……”）和编号列表：1. 记住此设备（按钮，设备名由浏览器生成：“Android Chrome”“iPhone Safari”；已记住时显示“此设备自 DD/MM/YYYY 起已被记住：应用（和此浏览器）无需密码即可进入。”和“忘记此设备”）；2. 安装（在应用内显示“你已经在应用中。”；api.js 保存了浏览器的安装提示（beforeinstallprompt）时显示“安装应用”按钮；在 iPhone 和 iPad 上显示 Safari 的路径（共享，添加到主屏幕）；否则显示浏览器菜单的路径）；3. 开启通知（指向“此设备上的通知”框的链接；在 iPhone 上只能从应用内）。下方，若有，显示“已记住的设备（更改密码会忘记全部）：”和表格 已记住的设备（此浏览器的带“（此设备）”）、自、最近使用和“忘记”。',
        'Tokens de API' => 'API 令牌',
        'A explicação (cabeçalho X-Api-Token; vale como o seu login; só aparece ao criar); o token recém-criado numa caixa tracejada em fonte fixa (para copiar); a tabela Nome, Criado em, Último uso e "Revogar"; o formulário com o nome ("onde vai usar") e "Criar token".' => '说明（X-Api-Token 请求头；等同于你的登录；只在创建时出现）；刚创建的令牌显示在等宽字体的虚线框中（便于复制）；表格：名称、创建时间、最后使用和“撤销”；表单：名称（“将在哪里使用”）和“创建令牌”。',
        'Notificações neste aparelho (Web Push)' => '此设备上的通知（Web Push）',
        'Sem as chaves no servidor, o aviso âmbar; sem suporte no navegador, a nota (no iPhone, adicionar à tela de início); senão "Receber notificações neste aparelho" (pede a permissão, registra o service worker (api.php?recurso=sw) e inscreve). A tabela dos aparelhos (Aparelho, Desde, "Desligar") e "Mandar uma notificação de teste". Para o master, "Chaves do Web Push (master)": "Gerar chaves" mostra as duas linhas para o config.php.' => '服务器没有密钥时显示琥珀色提示；浏览器不支持时显示说明（在 iPhone 上需添加到主屏幕）；否则显示“在此设备上接收通知”（请求权限、注册 service worker（api.php?recurso=sw） 并订阅）。设备表格（设备、开始时间、“关闭”）以及“发送一条测试通知”。对 master 还有“Web Push 密钥（master）”：“生成密钥”显示写入 config.php 的两行。',
        'Servidor de e-mail (só o master)' => '邮件服务器（仅限 master）',
        'A nota (de onde o sistema tira o e-mail e para que ele serve), a tabela Parte | O que o sistema leu do config.php (Método: SMTP, mail() ou "desligado" em negrito; Remetente; SMTP (envio): host:porta, a segurança, o usuário, "senha definida" ou "sem senha"; IMAP (cópia em Enviados) e POP (só o teste da conta): o mesmo, ou "não configurado (opcional)"), o aviso âmbar "Para corrigir no config.php:" com a lista dos problemas (se houver) e, com o envio ligado, "Testar as conexões (sem mandar nada)", o formulário "para quem" + "Mandar um e-mail de teste" e a nota do que o teste faz. Depois de um teste, a página para nele: "Resultado do teste", cada parte (SMTP, IMAP, POP, E-mail de teste) com o selo "ok" (verde) ou "falhou" (vermelho) e o erro, e "Conversa com os servidores" aberta, em fonte fixa (o que vai com ">", o que volta com "<", a senha e o usuário em base64 trocados pela descrição).' => '说明（系统从哪里发送电子邮件以及用途），表格 部分 | 系统从 config.php 读到的内容（方式：SMTP、mail() 或加粗的“已关闭”；发件人；SMTP（发送）：host:端口、安全方式、用户、“已设置密码”或“没有密码”；IMAP（在“已发送”中保存副本）和 POP（仅用于测试账户）：同上，或“未配置（可选）”），琥珀色提示“需要在 config.php 中修改：”及问题列表（如果有），以及在发送开启时显示“测试连接（不发送任何内容）”、表单“发给谁”+“发送一封测试邮件”和关于测试内容的说明。测试之后，页面停在测试处：“测试结果”，每个部分（SMTP、IMAP、POP、测试邮件）带“正常”（绿色）或“失败”（红色）标记和错误，以及展开的“与服务器的对话”，用等宽字体显示（发出的以“>”开头，返回的以“<”开头，密码和 base64 编码的用户名用说明代替）。',
        'Excluir a conta' => '删除账户',
        'A explicação do que sai e "Excluir a minha conta" (botão vermelho; a API mostra tudo o que sai junto e pede a confirmação; depois, vai para o cadastro).' => '说明会删除什么，以及“删除我的账户”（红色按钮；API 会显示一并删除的全部内容并要求确认；之后转到注册页面）。',
        'Aprovações e convites' => '审批与邀请',
        'aprovacoes.php' => 'aprovacoes.php',
        'recurso=aprovacoes' => 'recurso=aprovacoes',
        'recurso=conta, parte=menu (o seu login)' => 'recurso=conta, parte=menu（你的登录名）',
        'pedidos: aprovar, recusar' => 'pedidos: aprovar, recusar',
        'convites: convidar, aprovar, recusar, reenviar, cancelar' => 'convites: convidar, aprovar, recusar, reenviar, cancelar',
        'acessos: remover' => 'acessos: remover',
        'Tudo' => '全部',
        'h1 "Aprovações e convites". "Pedidos de acesso": Quem (o login e o e-mail), Pede, Recado, Vence em, "Aprovar" e "Recusar" (ou "Nenhum pedido esperando."). "Convites esperando a sua aprovação" (só quando há): E-mail, Quem convidou, Para, Vence em, "Aprovar e enviar", "Recusar". "Convidar": a explicação (o link vale N dias; quem não tem conta cria pelo link; o convite de um membro espera o dono), sem e-mail no servidor o aviso âmbar (o link aparece aqui, numa caixa para copiar), E-mail, Para ver (as coleções que você vê e "Tudo meu") e "Convidar". "Convites que você fez": E-mail, Para, Situação (enviado, esperando o dono), Vence em, "Reenviar" e "Cancelar". "Quem vê as suas coleções": Quem, Vê, Desde e "Tirar o acesso" (confirma) ou "Só você.".' => 'h1“审批与邀请”。“访问请求”：申请人（登录名和电子邮件）、申请内容、留言、到期时间、“批准”和“拒绝”（或“没有等待中的请求。”）。“等待你批准的邀请”（仅在有时显示）：电子邮件、邀请人、对象、到期时间、“批准并发送”、“拒绝”。“邀请”：说明（链接有效 N 天；没有账户的人通过链接创建；成员的邀请需等待所有者），服务器没有电子邮件时显示琥珀色提示（链接会显示在这里的框中供复制），电子邮件、可查看（你看到的收藏和“我的全部”）以及“邀请”。“你发出的邀请”：电子邮件、对象、状态（已发送、等待所有者）、到期时间、“重新发送”和“取消”。“谁能看到你的收藏”：谁、可看、开始时间以及“取消访问权限”（需确认），或“只有你。”。',
        'Criar conta' => '创建账户',
        'cadastro.php; ?convite=<token> (o convite); ?senha=<token> (a senha nova)' => 'cadastro.php；?convite=<token>（邀请）；?senha=<token>（新密码）',
        'recurso=cadastro (sem login)' => 'recurso=cadastro（无需登录）',
        'cadastro: criar_conta, esqueci_senha, nova_senha' => 'cadastro: criar_conta, esqueci_senha, nova_senha',
        'A página pública: sem menu (só o idioma), sem login. Normal: h1 "Criar conta", o formulário Login (sem dois-pontos), Senha, E-mail (largo), Idioma, "Para começar" (Uma coleção minha, com o conjunto inicial; Uma coleção minha, vazia; Pedir acesso à coleção de alguém, que abre Acesso a, Código, o quadro "Como pedir acesso (e por que pelo código)" já aberto e Recado, como em Minha conta: pelo código que o dono passou, sem nenhuma lista de contas), a nota da demonstração ("A conta nova é de demonstração por N dias...") e "Criar conta"; "Já tem conta? Entrar"; e "Esqueci a senha" (o e-mail ou o login e "Mandar o link"; sem e-mail no servidor, a nota). Cadastro fechado: o aviso âmbar. Com convite: "Você foi convidado para ver <alvo>.", "Já tem conta? Entre e aceite o convite" (conta.php?convite=...) e, se o e-mail não tem conta, o formulário com o e-mail já preenchido e a caixa "Criar também uma coleção minha". Com o link da senha: "Senha nova" e "Trocar a senha". Depois de criar ou trocar: "Pronto", a mensagem e o botão "Entrar".' => '公开页面：没有菜单（只有语言），无需登录。普通情况：h1“创建账户”，表单包含登录名（不含冒号）、密码、电子邮件（宽）、语言、“开始方式”（我的收藏，带初始集合；我的收藏，空的；申请访问别人的收藏，此时展开访问对象、编号、已展开的框“如何申请访问（以及为什么用编号）”和留言，与“我的账户”中相同：凭所有者给出的编号，没有任何账户列表）、演示说明（“新账户为演示账户，有效 N 天……”）以及“创建账户”；“已有账户？登录”；以及“忘记密码”（电子邮件或登录名和“发送链接”；服务器没有电子邮件时显示说明）。注册关闭时：琥珀色提示。带邀请时：“你被邀请查看 <alvo>。”、“已有账户？登录并接受邀请”（conta.php?convite=...），如果该电子邮件没有账户，则显示已填好电子邮件的表单和复选框“同时创建一个我自己的收藏”。带密码链接时：“新密码”和“修改密码”。创建或修改之后：“完成”、消息和“登录”按钮。',
        'Destinos' => '推送目标',
        'destinos.php#destino-<id>' => 'destinos.php#destino-<id>',
        'recurso=destinos' => 'recurso=destinos',
        'destinos: salvar, testar, excluir' => 'destinos: salvar, testar, excluir',
        'h1 "Destinos das mensagens", os links "← Configuração" e "Agendas" e a explicação. Cada destino num cartão (id destino-<id>): Nome, Ligado, Idioma (O da coleção e os seis), Fuso horário (das horas no texto) (O da coleção e os fusos do PHP com o deslocamento), o que é do tipo (o webhook: Método, Endereço, A mensagem vai (na URL, como formulário, como JSON), a tabela dos Campos com duas linhas vazias, o Corpo JSON, a tabela dos Cabeçalhos, com o valor escondido ("(guardado; vazio mantém)"); o e-mail: Para, e o aviso âmbar sem e-mail no servidor; o Web Push: Para os aparelhos de (quem vê a coleção), quantos aparelhos, o link para Minha conta, e o aviso âmbar sem as chaves), a Mensagem padrão com "Inserir âncora", "O que recebe" (a tabela Recebe, Aviso, Quando, Texto: a caixa de cada tipo e o "Personalizar" que abre o texto próprio com "Inserir âncora"), "Salvar", "Mandar um teste", "Mandar a da manhã agora", "Mandar a da noite agora", "Excluir", e "Como sai hoje" (De manhã, À noite, o texto em fonte fixa ou "(nada a enviar)"). No fim, "Novo destino": o tipo e o nome, "Criar".' => 'h1“消息推送目标”，链接“← 设置”和“日历”以及说明。每个推送目标一张卡片（id destino-<id>）：名称、启用、语言（收藏的语言及六种语言）、时区（文本中的时间）（收藏的以及 PHP 的时区带偏移）、该类型特有的内容（webhook：方法、地址、消息发送方式（在 URL 中、作为表单、作为 JSON）、带两行空行的字段表、JSON 正文、请求头表，值被隐藏（“（已保存；留空则保留）”）；电子邮件：收件人，服务器没有电子邮件时显示琥珀色提示；Web Push：发往其设备的用户（能看到该收藏的人）、设备数量、“我的账户”的链接，没有密钥时显示琥珀色提示）、带“插入占位符”的默认消息、“接收内容”（表格：接收、提醒、时间、文本：每种类型的复选框和“自定义”，后者展开带“插入占位符”的专用文本）、“保存”、“发送测试”、“现在发送早晨的消息”、“现在发送晚上的消息”、“删除”，以及“今天会发出什么”（早上、晚上，等宽字体的文本或“（没有要发送的）”）。最后是“新推送目标”：类型和名称，“创建”。',
        'Agendas' => '日历',
        'agendas.php#agenda-<id>; ?recado=<texto> (a volta da Microsoft)' => 'agendas.php#agenda-<id>；?recado=<texto>（从 Microsoft 返回）',
        'recurso=agendas' => 'recurso=agendas',
        'agendas: salvar, sincronizar, teste_criar, teste_remover, novo_link, outlook_conectar, excluir' => 'agendas: salvar, sincronizar, teste_criar, teste_remover, novo_link, outlook_conectar, excluir',
        'h1 "Agendas", os links "← Configuração" e "Destinos" e a explicação ("...O cron sincroniza de manhã e à noite; o link ICS o app de agenda lê quando quiser."). Cada agenda num cartão: Nome, Ligada, Eventos até quantos dias à frente, Idioma, Fuso horário (das horas no texto) (O da coleção e os fusos do PHP), o que é do tipo (Google: ID da agenda e a chave, o JSON colado; o caminho no servidor só o master; CalDAV: Endereço do calendário, Usuário, Senha, com a dica do Nextcloud, do iCloud e do Fastmail; Outlook: a conta conectada ou não, o calendário, "Conectar ao Outlook" (vai para a Microsoft e volta com o recado), e sem o aplicativo no servidor o aviso âmbar; link ICS: o link para assinar, com as dicas do Google, do Outlook e do iPhone, e "Trocar o link", que confirma), o Modelo do evento com "Inserir âncora" ("A primeira linha é o título do evento; o resto, a descrição."), "O que recebe", "Salvar", "Sincronizar agora", "Criar evento de teste" / "Remover evento de teste", "Excluir", e "O que tem de estar nela agora" (a data, a hora, o título e a descrição dos primeiros eventos, ou "Nada previsto no período."). No fim, "Nova agenda": o tipo e o nome, "Criar".' => 'h1“日历”，链接“← 设置”和“推送目标”以及说明（“……cron 每天早晚同步；ICS 链接由日历应用随时读取。”）。每个日历一张卡片：名称、启用、事件提前多少天、语言、时区（文本中的时间）（收藏的以及 PHP 的时区）、该类型特有的内容（Google：日历 ID 和密钥，即粘贴的 JSON；服务器上的路径仅限 master；CalDAV：日历地址、用户名、密码，附 Nextcloud、iCloud 和 Fastmail 的提示；Outlook：账户是否已连接、日历、“连接到 Outlook”（前往 Microsoft 并带着提示返回），服务器没有应用时显示琥珀色提示；ICS 链接：订阅链接，附 Google、Outlook 和 iPhone 的提示，以及需确认的“更换链接”）、带“插入占位符”的事件模板（“第一行是活动标题；其余是描述。”）、“接收内容”、“保存”、“立即同步”、“创建测试事件”/“删除测试事件”、“删除”，以及“现在应该在其中的内容”（前几个事件的日期、时间、标题和描述，或“该时段内没有安排。”）。最后是“新日历”：类型和名称，“创建”。',
        'ajuda.php#<âncora>' => 'ajuda.php#<锚点>',
        'recurso=manual (o HTML e o sumário)' => 'recurso=manual（HTML 和目录）',
        'h1 "Ajuda"; "Nesta página": o sumário com os títulos de nível 2 e 3 (recuados), cada um link para a sua âncora; depois o manual em HTML, com as tabelas que rolam de lado no celular, as imagens com borda e cantos, o código em fonte fixa. Abrindo com uma âncora no endereço, a página vai direto para ela.' => 'h1“帮助”；“本页”：目录含 2 级和 3 级标题（缩进），每一个都链接到其锚点；然后是 HTML 手册，表格在手机上可横向滚动，图像有边框和圆角，代码为等宽字体。地址中带锚点打开时，页面直接跳到该处。',
        'a página Hoje no computador, com o painel ao lado' => '电脑上的今天页面，面板在旁边',
        'a tabela dos relógios com as 12 colunas e os filtros' => '带 12 列和筛选的手表表',
        'o histórico de um relógio' => '一块手表的历史',
        'a aba Campos dos Cadastros' => '定义中的字段标签',
        'no celular: a Hoje, os cartões dos relógios e o painel em tela cheia' => '在手机上：今天、手表卡片和全屏面板',
        'a base de todas as páginas: topo() (antes de tudo, o login: pagina_login(); depois o head, o menu e o título) e rodape() (os scripts, com a data do arquivo na URL)' => '所有页面的基础：topo()（首先是登录：pagina_login()；然后是 head、菜单和标题）和 rodape()（脚本，URL 中带文件日期）',
        'o estilo de todas as páginas: as cores, as letras, os controles, os componentes e os tamanhos de tela' => '所有页面的样式：颜色、字体、控件、组件和屏幕尺寸',
        'a base do JavaScript das páginas: os textos no idioma (t(), com o dicionário de recurso=textos), ler e gravar pela API, os formatos do idioma (número, dinheiro, data, hora), o login, os formulários que gravam, gravar sem sair do lugar (salvarSemMover: a posição guardada antes do toque no botão e devolvida depois de remontar, e o recado na janelinha flutuante, avisoFlutuanteGravacao; avisoAoAbrir guarda o recado para depois de um reload; seguirIdiomaPadrao e reabrirNoIdioma cuidam dos cookies do idioma), as tabelas que viram fichas no celular, e o atualizarSozinho (a página lê tudo de novo a cada ATUALIZAR_SEGUNDOS, o atualizar_segundos de recurso=conta&parte=menu (a Configuração; 0: nunca; padrão 60), olhando de até 5 em 5 s, com a aba à mostra e na volta a ela; não com um campo de texto em foco, um formulário de gravação mexido e não gravado (data-mexido), uma gravação em andamento ou o que a página disser; a rolagem fica): Hoje (com o painel aberto; não com o quadro do modo aberto), Ficha, Plano, Totais e Histórico; e o porHtml, que põe o HTML novo de um bloco sem piscar (compara com o que está na tela e muda só os textos, os atributos e os nós que mudaram, achando as linhas pela chave data-id ou id; os campos ficam com o valor do HTML novo; as fotos com o mesmo endereço ficam, sem baixar de novo), usado pelos blocos que se atualizam (o destaque, os avisos e os próximos dias da Hoje, as linhas e o rodapé da tabela, o painel, o Plano, os Totais e o Histórico)' => '页面 JavaScript 的基础：语言中的文本（t()，带 recurso=textos 的词典）、通过 API 读取和写入、语言的格式（数字、金钱、日期、时刻）、登录、用于保存的表单、原地保存（salvarSemMover：在点击按钮前记下位置并在重新构建后恢复，消息显示在浮动小窗口 avisoFlutuanteGravacao 中；avisoAoAbrir 把消息保留到 reload 之后；seguirIdiomaPadrao 和 reabrirNoIdioma 负责语言 cookie）、在手机上变成档案卡的表格，以及 atualizarSozinho（页面每隔 ATUALIZAR_SEGUNDOS 秒重新读取全部数据，即 recurso=conta&parte=menu 的 atualizar_segundos（设置；0：从不；默认 60），最多每 5 秒检查一次，仅在标签页可见时以及回到该标签页时；文本框有焦点、写入表单有未保存的修改（data-mexido）、正在写入或页面另有说明时不刷新；滚动位置保持不变）：今天（含打开的面板；轮换模式框打开时不刷新）、手表卡片、计划、合计和历史；以及 porHtml，它在不闪烁的情况下放入一个块的新 HTML（与屏幕上现有的内容比较，只改变有变化的文本、属性和节点，按 data-id 或 id 键找到各行；字段取新 HTML 的值；地址相同的照片保持不变，不会重新下载），用于会自动刷新的块（今天页面的突出显示、提醒和接下来的日子，表格的行和底部，面板，计划，合计和历史）',
        'os idiomas: a lista (LINGUAS: o nome, o código curto do menu, o locale e os formatos da data e dos números), o idioma do pedido, t() e os formatos no PHP' => '各语言：列表（LINGUAS：名称、菜单短代码、locale 以及日期和数字格式）、请求的语言、t() 以及 PHP 中的格式',
        'o arquivo de um idioma (en, zh-CN, hi, es, fr): o texto em português => a tradução, por parte (telas, api, ajuda, manual, reconstrucao), gerado e conferido por testes/textos.php; o que falta sai em português, ou para com erro no modo estrito (TEXTOS_ESTRITO)' => '一种语言的文件（en、zh-CN、hi、es、fr）：葡萄牙语文本 => 译文，按部分（telas、api、ajuda、manual、reconstrucao），由 testes/textos.php 生成并核对；缺少的以葡萄牙语输出，或在严格模式（TEXTOS_ESTRITO）下因错误停止',
        'o esqueleto da página Hoje (o meio, a tabela dos relógios com os títulos e os filtros, e o painel)' => '今天页面的骨架（中间、带标题和筛选的手表表，以及面板）',
        'a página Hoje: o relógio do dia, os avisos de hoje, os próximos dias, o modo de rodízio e as linhas da tabela dos relógios' => '今天页面：当天的手表、今天的提醒、接下来的日子、轮换模式以及手表表的各行',
        'a tabela dos relógios: ordenar, filtrar, virar cartões quando as 12 colunas não cabem e os totais do rodapé (recurso=totais)' => '手表表格：排序、筛选、12 列放不下时变成卡片，以及底部的合计（recurso=totais）',
        'o painel do relógio (na página Hoje e na Ficha): os quadros, o Marcar, o Editar cadastro, o gráfico da carga, os dados e o histórico' => '手表面板（在今天页面和详情中）：各框、标记、编辑档案、电量图、数据和历史',
        'a foto reduzida no navegador antes de enviar (1200 px, JPEG 85%), com a prévia' => '发送前在浏览器中缩小的照片（1200 px，JPEG 85%），带预览',
        'a página Ficha do relógio: o painel do relógio numa página própria' => '手表详情页：手表面板在单独的页面上',
        'o esqueleto da página Plano' => '计划页面的骨架',
        'a página Plano: o resumo do período e o dia a dia, mês a mês' => '计划页面：时段摘要以及逐日，按月',
        'o esqueleto da página Configuração' => '设置页面的骨架',
        'a página Configuração: o banco desatualizado, os quadros das opções, o resumo dos avisos e das mensagens (o caminho para a página Avisos) e a cópia de segurança' => '设置页面：数据库过期提示、各选项框、提醒和消息的摘要（通往“提醒”页面的路径）以及备份',
        'o esqueleto da página Avisos' => '“提醒”页面的骨架',
        'a página Avisos: os avisos dos relógios (o cadastro), os lembretes (os eventos personalizados) e para onde vão (os destinos e as agendas)' => '“提醒”页面：手表提醒（定义）、定时提醒（自定义事件）以及发往何处（目的地和日历）',
        'o esqueleto da página Critérios' => '标准页面的骨架',
        'a página Critérios: as explicações, os lugares, os parâmetros, os subparâmetros, as faixas e a nota de cada relógio' => '标准页面：说明、位置、参数、子参数、区间以及每块手表的分数',
        'o esqueleto da página Grupos' => '分组页面的骨架',
        'a página Grupos: a árvore e o grupo de cada relógio' => '分组页面：树以及每块手表的分组',
        'o esqueleto da página Execuções do cron' => 'cron 执行页面的骨架',
        'a página Execuções do cron: os filtros, o resumo, a tabela e a paginação' => 'cron 执行页面：筛选、摘要、表格和分页',
        'o esqueleto da página Desejos' => '心愿单页面的骨架',
        'a página Desejos: a lista de desejos (com o Comprei) e os relógios fora da coleção' => '心愿单页面：心愿列表（带我买了）以及收藏之外的手表',
        'o esqueleto da página Estatísticas' => '统计页面的骨架',
        'o esqueleto da página de totais' => '合计页面的框架',
        'a página de totais: os quadros (a tabelinha com o total, o número ou o relógio) nos relógios do endereço' => '合计页面：方框（带合计的小表、数字或手表），基于地址中的手表',
        'o esqueleto da página Hora certa' => '准确时间页面的骨架',
        'o esqueleto da página Acessórios' => '配件页面的骨架',
        'o esqueleto da página Galeria' => '图库页面的骨架',
        'a página Galeria: a coleção em fotos, por grupo, para ver e imprimir' => '图库页面：以照片展示收藏，按分组，供查看和打印',
        'o esqueleto da página Passaporte do relógio' => '手表护照页面的骨架',
        'a página Passaporte: a ficha de um relógio para imprimir ou guardar em PDF' => '护照页面：一块手表的档案，供打印或存为 PDF',
        'a página Acessórios: o filtro por relógio, a lista com Editar e Excluir e o cadastro' => '配件页面：按手表筛选、带编辑和删除的列表以及档案',
        'a página Hora certa: o mostrador e a hora digital andando, acertados pela API, e os quadros do fuso, do calendário e da lua' => '准确时间页面：走动的表盘和数字时间，由 API 校准，以及时区、日历和月相的框',
        'a página Estatísticas: o período, o resumo, cada relógio, os gráficos em SVG e a coleção' => '统计页面：时段、摘要、每块手表、SVG 图表以及收藏',
        'o esqueleto da página Histórico' => '历史页面的骨架',
        'a página Histórico de um relógio: os filtros, o resumo do tempo e a linha do tempo' => '一块手表的历史页面：筛选、时间摘要和时间线',
        'o esqueleto da página Documentos' => '文档页面的骨架',
        'a página Documentos: o envio, as abas, a galeria com o visor, os vídeos, os PDFs, as NF-e e a edição' => '文档页面：上传、标签、带查看器的图库、视频、PDF、NF-e 以及编辑',
        'o esqueleto da página Cadastros' => '定义页面的骨架',
        'a página Cadastros: as abas Campos, Tipos de lançamento, Fórmulas e Categorias de documentos (os avisos ficam na página Avisos; os modos, na página Modos de rodízio)' => '定义页面：字段、记录类型、公式和文档类别等标签（提醒在“提醒”页面；模式在“轮换模式”页面）',
        'o esqueleto da página Modos de rodízio' => '“轮换模式”页面的骨架',
        'a página Modos de rodízio: os modos da coleção com o tipo, o critério, as semanas e de onde escolhem; o formulário com a tela de cada tipo (os campos viram os blocos da API ao enviar), o roteiro do personalizado com o teste em todos os relógios, e o roteiro gerado dos modos prontos' => '轮换模式页面：收藏的各模式及其类型、标准、周数和选自何处；每种类型的表单界面（提交时字段转为 API 的区块）、自定义模式的脚本及在所有手表上的测试，以及预设模式生成的脚本',
        'o esqueleto da página Usuários' => '用户页面的骨架',
        'a página Usuários: o painel do master (cada conta com o que tem e as ações: ver como, oficializar, prorrogar, voltar a demo, bloquear, alterar, trocar a senha, transferir, dar acesso, excluir) e criar conta' => '用户页面：master 面板（每个账户及其拥有的内容和操作：以其身份查看、转为正式、延长、改回演示、封禁、修改、修改密码、转移、授予访问权限、删除）以及创建账户',
        'o esqueleto da página Minha conta' => '“我的账户”页面的骨架',
        'a página Minha conta: as coleções, as árvores, pedir acesso, os dados, os tokens, as notificações deste aparelho, o servidor de e-mail (master) e excluir a conta' => '“我的账户”页面：收藏、树、申请访问、资料、令牌、此设备的通知、邮件服务器（master）以及删除账户',
        'o esqueleto da página Aprovações' => '审批页面的骨架',
        'a página Aprovações: os pedidos, os convites a aprovar, convidar, os convites feitos e quem vê as suas coleções' => '审批页面：申请、待批准的邀请、邀请、已发出的邀请以及谁能看到你的收藏',
        'o esqueleto da página pública Criar conta (sem menu, sem login)' => '公开的“创建账户”页面的骨架（没有菜单，无需登录）',
        'a página Criar conta: o cadastro aberto, o convite, o esqueci a senha e a senha nova' => '“创建账户”页面：公开注册、邀请、忘记密码和新密码',
        'o esqueleto da página Destinos' => '推送目标页面的骨架',
        'a página Destinos: cada destino das mensagens (webhook, e-mail, Web Push), o que recebe, o teste e como sai hoje' => '推送目标页面：每个消息推送目标（webhook、电子邮件、Web Push）、接收内容、测试以及今天会发出什么',
        'o esqueleto da página Agendas' => '日历页面的骨架',
        'a página Agendas: cada agenda (Google, CalDAV, Outlook, link ICS), o que recebe, a sincronização, o evento de teste e o que tem de estar nela' => '日历页面：每个日历（Google、CalDAV、Outlook、ICS 链接）、接收内容、同步、测试事件以及应在其中的内容',
        'o reloginho (um easter egg): 24 tipos de relógio desenhados em canvas com a hora certa, um na barra do menu (os segundos andando; o clique abre a Hora certa) e um no favicon (a aba, desenhado a cada minuto); cada hora do dia tem um modelo, pela ordem que a API manda no menu (relojinho.ordem: na ordem, sorteado ou sem repetir)' => '小手表（一个彩蛋）：24 种用 canvas 绘制、显示准确时间的手表，一块在菜单栏（秒针走动；点击打开准确时间），一块在网站图标（标签页，每分钟绘制）；一天中每个小时一种款式，按 API 在菜单中给出的顺序（relojinho.ordem：按顺序、抽取或不重复）',
        'o service worker do aplicativo no celular (PWA), entregue por api.php?recurso=sw com a versão e a lista dos arquivos na frente: guarda os arquivos das telas (nunca a API), entrega a página sem conexão quando a rede cai e mostra as notificações do Web Push (no clique, abre o sistema)' => '手机上应用（PWA）的 service worker，由 api.php?recurso=sw 提供，前面带版本号和文件列表：缓存界面文件（永不缓存 API），网络中断时提供无连接页面，并显示 Web Push 通知（点击打开系统）',
        'a página "sem conexão" do aplicativo (estática, nos seis idiomas): o service worker a entrega quando a rede cai' => '应用的“无连接”页面（静态，六种语言）：网络中断时由 service worker 提供',
        'o ícone do aplicativo (192 px: o manifesto, o favicon e as notificações)' => '应用图标（192 px：清单、网站图标和通知）',
        'o ícone do aplicativo (512 px: o manifesto, também como maskable)' => '应用图标（512 px：清单，也用作 maskable）',
        'o ícone do aplicativo no iPhone (o apple-touch-icon)' => 'iPhone 上的应用图标（apple-touch-icon）',
        'o esqueleto da página Ajuda' => '帮助页面的骨架',
        'a página Ajuda: o sumário e o manual em HTML (recurso=manual)' => '帮助页面：目录以及 HTML 手册（recurso=manual）',
        'a API, a porta única: a autenticação, o formato, a ordem dos recursos (cada um no seu arquivo da pasta api/, ou ali mesmo, os pequenos), os filtros, o JSON e o XML, e no cabeçalho a documentação inteira' => 'API，唯一入口：身份验证、格式、资源顺序（每一个在 api/ 文件夹自己的文件中，小的就在原处）、筛选、JSON 和 XML，以及页眉中的完整文档',
        'as funções que só a API usa (o XML, os textos legíveis do tempo, do plano, dos eventos e da agenda, os filtros das listas e a resposta) e o tratamento dos erros' => '仅 API 使用的函数（XML、时间、计划、事件和日历的可读文本、列表筛选和响应）以及错误处理',
        'api.php sem recurso: tudo o que está guardado' => '不带 recurso 的 api.php：已保存的全部内容',
        'recurso=hoje: tudo o que a página Hoje mostra' => 'recurso=hoje：今天页面显示的全部内容',
        'recurso=ficha: tudo o que o painel de um relógio mostra (ou o cadastro de um novo)' => 'recurso=ficha：一块手表的面板显示的全部内容（或新建的档案）',
        'recurso=config: a Configuração inteira' => 'recurso=config：完整的设置',
        'recurso=destinos: os destinos das mensagens da coleção, o que cada um recebe e a prévia de hoje' => 'recurso=destinos：收藏的消息推送目标、每个接收的内容以及今天的预览',
        'recurso=agendas: as agendas da coleção, o que cada uma recebe e o que tem de estar nela agora' => 'recurso=agendas：收藏的日历、每个接收的内容以及现在应在其中的内容',
        'recurso=desejos: a lista de desejos e os relógios fora da coleção' => 'recurso=desejos：心愿单以及收藏之外的手表',
        'recurso=passaporte: a ficha de um relógio para imprimir, tudo já em texto' => 'recurso=passaporte：一块手表供打印的档案，全部已经是文本',
        'recurso=galeria: a coleção em fotos, por grupo' => 'recurso=galeria：以照片展示的收藏，按分组',
        'recurso=hora_certa: a hora do servidor, o fuso, o UTC, a letra militar, o calendário e a lua (sem banco)' => 'recurso=hora_certa：服务器时间、时区、UTC、军用字母、日历和月相（不用数据库）',
        'recurso=totais: os totais calculados nos relógios mostrados (o rodapé, a página e o cadastro) e o teste de uma expressão' => 'recurso=totais：在显示的手表上计算的合计（底部、页面和定义）以及表达式的测试',
        'recurso=estatisticas: o uso da coleção num período, por relógio, dia da semana e mês, e a distribuição da coleção' => 'recurso=estatisticas：一段时间内收藏的使用情况，按手表、星期几和月份，以及收藏的分布',
        'recurso=historico: a linha do tempo de um relógio, com os filtros e o resumo' => 'recurso=historico：一块手表的时间线，带筛选和摘要',
        'recurso=plano: o plano dia a dia, o resumo por relógio e as páginas' => 'recurso=plano：逐日计划、按手表的摘要以及分页',
        'recurso=cron: as execuções do cron, com os filtros, o resumo e as páginas' => 'recurso=cron：cron 的执行，带筛选、摘要和分页',
        'recurso=arvore: a árvore dos grupos e o grupo de cada relógio' => 'recurso=arvore：分组树以及每块手表的分组',
        'recurso=cadastros: os campos, os tipos de lançamento, as fórmulas, os avisos, os modos e as categorias' => 'recurso=cadastros：字段、记录类型、公式、提醒、模式和类别',
        'recurso=calcular: o resultado de uma fórmula para um relógio (ou para todos)' => 'recurso=calcular：一个公式对一块手表（或全部）的结果',
        'recurso=documentos: os documentos de um relógio (ou de todos), as categorias e o limite' => 'recurso=documentos：一块手表（或全部）的文档、类别和限制',
        'recurso=documento: um arquivo de um documento (o original, a miniatura, a página de um PDF)' => 'recurso=documento：一个文档的一个文件（原件、缩略图、PDF 的一页）',
        'recurso=backup: as cópias de segurança da pasta, e uma cópia para baixar (arquivo=)' => 'recurso=backup：文件夹中的安全副本，以及一份供下载的副本（arquivo=）',
        'recurso=migracoes: as migrações pendentes do banco (a leitura) e aplicar (a escrita)' => 'recurso=migracoes：数据库待应用的迁移（读取）以及应用（写入）',
        'recurso=codigo: o código do sistema como está agora, arquivo por arquivo' => 'recurso=codigo：系统现在的代码，逐个文件',
        'recurso=ajuda: a documentação da API (cada consulta, cada escrita e o dicionário dos campos, a fonte única dele)' => 'recurso=ajuda：API 文档（每一次查询、每一次写入以及字段词典，它的唯一来源）',
        'as escritas (POST): cada recurso e ação vai para a função dele no operacoes.php, que valida, grava e responde' => '写入（POST）：每个资源和操作进入 operacoes.php 中它的函数，该函数校验、写入并响应',
        'o núcleo: o token, o login, a árvore, os campos, os lançamentos, o motor das fórmulas, os avisos, os critérios, o rodízio (o roteiro dos modos, roteiro_ler/modo_roteiro_texto, a escolha de um dia, escolha_do_dia, e o montador do plano, plano_montar, um só para os blocos e a escala) e as listas do código' => '核心：令牌、登录、树、字段、记录、公式引擎、提醒、标准、轮换（模式的脚本 roteiro_ler/modo_roteiro_texto、一天的选择 escolha_do_dia，以及计划生成器 plano_montar，区块和排班共用一个）和代码的列表',
        'as escritas: cada ação valida, grava e devolve ok, mensagem e erros (a API chama estas funções)' => '写入：每个操作校验、写入并返回 ok、消息和错误（API 调用这些函数）',
        'as coleções no núcleo: a coleção do pedido, os ids da raiz, o modelo.json (a árvore e a coleção novas), os segredos cifrados, a tabela sistema, a migração v25, o usuário do pedido, as coleções que cada um vê, excluir com os arquivos, a limpeza das contas e o impacto das exclusões' => '核心中的收藏部分：请求所在的收藏、根的 id、modelo.json（新的树和收藏）、加密的机密、sistema 表、v25 迁移、请求的用户、每个人能看到的收藏、连同文件一起删除、账户清理以及删除的影响',
        'os alertas: o pedido HTTP (e a conferência dos endereços de fora), os destinos (webhook, e-mail por SMTP/IMAP/POP, Web Push com VAPID), as mensagens da manhã e da noite, as agendas (Google, CalDAV, Outlook, o link ICS) e a sincronização' => '提醒部分：HTTP 请求（以及对外部地址的检查）、推送目标（webhook、通过 SMTP/IMAP/POP 的电子邮件、带 VAPID 的 Web Push）、早晨和晚上的消息、日历（Google、CalDAV、Outlook、ICS 链接）以及同步',
        'as contas: o cadastro aberto, Minha conta, as coleções e as árvores (copiar, transferir), os acessos, os convites, os pedidos, os tokens pessoais, o Vendo como e o painel do master' => '账户部分：公开注册、我的账户、收藏和树（复制、转移）、访问权限、邀请、申请、个人令牌、“以他人身份查看”以及 master 面板',
        'o conjunto inicial de uma coleção nova, sem códigos fixos (os grupos por apelido): os grupos, os campos, os tipos, as fórmulas, os avisos, os critérios, as categorias, os modos, a configuração e as mensagens padrão, em português' => '新收藏的初始集合，不含固定代码（分组用昵称引用）：分组、字段、类型、公式、提醒、标准、分类、模式、设置和默认消息，葡萄牙语',
        'o banco: MySQL/MariaDB, PostgreSQL, SQLite ou Firebird, o SQL escrito uma vez só e traduzido para cada um, e o catálogo do modelo' => '数据库：MySQL/MariaDB、PostgreSQL、SQLite 或 Firebird，SQL 只写一次并翻译到每一种，以及模型目录',
        'a reconstrução (recurso=reconstrucao): as regras de cada parte, a especificação das telas e esta lista do código' => '重建（recurso=reconstrucao）：每一部分的规则、各页面的规格以及这份代码清单',
        'o cron, a cada minuto: as mensagens, o pulso sozinho, a agenda, a manutenção dos documentos, sempre mudo e registrado no banco' => 'cron，每分钟：消息、独自上手腕、日历、文档维护，始终沉默并记录在数据库中',
        'a instalação pelo servidor (a mesma do POST recurso=instalacao)' => '通过服务器安装（与 POST recurso=instalacao 相同）',
        'a importação do sistema antigo pelo servidor (a mesma do POST recurso=importacao)' => '通过服务器导入旧系统（与 POST recurso=importacao 相同）',
        'criar um usuário ou trocar a senha pelo servidor (o mesmo do POST recurso=usuarios, acao=salvar)' => '通过服务器创建用户或更换密码（与 POST recurso=usuarios、acao=salvar 相同）',
        'a estrutura do banco (no dialeto do MySQL, traduzida para os outros): as tabelas, as chaves e as regras, sem dados' => '数据库结构（MySQL 方言，可翻译为其他方言）：表、键和规则，不含数据',
        'o modelo do config.php, com cada constante explicada (o config.php de verdade não sai: veja nao_mostrados)' => 'config.php 的模板，每个常量都有说明（真正的 config.php 不输出：见 nao_mostrados）',
        'o Apache: o que abre pelo navegador e o que fica bloqueado' => 'Apache：浏览器能打开的，以及被阻止的',
        'o nginx: o mesmo bloqueio do .htaccess' => 'nginx：与 .htaccess 相同的阻止',
        'o roteiro de aceitação: faz pela API o que uma pessoa faz e tira a fotografia de tudo o que a API devolve' => '验收脚本：通过 API 做一个人会做的事，并拍摄 API 返回的一切的快照',
        'compara duas fotografias do cenário (os quatro bancos, ou a reescrita com a versão atual)' => '比较场景的两份快照（四个数据库，或用当前版本重写后的）',
        'o teste de paridade com um comando: os quatro bancos ao mesmo tempo, numa pasta temporária, e a comparação' => '用一条命令做的一致性测试：四个数据库同时，在临时文件夹中，并进行比较',
        'o config dos testes (o acesso aos bancos pelo ambiente), apontado por RELOGIOS_CONFIG: o config.php de verdade fica intocado' => '测试用的 config（通过环境访问数据库），由 RELOGIOS_CONFIG 指向：真正的 config.php 保持不动',
        'gera o dicionário dos campos do cabeçalho do api.php a partir do da ajuda (a fonte única), e confere que batem' => '根据帮助中的词典生成 api.php 页眉的字段词典（唯一来源），并核对两者一致',
        'confere que todo campo das respostas da API está explicado no dicionário da ajuda' => '核对 API 响应的每个字段都在帮助的词典中有说明',
        'confere que uma conta não vê nem muda o que é de outra pelo token pessoal (todos os recursos, com os ids da outra) e que o pedido de acesso pelo código não mostra login nem nome de coleção' => '检查一个账户通过个人令牌既看不到也改不了另一个账户的内容（所有资源，带上另一个账户的 id），并检查凭编号申请访问时不显示登录名或收藏名称',
        'o teste da interface da Configuração em Chromium (sem rede nem banco): salvar, a troca de idioma e a rolagem mantida em celular, tablet e PC' => '在 Chromium 中对设置界面的测试（无网络、无数据库）：保存、切换语言以及在手机、平板和电脑上保持滚动位置',
        'a conferência do layout: todas as telas num navegador, em 15 tamanhos, com dados de estresse, procurando o que quebra' => '布局核对：在浏览器中以 15 种尺寸查看全部页面，使用压力数据，寻找会坏掉的地方',
        'as telas que as conferências do layout e dos textos fixos abrem, com o endereço de cada uma' => '布局检查和固定文本检查所打开的界面，以及每个界面的地址',
        'a conferência dos textos fixos: todas as telas com o sistema inteiro em chinês, procurando palavra em letra latina que não é dado de quem usa nem vem do dicionário' => '固定文本检查：把整个系统切换成中文后打开所有界面，查找既不是用户数据、也不来自词典的拉丁字母单词',
        'como rodar o teste de paridade e a conferência do layout' => '如何运行一致性测试和布局核对',
        'o manual inteiro: para quem usa, a instalação, a API e como é por dentro' => '完整手册：给使用者、安装、API 以及内部如何构成',
        'o que o sistema antigo fazia e onde está no novo' => '旧系统做什么，以及在新系统中位于何处',
        'a licença' => '许可证',
        'o que nunca entra no repositório (a configuração, as chaves, os bancos)' => '永不进入仓库的内容（配置、密钥、数据库）',
        'as quebras de linha (LF em tudo) e os binários' => '换行（全部为 LF）以及二进制文件',
        'os testes no GitHub a cada push no main: a paridade nos bancos (com a documentação da API) e o layout das telas' => '每次推送到 main 时在 GitHub 上的测试：各数据库的一致性（含 API 文档）以及页面布局',
        'confere os dicionários dos idiomas com o código (o texto que falta, o que sobra, o parâmetro diferente) e a origem de cada manual traduzido; junta traduções novas (--juntar)' => '把各语言的词典与代码对照（缺少的文本、多余的文本、不同的参数）以及每份翻译手册的来源；合并新的翻译（--juntar）',
        'a conferência da arquitetura: as páginas sem banco, a rede das telas só pela API, o banco só no núcleo, na API e no cron, os scripts de linha de comando como atalhos da API, a guarda do api/, o bloqueio pela web, a API e o config.php documentados, as migrações e o repositório' => '架构检查：页面不碰数据库，界面的网络请求只经过 API，数据库只由核心、API 和 cron 访问，命令行脚本是 API 的快捷方式，api/ 的保护，Web 访问的屏蔽，API 和 config.php 已有文档，迁移以及代码仓库',
        'monta o README de cada idioma (README.<idioma>.md) a partir do manual traduzido e do resto traduzido, e confere que estão em dia (--conferir)' => '根据翻译后的手册和翻译后的其余部分生成每种语言的 README（README.<idioma>.md），并检查它们是否最新（--conferir）',
        'o dicionário do idioma {1}: o texto em português => a tradução, por parte (telas, api, cadastro, ajuda, reconstrucao)' => '语言 {1} 的词典：葡萄牙语文本 => 译文，按部分划分（telas、api、cadastro、ajuda、reconstrucao）',
        'o manual da página Ajuda no idioma {1} (as seções do README para quem usa), com a origem na primeira linha' => '语言 {1} 的帮助页面手册（README 中面向用户的章节），第一行是来源',
        'o resto do README no idioma {1} (o que não está no manual), com a origem na primeira linha' => '语言 {1} 的 README 其余部分（不在手册中的内容），第一行是来源',
        'o README no idioma {1}, montado por testes/readme.php (não editar à mão)' => '语言 {1} 的 README，由 testes/readme.php 生成（不要手动编辑）',
        'tem as senhas do banco e o API_TOKEN' => '含有数据库密码和 API_TOKEN',
        'o config.exemplo.php (o modelo, com cada constante explicada) e listas.config_php no recurso=reconstrucao' => 'config.exemplo.php（模板，每个常量都有说明）以及 recurso=reconstrucao 中的 listas.config_php',
        'a chave JSON do Google (google-conta-servico.json ou o caminho da Configuração)' => 'Google 的 JSON 密钥（google-conta-servico.json 或设置中的路径）',
        'é uma credencial' => '它是一项凭据',
        'a seção mensagens do recurso=reconstrucao e o README (Google Agenda): como criar a conta de serviço e a chave' => 'recurso=reconstrucao 的 mensagens 一节以及 README（Google 日历）：如何创建服务账号和密钥',
        'o banco de dados (o servidor MySQL/PostgreSQL/Firebird, ou o arquivo do SQLite)' => '数据库（MySQL/PostgreSQL/Firebird 服务器，或 SQLite 文件）',
        'são os dados, não o código' => '它们是数据，不是代码',
        'o modelo em modelo_de_dados (recurso=reconstrucao) e os dados pela própria API (api.php sem recurso: tudo o que está guardado)' => 'modelo_de_dados 中的模型（recurso=reconstrucao）以及通过 API 本身取得的数据（不带 recurso 的 api.php：已保存的全部内容）',
        'a pasta dos documentos (DOCUMENTOS_PASTA)' => '文档文件夹（DOCUMENTOS_PASTA）',
        'são os arquivos de cada relógio, não o código' => '它们是每块手表的文件，不是代码',
        'recurso=documentos (a lista) e recurso=documento (cada arquivo)' => 'recurso=documentos（列表）和 recurso=documento（每个文件）',
        'as senhas dos usuários' => '用户密码',
        'não existem no sistema: só o hash' => '系统中不存在：只有哈希',
        'recurso=usuarios (o login e o hash) e senhas na ajuda (como conferir e migrar)' => 'recurso=usuarios（登录名和哈希）以及帮助中的 senhas（如何核对和迁移）',
        'a migração ' => '迁移 ',
        'a captura de tela: ' => '屏幕截图： ',
        'text/plain; charset=utf-8' => 'text/plain; charset=utf-8',
        'O código do sistema como está agora, lido do disco na hora: cada arquivo com a camada, o que ele é, o tamanho e o SHA-256. Um arquivo: arquivo=<nome> (o conteúdo como está, em conteudo; a imagem em conteudo_base64); com cru=1, o arquivo puro, sem JSON (texto como text/plain, para ler no navegador). Numa página, html traz o HTML que o navegador recebe, já montado (html=1 com cru=1: só ele), e usa, os arquivos que ela carrega. Todos de uma vez: conteudo=1 (com os filtros: f[arquivos][camada]=tela traz o HTML, o CSS e o JavaScript das telas). O que fica de fora de propósito está em nao_mostrados, com o que ver no lugar.' => '系统现在的代码，当时从磁盘读取：每个文件带层次、它是什么、大小和 SHA-256。单个文件：arquivo=<名称>（内容原样放在 conteudo 中；图像在 conteudo_base64 中）；cru=1 时为纯文件，无 JSON（文本为 text/plain，供在浏览器中阅读）。在一个页面上，html 带来浏览器收到的、已经组装好的 HTML（html=1 且 cru=1：只有它），usa 为它加载的文件。一次全部：conteudo=1（带筛选：f[arquivos][camada]=tela 带来各页面的 HTML、CSS 和 JavaScript）。有意排除的内容在 nao_mostrados 中，并说明用什么代替查看。',
        'as páginas: o esqueleto em PHP, o estilo e o JavaScript que lê a API e monta a tela' => '各页面：PHP 骨架、样式以及读取 API 并组装页面的 JavaScript',
        'o back-end: a API e o que ela usa (o núcleo, as escritas, o banco, a reconstrução)' => '后端：API 以及它使用的部分（核心、写入、数据库、重建）',
        'o cron e os scripts do servidor' => 'cron 以及服务器脚本',
        'o banco inicial e as migrações' => '初始数据库以及迁移',
        'a configuração do servidor web e o modelo do config.php' => 'Web 服务器的配置以及 config.php 的模板',
        'o roteiro de aceitação e a comparação' => '验收脚本以及比较',
        'o README e os outros textos' => 'README 以及其他文本',
        'os arquivos do git' => 'git 的文件',
        'as capturas das telas' => '各页面的截图',
        ' ou mais' => ' 或更多',
        'O Relojoeiro (Relógios 2) planeja o rodízio de uma coleção de relógios: escolhe o relógio de cada dia pela nota de cada um (critérios com pesos) e pelas regras do modo de rodízio, acompanha a energia de cada um (bateria, reserva de marcha, carga de luz, vida da pilha) pelas fórmulas do cadastro e pelo histórico de lançamentos, avisa o que fazer (carregar, dar corda, pôr no sol, trocar a pilha, revisão) pelos destinos das mensagens (Telegram e outros webhooks, e-mail, Web Push) e pelas agendas (Google, CalDAV, Outlook, link ICS), mede o gasto real da bateria pelas leituras e guarda os documentos de cada relógio. Esta resposta é o roteiro para reescrever o sistema inteiro do zero e chegar ao mesmo comportamento. Várias pessoas usam o mesmo sistema: cada conta tem as suas coleções (cada uma com os relógios, o histórico, o plano, as mensagens e as agendas), numa árvore de grupos que pode servir a várias coleções do mesmo dono, e pode ver as coleções de outros, por convite ou por pedido aprovado.' => 'Relojoeiro（Relógios 2）规划一个手表收藏的轮换：根据每只手表的评分（带权重的标准）和轮换模式的规则选出每天的手表，通过定义中的公式和记录历史跟踪每只手表的能量（电池、动力储备、光能充电、电池寿命），通过消息推送目标（Telegram 及其他 webhook、电子邮件、Web Push）和日历（Google、CalDAV、Outlook、ICS 链接）提醒该做什么（充电、上链、晒太阳、换电池、保养），根据读数测量电池的实际消耗，并保存每只手表的文档。本响应是从零重写整个系统并达到相同行为的路线图。多人使用同一个系统：每个账户有自己的收藏（每个收藏含手表、历史、计划、消息和日历），位于一棵可供同一所有者多个收藏使用的分组树中，并且可以通过邀请或获批的申请看到他人的收藏。',
        'Leia as seções na ordem: os princípios e a arquitetura, a ordem de construção, e cada módulo com as suas regras.' => '按顺序阅读各节：原则与架构、构建顺序，以及每个模块及其规则。',
        'O modelo de dados (modelo_de_dados) é o do banco em uso agora, lido dele: tabelas, colunas, chaves, índices e regras de validação. Os tipos vêm no dialeto desse banco; o dialeto de referência (MySQL) está no schema.sql.' => '数据模型（modelo_de_dados）是现在正在使用的数据库的模型，从它读取：表、列、键、索引和校验规则。类型以该数据库的方言给出；参考方言（MySQL）在 schema.sql 中。',
        'O contrato da API (cada consulta com parâmetros e exemplo, cada escrita com ações e campos, e o significado de cada campo das respostas) está em api.php?recurso=ajuda: a reescrita deve responder igual, para as telas, os scripts e quem integra continuarem funcionando.' => 'API 契约（每一次查询及其参数和示例、每一次写入及其操作和字段，以及响应中每个字段的含义）在 api.php?recurso=ajuda：重写必须同样响应，以便页面、脚本和集成方继续工作。',
        'O conhecimento sobre relógios não está no código: está no modelo.json (o conjunto inicial de uma coleção nova: os grupos, os campos, os tipos de lançamento, as fórmulas, os avisos, os critérios dos grupos, as categorias, os modos, a configuração e as mensagens padrão, sem nenhum código fixo: os grupos se citam por apelido). O schema.sql só tem a estrutura. Leia também por recurso=cadastros e recurso=criterios. A reescrita traz esse cadastro como dado, não como código, no idioma de quem cria a coleção.' => '关于手表的知识不在代码中：它在 modelo.json 里（新收藏的初始集合：分组、字段、记录类型、公式、提醒、分组的标准、分类、模式、设置和默认消息，不含任何固定代码：分组之间用昵称引用）。schema.sql 只有结构。也可以通过 recurso=cadastros 和 recurso=criterios 读取。重写时把这些定义作为数据而不是代码带入，使用创建收藏者的语言。',
        'As telas (telas) são a especificação visual: o visual com os valores exatos, o menu e cada página, parte por parte, com cada tabela, campo, botão e mensagem, palavra por palavra. A reescrita reproduz a mesma interface, não uma parecida: o que está lá existe, e o que não está não existe. As capturas em docs/telas/ mostram o resultado.' => '各页面（telas）是视觉规格：带精确数值的视觉、菜单和每一页，一部分一部分，含每张表、字段、按钮和消息，逐词。重写要再现同一界面，而不是相似的：那里有的就存在，那里没有的就不存在。docs/telas/ 中的截图显示结果。',
        'O código de verdade, como está agora, sai pelo recurso=codigo (a lista em codigo, abaixo): o CSS, o JavaScript, cada página e o HTML que ela entrega ao navegador, a API, o banco e o resto, lido do disco na hora (arquivo=<nome>; cru=1 para o arquivo puro). Cada página em telas diz os arquivos dela (codigo). O que não sai (o config.php, as chaves, os dados) está em codigo.nao_mostrados, com o que ver no lugar.' => '真正的代码，现在的样子，由 recurso=codigo 输出（清单在下面的 codigo 中）：CSS、JavaScript、每一页以及它交给浏览器的 HTML、API、数据库和其余部分，当时从磁盘读取（arquivo=<名称>；cru=1 为纯文件）。telas 中的每一页标明它的文件（codigo）。不输出的内容（config.php、密钥、数据）在 codigo.nao_mostrados 中，并说明用什么代替查看。',
        'O README.md explica cada tela e cada opção para quem usa (as seções para quem usa saem também pela API, em recurso=manual: o texto da página Ajuda); o testes/cenario.php é o roteiro de aceitação (veja a seção testes).' => 'README.md 向使用者说明每一页和每一个选项（给使用者的各节也由 API 输出，在 recurso=manual：帮助页面的文本）；testes/cenario.php 是验收脚本（见 testes 一节）。',
        'Os princípios (não negociáveis)' => '原则（不可协商）',
        'O sistema não sabe nada de relógios: o código tem só mecanismos (árvore, campos, tipos de lançamento, fórmulas, avisos, critérios, modos). Que um automático tem reserva de marcha, ou que um solar carrega no sol, está escrito em fórmulas cadastradas, que o usuário lê, edita e testa pela tela. Mudar uma regra de relógio é mudar cadastro (com uma migração), não código.' => '系统对手表一无所知：代码里只有机制（树、字段、记录类型、公式、提醒、标准、模式）。自动表有动力储存，或太阳能表在太阳下充电，这些写在已登记的公式中，用户通过页面阅读、编辑和测试。改变一条手表规则是改变档案（带一次迁移），不是改变代码。',
        'Tudo pela API: as páginas só desenham; toda leitura e toda gravação passa pela API, a mesma que um script usa. Nenhuma regra de negócio no navegador além de mostrar e esconder campos.' => '一切通过 API：页面只绘制；每一次读取和每一次写入都经过 API，脚本使用的是同一个。除了显示和隐藏字段，浏览器中没有任何业务规则。',
        'Falha segura: sem token válido, com o fuso inválido ou com o banco desatualizado (migração pendente), o sistema para e diz o motivo (a API responde 500 ou 503, o cron registra e não faz nada), em vez de rodar pela metade.' => '故障安全：没有有效令牌、时区无效或数据库未更新（有待应用的迁移）时，系统停止并说明原因（API 响应 500 或 503，cron 记录且什么都不做），而不是做到一半。',
        'O banco se defende: relacional e normalizado, toda ligação é chave estrangeira (obrigatória: some junto, ON DELETE CASCADE; opcional: a ligação se desfaz, SET NULL), nenhuma lista guardada como texto, e regras de validação (CHECK, NOT NULL, UNIQUE) iguais às da tela. Uma gravação errada é recusada pelo banco venha de onde vier (a API responde 409 com a regra quebrada).' => '数据库自我防护：关系型且规范化，每一条关联都是外键（必填：一起消失，ON DELETE CASCADE；可选：关联解除，SET NULL），没有任何列表以文本保存，校验规则（CHECK、NOT NULL、UNIQUE）与页面相同。错误的写入无论来自何处都被数据库拒绝（API 以被打破的规则响应 409）。',
        'Cada coisa é de alguém: a coleção tem um dono, a árvore de grupos tem um dono, e tudo o que se lê ou se grava vale na coleção do pedido. A separação é do núcleo, não de cada consulta: a camada do banco reescreve cada comando para enxergar só a coleção (e a árvore dela), e quem não vê uma coleção recebe 404, como se ela não existisse.' => '每样东西都属于某个人：收藏有所有者，分组树有所有者，读取和保存的一切都作用于请求所在的收藏。这种隔离由核心负责，而不是每条查询：数据库层会改写每条命令，使其只能看到该收藏（及其树），看不到某个收藏的人会得到 404，如同它不存在。',
        'Nada some sem aviso: toda exclusão mostra antes o que sai junto (seguindo o banco em cascata, no banco inteiro: uma árvore serve a várias coleções) e só apaga com a confirmação; os arquivos do disco saem junto, na hora.' => '没有任何东西会在无提示的情况下消失：每次删除都会先显示一并删除的内容（按数据库的级联、在整个数据库中统计：一棵树可供多个收藏使用），只有确认后才删除；磁盘上的文件会立即一并删除。',
        'Os mesmos resultados em MySQL/MariaDB, PostgreSQL, SQLite e Firebird: o SQL do sistema é escrito uma vez só; o que muda de banco para banco fica numa camada de tradução. Maiúsculas e acentos não contam nos textos curtos ("Relógio" = "RELOGIO"), em todos; no MySQL/MariaDB, toda tabela em utf8mb4_unicode_ci (a utf8mb4_general_ci, padrão do MariaDB, ordena diferente); no Firebird, a collation UNICODE_CI_AI.' => '在 MySQL/MariaDB、PostgreSQL、SQLite 和 Firebird 上结果相同：系统的 SQL 只写一次；随数据库变化的部分放在翻译层。在所有库中，短文本不区分大小写和重音（“Relógio” = “RELOGIO”）；在 MySQL/MariaDB 中，每张表为 utf8mb4_unicode_ci（MariaDB 默认的 utf8mb4_general_ci 排序不同）；在 Firebird 中，collation 为 UNICODE_CI_AI。',
        'Datas e horas no fuso do sistema (FUSO). Nas fórmulas, o tempo é contado em dias no horário local: a meia-noite local de qualquer data é um número inteiro e a fração é a hora do dia; assim uma data e o agora entram na mesma conta sem o fuso aparecer.' => '日期和时刻用系统时区（FUSO）。在公式中，时间按本地时间以天计数：任意日期的本地午夜是一个整数，小数是一天中的时刻；这样日期和现在进入同一计算而时区不出现。',
        'O cron é mudo e rastreável: roda a cada minuto, não escreve na saída, e registra no banco o que fez.' => 'cron 沉默且可追溯：每分钟运行，不向输出写任何内容，并在数据库中记录所做的事。',
        'Mensagens que explicam o que fazer ("Dê um nome ao relógio (até 120 caracteres)."), em seis idiomas: português (o original), inglês, chinês simplificado, hindi, espanhol e francês. Nenhum texto fixo: todo texto que alguém lê passa por t("o texto em português", parâmetros), com o português como chave (como no gettext) e os parâmetros entre chaves ({1}, {nome}) trocados depois da tradução; cada idioma tem o seu dicionário (o texto em português => a tradução), e o que falta sai em português. A API manda os códigos (origem: informado, padrao, vazio...) e, ao lado, o texto no idioma (origem_texto): a tela mostra o texto e compara o código, nunca o texto. O que não se traduz de propósito (a marca na tela da Hora certa, "24H", o alfabeto da OTAN, os exemplos de endereço) passa por fixo("..."), que devolve o texto como está. O idioma de cada pessoa é dela (o seletor do menu, guardado no navegador); quem não escolheu vê o padrão da instalação (config.idioma), senão o do navegador, senão português. As datas e os números seguem o idioma. Os nomes cadastrados ficam como foram escritos.' => '说明要做什么的消息（“给手表起一个名称（最多 120 个字符）。”），六种语言：葡萄牙语（原文）、英语、简体中文、印地语、西班牙语和法语。没有固定文本：任何人阅读的每一段文本都经过 t(“葡萄牙语文本”, 参数)，以葡萄牙语为键（如同 gettext），花括号中的参数（{1}、{nome}）在翻译之后替换；每种语言有自己的词典（葡萄牙语文本 => 译文），缺少的以葡萄牙语输出。API 发送代码（origem：informado、padrao、vazio……），并在旁边附上该语言的文本（origem_texto）：界面显示文本、比较代码，从不比较文本。故意不翻译的内容（“准确时间”界面上的品牌名、“24H”、北约字母、地址示例）经过 fixo("...")，原样返回文本。每个人的语言是他自己的（菜单中的选择器，保存在浏览器中）；没有选择的人看到安装的默认（config.idioma），否则是浏览器的，否则是葡萄牙语。日期和数字跟随语言。已登记的名称保持原样书写。',
        'A arquitetura' => '架构',
        'Um back-end único, a API (api.php): GET lê (recurso=...), POST grava (recurso=... e acao=...). Responde JSON (ou XML com formato=xml). O api.php faz a porta (a autenticação, o formato, a ordem dos recursos, os filtros e a resposta); cada recurso grande fica num arquivo da pasta api/ (api/hoje.php, api/ficha.php, api/ajuda.php...), que roda dentro dele, com as mesmas variáveis. Autenticação em todo pedido: o token (cabeçalho X-Api-Token ou parâmetro token, igual ao API_TOKEN) ou o login do site (HTTP Basic com usuário e senha da tabela usuario, senha com password_hash).' => '单一后端，即 API（api.php）：GET 读取（recurso=...），POST 写入（recurso=... 和 acao=...）。响应 JSON（或 formato=xml 时为 XML）。api.php 做入口（身份验证、格式、资源顺序、筛选和响应）；每个大资源放在 api/ 文件夹的一个文件中（api/hoje.php、api/ficha.php、api/ajuda.php……），在它内部运行，使用相同的变量。每个请求都要身份验证：令牌（请求头 X-Api-Token 或参数 token，等于 API_TOKEN）或网站登录（HTTP Basic，使用 usuario 表的用户名和密码，密码用 password_hash）。',
        'Um núcleo (lib.php): o motor das fórmulas, as variáveis de cada relógio, os avisos, as notas, o plano, a escala, a previsão, o gasto medido, o pulso sozinho, a linha do tempo e os documentos; o colecoes.php (o escopo da coleção, o modelo.json, os segredos cifrados, a configuração do sistema, a migração v25, o impacto das exclusões); o alertas.php (os destinos das mensagens: webhook, e-mail por SMTP com cópia por IMAP, Web Push com VAPID; as agendas: Google, CalDAV, Outlook, ICS); o contas.php (o cadastro aberto, a conta, as coleções e as árvores, os convites, os pedidos, os tokens e o painel do master).' => '一个核心（lib.php）：公式引擎、每只手表的变量、提醒、评分、计划、排班表、预测、实测消耗、自动上腕、时间线和文档；colecoes.php（收藏的作用范围、modelo.json、加密的机密、系统设置、v25 迁移、删除的影响）；alertas.php（消息推送目标：webhook、通过 SMTP 发送并通过 IMAP 保存副本的电子邮件、带 VAPID 的 Web Push；日历：Google、CalDAV、Outlook、ICS）；contas.php（公开注册、账户、收藏和树、邀请、申请、令牌以及 master 面板）。',
        'As gravações (operacoes.php e, as das contas, contas.php): uma função por recurso (op_relogio, op_lancamento, op_campos, op_conta, op_colecoes...), que valida tudo, grava e devolve {ok, mensagem, erros[], ...}. A tela e a API chamam as mesmas.' => '写入（operacoes.php，账户相关的在 contas.php）：每个资源一个函数（op_relogio、op_lancamento、op_campos、op_conta、op_colecoes……），负责全部校验、保存并返回 {ok, mensagem, erros[], ...}。界面和 API 调用的是同一些函数。',
        'O banco (banco.php): a conexão com as extensões do PHP (mysqli, pgsql, sqlite3, pdo_firebird), parâmetros sempre por ? (nunca texto colado no SQL), e a tradução do dialeto do MySQL para os outros: AUTO_INCREMENT, ENUM (vira CHECK ... IN), TINYINT, DATETIME, os INDEX dentro do CREATE TABLE, AFTER, MODIFY COLUMN (o SQLite refaz a tabela), INSERT IGNORE, REPLACE INTO, NOW(), <=>, LIKE sem diferenciar maiúsculas; no Firebird, também LIMIT/OFFSET (OFFSET ... ROWS FETCH NEXT ... ROWS ONLY), DATE(x) (CAST AS DATE), CONCAT (||), LENGTH/LEAST/GREATEST (OCTET_LENGTH/MINVALUE/MAXVALUE), o SELECT sem FROM (FROM RDB$DATABASE), o INSERT de várias linhas (um por linha), a tabela no (palavra reservada: "NO"), nomes de índice e de regra com até 31 letras, o TEXT como VARCHAR(8191) e a chave única de várias colunas com coluna vazia como índice único de uma expressão; e três comandos próprios das migrações: ALTER FOREIGN KEY, DROP COLUMN e ADD CONSTRAINT ... CHECK (trocando a regra sem perder a anterior se os dados não cumprem a nova).' => '数据库（banco.php）：用 PHP 扩展连接（mysqli、pgsql、sqlite3、pdo_firebird），参数始终用 ?（绝不把文本拼进 SQL），并把 MySQL 方言翻译到其他库：AUTO_INCREMENT、ENUM（变成 CHECK ... IN）、TINYINT、DATETIME、CREATE TABLE 内部的 INDEX、AFTER、MODIFY COLUMN（SQLite 重建表）、INSERT IGNORE、REPLACE INTO、NOW()、<=>、不区分大小写的 LIKE；在 Firebird 中，还有 LIMIT/OFFSET（OFFSET ... ROWS FETCH NEXT ... ROWS ONLY）、DATE(x)（CAST AS DATE）、CONCAT（||）、LENGTH/LEAST/GREATEST（OCTET_LENGTH/MINVALUE/MAXVALUE）、没有 FROM 的 SELECT（FROM RDB$DATABASE）、多行 INSERT（一行一条）、表 no（保留字：“NO”）、索引名和规则名最多 31 个字母、TEXT 作为 VARCHAR(8191)，以及含空列的多列唯一键作为表达式的唯一索引；还有迁移专用的三条命令：ALTER FOREIGN KEY、DROP COLUMN 和 ADD CONSTRAINT ... CHECK（若数据不满足新规则，则更换规则而不丢掉旧的）。',
        'As páginas (index.php, plano.php, desejos.php, estatisticas.php, hora.php, acessorios.php, galeria.php, passaporte.php, ficha.php, documentos.php, historico.php, avisos.php, configuracao.php, modos.php, criterios.php, grupos.php, cadastros.php, execucoes.php, conta.php, aprovacoes.php, usuarios.php, destinos.php, agendas.php, ajuda.php, e a pública cadastro.php) só entregam o esqueleto, sem conferir nem o login; o JavaScript de cada uma (hoje.js, painel.js, configuracao.js, ajuda.js...) chama a API e monta a tela, sem fazer conta: resumos, porcentagens e situações (o resumo do plano, a porcentagem de cada estado no histórico, o peso efetivo dos critérios, a situação do cron, o manual em HTML) vêm prontos da API. Formulários com data-recurso gravam pela API e a página se remonta com a resposta.' => '页面（index.php、plano.php、desejos.php、estatisticas.php、hora.php、acessorios.php、galeria.php、passaporte.php、ficha.php、documentos.php、historico.php、avisos.php、configuracao.php、modos.php、criterios.php、grupos.php、cadastros.php、execucoes.php、conta.php、aprovacoes.php、usuarios.php、destinos.php、agendas.php、ajuda.php，以及公开的 cadastro.php）只提供骨架，连登录都不检查；每个页面的 JavaScript（hoje.js、painel.js、configuracao.js、ajuda.js……）调用 API 并组装界面，不做任何计算：摘要、百分比和状态（计划摘要、历史中每种状态的百分比、标准的有效权重、cron 状态、HTML 格式的说明书）都由 API 现成提供。带 data-recurso 的表单通过 API 保存，页面根据响应重新组装。',
        'A API faz tudo, inclusive o que vem antes das telas: a instalação do banco vazio (recurso=instalacao, pelo token), o primeiro usuário (recurso=usuarios pelo token), a importação do sistema anterior (recurso=importacao) e o login das páginas (recurso=entrar: a página sem login recebe 401 da API, o api.js manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e a API devolve para a página). Os scripts de linha de comando (instalar.php, criar_usuario.php, importar.php) só chamam as mesmas operações.' => 'API 做一切，包括页面之前的事：空数据库的安装（recurso=instalacao，用令牌）、第一个用户（用令牌的 recurso=usuarios）、从前一个系统导入（recurso=importacao）以及页面登录（recurso=entrar：没有登录的页面从 API 收到 401，api.js 转到 api.php?recurso=entrar&volta=<该页>，浏览器询问用户名和密码，API 再回到该页）。命令行脚本（instalar.php、criar_usuario.php、importar.php）只调用相同的操作。',
        'Fora da API, só o cron (cron.php), a cada minuto pela linha de comando, com as mesmas funções que a API usa; o que ele fez sai em recurso=cron.' => 'API 之外，只有 cron（cron.php），每分钟由命令行运行，使用 API 所用的相同函数；它所做的出现在 recurso=cron 中。',
        'Sem framework e sem dependências: PHP 8.1+ e JavaScript puro. A reescrita pode usar outra pilha, desde que mantenha o contrato da API, o modelo de dados e as regras.' => '没有框架、没有依赖：PHP 8.1+ 和纯 JavaScript。重写可以使用另一套技术栈，只要保持 API 契约、数据模型和规则。',
        'A ordem de construção' => '构建顺序',
        '1. O banco: as tabelas do modelo_de_dados, com as chaves e as regras; a instalação (o schema inteiro num banco vazio) e as migrações (uma lista ordenada; cada uma com o SQL, um passo opcional em programa, e uma marca de aplicada: uma tabela, uma coluna ou uma linha da tabela sistema; com alguma pendente, o sistema para e a Configuração mostra o botão de aplicar). A v25 refaz o banco inteiro: copia tudo para um arquivo, cria a estrutura nova e devolve os registros na forma nova, com os mesmos ids.' => '1. 数据库：modelo_de_dados 中的表，带键和规则；安装（在空数据库中建立整个 schema）和迁移（一个有序列表；每项含 SQL、一个可选的程序步骤和一个已应用标记：一张表、一列或 sistema 表中的一行；有待处理的迁移时，系统停止，设置页面显示应用按钮）。v25 会重建整个数据库：把所有内容复制到一个文件，创建新结构，并以新形式、相同的 id 写回记录。',
        '2. O conjunto inicial (modelo.json: a árvore Smartwatch / Tradicional › Mecânico › Automático e Corda manual / Tradicional › Quartzo › Pilha e Solar, os campos, os tipos de lançamento, as fórmulas, os avisos, os critérios, as categorias e os modos) como dados, entrando no idioma de quem cria a coleção.' => '2. 初始集合（modelo.json：树 Smartwatch / Tradicional › Mecânico › Automático 和 Corda manual / Tradicional › Quartzo › Pilha 和 Solar，字段、记录类型、公式、提醒、标准、分类和模式）作为数据，以创建收藏者的语言载入。',
        '3. As contas e a autenticação (o login HTTP Basic, o token pessoal, o token do servidor), a coleção do pedido e o escopo dela no banco, e o esqueleto da API: os formatos, os erros (400, 401, 403, 404, 409, 413, 500, 503) e os filtros genéricos de qualquer consulta (incluir, excluir, f[], busca, ordem, limite, pagina, mostrar).' => '3. 账户与认证（HTTP Basic 登录、个人令牌、服务器令牌）、请求所在的收藏及其在数据库中的作用范围，以及 API 的骨架：格式、错误（400、401、403、404、409、413、500、503）以及任何查询的通用筛选（incluir、excluir、f[]、busca、ordem、limite、pagina、mostrar）。',
        '4. A árvore, os campos (com a validação do valor pelo tipo), os relógios e as fotos.' => '4. 树、字段（按类型校验值）、手表和照片。',
        '5. Os tipos de lançamento e os lançamentos (instantâneo, com valor, sessão; sessão exclusiva fecha as outras exclusivas no mesmo instante; sem sobreposição de sessões do mesmo tipo), e a linha do tempo.' => '5. 记录类型和记录（瞬时、带数值、时段；独占时段在同一时刻结束其他独占时段；同一类型的时段不重叠），以及时间线。',
        '6. O motor das fórmulas (abaixo), as variáveis de um relógio e o botão Testar.' => '6. 公式引擎（见下）、一块手表的变量以及测试按钮。',
        '7. Os avisos, a visão de cada relógio (agora, carga, situação, próxima manutenção) e a página Hoje.' => '7. 提醒、每块手表的视图（现在、电量、情况、下次保养）以及今天页面。',
        '8. O gasto medido pelas leituras e a previsão da energia (autonomia).' => '8. 由读数得出的实测消耗以及能量预测（续航）。',
        '9. Os critérios e a nota; os modos de rodízio, o plano, a garantia de rodízio, trocar o dia, sortear de novo; a escala inteligente.' => '9. 标准和分数；轮换模式、计划、轮换保障、更换某一天、重新抽签；智能排班表。',
        '10. O pulso sozinho e as sessões esquecidas; o cron.' => '10. 独自上手腕以及被忘记的时段；cron。',
        '11. Os destinos das mensagens (webhook, e-mail, Web Push), as agendas (Google, CalDAV, Outlook, link ICS) e os eventos personalizados, cada um com o que recebe e o seu modelo.' => '11. 消息推送目标（webhook、电子邮件、Web Push）、日历（Google、CalDAV、Outlook、ICS 链接）和自定义事件，每个都有其接收内容和模板。',
        '12. Os documentos (pasta, cópia no banco em três níveis, galeria, vídeos, PDF, NF-e) e a manutenção deles no cron.' => '12. 文档（文件夹、数据库副本的三级、图库、视频、PDF、NF-e）以及 cron 中对它们的维护。',
        '13. As telas, as contas (o cadastro aberto, Minha conta, as Aprovações, o painel do master), as execuções do cron, a ajuda (o README dentro do sistema: os mesmos trechos que recurso=manual devolve) e a importação do sistema anterior.' => '13. 界面、账户（公开注册、我的账户、审批、master 面板）、cron 执行记录、帮助（系统内的 README：与 recurso=manual 返回的相同片段）以及从旧系统导入。',
        '14. A aceitação: o roteiro de testes nos quatro bancos dá as mesmas respostas (seção testes).' => '14. 验收：四个数据库上的测试脚本给出相同响应（testes 一节）。',
        'A árvore, os campos e os relógios' => '树、字段和手表',
        'A árvore de grupos tem quantos níveis o usuário quiser; um relógio fica num grupo só (ou na raiz). Tudo o que se cadastra num grupo (campos, tipos de lançamento, fórmulas, avisos, critérios, a origem de um bloco de modo) vale para ele e para tudo abaixo dele.' => '分组树有用户想要的多少层；一块手表只在一个分组中（或在根）。登记在一个分组上的一切（字段、记录类型、公式、提醒、标准、模式区块的来源）对该分组及其下的一切有效。',
        'O mesmo nome pode se repetir em ramos diferentes, mas não entre irmãos. Mover um grupo para dentro dele mesmo (ou de um de dentro) é recusado. Excluir um grupo pela tela passa antes o que era dele para o grupo de cima (os de dentro, os relógios, os campos, os tipos, as fórmulas, os avisos e os blocos que sorteavam dele); versões de fórmula e de aviso que o grupo de cima já tem saem.' => '同一名称可以在不同分支重复，但不能在兄弟之间重复。把一个分组移入它自己（或它内部的一个）会被拒绝。通过页面删除一个分组时，先把它的内容交给上级分组（内部的、手表、字段、类型、公式、提醒以及从它抽签的区块）；上级分组已经有的公式版本和提醒版本则去掉。',
        'Campos: identificador (minúsculas, números e _, começando por letra, até 40; único entre campos e fórmulas, porque é o nome nas fórmulas; não muda se alguma fórmula usa), nome, tipo (listas.tipos_de_campo), unidade, valor padrão, o grupo, a ordem e a marca só nos desejados (so_desejado). Os campos de um relógio são os de todos e os de cada grupo da cadeia dele (os só nos desejados, só no desejado).' => '字段：标识符（小写、数字和 _，以字母开头，最多 40；在字段和公式之间唯一，因为它是公式中的名称；若有公式使用则不能改）、名称、类型（listas.tipos_de_campo）、单位、默认值、分组、顺序以及仅心愿中的标记（so_desejado）。一块手表的字段是全部的以及它链条上每个分组的（仅心愿中的，只在心愿中）。',
        'O valor de um campo é conferido e normalizado pelo tipo: inteiro; decimal (aceita 1.079,99, 1079,99 e 1079.99, grava com ponto); sim/não (1, sim, s, true; 0, não, nao, n, false); data AAAA-MM-DD; lista (uma das opções); texto (até 1000). Vazio apaga. O valor usado nas contas é o informado, senão o padrão do campo.' => '字段的值按类型核对并规范化：整数；小数（接受 1.079,99、1079,99 和 1079.99，以点保存）；是/否（1、sim、s、true；0、não、nao、n、false）；日期 AAAA-MM-DD；列表（选项之一）；文本（最多 1000）。空则删除。计算中使用的值是已填写的，否则是字段的默认。',
        'A situação na coleção de cada relógio (posse): colecao (o padrão), desejado (a lista de desejos), emprestado, vendido ou arquivado. Só o que está na coleção entra no rodízio: nas outras, o relógio fica indisponível (o banco garante, ck_relogio_posse_disponivel; a gravação força disponivel=0 e diz isso na mensagem), e por isso sai do sorteio, da escala e dos avisos sem regra a mais. Saindo da coleção, as sessões abertas dele fecham agora (com a nota "Fechei agora: ..."), os dias dele no plano de amanhã em diante saem e são sorteados de novo (com escala, gerar_escala de amanhã; sem, garantir_plano); hoje fica, mas a sessão do dia (o pulso sozinho) não abre para um relógio fora da coleção. Voltando para a coleção sem dizer o disponível, ele fica disponível. Da coleção (contam na tabela da página Hoje e no valor): na coleção e emprestado (o estado do emprestado parado é "Emprestado"); desejado, vendido e arquivado vão para fora_da_colecao (recurso=hoje) e para a página Desejos. Um campo com so_desejado=1 (o preço-alvo, a prioridade) vale só no desejado: campos_do_relogio o deixa de fora nos outros, e a gravação dos valores também. A lista de desejos (recurso=desejos) vem da prioridade mais alta para a mais baixa (a ordem das opções do campo prioridade_desejo; sem prioridade, no fim), depois pelo nome, com a soma dos preços-alvo; no painel do desejado, o quadro Desejo e os documentos tomam o lugar dos do dia a dia.' => '每块手表在收藏中的情况（posse）：colecao（默认）、desejado（心愿单）、emprestado、vendido 或 arquivado。只有在收藏中的才进入轮换：在其他情况中，手表变为不可用（数据库保证，ck_relogio_posse_disponivel；写入强制 disponivel=0 并在消息中说明），因此无需额外规则就离开抽签、排班表和提醒。离开收藏时，它已打开的时段现在结束（说明“现在结束了：……”），它在计划中从明天起的日子被去掉并重新抽签（有排班表时，从明天 gerar_escala；没有时，garantir_plano）；今天保留，但当天的时段（独自上手腕）不会为收藏之外的手表打开。回到收藏而未说明可用时，它变为可用。属于收藏（计入今天页面的表格和金额）：在收藏中和已借出（已借出停着的状态是“已借出”）；desejado、vendido 和 arquivado 进入 fora_da_colecao（recurso=hoje）以及心愿单页面。so_desejado=1 的字段（目标价格、优先级）只在心愿中有效：campos_do_relogio 在其他情况中把它排除，值的写入也同样。心愿单（recurso=desejos）从最高优先级到最低（prioridade_desejo 字段选项的顺序；没有优先级的在末尾），然后按名称，并带目标价格合计；在心愿中的面板里，心愿框和文档取代逐日的那些。',
        'Acessórios (tabela acessorio): nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro), o relógio de que ele é (opcional: sem ele, solto; excluir o relógio deixa solto, ON DELETE SET NULL), observação (até 1000) e quando foi cadastrado. A lista vem pelo tipo e pelo nome; a ficha traz os do relógio.' => '配件（表 acessorio）：名称（最多 120）、类型（pulseira（表带）、caixa（表盒）、estojo（收纳盒）、ferramenta（工具）、carregador（充电器）、peca（零件）、outro（其他））、它所属的手表（可选：没有则为未绑定；删除手表则变为未绑定，ON DELETE SET NULL）、备注（最多 1000）以及何时登记。列表按类型和名称；详情带来该手表的那些。',
        'Relógio: nome (até 120), grupo, situação na coleção, disponível (fora do rodízio e dos avisos quando não), a marca da cópia no banco dos documentos, a foto (JPEG, PNG ou WebP até 4 MB; o navegador reduz para 1200 px antes de enviar). Excluir apaga junto os valores, a foto, os documentos (e os arquivos), os lançamentos, o plano e os critérios próprios.' => '手表：名称（最多 120）、分组、在收藏中的情况、可用（否时离开轮换和提醒）、文档在数据库中副本的标记、照片（JPEG、PNG 或 WebP，最多 4 MB；浏览器在发送前缩小到 1200 px）。删除会一并去掉值、照片、文档（及文件）、记录、计划和自有标准。',
        'Os tipos de lançamento, os lançamentos e a linha do tempo' => '记录类型、记录和时间线',
        'Formatos (listas.formatos_de_lancamento): instantâneo (corda, troca de pilha), com valor (a leitura de carga, com unidade) e sessão, com início e fim (no pulso, no winder, no sol). Só a sessão tem "fecha às" (a hora em que a esquecida aberta fecha sozinha) e pode ser exclusiva (abrir uma exclusiva fecha as outras exclusivas abertas no mesmo instante: o relógio fica num lugar só). Só o com valor pode medir o gasto. A condição ("vale quando") é uma fórmula: o tipo só vale para os relógios em que ela dá verdadeiro.' => '格式（listas.formatos_de_lancamento）：瞬时（上链、更换电池）、带数值（电量读数，带单位）和时段，有开始和结束（在手腕上、在上链盒中、在晒太阳中）。只有时段有“结束于”（被忘记的已打开时段自行结束的时刻），并且可以是独占的（打开一个独占时段会在同一时刻结束其他已打开的独占时段：手表只在一个地方）。只有带数值的可以测量消耗。条件（“何时有效”）是一个公式：该类型只对它给出真的手表有效。',
        'Lançar: lancar (instantâneo ou com valor, num instante até agora), iniciar e encerrar (uma sessão; encerrar não antes do início), alternar (a sessão aberta se fecha, a fechada se abre: um botão só num atalho de celular), periodo (uma sessão inteira que já passou, sem sobrepor outra exclusiva de outro tipo; no pulso do relógio do dia, origem rodizio, como o iniciar; os trechos do mesmo tipo que ela cobre ou em que encosta viram um só, do primeiro início ao último fim, aberto se um deles está aberto), alterar e excluir (corrigir uma marcação). Em todas, relogio_id=hoje é o relógio do dia pelo plano. O formato de um tipo não muda depois de ter lançamentos; um tipo com lançamentos não é excluído.' => '记录：lancar（瞬时或带数值，在直到现在的某一时刻）、iniciar 和 encerrar（一个时段；结束不早于开始）、alternar（已打开的时段关闭，已关闭的打开：手机快捷方式上只有一个按钮）、periodo（一段已经过去的完整时段，不与另一种类型的独占时段重叠；当天手表在手腕上时，origem 为 rodizio，与 iniciar 相同；它覆盖或相接的同类型片段合并为一段，从最早的开始到最晚的结束，若其中之一仍打开则保持打开）、alterar 和 excluir（改正一条标记）。在全部操作中，relogio_id=hoje 是计划中当天的手表。一个类型在已有记录之后不能改格式；有记录的类型不能删除。',
        'A origem: manual (pela tela ou pela API), rodizio (a sessão no pulso do relógio do dia, aberta pelo sistema ou pelo Pôs no relógio do dia) e importado.' => '来源：manual（通过页面或 API）、rodizio（当天手表在手腕上的时段，由系统或“已戴上当天的手表”打开）和 importado。',
        'A linha do tempo de um relógio divide o histórico em trechos contínuos: em uso pelo rodízio, em uso fora do plano (no pulso sem ser o relógio do dia), em cada tipo de sessão (no winder, no sol...) e em repouso (o que sobra); e as marcações (corda, carga, pilha, revisão) como pontos, sem duração. O resumo dá o tempo e a porcentagem em cada estado.' => '一块手表的时间线把历史分成连续片段：轮换中的使用中、计划之外的使用中（戴在手腕上但不是当天的手表）、每种时段类型（在上链盒中、在晒太阳中……）以及休息中（剩余的）；标记（上链、电量、电池、检修）作为点，没有时长。摘要给出每种状态的时间和百分比。',
        'O estado de agora de um relógio: em uso (uma sessão no pulso aberta), numa sessão (outra sessão aberta: o estado é o nome do tipo, "No sol", "No winder", "No carregador"; duas juntas, "No sol · No winder") ou em repouso; na tabela da página Hoje, o indisponível em repouso aparece como indisponível. Com o desde quando: o começo da sessão no pulso, o da sessão mais recente, ou o fim da última no pulso ("Em repouso desde 21:40"). A sessão esquecida aberta conta só até o "fecha às" dela. O pulso é o único tipo que o código conhece pelo identificador; os outros entram pelo nome.' => '一块手表现在的状态：使用中（一个在手腕上的时段已打开）、在一个时段中（另一个时段已打开：状态是类型名称，“晒太阳中”、“上链盒中”、“充电器中”；两个一起，“晒太阳中 · 上链盒中”）或休息中；在今天页面的表格中，休息中的不可用显示为不可用。带从何时起：手腕上时段的开始、最近一个时段的开始，或最后一次在手腕上的结束（“自 21:40 起休息中”）。被忘记的已打开时段只计到它的“结束于”。手腕是代码唯一按标识符认识的类型；其他的按名称进入。',
        'O motor das fórmulas' => '公式引擎',
        'A sintaxe é a de uma planilha: números com vírgula ou ponto, textos entre aspas, ; separando os argumentos, + - * / ^ (a potência associa à direita), as comparações = <> < <= > >= (dão 1 ou 0), o sinal, os parênteses, as variáveis e as funções (listas.funcoes_das_formulas). A precedência, da mais fraca para a mais forte: comparação, soma, produto, potência, sinal.' => '语法如同一张电子表格：数字用逗号或点，文本在引号之间，; 分隔参数，+ - * / ^（幂从右结合），比较 = <> < <= > >=（给出 1 或 0），符号、括号、变量和函数（listas.funcoes_das_formulas）。优先级，从最弱到最强：比较、加法、乘法、幂、符号。',
        'Um valor vazio se propaga pela conta (vazio + 1 = vazio); a divisão por zero dá vazio. MIN e MAX ignoram os vazios. PADRAO(x; outro) troca o vazio. Um erro de escrita diz a posição ("falta fechar as aspas", "\\";\\" sobrando na posição 12").' => '空值在计算中传播（空 + 1 = 空）；除以零得到空。MIN 和 MAX 忽略空值。PADRAO(x; outro) 替换空值。书写错误会指出位置（“引号没有闭合”、“位置 12 多出了“;””）。',
        'As variáveis de um relógio: os campos (o valor usado), as fórmulas (pelo identificador; uma fórmula pode usar outra, sem ciclo) e as que o sistema dá. Cada fórmula pode ter uma versão por grupo; vale a do grupo mais perto do relógio (a dele, senão a de cima, ... senão a de todos). Uma fórmula que não tem versão para o relógio fica vazia nele.' => '一块手表的变量：字段（使用的值）、公式（按标识符；一个公式可以使用另一个，不能成环）以及系统给出的那些。每个公式可以按分组有一个版本；取离手表最近的分组的（它自己的，否则上级的，……否则全部的）。对这块手表没有版本的公式在它那里为空。',
        'As funções de histórico leem os lançamentos do relógio até o instante da conta (o primeiro argumento é o identificador do tipo, entre aspas). ACUMULA percorre o histórico como um saldo: começa no início, perde por hora, ganha por hora em cada sessão da lista, passa a valer o efeito num instantâneo da lista, sempre entre 0 e o máximo. É ela que faz a reserva de marcha e a carga de luz.' => '历史函数读取该手表直到计算时刻的记录（第一个参数是类型的标识符，在引号中）。ACUMULA 把历史当作余额遍历：从起点开始，按小时损失，在列表中每个时段按小时获得，在列表中的一个瞬时变为该效果的值，始终在 0 和最大值之间。动力储存和光充电量就是由它完成的。',
        'Testar: a mesma fórmula calculada em todos os relógios (ou nos escolhidos), sem gravar, com o caminho da conta (rastro). Antes de gravar uma fórmula, o sistema a lê (erro de escrita) e confere as variáveis e os tipos que ela usa. Renomear ou excluir um campo, um tipo ou uma fórmula que outra fórmula usa é recusado, com a lista de quem usa.' => '测试：同一公式在全部手表（或所选的）上计算，不保存，带计算路径（rastro）。保存公式之前，系统读取它（书写错误）并核对其使用的变量和类型。重命名或删除被另一个公式使用的字段、类型或公式会被拒绝，并列出使用者。',
        'O tempo nas contas é em dias: HOJE() é a meia-noite local de hoje, AGORA() o instante, e as datas dos campos viram dias pelo mesmo relógio. As horas viram dias dividindo por 24.' => '计算中的时间以天计：HOJE() 是今天的本地午夜，AGORA() 是此刻，字段的日期按同一时钟变成天。小时除以 24 变成天。',
        'Os avisos e a visão de cada relógio' => '提醒以及每块手表的视图',
        'Um aviso tem uma fórmula que dá a data prevista (expressao, em dias), uma condição (vale quando), a antecedência (0 a 3650 dias), o texto (até 300, com {relogio}, {data}, {quando} e {limite}), o tipo de lançamento que resolve (o botão na tela Hoje), se está ativo, uma versão por grupo (como as fórmulas), e como a escala simula a solução (escala: nao, uso ou sempre; o valor ou as horas simuladas) e se entra na agenda só dentro da janela de antecedência ou sempre.' => '一个提醒有一个给出预计日期的公式（expressao，以天计）、一个条件（何时有效）、提前量（0 到 3650 天）、文本（最多 300，带 {relogio}、{data}、{quando} 和 {limite}）、用来解决的记录类型（今天页面上的按钮）、是否启用、按分组的一个版本（如同公式），以及排班表如何模拟解决方案（escala：nao、uso 或 sempre；模拟的数值或小时）以及是只在提前量窗口内进入日历还是始终进入。',
        'Um relógio fora da coleção (desejado, vendido, arquivado) não tem aviso nenhum (o emprestado tem). O aviso vale para um relógio disponível quando a condição dá verdadeiro e a data prevista existe; sai hoje quando a data menos a antecedência já chegou. Estado: atrasado (a data passou) ou em breve. O aviso de um relógio com uma sessão aberta à mão (carregando, no sol) não vai para a agenda enquanto ela estiver aberta: a data andaria a cada conta.' => '收藏之外的手表（心愿中、已售出、已归档）没有任何提醒（已借出的有）。当条件为真且预计日期存在时，提醒对一块可用手表有效；日期减去提前量已经到达时，今天发出。状态：atrasado（日期已过，即逾期）或即将。一块手表有手动打开的时段（正在充电、在晒太阳）时，它的提醒在该时段打开期间不进入日历：日期会在每次计算时变动。',
        'Os avisos de carga usam o limite de carga: o do relógio (campo carga_minima), senão o geral da Configuração (carga_limiar); o solar usa sol_limiar. A data do Carregar é pelo gasto do estado de agora (no pulso, o de uso; guardado, o de guardado); no carregador, o Carregar some e vale o Tirar do carregador (carregado: vence quando a bateria enche no carregador).' => '电量提醒使用电量下限：手表自己的（字段 carga_minima），否则是设置中的一般值（carga_limiar）；太阳能使用 sol_limiar。充电的日期按现在状态的消耗（在手腕上，用使用中的；存放着，用存放的）；在充电器中，充电消失，改为离开充电器有效（已充满：在充电器中电池充满时到期）。',
        'Um aviso pode ser "na hora" (na_hora): além do alerta da manhã, o cron manda pelos destinos que o recebem no minuto em que ele vence, uma vez, e guarda quais já foram (config.na_hora_enviados, relogio_id:identificador); um aviso sai da lista quando deixa de vencer. O botão do aviso na página Hoje vem da API (resolve.acao e resolve.botao): a sessão que resolve, aberta, se encerra ("Tirou do carregador"); fechada, se inicia ("Pôs no sol"); a leitura se informa.' => '提醒可以是“准时”的（na_hora）：除早晨的提醒外，cron 会在它到期的那一分钟通过接收它的推送目标发送一次，并记录哪些已经发送（config.na_hora_enviados，relogio_id:identificador）；提醒不再到期时就从列表中移除。今天页面上提醒的按钮来自 API（resolve.acao 和 resolve.botao）：用来解决它的时段若已开始则结束（“从充电器上取下”）；若未开始则开始（“放到阳光下”）；读数则直接填写。',
        'O aviso Encostado (encostado, de todos os relógios, resolve com o pulso) é só cadastro: a data prevista é PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias") (a Configuração, padrão 30), antecedência 0; sem nunca ter ido ao pulso nem data da compra, não avisa. Não entra na próxima manutenção nem no "O que fazer": a tabela da coleção tem a coluna Encostado, o cartão do dia mostra a falta quando já venceu, e o quadro Agora do painel também. A caixa "Avisar quando um relógio fica encostado" da Configuração (config encostado_ativo) liga e desliga o aviso do cadastro (aviso.ativo, o mesmo que a página Avisos); desligado, some tudo que é dele: o aviso em Hoje é dia de e nas mensagens, a linha do cartão e do painel, a coluna e o filtro da tabela.' => '闲置提醒（encostado，全部手表，用手腕解决）只是档案：预计日期是 PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias")（设置，默认 30），提前量 0；从未上手腕也没有购买日期时，不提醒。它不进入下次保养，也不进入“要做什么”：收藏表格有闲置列，当天的卡片在已经到期时显示缺失，面板的现在框也显示。 设置中的“手表闲置时提醒”复选框（config encostado_ativo）开启和关闭档案的提醒（aviso.ativo，与提醒页面相同）；关闭后，属于它的一切都消失：“今天该戴”和消息中的提醒、卡片和面板中的行、表格的列和筛选。',
        'A visão de cada relógio (a tabela da página Hoje e o painel): em uso ou em repouso desde quando, a carga estimada agora e de onde vem (a fórmula energia e a origem), a situação (frases curtas: autonomia restante, reserva...), a próxima manutenção (o aviso mais perto, sem o Encostado), o que fazer e a coluna Encostado.' => '每块手表的视图（今天页面的表格和面板）：使用中或休息中从何时起、现在估计的电量以及来自何处（公式 energia 和来源）、情况（短句：剩余续航、储能……）、下次保养（最近的提醒，不含闲置）、要做什么以及闲置列。',
        'O gasto medido pelas leituras e a autonomia' => '由读数得出的实测消耗以及续航',
        'Cada leitura de carga de um tipo que mede o gasto é comparada com a anterior do mesmo relógio: o intervalo vira uma medição, com a queda, as horas no pulso e as horas fora do pulso no intervalo (o horário de uso conta como pulso sozinho quando o pulso sozinho está ligado; as marcações Pôs e Tirou mandam) e a marcação das duas leituras (lancamento.estado: uso ou repouso, gravada na leitura; a leitura sem marcação, de antes ou de um script que não diz, vale o que o pulso registrado dizia naquele instante). Uma subida é recarga: novo ponto de partida, sem medir. Só entram intervalos de 1 hora ou mais. Um intervalo com outra sessão no meio (o carregador) não mede: a medição só separa pulso e guardado. Ao lançar uma leitura marcada ao contrário do pulso registrado naquele instante, a API responde confirmar: true com a pergunta, e só grava de novo com confirmar=1 (vale o que a pessoa marcou; nada é impedido e o pulso registrado não muda).' => '测量消耗的类型中每次电量读数都与同一手表的上一次比较：间隔成为一次测量，包含下降量、间隔内佩戴小时数和未佩戴小时数（开启自动佩戴时，使用时段自动算作佩戴；“戴上”和“取下”标记起决定作用）以及两次读数的标记（lancamento.estado：uso 或 repouso，保存在读数中；没有标记的读数，无论是之前的还是脚本未说明的，以那一刻记录的佩戴状态为准）。上升即充电：新的起点，不测量。只有 1 小时或更长的间隔才计入。中间有其他会话（充电器）的间隔不测量：测量只区分佩戴和存放。录入的读数标记与那一刻记录的佩戴状态相反时，API 返回 confirmar: true 和提问，只有再次发送并带 confirmar=1 才保存（以本人的标记为准；不会阻止任何操作，记录的佩戴状态也不改变）。',
        'Cinco motores transformam as medições nos dois gastos (GASTO_MOTORES: horas, robusto, marcacao, cadastro, formulas), e a pessoa escolhe em três níveis, o de cima valendo sobre os de baixo (gasto_motor_de: a chave gasto_motor da Configuração da coleção; senão o valor do campo gasto_motor no relógio (uma lista com os cinco, na raiz do cadastro inicial); senão o padrão desse campo, na versão dele mais perto do relógio na árvore (o grupo); senão horas). A ficha diz o motor e de onde veio (previsao.gasto.motor, motor_nome, motor_de). Quais medições entram é outra chave, medicao_base: dias (as dos últimos medicao_janela_dias, padrão 90) ou leituras (as últimas medicao_janela_leituras de cada tipo, em uso e em repouso, padrão 20); sem nenhuma na janela, as de antes (medicoes_janela).' => '五种引擎把测量转换成两种消耗（GASTO_MOTORES：horas、robusto、marcacao、cadastro、formulas），由本人在三个层级选择，上层优先于下层（gasto_motor_de：收藏设置的 gasto_motor 键；否则手表中 gasto_motor 字段的值（初始档案根部的一个含五项的列表）；否则该字段在树中离手表最近版本的默认值（分组）；否则 horas）。档案说明引擎及其来源（previsao.gasto.motor、motor_nome、motor_de）。哪些测量计入是另一个键 medicao_base：dias（最近 medicao_janela_dias 天的，默认 90）或 leituras（每类最近 medicao_janela_leituras 次，使用中和静置中，默认 20）；窗口内没有时，用之前的（medicoes_janela）。',
        '1. horas (gasto_medido_horas, o original): cada medição dividida pelas marcações de pulso minuto a minuto (horas_pulso, horas_guardado), e os dois gastos saem juntos por mínimos quadrados nas quedas, cada medição pesando as horas que cobre (peso_horas); sem separar os dois, a média de cada lado. 2. robusto (gasto_medido_desde): a conta é feita nas LEITURAS: entre duas recargas, leitura = carga do começo − gasto em uso × dias de uso − gasto guardado × dias guardado + erro. Medições seguidas (o fim de uma é o começo da outra) formam um trecho, cada trecho com a carga do começo dele (desconhecida; sai da conta tirando a média de cada trecho), e os dois gastos valem para todos. Mínimos quadrados com o mesmo peso para todas as leituras (o erro é o do mostrador e do medidor, o mesmo em 2 horas ou 2 semanas), repesados por Huber (peso 1 até 1,345 σ do desvio; depois 1,345 σ ÷ |desvio|; σ = 1,4826 × a mediana dos desvios, no mínimo 0,5 ponto), até os pesos pararem de mudar. O gasto do cadastro (taxa_uso e taxa_repouso sem as medições, gasto_prior) entra como média a priori, com desvio padrão de metade do valor (no mínimo 2% por dia de uso e 0,5% por dia guardado): a conta é a média a posteriori, (XᵀWX/σ² + Λ)β = XᵀWy/σ² + Λβ0, nunca negativa; a incerteza (uso_dp, repouso_dp) é a raiz da diagonal da inversa. De cada medição, a leitura dela que pesa menos (a do começo ou a do fim) dá o peso, o erro (em pontos) e o valor; pesando menos da metade, ela não bate com as outras (fora).' => '1. horas（gasto_medido_horas，原始）：每次测量按逐分钟的佩戴标记划分（horas_pulso、horas_guardado），两种消耗由对下降量的最小二乘法一起得出，每次测量以其覆盖的小时数为权重（peso_horas）；无法区分两者时，取各自一侧的平均。2. robusto（gasto_medido_desde）：计算在读数上进行：两次充电之间，读数 = 起始电量 − 使用中消耗 × 使用天数 − 存放消耗 × 存放天数 + 误差。连续的测量（一次的结束是下一次的开始）构成一个时段，每个时段有自己的起始电量（未知；通过减去各时段均值从计算中消去），两种消耗对所有时段都适用。对所有读数使用相同权重的最小二乘（误差来自显示和电量计，2 小时和 2 周的误差相同），用 Huber 重新加权（残差在 1.345 σ 以内权重 1；之后为 1.345 σ ÷ |残差|；σ = 1.4826 × 残差的中位数，至少 0.5 点），直到权重不再变化。档案的消耗（不含测量的 taxa_uso 和 taxa_repouso，gasto_prior）作为先验均值进入，标准差为其值的一半（至少每使用日 2%、每存放日 0.5%）：计算结果是后验均值，(XᵀWX/σ² + Λ)β = XᵀWy/σ² + Λβ0，永不为负；不确定度（uso_dp、repouso_dp）是逆矩阵对角线的平方根。每次测量中权重较小的那次读数（起始或结束）给出权重、误差（以点计）和值；权重低于一半时，它与其他不吻合（fora）。',
        '3. marcacao (medicoes_da_conta por marcação + gasto_medido_desde): só as medições cujas duas leituras têm a mesma marcação; a marcada em uso mede o gasto em uso com o tempo inteiro do intervalo como dias de uso (as horas de um dia de uso são as do horário de uso), e a marcada em repouso mede o gasto fora com o intervalo inteiro em dias guardados; as duas contas nunca se cruzam (o pulso registrado não entra), cada uma robusta como a 2, com a incerteza; com poucas medições o cadastro (o ponto de partida) puxa o medido, e a API dá também o que só as leituras dariam (previsao.gasto.<medida>.so_leituras, a mesma conta sem o cadastro; puxado: verdadeiro quando os dois diferem) e quantas medições de cada tipo entram (medicoes); o detalhe do gasto medido diz "pela marcação, dos últimos 90 dias: 1 em uso e 1 em repouso". 4. cadastro: MEDIDO dá vazio e valem só o decaimento e a autonomia do cadastro; as medições continuam sendo feitas e ficam no histórico. 5. formulas: vale o que as fórmulas taxa_uso e taxa_repouso derem; nelas MEDIDO é a conta 3, e as funções LEITURAS, QUEDA, DIAS_MEDIDOS, MEDIA_TAXA, MEDIANA_TAXA (todas com "uso" ou "repouso" e, opcional, os últimos N dias; sem N ou 0, a janela da Configuração) e ULTIMA_TAXA dão as peças das medições pela marcação. Nos outros motores as fórmulas também valem (é delas que sai o gasto que vale). A pessoa também tira ou põe uma medição na conta (lancamento medicao, usada 0 ou 1), sem apagar nada; vale nos motores 1, 2, 3 e 5. O resultado também é dado na janela anterior, para comparar (a bateria envelhecendo).' => '3. marcacao（按标记的 medicoes_da_conta + gasto_medido_desde）：只取两次读数标记相同的测量；标记为使用中的以整个间隔作为使用天数测量使用中消耗（一个使用日的小时数即使用时段的小时数），标记为静置中的以整个间隔作为存放天数测量未佩戴消耗；两种计算永不交叉（记录的佩戴状态不参与），各自像 2 一样稳健，带不确定度；测量较少时，档案（起点）会拉动实测值，API 还给出仅凭读数会得到的值（previsao.gasto.<medida>.so_leituras，不以档案为起点的同一计算；puxado：两者不同时为 true）以及每种类型计入的测量数（medicoes）；实测消耗的说明为“按标记，最近 90 天：使用中 1 次，静置中 1 次”。4. cadastro：MEDIDO 为空，只有档案的衰减和续航生效；测量仍然进行并留在历史中。5. formulas：以 taxa_uso 和 taxa_repouso 公式的结果为准；其中 MEDIDO 是计算 3，函数 LEITURAS、QUEDA、DIAS_MEDIDOS、MEDIA_TAXA、MEDIANA_TAXA（都带 "uso" 或 "repouso"，可选最近 N 天；不给 N 或为 0 时用设置中的窗口）和 ULTIMA_TAXA 给出按标记测量的各部分。其他引擎中公式同样生效（生效的消耗来自公式）。本人也可以把一次测量移出或放回计算（lancamento medicao，usada 0 或 1），不删除任何东西；在引擎 1、2、3 和 5 中有效。结果也在前一窗口给出，以便比较（电池老化）。',
        'MEDIDO("uso") e MEDIDO("repouso") dão esses gastos às fórmulas; corrigir uma marcação de pulso (ou a marcação de uma leitura) recalcula as horas das medições que cobrem aquele trecho.' => 'MEDIDO("uso") 和 MEDIDO("repouso") 把这些消耗提供给公式；修正佩戴标记（或读数的标记）会重新计算覆盖该时段的测量的小时数。',
        'A autonomia: cheio pelo cadastro e pela conta (com o gasto medido), quando acaba seguindo o plano (simulando os dias do plano), quanto dura no pulso sem tirar e guardado; e a previsão do smartwatch (a carga dia a dia, até o limite).' => '续航：按档案和按计算充满（用实测消耗）、按计划走到何时结束（模拟计划中的日子）、不摘下时在手腕上能持续多久以及存放时；以及智能手表的预测（逐日电量，直到下限）。',
        'Os critérios e a nota' => '标准与分数',
        'Um conjunto de critérios por lugar: todos os relógios, um grupo ou um relógio. O relógio usa o conjunto mais perto dele, inteiro (o dele, senão o do grupo, senão o de cima, ..., senão o de todos).' => '每个位置一套标准：全部手表、一个分组或一块手表。手表使用离它最近的整套（它自己的，否则分组的，否则上级的，……否则全部的）。',
        'O conjunto tem parâmetros com peso (somam 100%); cada parâmetro tem subparâmetros com peso (somam 100% dentro dele); cada subparâmetro lê uma variável (um campo ou uma fórmula) e transforma o valor em nota (0 a 100) pelas faixas: de um número até outro (a primeira começa em 0, sem buracos nem sobreposição, só a última sem limite) ou por categoria (campo de lista ou texto).' => '集合有带权重的参数（合计 100%）；每个参数有带权重的子参数（在它内部合计 100%）；每个子参数读取一个变量（一个字段或一个公式）并按区间把值变成分数（0 到 100）：从一个数到另一个数（第一个从 0 开始，没有空洞也没有重叠，只有最后一个没有上限）或按类别（列表字段或文本）。',
        'A nota do parâmetro é a média das notas dos subparâmetros, pelo peso; a nota do relógio, a média dos parâmetros, pelo peso. Um subparâmetro sem valor (campo vazio, valor fora de toda faixa) sai da conta e os outros dividem o peso dele. A conta inteira de cada nota é mostrada (cada faixa, cada peso, cada ponto).' => '参数的分数是子参数分数按权重的平均；手表的分数是参数按权重的平均。没有值的子参数（空字段、值落在所有区间之外）离开计算，其他的分掉它的权重。每一个分数的完整计算都会显示（每一个区间、每一个权重、每一个得分）。',
        'Restaurar os critérios iniciais apaga os de todos os lugares e volta aos do cadastro inicial.' => '恢复初始标准会删除所有位置的标准并回到初始档案中的那些。',
        'Os modos de rodízio, o plano e a escala inteligente' => '轮换模式、计划与智能排班表',
        'Hoje sem relógio (rodizio sem_relogio): o plano de hoje sai e hoje vira um dia livre; a sessão do rodízio de hoje que já começou fecha agora (o tempo dela conta como uso), a que ainda não começou sai; a sessão do dia (o pulso sozinho) não abre num dia sem plano, e o garantir_plano não põe de volta como plano de hoje o relógio que esteve no pulso pelo rodízio num dia livre. Os outros dias não mudam. Desfaz: trocar_dia (ou usando) de hoje, ou resortear_hoje.' => '今天没有手表（rodizio sem_relogio）：今天的计划去掉，今天变成空闲日；今天已经开始的轮换时段现在结束（它的时间计为使用），尚未开始的去掉；当天的时段（独自上手腕）在没有计划的一天不打开，并且 garantir_plano 不会把曾因轮换在空闲日上手腕的手表放回为今天的计划。其他日子不变。撤销：今天的 trocar_dia（或 usando），或 resortear_hoje。',
        'Um modo tem um tipo (modo.tipo: semana, semana_fds, dia_semana, aleatorio, escala, personalizado), a forma de escolha (selecao: inteligente, a maior nota; ponderado, sorteio com a nota como chance; aleatorio; fifo, quem espera há mais tempo), as semanas à frente (modo.semanas, 1 a 8; a escala usa escala_dias, 7 a 730), o ciclo e blocos de dias da semana (cada dia em um bloco só; cada bloco diz de onde escolher: um grupo, a coleção toda ou um relógio fixo, e se é um relógio por dia ou um para o bloco). No máximo um modo em uso. A tela de cada tipo é só um jeito de preencher os blocos (um por semana: um bloco com os sete dias, um para o bloco; semana e fim de semana: segunda a sexta e sábado e domingo; por dia da semana: um bloco por dia; aleatório e escala: um bloco com os sete dias); o tipo se infere dos blocos quando não vem (modo_tipo_inferir), e foi assim que a migração v30 classificou os modos que existiam.' => '一个模式有类型（modo.tipo：semana、semana_fds、dia_semana、aleatorio、escala、personalizado）、选择方式（selecao：inteligente，最高评分；ponderado，以评分为几率抽签；aleatorio；fifo，等待最久的）、提前周数（modo.semanas，1 到 8；排班使用 escala_dias，7 到 730）、循环和星期几区块（每天只属于一个区块；每个区块说明选自何处：一个分组、整个收藏或一块固定手表，以及是每天一块还是整段一块）。最多一个模式在使用。每种类型的界面只是填写区块的一种方式（每周一块：一个含七天的区块，整段一块；工作日和周末：周一到周五和周六周日；按星期几：每天一个区块；随机和排班：一个含七天的区块）；类型未提供时由区块推断（modo_tipo_inferir），迁移 v30 就是这样给已有模式分类的。',
        'Por baixo, todo modo é um roteiro: linhas "nome = expressão" na língua das fórmulas (roteiro_ler: nome repetido, escrita, variável ou tipo de lançamento desconhecido e círculo são erros), em que o motor lê cinco saídas (ROTEIRO_SAIDAS, com a expressão padrão de cada uma quando falta): candidato (1 entra no dia; padrão 1), nota (padrão nota_criterios, a variável do motor com a nota pelos critérios), peso (a chance; padrão 0), dias (quantos dias seguidos fica; padrão 1) e garantia (1 passa na frente; padrão E(CONFIG("max_sem_uso") > 0; dias_sem_uso > CONFIG("max_sem_uso"))). O personalizado grava o texto (modo.roteiro); os outros tipos geram o roteiro a cada uso, dos blocos e da forma de escolha (modo_roteiro_texto: candidato por dia da semana com NO_GRUPO(caminho) ou RELOGIO(nome), SE(DIA_SEMANA() <= 5; ...) ou ESCOLHA(DIA_SEMANA(); ...); dias "8 - DIA_SEMANA()" num bloco de sete dias um para o bloco, ESCOLHA por dia nos outros, PADRAO(dias_seguidos; 1) na escala; a forma: inteligente "peso = 0", ponderado "peso = MAX(1; nota_criterios)", aleatorio "peso = 1" e "garantia = 0", fifo "nota = dias_sem_uso" e "peso = 0"). As linhas do roteiro valem como variáveis (ctx locais, por cima de campo ou fórmula de mesmo nome). As funções do rodízio: DIA_SEMANA, SEMANA_DO_ANO (do dia que está sendo montado, ctx dia), NO_GRUPO (nome, caminho ou #id, sem acento nem maiúscula), RELOGIO, ESCOLHIDO_HA(n) (o plano há n dias; negativo: à frente), VEZES_NO_PLANO(n), ESCOLHA(n; ...) (só o escolhido é calculado) e SORTEIO() (0 a 1, do lote dos sorteios).' => '本质上，每种模式都是一个脚本：公式语言的“名称 = 表达式”各行（roteiro_ler：重复名称、书写、未知变量或记录类型、循环依赖都是错误），引擎从中读取五个输出（ROTEIRO_SAIDAS，缺失时用各自的默认表达式）：candidato（1 进入当天；默认 1）、nota（默认 nota_criterios，引擎变量，按标准的评分）、peso（几率；默认 0）、dias（连续佩戴多少天；默认 1）和 garantia（1 优先；默认 E(CONFIG("max_sem_uso") > 0; dias_sem_uso > CONFIG("max_sem_uso"))）。自定义保存文本（modo.roteiro）；其他类型每次使用时由区块和选择方式生成脚本（modo_roteiro_texto：每个星期几的 candidato 用 NO_GRUPO(路径) 或 RELOGIO(名称)、SE(DIA_SEMANA() <= 5; ...) 或 ESCOLHA(DIA_SEMANA(); ...)；dias 在整段一块的七天区块中为 "8 - DIA_SEMANA()"，其他为按天的 ESCOLHA，排班为 PADRAO(dias_seguidos; 1)；选择方式：inteligente "peso = 0"，ponderado "peso = MAX(1; nota_criterios)"，aleatorio "peso = 1" 和 "garantia = 0"，fifo "nota = dias_sem_uso" 和 "peso = 0"）。脚本的各行作为变量生效（ctx locais，优先于同名字段或公式）。轮换函数：DIA_SEMANA、SEMANA_DO_ANO（正在生成的那一天，ctx dia）、NO_GRUPO（名称、路径或 #id，不区分重音和大小写）、RELOGIO、ESCOLHIDO_HA(n)（n 天前的计划；负数：往后）、VEZES_NO_PLANO(n)、ESCOLHA(n; ...)（只计算被选的）和 SORTEIO()（0 到 1，来自抽签的批次）。',
        'A escolha de um dia (escolha_do_dia, para todos os modos, o "Sortear este dia por" e o Decida por mim do rodízio manual, cada um com o seu roteiro: roteiro_da_forma): o roteiro em cada relógio (candidato = 0 sai); só entre os candidatos, o de ontem fica de fora (se houver outro candidato; o único candidato repete, com "o de ontem (...) repetiu: é o único candidato do dia" no motivo); o ciclo do modo, também entre os candidatos (quem já passou na semana, pelo plano desde o primeiro dia da semana; se sobraria ninguém, não vale, e o motivo diz "todos os candidatos do dia já passaram na semana: o ciclo não tirou nenhum"); quem tem garantia = 1 ganha, o mais tempo parado primeiro (empate: o cadastrado primeiro; o motivo "Garantia de rodízio: ...", ou "Garantia do roteiro: ..." num roteiro escrito à mão); senão o peso: todos 0, a maior nota (empate: o cadastrado primeiro; "A maior nota (91,2), entre 4 candidatos." ou, na fila, "Fila: o mais tempo sem uso (...)"); todos iguais, sorteio simples ("Sorteio simples, entre 4 candidatos, todos com a mesma chance (fonte)."); senão o peso de cada um é a chance ("Sorteio pela nota, ...: nota 70,2, 16,4% de chance" ou "Sorteio pelo peso, ...: peso 100, 96,2% de chance"). Devolve o id, o motivo e os dias seguidos. A garantia de rodízio (max_sem_uso, padrão 21) é a config da coleção, a mesma para todos os modos; os dias sem uso de um relógio nunca usado contam desde a compra (sem data de compra: 9999).' => '一天的选择（escolha_do_dia，适用于所有模式、“按此方式抽这一天”和手动轮换的“替我决定”，各有自己的脚本：roteiro_da_forma）：对每块手表运行脚本（candidato = 0 退出）；只在候选中，昨天的排除（如果有别的候选；唯一的候选会重复，理由中写“昨天的（...）重复了：它是当天唯一的候选”）；模式的循环，同样在候选中（本周已轮过的，按本周第一天以来的计划；如果会一个不剩则不生效，理由写“当天所有候选本周都已轮过：循环没有排除任何一个”）；garantia = 1 的获胜，闲置最久的先（平局：先登记的；理由“轮换保证：...”，手写脚本为“脚本保证：...”）；否则看权重：全为 0，取最高评分（平局：先登记的；“最高评分（91.2），4 个候选中。”或队列中“队列：最久未使用的（...）”）；全部相等，简单抽签（“简单抽签，4 个候选中，所有手表机会相同（来源）。”）；否则各自的权重就是几率（“按评分抽签，...：评分 70.2，16.4% 的几率”或“按权重抽签，...：权重 100，96.2% 的几率”）。返回 id、理由和连续天数。轮换保证（max_sem_uso，默认 21）是收藏的配置，所有模式相同；从未使用过的手表的闲置天数从购买起算（没有购买日期：9999）。',
        'O montador do plano (plano_montar, um só para os blocos e a escala): de hoje até o horizonte, dia a dia; cada dia sem plano (e não livre) é escolhido por escolha_do_dia entre os disponíveis; o escolhido fica os dias que o roteiro deu, enquanto o dia seguinte estiver vago, não livre e ele continuar candidato nele (fora da escala, mesmo depois do horizonte: um relógio para a semana fica a semana inteira), com os motivos "... Fica N dias seguidos." e "Segue no pulso: dia i de N seguidos."; cada dia do plano vira uma sessão simulada no pulso no horário de uso (fora da escala, só o uso; na escala, a carga inteira e os avisos, como antes: o que vence vira plano.acao, o lançamento que resolve é simulado terminando no começo do dia). A semana do rodízio começa no dia da Configuração semana_inicio (segunda, o padrão, ou domingo: semana_comeca, semana_inicio e semana_fim no lib). O horizonte fora da escala (horizonte_do_modo): o último dia da última das semanas do modo (com uma semana só, no último dia da semana também o primeiro da seguinte); o ciclo conta o plano desde o primeiro dia da semana; a próxima semana é a que começa depois do último dia desta; no roteiro gerado, o relógio para o bloco fica até o último dia do bloco na ordem da semana (bloco_seguidos: o bloco que atravessa a virada da semana sem ter os sete dias, como sábado e domingo com a semana começando no domingo, conta do primeiro dia dele depois de um dia de fora); garantir_plano completa o que falta até ele, e resortear refaz até ele (ou até onde o sorteio já ia); gerar_escala apaga os sorteados de ini em diante e chama plano_montar até escala_fim. proxima_semana continua pela API em qualquer modo sem escala; a tela só a mostra com semanas > 1.' => '计划生成器（plano_montar，区块和排班共用一个）：从今天到范围终点，逐天进行；每个没有计划（且非空闲）的日子由 escolha_do_dia 在可用手表中选择；被选中的按脚本给出的天数留下，只要下一天空着、非空闲且它在那天仍是候选（排班之外，即使超出范围：整周一块的手表留满整周），理由为“... 连续佩戴 N 天。”和“继续佩戴：连续 N 天中的第 i 天。”；计划的每一天在使用时段变成一次模拟的佩戴会话（排班之外只模拟使用；排班中还模拟整个电量和提醒，和以前一样：到期的变成 plano.acao，解决它的记录模拟在当天开始时结束）。排班之外的范围（horizonte_do_modo）：模式最后一周的最后一天（只有一周时，在一周的最后一天也包括下一周的第一天）；轮换的一周从设置 semana_inicio 的那天开始（星期一为默认，或星期日：lib 中的 semana_comeca、semana_inicio 和 semana_fim）；循环从本周第一天起计算计划；下一周是本周最后一天之后开始的那一周；在生成的脚本中，整段一块的手表按一周的顺序留到该段的最后一天（bloco_seguidos：没有全部七天却跨越周交界的段，如每周从星期日开始时的星期六和星期日，从它在一个段外日子之后的第一天算起）；garantir_plano 补齐到此为止缺失的部分，resortear 重做到此为止（或到抽签原本已到的位置）；gerar_escala 删除从 ini 起的抽签结果并调用 plano_montar 到 escala_fim。proxima_semana 在任何非排班模式中仍可通过 API 使用；界面只在 semanas > 1 时显示它。',
        'O plano guarda o relógio de cada dia, o bloco, a origem (sorteio ou manual), a ação do dia e o motivo, numa frase ("Garantia de rodízio: ...", "Sorteio pela nota, entre 5 candidatos: nota 70,2, 16,4% de chance", "Escolhido à mão"). O cron monta o dia que falta (à 0h da segunda, a semana nova); trocar o relógio de um dia o marca como manual; sortear de novo refaz o período; usando hoje põe outro relógio no período atual e refaz o plano.' => '计划保存每一天的手表、区块、来源（抽签或手动）、当天的操作和事由，成一句（“轮换保障：……”、“按分数抽签，在 5 个候选人中：分数 70,2，16,4% 的机会”、“手动选定”）。cron 编制缺少的那一天（星期一 0 点，新的一周）；更换某一天的手表把它标为手动；重新抽签重做该时段；今天正在使用则在当前时段放入另一块手表并重做计划。',
        'Um período escolhido à mão (rodizio, acao=periodo): de, até (de hoje até 2 anos), os relógios na ordem e quantos dias seguidos cada (dias_cada): cada dia do período fica manual, com o relógio da vez (depois do último, volta ao primeiro; hoje, ele passa a ser o do pulso a partir de agora); na escala, ela é refeita a partir do começo do período. De amanhã em diante: periodo_sortear apaga o que o período tem (à mão, sorteado ou livre) e sorteia de novo; periodo_livre apaga e deixa os dias livres (a tabela plano_livre: sem relógio e sem sorteio; o sorteio e a escala pulam esses dias, e a escala não estica um bloco sobre eles). Escolher um relógio para um dia livre (trocar_dia, periodo, usando) o tira de plano_livre; trocar_dia 0 também (volta ao sorteio). Os dias manuais e os livres de amanhã em diante ficam quando se sorteia de novo ou se monta a próxima semana (hoje, o sortear de novo sorteia); trocar de modo refaz os sorteados. A API dá os dias livres em plano.livres e hoje.livres (as telas os põem entre os dias do plano, como "livre: escolha à mão").' => '手动选择的时段（rodizio，acao=periodo）：从、到（从今天直到 2 年）、手表按顺序以及每一块连续多少天（dias_cada）：该时段的每一天变为手动，用轮到的手表（最后一块之后回到第一块；今天，它从现在起成为手腕上的那只）；在排班表中，从该时段的起点重做。从明天起：periodo_sortear 去掉该时段已有的（手动、抽签或空闲）并重新抽签；periodo_livre 去掉并让这些天空闲（表 plano_livre：无手表且无抽签；抽签和排班表跳过这些天，排班表也不把一个区块拉过它们）。为空闲日选择一块手表（trocar_dia、periodo、usando）会把它从 plano_livre 去掉；trocar_dia 0 也同样（回到抽签）。重新抽签或编制下一周时，从明天起的手动日和空闲日保留（今天，重新抽签会抽签）；更换模式会重做已抽签的。API 在 plano.livres 和 hoje.livres 中给出空闲日（页面把它们放在计划日之间，如“空闲：请手动选择”）。',
        'O Rodízio manual (a última opção da lista Modo de rodízio da página Hoje; não é um modo: fora do período vale o modo ativo): de e até (de hoje até 2 anos); recurso=rodizio_manual dá os dias de 7 em 7 (pagina), cada um com o que o plano tem e a escolha de partida do seletor: o relógio escolhido à mão, livre (dia livre) ou auto (Decida por mim: o dia sorteado ou sem relógio). rodizio acao=manual grava o período inteiro: dias[data] = o id, auto, sortear:<forma> (inteligente, ponderado, aleatorio ou fifo: o dia sorteado ao gravar por essa forma, sem o de ontem e o de amanhã, escolha_do_dia) ou livre (hoje não); o dia que não vem fica com a escolha de partida. Os dias com relógio ficam manual ("Escolhido à mão no rodízio manual de DD/MM a DD/MM."); os livres vão para plano_livre; hoje com outro relógio passa a ser o do pulso a partir de agora (hoje em auto continua o que está); na escala, ela é refeita a partir do começo. O Decida por mim decide ao gravar e grava manual, com o motivo ("Decida por mim: a maior nota (62,9), entre 4 candidatos. O de ontem (X) ficou de fora." ou "Decida por mim, pela garantia de rodízio: parado há 33 dias, além do limite de 15 dias sem uso, ..."): de hoje até o fim do período, dia a dia, cada dia vira uma sessão simulada no pulso (os do plano antes do período, os escolhidos e os decididos), e no dia auto: os disponíveis, menos o de ontem e o escolhido para amanhã (se sobrar outro); a garantia de rodízio na frente (o mais tempo parado além de max_sem_uso); senão a maior nota no começo do uso do dia; empate: o menor id. A resposta diz quantos dias foram escolhidos, decididos, livres e quantos ficaram como já estavam.' => '手动轮换（今天页面轮换模式列表的最后一项；它不是一个模式：时段之外仍是启用的模式）：从和到（从今天直到 2 年）；recurso=rodizio_manual 每 7 天给出日子（pagina），每一天带计划中已有的以及选择器的起始选择：手动选定的手表、livre（空闲日）或 auto（帮我决定：抽签的那一天或没有手表）。rodizio acao=manual 写入整个时段：dias[data] = id、auto、sortear:<方式>（inteligente、ponderado、aleatorio 或 fifo：保存时按该方式为该日抽签，排除昨天和明天的，escolha_do_dia）或 livre（不含今天）；没有传来的那一天保留起始选择。有手表的日子变为手动（“在 DD/MM 至 DD/MM 的手动轮换中手动选定。”）；空闲的进入 plano_livre；今天若是另一块手表，则从现在起成为手腕上的那只（今天为 auto 则继续当前的）；在排班表中，从起点重做。帮我决定在写入时决定并记为手动，带事由（“帮我决定：最高分数（62,9），在 4 个候选人中。昨天的（X）被排除。”或“帮我决定，按轮换保障：已停 33 天，超过 15 天未使用的上限，……”）：从今天到时段结束，逐日，每一天变成手腕上的一个模拟时段（时段之前计划中的、已选择的和已决定的），在 auto 的那一天：可用的，减去昨天的以及为明天选定的（若还剩另一块）；轮换保障在前（超过 max_sem_uso、停得最久的）；否则取当天使用开始时的最高分数；平局：最小的 id。响应说明多少天被选择、被决定、空闲以及多少天保持原样。',
        'Apagar a programação (página Plano e quadro Modo de rodízio): apagar um período (periodo_sortear: os dias dele, de amanhã em diante, saem da tabela plano e o modo monta esses dias de novo; sem o de, de amanhã; sem o ate, até o último dia do plano; periodo_livre, só pela API: sai tudo e os dias ficam livres) e apagar tudo (rodizio apagar_tudo: sai toda a programação de amanhã em diante, à mão, sorteada e livre; com hoje=1, "Excluindo hoje", de hoje em diante; depois o modo ativo monta o plano de novo, gerar_escala na escala e garantir_plano até o fim da semana no sorteio; hoje, se mudar, o novo vai para o pulso a partir de agora, como no resortear_hoje).' => '清除安排（计划页面和轮换模式框）：清除一个时段（periodo_sortear：时段内从明天起的日子从 plano 表中删除，模式会重新安排这些日子；没有 de 时从明天开始；没有 ate 时到计划的最后一天；periodo_livre 仅通过 API：全部删除，这些日子变为空闲）以及全部清除（rodizio apagar_tudo：从明天起的全部安排都删除，包括手动的、抽签的和空闲的；带 hoje=1，“包括今天”，从今天起；之后启用的模式重新生成计划，排班表用 gerar_escala，抽签用 garantir_plano 到本周结束；今天如果改变，新的手表从现在起上腕，与 resortear_hoje 相同）。',
        'As listas longas de dias vêm da API uma página por vez (plano_pagina): os Próximos dias (hoje.proximos e recurso=proximos, de hoje até o fim do plano) e o dia a dia da página Plano (plano.dia_a_dia, com o filtro relogio), com os dias livres no meio (origem livre; sem eles no filtro de relógio), cada dia com o dia da semana (dia_semana 1 a 7, dia_semana_curto); o tamanho da página é o Mostrar até da Configuração (config proximos_por_pagina, padrão 7; plano_por_pagina, padrão 31; 1 a 366; por_pagina no pedido vale por cima), e o recurso=config devolve os dois já com o padrão (mostrar_ate).' => '长日子列表由 API 一次一页给出（plano_pagina）：接下来的日子（hoje.proximos 和 recurso=proximos，从今天到计划结束）以及计划页面的逐日（plano.dia_a_dia，带 relogio 筛选），空闲日在中间（来源 livre；手表筛选中没有它们），每一天带星期几（dia_semana 1 到 7，dia_semana_curto）；页大小是设置中的显示至（config proximos_por_pagina，默认 7；plano_por_pagina，默认 31；1 到 366；请求中的 por_pagina 优先），recurso=config 返回两者且已带默认（mostrar_ate）。',
        'A escala inteligente (um modo com escala_dias de 7 a 730; o roteiro dela: peso = 0, a maior nota, e dias = PADRAO(dias_seguidos; 1)) planeja tudo de uma vez simulando dia a dia: a nota de cada relógio com o estado simulado daquele dia; a escolha (o smartwatch fica os dias que a bateria aguenta, até 7); a sessão no pulso no horário de uso e o efeito dela em todos; os avisos (se o escolhido vai precisar de carga ou corda, anota a ação no dia e simula o lançamento que resolve). Toda manhã o cron refaz a escala a partir do estado real. Notas iguais na maior: o cadastrado primeiro, como nos outros modos.' => '智能排班（escala_dias 为 7 到 730 的模式；其脚本：peso = 0，最高评分，dias = PADRAO(dias_seguidos; 1)）通过逐天模拟一次规划全部：用那天的模拟状态计算每块手表的评分；选择（智能手表留到电池能撑的天数，最多 7 天）；使用时段的佩戴会话及其对所有手表的影响；提醒（如果被选中的将需要充电或上弦，就在那天记下操作并模拟解决它的记录）。每天早上 cron 根据真实状态重做排班。最高评分相同时：先登记的，和其他模式一样。',
        'O sorteio (sorteio(min, max): o modo aleatório, o sorteio pela nota ou pelo peso e a função SORTEIO() do roteiro) usa números aleatórios de fora, nesta ordem: RANDOM.ORG (www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new: ruído atmosférico); senão o ANU QRNG (qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16, o endereço antigo, sem chave: {"success": true, "data": [...]}; quântico); senão o gerador seguro do PHP (random_int). Um lote de 64 números de 16 bits por pedido, na memória do pedido; cada sorteio junta quantos pedaços de 16 bits precisar e descarta o valor que passa do último múltiplo inteiro da faixa (sem viés). Cada serviço tem 4 segundos; a resposta tem de vir completa e dentro da faixa, senão vale como falha. Se os dois falham, a config aleatorio_fora guarda quando, e por 10 minutos o sistema nem tenta (usa o do PHP); a config aleatorio_ultima guarda a fonte do último lote e quando (recurso=config: aleatorio.ultimo_lote, aleatorio.fora_desde; a Configuração mostra no quadro Sorteios). O motivo de cada dia sorteado termina com a fonte entre parênteses ("... todos com a mesma chance (RANDOM.ORG)."). Com RELOGIOS_SEMENTE (os testes), mt_rand com a semente, sem rede (a fonte: "semente de teste"). O que é segredo (o sal das senhas, os nomes dos arquivos dos documentos) fica no gerador do PHP: número que viaja pela internet não serve para segredo.' => '抽签（sorteio(min, max)：随机模式、按评分或按权重抽签以及脚本的 SORTEIO() 函数）使用外部随机数，顺序如下：RANDOM.ORG（www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new：大气噪声）；否则 ANU QRNG（qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16，旧地址，无需密钥：{"success": true, "data": [...]}；量子）；否则 PHP 的安全生成器（random_int）。每次请求一批 64 个 16 位数，保存在请求内存中；每次抽签拼接所需数量的 16 位片段，并丢弃超过范围最后一个整数倍的值（无偏差）。每个服务有 4 秒；回应必须完整且在范围内，否则算失败。两者都失败时，配置 aleatorio_fora 记录时间，10 分钟内系统不再尝试（使用 PHP 的）；配置 aleatorio_ultima 记录最后一批的来源和时间（recurso=config：aleatorio.ultimo_lote、aleatorio.fora_desde；设置在“抽签”面板中显示）。每个抽签日的理由以括号中的来源结尾（“... 所有手表机会相同（RANDOM.ORG）。”）。使用 RELOGIOS_SEMENTE（测试）时，用种子的 mt_rand，不联网（来源：“测试种子”）。机密内容（密码的盐、文档的文件名）留在 PHP 的生成器中：经互联网传输的数字不能用于机密。',
        'O pulso sozinho e as sessões esquecidas' => '独自上手腕以及被忘记的时段',
        'O horário de uso (uso_inicio e uso_fim) diz quando o relógio do dia está no pulso. Pôr sozinho (pulso_auto_inicio): no início do horário, o cron abre a sessão no pulso do relógio do dia (origem rodizio). Tirar sozinho (pulso_auto_fim): o "fecha às" do tipo No pulso segue o fim do horário. Desligados, só as marcações Pôs e Tirou contam; o que foi marcado sempre vale. Com o relógio do dia noutra sessão exclusiva aberta (no carregador, no sol, no winder), o pôr sozinho espera; se ele saiu de uma depois do início do horário, a sessão no pulso começa quando ele saiu.' => '使用时段（uso_inicio 和 uso_fim）说明当天的手表何时在手腕上。自动戴上（pulso_auto_inicio）：在时段开始时，cron 打开当天手表在手腕上的时段（来源 rodizio）。自动摘下（pulso_auto_fim）：类型“在手腕上”的“结束于”跟随使用时段的结束。关闭时，只有戴上和摘下的标记算数；已经标记的始终有效。当天的手表在另一个已打开的独占时段中（在充电器中、在晒太阳中、在上链盒中）时，自动戴上等待；若它在使用时段开始之后离开了其中一个，手腕上的时段从它离开时开始。',
        'Toda sessão esquecida aberta fecha sozinha no "fecha às" do tipo dela (a do sol, em sol_fim).' => '每一个被忘记的已打开时段在它类型的“结束于”自行结束（晒太阳的，在 sol_fim）。',
        'O cron' => 'cron',
        'A cada minuto: confere o token, o fuso e as migrações (pendente: registra e para); apaga execuções antigas (sem atividade, 7 dias; com atividade ou erro, 1 ano); monta o dia do plano que falta; fecha as sessões esquecidas; abre a sessão no pulso do dia; dispara os eventos personalizados no minuto marcado (depois de uma parada de até 7 dias, sai uma vez só, sem repetir); a manutenção dos documentos.' => '每分钟：核对令牌、时区和迁移（待处理：记录并停止）；删除旧的执行（无活动，7 天；有活动或错误，1 年）；编制计划中缺少的那一天；结束被忘记的时段；打开当天在手腕上的时段；在标记的分钟触发自定义事件（停机最多 7 天之后，只发出一次，不重复）；文档维护。',
        'Por coleção, na hora da manhã dela (horario_manha), uma vez por dia: refaz a escala a partir do estado real, manda a mensagem do dia (o relógio de hoje e os avisos) por cada destino ligado e sincroniza as agendas. Na hora da noite (horario_noite): a da véspera (o relógio de amanhã e o que preparar) e a sincronização; conta os documentos. O sistema inteiro, a cada minuto: a limpeza das contas (o aviso de vencimento da demonstração, 7 dias e 1 dia antes, por e-mail; a conta vencida sai com tudo; os convites, os pedidos e os links de senha vencidos saem; a conta comum sem nada sai), a manutenção dos documentos e, depois das 20h, uma vez por dia, a cópia de segurança.' => '每个收藏在其早晨时间（horario_manha）每天一次：根据实际状态重做排班表，通过每个启用的推送目标发送当天的消息（今天的手表和提醒），并同步日历。在晚上时间（horario_noite）：发送前一天的消息（明天的手表和需要准备的事项）并同步；统计文档。整个系统每分钟：账户清理（演示到期提醒，提前 7 天和 1 天通过电子邮件发送；到期的账户连同一切删除；过期的邀请、申请和密码链接删除；一无所有的普通账户删除）、文档维护，以及晚上 8 点之后每天一次的备份。',
        'Os avisos na hora, a cada minuto, em cada coleção: os vencidos agora que ainda não foram vão pelos destinos que os recebem.' => '准时提醒，每分钟，在每个收藏中：现在到期且尚未发送的，通过接收它们的推送目标发出。',
        'A cópia de segurança: um arquivo relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz na BACKUP_PASTA (fora da pasta publicada: dentro dela, recusada), JSON Lines comprimido, o mesmo nos quatro bancos: a primeira linha é o cabeçalho (relojoeiro_copia 1, criada, banco, versao: a última migração, documentos, tabelas); depois, para cada tabela, uma linha {tabela, colunas, binarias} e uma linha por registro com a lista dos valores (binários em base64). As tabelas vêm na ordem em que voltam (a citada antes da que cita; a que cita a si mesma, a árvore, volta em rodadas). Ficam as BACKUP_MANTER mais novas (padrão 7). O conteúdo dos documentos (documento_parte) só com BACKUP_DOCUMENTOS = true. Restaurar: só da mesma versão; antes, uma cópia do que está agora; depois, numa transação, apaga tudo (na ordem inversa) e grava a cópia; sem o conteúdo dos documentos, documento.no_banco volta a 0.' => '安全副本：BACKUP_PASTA 中一个文件 relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz（在已发布文件夹之外：在其中则拒绝），压缩的 JSON Lines，四个数据库相同：第一行是页眉（relojoeiro_copia 1、criada、banco、versao：最近一次迁移、documentos、tabelas）；然后，对每张表，一行 {tabela, colunas, binarias} 以及每个记录一行，带值的列表（二进制为 base64）。表按恢复时的顺序（被引用的在引用它的之前；引用自身的，即树，分轮恢复）。保留最新的 BACKUP_MANTER 份（默认 7）。文档内容（documento_parte）仅在 BACKUP_DOCUMENTOS = true 时。恢复：仅同一版本；之前，先做当前内容的一份副本；然后，在一个事务中，删除一切（逆序）并写入副本；没有文档内容时，documento.no_banco 回到 0。',
        'Com BACKUP_ATIVO = false no config.php, o cron não faz a cópia de segurança e a escrita fazer é recusada.' => '在 config.php 中设置 BACKUP_ATIVO = false 时，cron 不做备份，写入操作 fazer 被拒绝。',
        'Mudo: avisos do PHP e erros entram no registro, nunca na saída. Grava em cron_execucao o que fez o sistema (só quando fez algo, ou deu erro) e em cron_execucao_colecao o de cada coleção; o último erro em sistema.cron_erro (sai na primeira execução sem erro) e a última rodada com atividade em sistema.cron_registro. Erro fatal sem banco vai para um arquivo na pasta temporária.' => '静默：PHP 警告和错误写入日志，绝不输出。在 cron_execucao 中记录系统所做的事（仅在做了某事或出错时），在 cron_execucao_colecao 中记录每个收藏的；最后一个错误记录在 sistema.cron_erro（第一次无错误的执行时清除），最后一轮有活动的记录在 sistema.cron_registro。没有数据库时的致命错误写入临时文件夹中的一个文件。',
        'As mensagens, as agendas e os eventos personalizados' => '消息、日历和自定义事件',
        'Os destinos (listas.tipos_de_destino) de cada coleção: webhook (um pedido HTTP GET, POST ou PUT, com a mensagem na URL, como formulário ou como JSON, os campos e os cabeçalhos, estes cifrados; o Telegram é um webhook), e-mail (pelo SMTP do config.php, com STARTTLS ou TLS, e a cópia em Enviados por IMAP) e Web Push (os aparelhos de um usuário que vê a coleção; aes128gcm e VAPID ES256). Cada um tem a mensagem padrão (o modelo, com as âncoras) e o idioma, e escolhe o que recebe: o relógio do dia, a véspera, cada aviso e cada evento personalizado, cada um com o texto próprio opcional. Os itens do mesmo horário vão juntos; o webhook manda em partes de até 3000 caracteres.' => '每个收藏的推送目标（listas.tipos_de_destino）：webhook（HTTP GET、POST 或 PUT 请求，消息放在 URL 中、作为表单或作为 JSON，带字段和请求头，后者加密；Telegram 就是一个 webhook）、电子邮件（通过 config.php 中的 SMTP，使用 STARTTLS 或 TLS，并通过 IMAP 在“已发送”中保存副本）和 Web Push（能看到该收藏的某个用户的设备；aes128gcm 和 VAPID ES256）。每个都有默认消息（模板，带占位符）和语言，并选择接收的内容：当天的手表、前一天、每个提醒和每个自定义事件，每项可带可选的专用文本。同一时间的项目一起发送；webhook 按每段最多 3000 个字符分段发送。',
        'As agendas (listas.tipos_de_agenda): Google Agenda (uma conta de serviço; token por JWT RS256), CalDAV (Nextcloud, iCloud com senha de app, Fastmail: um PUT de um .ics por evento), Outlook (o Microsoft Graph, com a conta conectada pelo OAuth do aplicativo registrado) e o link ICS (um calendário que o app de agenda assina; sem login, pela chave secreta do link). O sistema calcula o que tem de estar em cada uma (de hoje até janela_dias: os avisos marcados para ela, no horário da manhã do dia previsto; o relógio do dia e a véspera, pelo plano; os eventos personalizados) e deixa a agenda igual: cria o que falta, atualiza o que mudou (a assinatura do título e da descrição) e apaga o que deixou de valer; o que já passou fica, como histórico.' => '日历（listas.tipos_de_agenda）：Google 日历（服务账户；令牌通过 JWT RS256 获取）、CalDAV（Nextcloud、使用应用专用密码的 iCloud、Fastmail：每个事件 PUT 一个 .ics）、Outlook（Microsoft Graph，账户通过已注册应用的 OAuth 连接）和 ICS 链接（日历应用订阅的日历；无需登录，凭链接的密钥）。系统计算每个日历中应有的内容（从今天到 janela_dias：为它勾选的提醒，在预计日期的早晨时间；当天的手表和前一天，根据计划；自定义事件）并使日历与之一致：创建缺少的，更新有变化的（标题和描述的签名），删除不再适用的；已经过去的保留，作为历史。',
        'Os segredos (senhas, chaves, tokens, cabeçalhos) ficam cifrados no banco (AES-256-GCM, com a SEGREDO_CHAVE do config.php; sem ela, o API_TOKEN) e nunca voltam para a tela: a resposta diz só se estão preenchidos. Fora das coleções do master, os endereços que o usuário escreve (webhook, CalDAV, Web Push) têm de ser da internet: nada da rede do servidor.' => '机密（密码、密钥、令牌、请求头）在数据库中加密保存（AES-256-GCM，使用 config.php 中的 SEGREDO_CHAVE；没有则用 API_TOKEN），绝不返回到界面：响应只说明是否已填写。在 master 的收藏之外，用户填写的地址（webhook、CalDAV、Web Push）必须位于互联网上：不能是服务器网络中的任何地址。',
        'Evento personalizado: nome, ativo, repetição (listas.repeticoes), data (uma vez; a cada N dias: a partir dela), hora, dias da semana, dia do mês (1 a 31; mês sem o dia, o último), intervalo (1 a 3650), relógio opcional (com ele, as âncoras do relógio funcionam). Só o que a repetição usa fica gravado. O evento novo vai para todos os destinos da coleção; cada disparo fica gravado, para não disparar duas vezes.' => '自定义事件：名称、启用、重复方式（listas.repeticoes）、日期（一次；每 N 天：从该日起）、时间、星期几、每月第几天（1 到 31；没有该日的月份取最后一天）、间隔（1 到 3650）、可选的手表（有手表时，手表的占位符可用）。只保存重复方式用到的内容。新事件发往收藏的所有推送目标；每次触发都会记录，避免触发两次。',
        'As contas, as coleções e o acesso' => '账户、收藏与访问',
        'Contas: o login (sem dois-pontos), o e-mail, a senha (o hash), o papel (master: cuida do sistema inteiro, vê todas as coleções e o painel das contas; comum), o idioma, e o vencimento da conta de demonstração. O primeiro usuário é o master. A conta criada pelo cadastro aberto (cadastro.php, CADASTRO_ABERTO) é de demonstração por DEMO_DIAS dias, com aviso por e-mail 7 dias e 1 dia antes; vencida, o cron a apaga com tudo. O master oficializa, prorroga, volta a demonstração, bloqueia, transfere uma coleção, dá acesso, exclui e vê o sistema como outro usuário (Vendo como).' => '账户：登录名（不含冒号）、电子邮件、密码（哈希）、角色（master：管理整个系统，看到所有收藏和账户面板；comum）、语言，以及演示账户的到期时间。第一个用户是 master。通过公开注册（cadastro.php，CADASTRO_ABERTO）创建的账户为演示账户，有效 DEMO_DIAS 天，到期前 7 天和 1 天通过电子邮件提醒；到期后由 cron 连同一切删除。master 可以转为正式、延长、改回演示、封禁、转移收藏、授予访问权限、删除，以及以其他用户身份查看系统（以他人身份查看）。',
        'Coleções e árvores: cada coleção tem um dono e usa uma árvore de grupos do mesmo dono; uma árvore pode servir a várias coleções, e o cadastro dela (campos, tipos, fórmulas, avisos, categorias, critérios dos grupos) vale em todas. A coleção nova nasce com o conjunto inicial (numa árvore nova), vazia (só a raiz) ou numa árvore que já existe. Transferir uma coleção leva a árvore junto quando só ela a usa; senão, o novo dono ganha uma cópia da árvore e a coleção passa para a cópia (os relógios, os valores, os lançamentos, os documentos e os blocos dos modos acompanham os ids novos).' => '收藏与树：每个收藏有一个所有者，并使用同一所有者的一棵分组树；一棵树可供多个收藏使用，其定义（字段、类型、公式、提醒、分类、分组的标准）对所有这些收藏生效。新收藏可以带初始集合（在一棵新树中）、为空（只有根）或使用已有的树。转移收藏时，如果只有它使用该树，树会一起转移；否则新所有者获得树的副本，收藏改用该副本（手表、值、记录、文档和模式的区块都跟随新的 id）。',
        'O acesso: o dono vê as suas; um membro vê uma coleção (colecao_usuario); quem tem tudo de um dono vê todas as dele, também as que vierem (acesso_dono). Entra-se por convite (o dono, ou o master, convida por e-mail com um link de token; o convite de um membro espera o dono aprovar; quem não tem conta cria pelo link) ou por pedido (o pedido espera o dono, ou o master, aprovar; aprovado ou recusado, a pessoa recebe um e-mail). Convites e pedidos vencem em CONVITE_DIAS dias. A conta comum que fica sem nada (sem coleção, sem acesso, sem pedido nem convite) sai.' => '访问：所有者看到自己的收藏；成员看到某一个收藏（colecao_usuario）；拥有某个所有者全部内容的人看到他所有的收藏，包括以后的（acesso_dono）。可以通过邀请进入（所有者或 master 通过电子邮件发送带令牌链接的邀请；成员的邀请需等待所有者批准；没有账户的人通过链接创建账户），或通过申请进入（申请等待所有者或 master 批准；批准或拒绝后，申请人会收到一封电子邮件）。邀请和申请在 CONVITE_DIAS 天后过期。一无所有（没有收藏、没有访问权限、没有申请也没有邀请）的普通账户会被删除。',
        'O escopo: a coleção do pedido (colecao=, o cookie do seletor do menu, ou a primeira) decide tudo o que se lê e se grava: a camada do banco reescreve cada SELECT, UPDATE e DELETE para enxergar só as linhas da coleção e da árvore dela (a raiz da árvore não aparece, e as colunas que a citam leem vazio, como no tempo de uma pessoa só). A configuração é por coleção; os valores do sistema inteiro (o cron, a cópia de segurança, o aleatório, as migrações, o endereço do sistema) ficam na tabela sistema.' => '作用范围：请求所在的收藏（colecao=、菜单选择器的 cookie，或第一个）决定读取和保存的一切：数据库层改写每条 SELECT、UPDATE 和 DELETE，使其只能看到该收藏及其树的行（树的根不显示，引用它的列读出为空，就像单人使用时一样）。设置按收藏区分；整个系统的值（cron、备份、随机数、迁移、系统地址）保存在 sistema 表中。',
        'Os tokens pessoais (Minha conta) valem como o login do dono; o token do servidor (API_TOKEN) vale como o master mais antigo. O Esqueci a senha manda um link de token (2 horas) por e-mail.' => '个人令牌（我的账户）等同于其所有者的登录；服务器令牌（API_TOKEN）等同于最早的 master。“忘记密码”通过电子邮件发送一个令牌链接（2 小时）。',
        'Os documentos de cada relógio' => '每块手表的文档',
        'Qualquer arquivo, cada um numa categoria (as que aceitam só algumas famílias recusam as outras), com título, data e descrição. O tipo vem do conteúdo do arquivo; quando o conteúdo diz pouco (texto, binário genérico, zip), da extensão. A família decide como abre: imagem (galeria com visor em tela cheia e apresentação, com a miniatura feita no navegador), vídeo (player, em sequência na ordem escolhida), PDF (visualizador), XML (o resumo da NF-e: emitente, número, série, data, valor, chave e produtos; lido sem baixar nada de fora), o resto para baixar. Inline só o que o navegador mostra sem rodar nada (HTML, SVG e XML sempre como download); atende pedido de pedaço (Range).' => '任意文件，每一个属于一个类别（只接受某些系列的会拒绝其他的），带标题、日期和描述。类型来自文件内容；当内容说明很少时（文本、通用二进制、zip），来自扩展名。系列决定如何打开：图像（带全屏查看器和放映的图库，缩略图在浏览器中生成）、视频（播放器，按所选顺序连续播放）、PDF（查看器）、XML（NF-e 摘要：开票方、号码、系列、日期、金额、密钥和产品；读取时不从外部下载任何东西）、其余供下载。Inline 只用于浏览器显示时不运行任何东西的（HTML、SVG 和 XML 始终作为下载）；响应分段请求（Range）。',
        'Os arquivos ficam numa pasta fora da publicada (DOCUMENTOS_PASTA), em r<id do relógio>/ com nome aleatório. Limite por arquivo: DOCUMENTOS_LIMITE (padrão 100 MB) e os do PHP e do servidor web.' => '文件放在已发布文件夹之外的一个文件夹中（DOCUMENTOS_PASTA），在 r<手表 id>/ 中，名称为随机。每个文件的限制：DOCUMENTOS_LIMITE（默认 100 MB）以及 PHP 和 Web 服务器的限制。',
        'A cópia no banco (documento_parte, pedaços de 4 MB, com o SHA-256): três níveis, e o de cima vale sobre os de baixo. A coleção (a chave documentos_copia da Configuração: todos; nenhum; vazia, decidem os de baixo; o DOCUMENTOS_COPIA_BANCO do config.php, que valia para o servidor inteiro, não vale mais, e a Configuração avisa se ele ainda está definido), o relógio (copia_banco: todos os dele) e o arquivo (copia_banco: só ele). A tela só mostra a escolha de quem decide. A cópia entra na hora no envio e em editar; pelo relógio, o cron copia aos poucos; quando ninguém mais pede, sai, mas só se o arquivo da pasta confere com ela (o documento nunca fica sem as duas).' => '数据库副本（documento_parte，4 MB 分块，带 SHA-256）：三个层级，上层优先于下层。收藏（设置的 documentos_copia 键：todos；nenhum；空时由下层决定；config.php 中对整个服务器生效的 DOCUMENTOS_COPIA_BANCO 已不再生效，若仍定义则设置页提示）、手表（copia_banco：它的所有文件）和文件（copia_banco：仅它自己）。界面只显示做决定者的选择。上传和编辑时副本立即存入；按手表时由 cron 逐步复制；没有人再要求时移除，但只在文件夹中的文件与之一致时（文档永远不会两者都没有）。',
        'A manutenção (o cron, a cada minuto, até 256 MB por rodada): o arquivo que sumiu da pasta, ou ficou cortado (o tamanho não confere com o do envio), volta da cópia (conferindo o SHA-256); a cópia pedida que falta é feita; a que ninguém pede sai; a pasta de um relógio que não existe mais sai inteira; o arquivo que não é de nenhum documento sai (só depois de 10 minutos: um envio pode estar no meio). Os perdidos (sem arquivo e sem cópia) são contados à noite.' => '维护（cron，每分钟，每一轮最多 256 MB）：从文件夹消失或被截断（大小与上传时不符）的文件从副本恢复（核对 SHA-256）；被要求但缺少的副本被做出；不再有人要求的去掉；不再存在的手表的文件夹整份去掉；不属于任何文档的文件去掉（仅在 10 分钟之后：一次上传可能正在进行）。丢失的（没有文件也没有副本）在夜晚清点。',
        'O aplicativo no celular (PWA)' => '手机上的应用（PWA）',
        'O sistema se instala como aplicativo no celular e no tablet sem loja nenhuma: toda página aponta o manifesto (<link rel="manifest" href="api.php?recurso=manifest" crossorigin="use-credentials">, com o ícone e as marcas que o iPhone lê fora dele: apple-touch-icon, apple-mobile-web-app-capable, apple-mobile-web-app-title) e o api.js registra o service worker (navigator.serviceWorker.register("api.php?recurso=sw")) e guarda o beforeinstallprompt para o botão "Instalar o aplicativo" de Minha conta. O manifesto (app_manifesto, no lib.php): id e scope ./, start_url index.php, display standalone, as cores do tema (#e4e8ec e #1c2530), os ícones 192 e 512 (o 512 também maskable). Os dois recursos respondem sem login.' => '系统无需任何商店即可作为应用安装到手机和平板：每个页面都指向清单（<link rel="manifest" href="api.php?recurso=manifest" crossorigin="use-credentials">，附图标以及 iPhone 在清单之外读取的标签：apple-touch-icon、apple-mobile-web-app-capable、apple-mobile-web-app-title），api.js 注册 service worker（navigator.serviceWorker.register("api.php?recurso=sw")）并保存 beforeinstallprompt 供“我的账户”的“安装应用”按钮使用。清单（lib.php 中的 app_manifesto）：id 和 scope 为 ./，start_url 为 index.php，display 为 standalone，主题颜色（#e4e8ec 和 #1c2530），192 和 512 图标（512 也用作 maskable）。这两个资源无需登录即可响应。',
        'O service worker (sw.js, entregue pela API com VERSAO e ARQUIVOS na frente, app_service_worker): na instalação guarda o estilo, os scripts, os ícones e a página sem conexão (com o ?v= das páginas) num cache com o nome da versão (o sha1 dos nomes, datas e tamanhos desses arquivos: qualquer mudança neles é um service worker novo, e o cache antigo sai ao ativar); o estilo, os scripts, as imagens e os textos do idioma (api.php?recurso=textos&formato=js) saem do cache quando já estão nele, senão da rede (e entram); as páginas vêm sempre da rede, e sem rede sai a offline.html; a API nunca fica em cache. O push e o notificationclick do Web Push ficam nele (o push.js de antes).' => 'service worker（sw.js，由 API 提供，前面带 VERSAO 和 ARQUIVOS，app_service_worker）：安装时将样式、脚本、图标和无连接页面（带页面的 ?v=）存入以版本命名的缓存（版本为这些文件的名称、日期和大小的 sha1：任何变动都是新的 service worker，旧缓存在激活时删除）；样式、脚本、图片和语言文本（api.php?recurso=textos&formato=js）已在缓存时从缓存读取，否则来自网络（并存入）；页面始终来自网络，无网络时提供 offline.html；API 永不缓存。Web Push 的 push 和 notificationclick 在其中（原来的 push.js）。',
        'Entrar sem a senha: "Lembrar este aparelho" (recurso=conta, acao=aparelho_lembrar) cria uma chave (24 bytes aleatórios em base64url), grava o hash dela (sha256 com o prefixo do sistema, como os tokens) na tabela usuario_aparelho (usuario_id, nome, chave_hash, criado, ultimo_uso) e a chave num cookie aparelho (HttpOnly, SameSite=Lax, Secure no https, um ano, na pasta do sistema). O pedido que chega sem o login do site e com o cookie entra como o dono da chave (usuario_por_aparelho, em usuario_autenticado; a conta bloqueada ou vencida não entra; ultimo_uso no máximo uma vez por minuto). "Esquecer" (aparelho_esquecer, id ou o deste pedido) apaga a linha e o cookie; trocar a senha apaga todos. O manifesto pedido com o cookie leva a chave no start_url (index.php?aparelho=...): o aplicativo instalado abre por ela, pagina_login grava o cookie no navegador do aplicativo (no iPhone ele não compartilha os cookies do Safari) e abre a página de novo sem a chave na barra.' => '无需密码进入：“记住此设备”（recurso=conta，acao=aparelho_lembrar）生成一个密钥（24 个随机字节，base64url），将其哈希（带系统前缀的 sha256，与令牌相同）存入 usuario_aparelho 表（usuario_id、nome、chave_hash、criado、ultimo_uso），并将密钥存入 aparelho cookie（HttpOnly、SameSite=Lax、https 下 Secure、一年、系统目录下）。不带站点登录但带 cookie 的请求以密钥所有者身份进入（usuario_autenticado 中的 usuario_por_aparelho；被锁定或过期的账户不能进入；ultimo_uso 每分钟最多更新一次）。“忘记”（aparelho_esquecer，id 或本次请求的设备）删除该行和 cookie；更改密码删除全部。带 cookie 请求的清单在 start_url 中携带密钥（index.php?aparelho=...）：已安装的应用凭它打开，pagina_login 将 cookie 存入应用的浏览器（在 iPhone 上它不共享 Safari 的 cookie），然后以不带密钥的地址重新打开页面。',
        'O fuso horário (migrações v28 e v29: usuario.fuso, as chaves fuso e hora_relogio da config, destino.fuso e agenda.fuso). Dois relógios. 1) O relógio da coleção (lib.php: fuso_da_colecao, o config fuso, senão o do sistema; hoje_da_colecao() é a meia-noite de hoje nele, hora_da_colecao() a hora de parede, dia_da_colecao(instante) o dia em que um instante cai, instante(data, hora) o instante de uma hora de parede da coleção e meia_noite_seguinte(instante)) manda no rodízio: todo "hoje" da API e do cron (o plano, o relógio do dia, as rodadas, a escala, as estatísticas por dia, dia_comecou, o pulso automático) sai de hoje_da_colecao(), e toda hora de parede (uso_inicio, uso_fim, fecha_as, horario_manha, horario_noite) vira instante por instante(); o cron calcula o hoje e o agora de cada coleção dentro do laço dela, depois do fuso_definir. 2) O fuso do pedido (fuso_definir, api.php, depois do idioma: usuario.fuso vazio é o da coleção, "navegador" é o cookie fuso_navegador que o api.js grava em toda página com Intl.DateTimeFormat().resolvedOptions().timeZone, ou fuso_pedido= no pedido (sem os dois, o da coleção), senão o nome fixo) manda nos instantes que a pessoa vê e digita: o PHP roda nele (date_default_timezone_set) e a camada do banco converte (banco.php, banco_fuso e banco_fuso_converter, em banco_executar_cru): todo parâmetro no formato AAAA-MM-DD HH:MM[:SS] vai do fuso do pedido para o do sistema (o das datas gravadas: FUSO_SISTEMA, o FUSO do config.php ou o do PHP), e todo valor lido nesse formato volta; a data sozinha não muda, nem os anos fora de 1900 a 9998; o NOW() do Firebird sai no fuso do sistema; no fuso do sistema nada é convertido. 3) As mensagens e as agendas: alvo_fuso (o fuso do destino ou da agenda, senão o da coleção) e no_idioma_e_fuso_de (alertas.php) rodam a montagem do texto, a sincronização e o ICS no idioma e no fuso do alvo, e voltam ao de antes; os instantes dos eventos (data + hora de parede) são montados no fuso da coleção (fuso_colecao_tz). fuso_valido aceita qualquer nome de DateTimeZone::listIdentifiers() (sem diferenciar maiúsculas) e fusos_lista dá todos com o deslocamento de agora (as listas das telas).' => '时区（迁移 v28 和 v29：usuario.fuso、config 的 fuso 和 hora_relogio 键、destino.fuso 和 agenda.fuso）。两个时钟。1）收藏的时钟（lib.php：fuso_da_colecao，即 config fuso，否则系统的；hoje_da_colecao() 是其中今天的午夜，hora_da_colecao() 是墙上时间，dia_da_colecao(时刻) 是某时刻所在的日子，instante(日期, 时间) 是收藏某个墙上时间的时刻，以及 meia_noite_seguinte(时刻)）主宰轮换：API 和 cron 的每个“今天”（计划、当日手表、各轮次、排程、按天统计、dia_comecou、自动上手腕）都来自 hoje_da_colecao()，每个墙上时间（uso_inicio、uso_fim、fecha_as、horario_manha、horario_noite）都通过 instante() 变成时刻；cron 在每个收藏的循环内、fuso_definir 之后计算其今天和现在。2）请求的时区（fuso_definir，api.php，在语言之后：usuario.fuso 为空是收藏的，“navegador”是 api.js 在每个页面用 Intl.DateTimeFormat().resolvedOptions().timeZone 写入的 fuso_navegador cookie，或请求中的 fuso_pedido=（两者都没有时为收藏的），否则是固定名称）主宰此人查看和输入的时刻：PHP 在其中运行（date_default_timezone_set），数据库层进行转换（banco.php，banco_fuso 和 banco_fuso_converter，在 banco_executar_cru 中）：所有 YYYY-MM-DD HH:MM[:SS] 格式的参数从请求时区转为系统时区（即保存日期所用的：FUSO_SISTEMA，config.php 的 FUSO 或 PHP 的），所有读到的该格式的值转回；单独的日期不变，1900 到 9998 之外的年份也不变；Firebird 的 NOW() 按系统时区输出；在系统时区下什么都不转换。3）消息和日历：alvo_fuso（推送目标或日历的时区，否则收藏的）和 no_idioma_e_fuso_de（alertas.php）在目标的语言和时区下运行文本组装、同步和 ICS，然后恢复之前的；事件的时刻（日期 + 墙上时间）按收藏的时区构建（fuso_colecao_tz）。fuso_valido 接受 DateTimeZone::listIdentifiers() 中的任何名称（不区分大小写），fusos_lista 给出全部并带当前偏移（界面的列表）。',
        'Os modos com tipo, semanas e roteiro (migração v30: modo.tipo, modo.semanas, modo.roteiro, ck_modo_semanas; o passo em PHP migracao_v30_dados dá o tipo a cada modo que existe pela forma dos blocos). O modelo.json traz o tipo e as semanas dos cinco modos prontos. Nada muda no plano gravado: o roteiro dos modos prontos é gerado dos blocos, e o montador único (plano_montar) sorteia como antes, com as mesmas frases de motivo.' => '带类型、周数和脚本的模式（迁移 v30：modo.tipo、modo.semanas、modo.roteiro、ck_modo_semanas；PHP 步骤 migracao_v30_dados 按区块形状给每个已有模式赋类型）。modelo.json 提供五个预设模式的类型和周数。已保存的计划不变：预设模式的脚本由区块生成，统一生成器（plano_montar）照旧抽签，理由句子相同。',
        'Os totais' => '合计',
        'Os totais (migração v31: a tabela total, presa à raiz da árvore como o cadastro; o passo em PHP migracao_v31_dados grava os prontos do modelo.json, os totais, em cada árvore sem nenhum, e arvore_criar grava numa árvore nova, com o nome e os textos entre aspas da expressão no idioma: totais_do_modelo). Cada total: coluna (a chave de uma coluna da tabela dos relógios: codigo, nome, tipo, estado, carga, ultimo, manut, em, fazer, encostado, compra, valor; null: nenhuma), nome, expressao, rodape e pagina (1 ou 0; o rodapé só com coluna: ck_total_lugares; pelo menos um dos dois, conferido na gravação), largura (estreito, largo), formato (numero, inteiro, decimal, moeda, porcentagem, data, dias) e ordem (de 10 em 10; subir e descer trocam com o vizinho).' => '合计（迁移 v31：total 表，像定义一样挂在树根上；PHP 步骤 migracao_v31_dados 把 modelo.json 中预设的 totais 保存到每棵还没有的树中，arvore_criar 在新树中保存，名称和表达式中引号内的文本使用该语言：totais_do_modelo）。每个合计：coluna（手表表格某列的键：codigo、nome、tipo、estado、carga、ultimo、manut、em、fazer、encostado、compra、valor；null：无）、nome、expressao、rodape 和 pagina（1 或 0；底部只在有列时：ck_total_lugares；两者至少一个，保存时检查）、largura（estreito、largo）、formato（numero、inteiro、decimal、moeda、porcentagem、data、dias）和 ordem（每次 10；subir 和 descer 与相邻的交换）。',
        'O motor de totais (lib.php): a expressão é lida pelo leitor das fórmulas com as funções de total aceitas (total_ler: $FUNCOES_TOTAIS, só nos totais) e conferida por total_validar: as variáveis só dentro de uma função de total; uma função de total dentro da outra só como a conta do AGRUPADO (o 2º argumento) e os limites das FAIXAS (no nível do conjunto); AGRUPADO, FAIXAS, QUEM_MAIOR e QUEM_MENOR só como a expressão inteira; fora das funções de total, nada que precise de um relógio (as funções do histórico, NO_GRUPO, MEDIDO, DIA_SEMANA...). O conjunto (totais_relogios) é o dos relógios da tabela da página Hoje (da_colecao), ou só os ids pedidos, cada um com o contexto de uma fórmula e as variáveis da tabela (tabela_variaveis, da mesma linha da tabela: tabela_linha): codigo, nome, tipo, estado, disponivel, em_uso, carga, ultimo_uso (agora, se no pulso; vazio: nunca), manutencao_data, manutencao_nome, encostado_data, avisos (quantos avisos ele tem), posse; as datas em dias, como nas fórmulas.' => '合计引擎（lib.php）：表达式由公式读取器读取，接受合计函数（total_ler：$FUNCOES_TOTAIS，仅在合计中），并由 total_validar 检查：变量只能在合计函数内；合计函数套在另一个合计函数内只能作为 AGRUPADO 的计算（第 2 个参数）和 FAIXAS 的限值（在集合层面）；AGRUPADO、FAIXAS、QUEM_MAIOR 和 QUEM_MENOR 只能作为整个表达式；在合计函数之外，不能用任何需要手表的东西（历史函数、NO_GRUPO、MEDIDO、DIA_SEMANA……）。集合（totais_relogios）是今天页面表格中的手表（da_colecao），或只是请求的 id，每块都带有公式的上下文和表格变量（tabela_variaveis，来自表格的同一行：tabela_linha）：codigo、nome、tipo、estado、disponivel、em_uso、carga、ultimo_uso（正戴着则为现在；空：从未）、manutencao_data、manutencao_nome、encostado_data、avisos（它有多少条提醒）、posse；日期以天表示，同公式。',
        'As funções (total_valor, total_resultado): CONTA() quantos; CONTA(x) quantos têm x; CONTA_SE(c) quantos têm c diferente de 0; DISTINTOS(x) quantos valores diferentes; SOMA, MEDIA, MEDIANA, MENOR, MAIOR (dos números; vazio sem nenhum); QUEM_MAIOR(x) e QUEM_MENOR(x): o relógio (o primeiro na ordem do nome, no empate) e o valor. AGRUPADO(chave; conta; limite): uma linha por valor da chave (a conta, padrão CONTA(), feita só com os relógios da linha), na ordem dos números e dos meses (AAAA-MM) quando todas as chaves são assim, senão do maior para o menor (empate: pelo rótulo); limite deixa as que mais têm e junta o resto em "outros" (a conta com todos eles); os sem chave em "sem valor", no fim; o total é a conta com todos. FAIXAS(x; l1; ...; ln) (os limites crescentes): "até l1", "l1+1 a l2" (limites inteiros; senão "mais de l1 até l2") ..., "mais de ln" só quando tem algum, "sem valor" só quando tem algum; a unidade de x (a da variável da tabela, do campo ou da fórmula; DIAS_DESDE e DIAS_ATE: dias) nos rótulos; o total é quantos são. Fora delas, as funções comuns calculam por cima dos resultados (SE, MIN, ARREDONDA, as contas). MES(data), ANO(data) e MES_ANO(data) (texto AAAA-MM; o rótulo sai "ago/2026") valem também nas fórmulas.' => '函数（total_valor、total_resultado）：CONTA() 多少块；CONTA(x) 多少块有 x；CONTA_SE(c) 多少块的 c 不为 0；DISTINTOS(x) 有多少个不同的值；SOMA、MEDIA、MEDIANA、MENOR、MAIOR（针对数字；没有则为空）；QUEM_MAIOR(x) 和 QUEM_MENOR(x)：手表（平局时按名称顺序取第一个）和值。AGRUPADO(键; 计算; 限制)：键的每个值一行（计算默认 CONTA()，只用该行的手表），当所有键都是数字或月份（YYYY-MM）时按其顺序，否则从大到小（平局：按标签）；限制保留最多的几行，其余合并为“其他”（用它们全部计算）；没有键的放在最后的“无值”；合计为用全部计算。FAIXAS(x; l1; ...; ln)（递增的限值）：“l1 以内”、“l1+1 至 l2”（整数限值；否则“大于 l1 至 l2”）……“超过 ln”只在有时出现，“无值”只在有时出现；标签中带 x 的单位（表格变量、字段或公式的单位；DIAS_DESDE 和 DIAS_ATE：天）；合计为数量。在它们之外，普通函数在结果之上计算（SE、MIN、ARREDONDA、运算）。MES(日期)、ANO(日期) 和 MES_ANO(日期)（文本 YYYY-MM；标签显示为“8月/2026”）也可用于公式。',
        'O texto (total_texto, total_calcular): numero (inteiro quando é, senão até 2 casas), inteiro, decimal (2 casas), moeda (R$), porcentagem (arredondada, com %), data (dd/mm/aaaa no formato do idioma), dias ("1 dia", "N dias"); vazio: "—". Nas FAIXAS e no AGRUPADO sem conta, as linhas e o total são contagens: inteiro. Uma expressão com erro (total_validar) ou limites das FAIXAS fora de ordem: tipo erro, com a mensagem.' => '文本（total_texto、total_calcular）：numero（是整数时为整数，否则最多 2 位小数）、inteiro、decimal（2 位小数）、moeda（R$）、porcentagem（四舍五入，带 %）、data（按语言的日期格式）、dias（“1 天”、“N 天”）；空：“—”。在 FAIXAS 和没有计算的 AGRUPADO 中，各行和合计都是计数：inteiro。表达式有误（total_validar）或 FAIXAS 的限值顺序不对：类型 erro，附消息。',
        'As estatísticas' => '统计',
        'recurso=estatisticas conta o tempo no pulso de cada relógio em cada dia do período (as sessões do tipo pulso partidas na meia-noite, a aberta até agora; as marcações antigas no pulso contam o dia, sem horas). Dela saem: os dias de uso e as horas de cada relógio, a parte de cada um, a barra (comparada com o mais usado), a tendência (a segunda metade do período contra a primeira: até 20% ou menos de 1 h de diferença é estável; menos de 1 h no total ou período de menos de 14 dias, poucos dados), o uso por dia da semana e por mês (com a média por dia e a barra comparada com o maior) e o resumo. O custo por uso e os dias de uso desde sempre são as fórmulas custo_por_uso e dias_de_uso. A coleção (na coleção e emprestados) é dividida por grupo, marca, ano da compra, situação e cada campo de lista (menos os só dos desejados). Período padrão: os últimos 90 dias; até hoje; no máximo 3661 dias; de=tudo: desde o primeiro uso.' => 'recurso=estatisticas 计算时段内每一天每块手表在手腕上的时间（类型 pulso 的时段在午夜切开，已打开的直到现在；旧的手腕标记只计天数，不计小时）。由此得出：每块手表的使用天数和小时、每一块的份额、条形（与用得最多的比较）、趋势（时段的后半相对前半：相差在 20% 以内或少于 1 h 为稳定；合计少于 1 h 或时段少于 14 天，数据不足）、按星期几和按月份的使用（带每天平均以及与最大者比较的条形）和摘要。每次使用成本和有史以来的使用天数是公式 custo_por_uso 和 dias_de_uso。收藏（在收藏中和已借出）按分组、品牌、购买年份、情况和每个列表字段划分（仅心愿的除外）。默认时段：最近 90 天；直到今天；最多 3661 天；de=tudo：从第一次使用起。',
        'A hora certa' => '准确时间',
        'recurso=hora_certa não usa o banco: a hora do servidor (microtime) no fuso do sistema e em UTC; a letra militar do fuso pelo deslocamento em horas cheias (A a M sem J a leste, N a Y a oeste, Z no UTC; fora da hora cheia, nenhuma); o grupo data-hora DDHHMM + letra + mês em inglês + ano com dois dígitos; o calendário pelo formato de datas (z, L, W, o); o dia juliano = segundos / 86400 + 2440587,5; a lua pela idade no ciclo sinódico médio de 29,530588853 dias a partir da lua nova de 06/01/2000 18:14 UTC (dia juliano 2451550,1), a parte iluminada (1 - cos(2π idade/ciclo)) / 2 e a fase pelos oitavos do ciclo (os limites 1,85; 5,54; 9,23; 12,92; 16,61; 20,30; 23,99; 27,68 dias).' => 'recurso=hora_certa 不使用数据库：服务器时间（microtime）在系统时区和 UTC；时区的军用字母按整小时偏移（东向 A 到 M，不含 J，西向 N 到 Y，UTC 为 Z；不是整小时则没有）；日期时间组（DTG）DDHHMM + 字母 + 英语月份 + 两位年份；日历按日期格式（z、L、W、o）；儒略日 = 秒 / 86400 + 2440587,5；月相按从 2000-01-06 18:14 UTC 新月（儒略日 2451550,1）起、平均朔望周期 29,530588853 天的月龄，被照亮部分 (1 - cos(2π 月龄/周期)) / 2，以及按周期八分之一的相位（界限 1,85；5,54；9,23；12,92；16,61；20,30；23,99；27,68 天）。',
        'As telas' => '各页面',
        'O reloginho (relojinho.js, em toda página, depois dos scripts dela): no canto esquerdo da barra do menu, um relógio de 30 px desenhado em canvas (nítido nas telas de alta densidade) com a hora certa do aparelho, os segundos andando (redesenhado a cada segundo); um link para a Hora certa, com o título "<modelo> · HH:MM". O mesmo desenho, em 64 px e sem os segundos, vira o favicon (o href do <link rel="icon">, um PNG em data URL, refeito a cada minuto): a aba do navegador mostra a hora. 24 tipos de relógio, todos diferentes (23 de hoje e um futurista), um para cada hora do dia: o modelo da hora H é relojinho.ordem[H] do menu (recurso=conta&parte=menu; sem ele, H). A ordem vem da API pela Configuração relojinho_modo: hora (a própria hora: 0 a 23), aleatorio (cada hora, um resumo sha1 de coleção|dia|hora módulo 24, podendo repetir) ou sem_repeticao (os 24 ordenados pelo sha1 de coleção|dia|modelo: cada um uma vez por dia); o mesmo o dia inteiro em toda página. Ao chegar a ordem (o modelo muda), o título e o favicon se refazem na hora. Os modelos, na ordem: Clássico (redondo, dourado, mostrador creme, ponteiros dauphine, couro marrom), Mergulhador (preto, bisel azul-marinho com marcas, pontos luminosos, pulseira de aço), Aviador (preto, numerais, triângulo às 12, couro), Militar (verde, numerais, nato verde e marrom), Smartwatch (quadrado arredondado, tela preta com anel verde, silicone), Tanque (retangular dourado, ponteiros azuis, couro preto), Esportivo azul (mostrador azul com brilho, aço), Cronógrafo (três subdiais, bisel taquímetro preto), Esqueleto (ouro rosa, engrenagens insinuadas), Solar (raios laranja, borracha), Vintage (caixa almofada, mostrador creme envelhecido, numerais), GMT (bisel vermelho e azul, quarto ponteiro vermelho), Octogonal (caixa de oito lados, mostrador azul com brilho, janela da data no 3, aço), Fases da lua (ouro rosa, mostrador azul-noite, janela em arco no 6 com a lua da fase de hoje, couro azul), Calendário (mostrador cinza com brilho, janela da data, pulseira milanesa de malha cruzada), Bauhaus (mostrador claro, numerais, ponteiros finos, segundos vermelhos, couro cinza), Digital (caixa larga de resina, visor de cristal líquido verde-acinzentado com HH:MM e os segundos pequenos, sem ponteiros), De bolso (dourado, sem pulseira: argola e coroa em cima e a corrente pontilhada, numerais romanos, segundos num submostrador no 6), Regulador (os minutos no centro, as horas num submostrador no 12 e os segundos no 6), Ponteiro único (só o das horas, comprido, e os quartos de hora entre os índices), Turbilhão (platina, mostrador azul, a abertura no 6 com a gaiola girando uma volta por minuto), Joia (ouro rosa, 24 brilhantes no bisel, mostrador de madrepérola), Madeira (caixa e mostrador de madeira com veios, pulseira em gomos) e, o 24º, Futurista (desenhado à parte, relojinhoFuturista: sem pulseira, colado na pele: a borda cor de pele e a faixa escura com os circuitos, a caixa prateada em forma de seixo (um oval e uma faixa de pontas redondas) com o miolo de carbono, as luzes brancas em cima e embaixo e o hexágono no alto; o mostrador redondo azul-noite com o anel ciano, o anel magenta um pouco torto e o anel dos segundos que se enche; dentro, a data em magenta, a carinha da IA num círculo ciano (dois olhos que piscam a cada 8 segundos e o sorriso), o coração com o pulso, o sinal, as barrinhas magenta da voz dos dois lados, as setinhas e a hora grande; fora da caixa, dois hologramas flutuando). Na janela da data, o dia do mês do aparelho; no lugar da data e da lua, sem índice. No celular a barra é flex: o reloginho, o nome da página com o botão Menu (flex: 1) e, aberta, a lista na largura toda.' => '小手表（relojinho.js，在每个页面上，在其脚本之后）：菜单栏左角一块 30 px 的 canvas 绘制手表（高密度屏幕上清晰），显示设备的准确时间，秒针走动（每秒重绘）；链接到“准确时间”，标题为“<款式> · HH:MM”。同样的图案以 64 px、不带秒针成为网站图标（<link rel="icon"> 的 href，data URL 形式的 PNG，每分钟重做）：浏览器标签页显示时间。24 种各不相同的手表（23 种现有的和 1 种未来风格的），一天每个小时一种：小时 H 的款式是菜单中的 relojinho.ordem[H]（recurso=conta&parte=menu；没有时为 H）。顺序由 API 按设置 relojinho_modo 给出：hora（小时本身：0 到 23）、aleatorio（每小时取 收藏|日期|小时 的 sha1 摘要对 24 取模，可能重复）或 sem_repeticao（24 种按 收藏|日期|款式 的 sha1 排序：每天每种一次）；一整天在每个页面上都相同。顺序到达时（款式改变），标题和网站图标立即重做。款式依次为：经典（圆形，金色，米色表盘，太子妃针，棕色皮带）、潜水表（黑色，带刻度的深蓝表圈，夜光圆点，钢表带）、飞行员表（黑色，数字，12 点三角，皮带）、军表（绿色，数字，绿棕 nato 带）、Smartwatch（圆角方形，黑屏绿环，硅胶）、坦克表（金色长方形，蓝针，黑皮带）、蓝色运动表（带光泽的蓝盘，钢）、计时码表（三个小表盘，黑色测速圈）、镂空表（玫瑰金，隐约的齿轮）、太阳能表（橙色光线，橡胶）、Vintage（枕形表壳，做旧米色表盘，数字）、GMT（红蓝表圈，第四根红针）、八角形（八边形表壳，带光泽的蓝盘，3 点日期窗，钢）、月相（玫瑰金，夜蓝表盘，6 点拱形窗显示今天的月亮，蓝皮带）、日历（带光泽的灰盘，日期窗，交叉网格米兰表带）、Bauhaus（浅色表盘，数字，细针，红色秒针，灰皮带）、数字表（宽大的树脂表壳，灰绿色液晶屏显示 HH:MM 和小秒数，没有指针）、怀表（金色，没有表带：顶部是表环和表冠，以及点状表链，罗马数字，6 点小表盘显示秒）、调节器（分针在中央，12 点小表盘显示小时，6 点显示秒）、单针（只有一根长时针，刻度之间有一刻钟标记）、陀飞轮（铂金，蓝色表盘，6 点开口处框架每分钟转一圈）、珠宝（玫瑰金，表圈镶 24 颗钻石，珍珠母贝表盘）、木质（带纹理的木制表壳和表盘，分节表带）以及第 24 种未来（单独绘制，relojinhoFuturista：没有表带，贴在皮肤上：肤色边缘和带电路的深色带，碳纤维芯的银色卵石形表壳（一个椭圆加一条圆头的带），上下各一道白光，顶部一个六边形；夜蓝色圆形表盘，青色环、略微倾斜的品红色环和逐渐填满的秒环；里面是品红色日期、青色圆圈里的 AI 小脸（两只眼睛每 8 秒眨一次，还有微笑）、带脉搏的心形、信号、两侧的品红色声音条、小箭头和大号时间；表壳外有两个漂浮的全息图）。日期窗显示设备的当月日期；日期、月亮和小表盘的位置不画刻度。在手机上菜单栏为 flex：小手表、带 Menu 按钮的页面名（flex: 1），展开时列表占满整行。',
        'A especificação completa, tela por tela, está em telas (abaixo): o visual com os valores exatos (cores, letras, controles, componentes, larguras), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem com cada tabela, campo, botão e mensagem. Aqui, o resumo.' => '完整规格，逐页，在下面的 telas 中：带精确数值的视觉（颜色、字体、控件、组件、宽度）、菜单，以及每一页的地址、它在 API 中读取和写入的内容，以及按顺序的各部分，含每张表、字段、按钮和消息。这里是摘要。',
        'Hoje: no alto, o destaque: o relógio do dia ou, com destaque_hoje = pulso, o que está no pulso agora (a API escolhe: destaque.relogio_id) (com o Pôs e o Tirou), "Hoje é dia de" (os avisos com o botão que resolve), os próximos dias com o motivo e o trocar por…, o modo de rodízio (troca ali mesmo), e a tabela da coleção com filtros e ordenação; clicar num relógio abre o painel dele, ao lado da lista ou numa janela flutuante (painel_modo).' => '今天：顶部是突出显示：当天的手表，或当 destaque_hoje = pulso 时现在在手腕上的那块（API 选择：destaque.relogio_id）（带戴上和摘下），“今天是……的日子”（带用来解决的按钮的提醒），接下来的日子带事由和换成……，轮换模式（就在那里更换），以及带筛选和排序的收藏表格；点击一块手表打开它的面板，在列表旁边或浮动窗口中（painel_modo）。',
        'O painel (e a ficha, a mesma coisa numa página): a cabeça (foto, grupo, nome, marcas), quadros alinhados numa grade (Agora, Previsão, Gasto da bateria, Autonomia, Rodízio, Compra, Documentos, Próximas manutenções), cada um com rótulo e valor em duas colunas; o quadro Marcar (um menu só, "O que você quer marcar?", e embaixo só os campos daquilo); Editar cadastro; o gráfico da carga com as medições; os dados do relógio (o cadastro com a origem de cada valor e o resultado de cada fórmula com a versão); o histórico recente.' => '面板（以及详情，同一事物在一个页面上）：页眉（照片、分组、名称、标记），在网格中对齐的框（现在、预测、电池消耗、续航、轮换、购买、文档、接下来的保养），每一个以两列显示标签和值；标记框（只有一个菜单，“你想标记什么？”，下方只有那一项的字段）；编辑档案；带测量的电量图；手表的数据（档案，带每个值的来源，以及每个公式的结果和版本）；最近的历史。',
        'Plano, Histórico, Documentos (com o menu ⋮ em cada arquivo), Avisos, Configuração (quadros com uma opção por linha e a barra de salvar presa no pé), Destinos, Agendas, Modos de rodízio, Critérios, Grupos, Cadastros, Execuções do cron, Minha conta, Aprovações, Usuários (o painel do master), Ajuda (as seções do README) e o cadastro aberto.' => '计划、历史、文档（每个文件带 ⋮ 菜单）、提醒、设置（每行一个选项的面板，保存栏固定在底部）、推送目标、日历、轮换模式、标准、分组、定义、cron 运行记录、我的账户、审批、用户（master 面板）、帮助（README 的各节）以及公开注册。',
        'Três tamanhos com o mesmo sistema visual: até 900 px (celular e tablet de pé) o menu fica recolhido, as tabelas viram cartões e o relógio abre em tela cheia (o voltar do aparelho fecha); de 901 a 1199 px o painel ao lado desliza por cima, pela direita. A mesma informação em todos os tamanhos: nenhuma coluna, filtro ou dia é escondido por falta de espaço. A tabela dos relógios tem sempre as 12 colunas; quando a tabela inteira não cabe na largura que tem (medida com os dados, com ou sem o painel aberto), cada relógio vira um cartão com os mesmos 12 campos na mesma ordem, cada um com o nome da coluna em cima (2 colunas no celular, 5 no tablet), os títulos viram botões de ordenar e os 11 filtros ficam todos. Campos com letra de 16 px no celular (o iPhone não aproxima a tela).' => '同一视觉系统的三种尺寸：直到 900 px（手机和竖放平板）菜单收起，表格变成卡片，手表全屏打开（设备的返回关闭它）；从 901 到 1199 px，旁边的面板从右侧滑到上面。所有尺寸上信息相同：没有任何一列、筛选或日子因空间不足被隐藏。手表表始终有 12 列；当整张表在现有宽度中放不下时（用数据测量，面板打开或未打开），每块手表变成一张卡片，同样的 12 个字段按同样顺序，每一个上方是列名（手机上 2 列，平板上 5 列），标题变成排序按钮，11 个筛选全部保留。手机上字段字号 16 px（iPhone 不会放大页面）。',
        'Segurança' => '安全',
        'Todo pedido da API exige autenticação (o login do site, um token pessoal, a chave de um aparelho lembrado no cookie, ou o token do servidor), menos o cadastro aberto, o link ICS, os textos das telas, o manifesto e o service worker do aplicativo; as páginas são só o esqueleto, sem dado nenhum, e quem chega sem login vai para o login da API. Cada pedido só vê a coleção dele (o escopo é do banco), e a coleção que ele não vê responde 404. A cópia de segurança e as migrações são só do master. O cron e os scripts só pela linha de comando. Os arquivos internos (núcleo, banco, configuração, scripts, testes, dados, os que começam com ponto) ficam bloqueados no servidor web (.htaccess e nginx).' => '每个 API 请求都需要认证（网站登录、个人令牌、cookie 中已记住设备的密钥，或服务器令牌），公开注册、ICS 链接、界面文本、应用的清单和 service worker 除外；页面只是骨架，不含任何数据，未登录的访问者会转到 API 登录。每个请求只能看到自己的收藏（作用范围由数据库负责），看不到的收藏返回 404。备份和迁移仅限 master。cron 和脚本只能从命令行运行。内部文件（核心、数据库、设置、脚本、测试、数据、以点开头的文件）在 Web 服务器上被屏蔽（.htaccess 和 nginx）。',
        'SQL sempre com parâmetros; textos escapados no HTML; XML da NF-e lido sem entidades nem rede; arquivos servidos inline só dos tipos seguros; senhas com password_hash; o token comparado em tempo constante.' => 'SQL 始终带参数；文本在 HTML 中转义；NF-e 的 XML 读取时无实体也无网络；文件 inline 提供时只限于安全类型；密码用 password_hash；令牌以常数时间比较。',
        'Senhas: só o hash, pelo password_hash do PHP (bcrypt, $2y$<custo>$<sal de 22><resultado de 31>); o login confere com o password_verify (o bcrypt da senha digitada com o sal e o custo do hash). A API entrega o login e o hash de cada usuário (recurso=usuarios: senha_hash, senha_algoritmo, senha_custo) e aceita criar um usuário pelo hash de outro sistema (usuarios/salvar com senha_hash; bcrypt $2y$, $2b$ ou $2a$, ou argon2; o $2b$ guardado como $2y$, o mesmo cálculo). A reescrita tem de conferir pelo mesmo bcrypt, para os usuários migrarem com a mesma senha. Os arquivos dos documentos só pelo recurso=documento.' => '密码：只有哈希，用 PHP 的 password_hash（bcrypt，$2y$<成本>$<22 的盐><31 的结果>）；登录用 password_verify 核对（用哈希的盐和成本对所输入的密码做 bcrypt）。API 给出每个用户的登录名和哈希（recurso=usuarios：senha_hash、senha_algoritmo、senha_custo）并接受用来自另一个系统的哈希创建用户（usuarios/salvar 带 senha_hash；bcrypt $2y$、$2b$ 或 $2a$，或 argon2；$2b$ 存为 $2y$，同一计算）。重写必须用同一个 bcrypt 核对，以便用户以同一密码迁移。文档的文件只能通过 recurso=documento。',
        'Os testes e a aceitação' => '测试与验收',
        'testes/cenario.php faz pela API o que uma pessoa faz (cadastra relógios de cada tipo, lança cordas, cargas, sol, winder e pilha, monta a escala, mexe nos critérios, nos eventos e nas fotos, roda o cron) e tira a fotografia de tudo o que a API devolve; testes/comparar.php compara duas fotografias. Com RELOGIOS_SEMENTE (o sorteio fica previsível), o roteiro rodado em MySQL, PostgreSQL, SQLite e Firebird, num banco recém-instalado, tem de dar as mesmas respostas; e a reescrita, as mesmas da versão atual. testes/paridade.sh faz tudo com um comando (os bancos recriados, a instalação, o usuário, os servidores, o roteiro e a comparação), com o config de teste apontado pela variável de ambiente RELOGIOS_CONFIG (o núcleo carrega o arquivo que ela diz; sem ela, o config.php).' => 'testes/cenario.php 通过 API 做一个人会做的事（登记每种类型的手表，记录上链、电量、晒太阳、上链盒和电池，编制排班表，改动标准、事件和照片，运行 cron）并拍摄 API 返回的一切的快照；testes/comparar.php 比较两份快照。有 RELOGIOS_SEMENTE（抽签变为可预测）时，脚本在 MySQL、PostgreSQL、SQLite 和 Firebird 上、在刚安装的数据库中运行，必须给出相同响应；重写也必须与当前版本相同。testes/paridade.sh 用一条命令做完全部（重建数据库、安装、用户、服务器、脚本和比较），测试 config 由环境变量 RELOGIOS_CONFIG 指向（核心加载它所指的文件；没有它则用 config.php）。',
        'Além disso: nenhuma escrita do roteiro recusada; o dicionário da ajuda explica todos os campos das respostas; as telas sem erro de JavaScript e sem rolagem lateral no celular, no tablet e no computador.' => '此外：脚本的任何写入都没有被拒绝；帮助的词典说明了响应的全部字段；页面在手机、平板和电脑上没有 JavaScript 错误，也没有横向滚动。',
        'A documentação da API tem uma fonte só: o dicionário dos campos da ajuda (recurso=ajuda, campos); o do cabeçalho do api.php é gerado dele (testes/dicionario.php --gravar; sem o --gravar, confere). testes/campos.php confere que todo campo das respostas está explicado. Os dois rodam no testes/paridade.sh.' => 'API 文档只有一个来源：帮助的字段词典（recurso=ajuda，campos）；api.php 页眉中的由它生成（testes/dicionario.php --gravar；没有 --gravar 则核对）。testes/campos.php 核对响应的每个字段都有说明。两者都在 testes/paridade.sh 中运行。',
        'testes/layout.cjs abre todas as telas (com os quadros recolhidos abertos e cada opção dos menus que mostram partes) num navegador, em 15 tamanhos de 320 a 1920px, e mede o que quebra: a página que rola de lado, o elemento que sai da caixa em que está, a etiqueta partida, o texto cortado, o botão com o texto em duas linhas e o que fica por cima de outro. O esperado: 0 problemas.' => 'testes/layout.cjs 在浏览器中打开全部页面（收起的框被打开，以及显示各部分的菜单的每一个选项），尺寸从 320 到 1920px 共 15 种，并测量会坏掉的：页面横向滚动、元素越出它所在的框、标签被拆开、文本被截断、按钮上的文本变成两行、以及叠在另一个之上的。预期：0 个问题。',
        'Cada tabela com as colunas (nome, tipo no dialeto do banco em uso, se aceita vazio, o padrão), a chave primária, as chaves estrangeiras (a coluna, a tabela.coluna de referência e o que acontece ao apagar a linha de cima: CASCADE some junto, SET NULL desfaz a ligação), as chaves únicas, os índices e as regras de validação (CHECK). As colunas de texto curto não diferenciam maiúsculas nem acentos. Três referências ficam pelo nome, de propósito: as fórmulas e os critérios citam campos e fórmulas pelo identificador, e destino_aviso.tipo_aviso e agenda_aviso.tipo_aviso citam o aviso pelo identificador (vale para todas as versões dele).' => '每张表及其列（名称、所用数据库方言中的类型、是否允许为空、默认值）、主键、外键（列、引用的 表.列 以及删除上级行时的行为：CASCADE 一并删除，SET NULL 解除关联）、唯一键、索引和校验规则（CHECK）。短文本列不区分大小写和重音。有三种引用特意通过名称进行：公式和标准通过标识符引用字段和公式，destino_aviso.tipo_aviso 和 agenda_aviso.tipo_aviso 通过标识符引用提醒（对其所有版本生效）。',
    ],
];
